local function GetAtramentaFastFlagFunctions()
    local Environment = type(getgenv) == "function" and getgenv() or _G
    local Getter = Environment and rawget(Environment, "getfflag") or nil
    local Setter = Environment and rawget(Environment, "setfflag") or nil

    if type(Getter) ~= "function" and type(getfflag) == "function" then Getter = getfflag end
    if type(Setter) ~= "function" and type(setfflag) == "function" then Setter = setfflag end
    return Getter, Setter
end

local function TryAtramentaFastFlag(Name, Value)
    local Getter, Setter = GetAtramentaFastFlagFunctions()
    if type(Getter) ~= "function" or type(Setter) ~= "function" then return false end

    local ReadSuccess, Current = pcall(Getter, Name)
    if not ReadSuccess then
        AtramentaPerformanceRuntime.FlagFailures += 1
        return false
    end

    if AtramentaPerformanceRuntime.OriginalKnown[Name] ~= true then
        AtramentaPerformanceRuntime.OriginalKnown[Name] = true
        AtramentaPerformanceRuntime.Original[Name] = Current
    end

    if tostring(Current) ~= tostring(Value) then
        local WriteSuccess = pcall(Setter, Name, tostring(Value))
        if not WriteSuccess then
            AtramentaPerformanceRuntime.FlagFailures += 1
            return false
        end
    end

    AtramentaPerformanceRuntime.Applied[Name] = tostring(Value)
    AtramentaPerformanceRuntime.FlagCount += 1
    return true
end

function ApplyAtramentaPerformanceFlags()
    if AtramentaPerformanceRuntime.Enabled ~= true then return false end

    AtramentaPerformanceRuntime.FlagCount = 0
    AtramentaPerformanceRuntime.FlagFailures = 0

    for Index = 1, #AtramentaPerformanceRuntime.Flags do
        local Entry = AtramentaPerformanceRuntime.Flags[Index]
        TryAtramentaFastFlag(Entry[1], Entry[2])
    end

    return AtramentaPerformanceRuntime.FlagCount > 0
end

function RestoreAtramentaPerformanceFlags()
    local Getter, Setter = GetAtramentaFastFlagFunctions()
    if type(Getter) ~= "function" or type(Setter) ~= "function" then return end

    for Name, AppliedValue in pairs(AtramentaPerformanceRuntime.Applied) do
        if AtramentaPerformanceRuntime.OriginalKnown[Name] == true then
            local ReadSuccess, Current = pcall(Getter, Name)
            if ReadSuccess and tostring(Current) == tostring(AppliedValue) then
                pcall(Setter, Name, tostring(AtramentaPerformanceRuntime.Original[Name]))
            end
        end
    end

    table.clear(AtramentaPerformanceRuntime.Applied)
end

function SetAtramentaPerformanceEnabled(Value)
    AtramentaPerformanceRuntime.Enabled = Value == true
    if AtramentaPerformanceRuntime.Enabled then
        ApplyAtramentaPerformanceFlags()
    else
        RestoreAtramentaPerformanceFlags()
    end
end

