local LastGarbageCollectorStep = 0

local function AtramentaStepGC(Budget)
    if os.clock()
            - LastGarbageCollectorStep
        < 12
    then
        return
    end

    LastGarbageCollectorStep =
        os.clock()

    Budget = tonumber(Budget)
end

local function AtramentaReleaseBuffer(Buffer)
    if type(Buffer) == "table" then
        if table.clear then
            AtramentaCallChecked(table.clear, Buffer)
        else
            for Key in pairs(Buffer) do Buffer[Key] = nil end
        end
    end
    Buffer = nil
    AtramentaStepGC(160)
end

local AtramentaGarbageScanner = { Running = false }

local function AtramentaScanGarbage(IncludeTables, Visitor, BatchSize)
    if type(getgc) ~= "function" or type(Visitor) ~= "function" then return false end
    if AtramentaGarbageScanner.Running then
        local WaitStarted = os.clock()
        repeat
            task.wait()
        until not AtramentaGarbageScanner.Running or os.clock() - WaitStarted >= 2
        if AtramentaGarbageScanner.Running then return false end
    end
    AtramentaGarbageScanner.Running = true
    local Success, Objects = AtramentaCallChecked(getgc, IncludeTables == true)
    if not Success or type(Objects) ~= "table" then Success, Objects = AtramentaCallChecked(getgc) end
    if not Success or type(Objects) ~= "table" then
        AtramentaGarbageScanner.Running = false
        return false
    end
    BatchSize = math.max(math.floor(tonumber(BatchSize) or 384), 32)
    local ProcessSuccess = AtramentaCallChecked(function()
        local ObjectCount = #Objects
        local BatchCount = 0
        if ObjectCount > 0 then
            for Index = 1, ObjectCount do
                Visitor(Objects[Index])
                BatchCount = BatchCount + 1
                if BatchCount >= BatchSize then
                    BatchCount = 0
                    task.wait()
                end
            end
        else
            for Unused, Object in pairs(Objects) do
                Visitor(Object)
                BatchCount = BatchCount + 1
                if BatchCount >= BatchSize then
                    BatchCount = 0
                    task.wait()
                end
            end
        end
    end)
    AtramentaReleaseBuffer(Objects)
    AtramentaGarbageScanner.Running = false
    AtramentaStepGC(32)
    return ProcessSuccess
end

function SendKeyPress(KeyCode, HoldDuration)
    HoldDuration = tonumber(HoldDuration) or 0.03


    local VirtualKeyCode =
        KeyCode == Enum.KeyCode.R and 0x52
        or KeyCode == Enum.KeyCode.V and 0x56
        or KeyCode == Enum.KeyCode.Z and 0x5A
        or KeyCode == Enum.KeyCode.X and 0x58
        or KeyCode == Enum.KeyCode.B and 0x42
        or KeyCode == Enum.KeyCode.G and 0x47
        or KeyCode == Enum.KeyCode.H and 0x48
        or KeyCode == Enum.KeyCode.Q and 0x51
        or KeyCode.Value


    if type(keypress) == "function" and type(keyrelease) == "function" then
        local Success = AtramentaCallChecked(function()
            keypress(VirtualKeyCode)
            task.wait(math.max(HoldDuration, 0))
            keyrelease(VirtualKeyCode)
        end)
        if Success then return true end
    end

    if type(key_down) == "function" and type(key_up) == "function" then
        local Success = AtramentaCallChecked(function()
            key_down(VirtualKeyCode)
            task.wait(math.max(HoldDuration, 0))
            key_up(VirtualKeyCode)
        end)
        if Success then return true end
    end

    if VirtualInputManager then
        local Success = AtramentaCallChecked(function()
            VirtualInputManager:SendKeyEvent(true, KeyCode, false, game)
            task.wait(math.max(HoldDuration, 0))
            VirtualInputManager:SendKeyEvent(false, KeyCode, false, game)
        end)
        if Success then return true end
    end

    return false
end

function ActivateGuiButton(Button)
    if not Button or not Button.Parent or not Button:IsA("GuiButton") then return false end
    if type(firesignal) == "function" then
        local Triggered = false
        AtramentaCallChecked(function()
            firesignal(Button.Activated)
            Triggered = true
        end)
        AtramentaCallChecked(function()
            firesignal(Button.MouseButton1Click)
            Triggered = true
        end)
        if Triggered then return true end
    end
    if VirtualInputManager then
        local Position = Button.AbsolutePosition
        local Size = Button.AbsoluteSize
        local X = Position.X + Size.X * 0.5
        local Y = Position.Y + Size.Y * 0.5
        return AtramentaCallChecked(function()
            VirtualInputManager:SendMouseButtonEvent(X, Y, 0, true, game, 0)
            task.wait()
            VirtualInputManager:SendMouseButtonEvent(X, Y, 0, false, game, 0)
        end)
    end
    return false
end

