local function IsHitFeedbackEnabled() return HitFeedbackState.HitmarkerEnabled or HitFeedbackState.ImpactEnabled or HitFeedbackState.DamageIndicatorEnabled or HitFeedbackState.HitParticlesEnabled == true or HitFeedbackState.HitSound ~= "None" end
local function IsShotTrackingEnabled() return HitFeedbackState.BulletTracerEnabled or IsHitFeedbackEnabled() or CombatLogState.Enabled == true end

local function GetPlayerFromTrackedCharacter(Character)
    if not Character then return nil end
    local Player = Players:GetPlayerFromCharacter(Character)
    if Player then return Player end
    local NamedPlayer = Players:FindFirstChild(Character.Name)
    if NamedPlayer and NamedPlayer:IsA("Player") then return NamedPlayer end
    for Unused, Candidate in ipairs(Players:GetPlayers()) do
        if Candidate.Character == Character then return Candidate end
    end
    return nil
end

local function GetHumanoidCharacterFromPart(Part)
    local Current = Part
    while Current and Current ~= workspace do
        if Current:IsA("Model") and Current:FindFirstChildOfClass("Humanoid") then return Current end
        Current = Current.Parent
    end
    return nil
end

local function ResolveTrackedCharacter(Player, PreferredCharacter)
    if not Player then return nil end
    local WorldContainer = workspace:FindFirstChild("©")
    local Characters = WorldContainer and WorldContainer:FindFirstChild("Characters")
    local WorldCharacter = Characters and Characters:FindFirstChild(Player.Name)
    if WorldCharacter and WorldCharacter:IsA("Model") then return WorldCharacter end
    if PreferredCharacter and PreferredCharacter:IsA("Model") then return PreferredCharacter end
    return Player.Character
end

function CombatLogRuntime.GetDisplayName(Player)
    if not Player then
        return "Unknown"
    end

    local Name =
        tostring(
            Player.DisplayName
            or Player.Name
            or "Unknown"
        )

    if Name == "" then
        Name =
            tostring(
                Player.Name
                or "Unknown"
            )
    end

    return Name
end

function CombatLogRuntime.FormatDistance(Value)
    Value =
        tonumber(Value)

    if not Value
        or Value ~= Value
        or Value == math.huge
        or Value == -math.huge
    then
        return nil
    end

    if Value >= 100 then
        return tostring(
            math.floor(
                Value + 0.5
            )
        )
    end

    return string.format(
        "%.1f",
        Value
    )
end

function CombatLogRuntime.ApplyLogLayout()
    if Library and type(Library.SetNotificationLayout) == "function" then
        Library:SetNotificationLayout(CombatLogState.Position, CombatLogState.Scale)
    end
end

function CombatLogRuntime.BindLibraryNotice(Notice)
    if typeof(Notice) == "Instance" then
        Notice:SetAttribute("AtramentaCombatLog", true)
        CombatLogRuntime.LibraryNotices[#CombatLogRuntime.LibraryNotices + 1] = Notice
    end
    CombatLogRuntime.ApplyLogLayout()
    return Notice
end

function CombatLogRuntime.ClearVisualLogs()
    for Index = #CombatLogRuntime.LibraryNotices, 1, -1 do
        local Notice = CombatLogRuntime.LibraryNotices[Index]
        CombatLogRuntime.LibraryNotices[Index] = nil
        if Notice and Notice.Parent and Notice:GetAttribute("AtramentaCombatLog") == true then Notice:Destroy() end
    end
end

function CombatLogRuntime.Emit(Kind, Message, Detail)
    if CombatLogState.Enabled ~= true then return end
    Kind = tostring(Kind or "Info")
    if (Kind == "Hit" or Kind == "Kill") and CombatLogState.Hits ~= true then return end
    if Kind == "Miss" and CombatLogState.Misses ~= true then return end
    if Kind == "Damage" and CombatLogState.Incoming ~= true then return end
    if Kind == "NearMiss" and CombatLogState.NearMiss ~= true then return end
    if not Library or type(Library.Notification) ~= "function" then return end

    local Mode = Kind == "Damage" and "Danger" or (Kind == "Miss" or Kind == "NearMiss") and "Warn" or "Success"
    local Description = tostring(Message or "")
    if tostring(Detail or "") ~= "" then Description = Description .. "  •  " .. tostring(Detail) end

    local Notice = Library:Notification({
        Title = "Atramenta",
        Description = Description,
        Duration = CombatLogState.Duration,
        Mode = Mode
    })
    CombatLogRuntime.BindLibraryNotice(Notice)
end

function CombatLogRuntime.GetShotSourceName(Shot)
    local Source =
        Shot
        and tostring(
            Shot.Source or ""
        )
        or ""

    if Source == "RageBot" then
        return "Ragebot"
    elseif Source == "SilentAimFallback"
        or Source == "Silent Aim"
    then
        return "Silent Aim"
    elseif Source == "Aimbot" then
        return "Aimbot"
    elseif Source == "Remote" then
        return "Weapon"
    elseif Source == "Local" then
        return "Manual"
    end

    return Source ~= ""
        and Source
        or "Weapon"
end

function CombatLogRuntime.GetShotTargetPart(Shot)
    if type(Shot) ~= "table"
        or not Shot.Player
    then
        return nil, nil
    end

    local Character =
        ResolveTrackedCharacter(
            Shot.Player,
            Shot.Character
        )

    if not Character then
        return nil, nil
    end

    local Part =
        Shot.PartName
        and Character:
            FindFirstChild(
                Shot.PartName,
                true
            )
        or nil

    if not Part
        or not Part:IsA("BasePart")
    then
        Part =
            Character:
                FindFirstChild(
                    "HumanoidRootPart",
                    true
                )
            or Character:
                FindFirstChild(
                    "Head",
                    true
                )
            or Character.PrimaryPart
    end

    return Character, Part
end

function CombatLogRuntime.GetWeaponRange(Tool)
    if not Tool then
        return nil
    end

    if type(GetBulletTracerWeaponData)
        == "function"
    then
        local Data =
            GetBulletTracerWeaponData(
                Tool
            )

        if type(Data) == "table" then
            local Range =
                tonumber(Data.Range)

            if Range
                and Range > 0
            then
                return Range
            end
        end
    end

    return nil
end

function CombatLogRuntime.GetPointSegmentDistance(Point, StartPosition, EndPosition)
    if typeof(Point) ~= "Vector3"
        or typeof(StartPosition) ~= "Vector3"
        or typeof(EndPosition) ~= "Vector3"
    then
        return math.huge, StartPosition
    end

    local Segment =
        EndPosition
        - StartPosition

    local LengthSquared =
        Segment:Dot(
            Segment
        )

    if LengthSquared <= 0.0001 then
        return (
            Point
            - StartPosition
        ).Magnitude,
            StartPosition
    end

    local Alpha =
        math.clamp(
            (
                Point
                - StartPosition
            ):Dot(Segment)
                / LengthSquared,
            0,
            1
        )

    local Closest =
        StartPosition
        + Segment * Alpha

    return (
        Point
        - Closest
    ).Magnitude,
        Closest
end

function CombatLogRuntime.GetPreferredBodyParts(Character)
    if not Character then
        return {}
    end

    local CurrentTime =
        os.clock()

    local Cached =
        CombatLogRuntime.
            BodyPartCache[
                Character
            ]

    if type(Cached) == "table"
        and CurrentTime
            < (
                tonumber(
                    Cached.RefreshAt
                )
                or 0
            )
        and type(Cached.Parts)
            == "table"
    then
        return Cached.Parts
    end

    local PreferredNames = {
        Head = true,
        HumanoidRootPart = true,
        UpperTorso = true,
        LowerTorso = true,
        Torso = true,
        ["Left Arm"] = true,
        ["Right Arm"] = true,
        ["Left Leg"] = true,
        ["Right Leg"] = true,
        LeftUpperArm = true,
        RightUpperArm = true,
        LeftLowerArm = true,
        RightLowerArm = true,
        LeftUpperLeg = true,
        RightUpperLeg = true,
        LeftLowerLeg = true,
        RightLowerLeg = true
    }

    local Parts = {}

    for _, Part in ipairs(
        Character:GetDescendants()
    ) do
        if Part:IsA("BasePart")
            and PreferredNames[
                Part.Name
            ]
        then
            Parts[#Parts + 1] =
                Part
        end
    end

    CombatLogRuntime.
        BodyPartCache[
            Character
        ] = {
            Parts = Parts,
            RefreshAt =
                CurrentTime + 1
        }

    return Parts
end

function CombatLogRuntime.GetClosestBodyPartToSegment(Character, StartPosition, EndPosition)
    if not Character then
        return nil,
            math.huge
    end

    local BestPart = nil
    local BestDistance =
        math.huge

    for _, Part in ipairs(
        CombatLogRuntime.
            GetPreferredBodyParts(
                Character
            )
    ) do
        if Part
            and Part.Parent
        then
            local CenterDistance =
                CombatLogRuntime.
                    GetPointSegmentDistance(
                        Part.Position,
                        StartPosition,
                        EndPosition
                    )

            local Radius =
                math.max(
                    math.min(
                        Part.Size.X,
                        Part.Size.Y,
                        Part.Size.Z
                    ) * 0.42,
                    0.22
                )

            local SurfaceDistance =
                math.max(
                    CenterDistance
                        - Radius,
                    0
                )

            if SurfaceDistance
                < BestDistance
            then
                BestDistance =
                    SurfaceDistance

                BestPart =
                    Part
            end
        end
    end

    return BestPart,
        BestDistance
end

function CombatLogRuntime.ResolvePlayerFromObject(Object)
    local Current =
        Object

    while Current
        and Current ~= workspace
    do
        if Current:IsA("Model") then
            local Player =
                Players:
                    GetPlayerFromCharacter(
                        Current
                    )

            if Player then
                return Player
            end

            local Named =
                Players:
                    FindFirstChild(
                        Current.Name
                    )

            if Named
                and Named:IsA(
                    "Player"
                )
            then
                return Named
            end
        end

        Current =
            Current.Parent
    end

    return nil
end

function CombatLogRuntime.FindNearestEnemyToPosition(Position, MaximumDistance)
    if typeof(Position) ~= "Vector3" then
        return nil
    end

    MaximumDistance =
        tonumber(MaximumDistance)
        or 18

    local BestPlayer = nil
    local BestDistance =
        MaximumDistance

    for _, Player in ipairs(
        Players:GetPlayers()
    ) do
        if Player ~= LocalPlayer then
            local Character =
                ResolveTrackedCharacter(
                    Player,
                    Player.Character
                )

            local Root =
                Character
                and Character:
                    FindFirstChild(
                        "HumanoidRootPart"
                    )

            if Root then
                local Distance =
                    (
                        Root.Position
                        - Position
                    ).Magnitude

                if Distance
                    < BestDistance
                then
                    BestDistance =
                        Distance

                    BestPlayer =
                        Player
                end
            end
        end
    end

    return BestPlayer
end

function CombatLogRuntime.ResolveEnemyShotSource(Origin, Object)
    local Player =
        CombatLogRuntime.ResolvePlayerFromObject(
            Object
        )

    if not Player
        and Object
        and Object.Parent
    then
        Player =
            CombatLogRuntime.ResolvePlayerFromObject(
                Object.Parent
            )
    end

    if not Player then
        Player =
            CombatLogRuntime.FindNearestEnemyToPosition(
                Origin,
                18
            )
    end

    if Player == LocalPlayer then
        return nil
    end

    return Player
end

function CombatLogRuntime.IsOwnVisual(Object)
    local Current =
        Object

    for _ = 1, 5 do
        if not Current then
            break
        end

        if string.find(
            string.lower(
                Current.Name
            ),
            "atramenta",
            1,
            true
        )
        then
            return true
        end

        Current =
            Current.Parent
    end

    return false
end

function CombatLogRuntime.RecordEnemyShot(Player, Origin, EndPosition, SourceObject)
    if CombatLogState.Enabled ~= true
        or not Player
        or Player == LocalPlayer
        or typeof(Origin) ~= "Vector3"
        or typeof(EndPosition) ~= "Vector3"
    then
        return
    end

    local Character =
        LocalPlayer.Character

    local Root =
        Character
        and Character:
            FindFirstChild(
                "HumanoidRootPart"
            )

    if not Root then
        return
    end

    local Part,
        MissDistance =
        CombatLogRuntime.GetClosestBodyPartToSegment(
            Character,
            Origin,
            EndPosition
        )

    if not Part
        or MissDistance == math.huge
    then
        return
    end

    local CurrentTime =
        os.clock()

    local Shot = {
        Time = CurrentTime,
        Player = Player,
        Origin = Origin,
        EndPosition = EndPosition,
        Part = Part,
        MissDistance = MissDistance,
        SourceObject = SourceObject
    }

    CombatLogRuntime.RecentEnemyShots[
        #CombatLogRuntime.RecentEnemyShots + 1
    ] = Shot

    for Index =
        #CombatLogRuntime.RecentEnemyShots,
        1,
        -1
    do
        local Entry =
            CombatLogRuntime.RecentEnemyShots[
                Index
            ]

        if not Entry
            or CurrentTime
                - (Entry.Time or 0)
                > 0.75
        then
            table.remove(
                CombatLogRuntime.RecentEnemyShots,
                Index
            )
        end
    end

    if CombatLogState.NearMiss ~= true then
        return
    end

    local Radius =
        math.clamp(
            tonumber(
                CombatLogState.NearMissRadius
            )
                or 4,
            0.5,
            10
        )

    if MissDistance <= 0.22
        or MissDistance > Radius
    then
        return
    end

    local Key =
        tostring(Player.UserId)
        .. ":"
        .. tostring(
            math.floor(
                Origin.X * 0.2
            )
        )
        .. ":"
        .. tostring(
            math.floor(
                Origin.Y * 0.2
            )
        )
        .. ":"
        .. tostring(
            math.floor(
                Origin.Z * 0.2
            )
        )

    local Previous =
        CombatLogRuntime.RecentNearMissKeys[
            Key
        ]

    if Previous
        and CurrentTime - Previous
            < 0.20
    then
        return
    end

    CombatLogRuntime.RecentNearMissKeys[
        Key
    ] = CurrentTime

    task.delay(
        0.20,
        function()
            if CombatLogRuntime.RecentDamageAt
                >= CurrentTime
            then
                return
            end

            if not Player.Parent then
                return
            end

            local DistanceText =
                CombatLogRuntime.FormatDistance(
                    MissDistance
                )

            if not DistanceText then
                return
            end

            local ShooterRoot =
                ResolveTrackedCharacter(
                    Player,
                    Player.Character
                )

            ShooterRoot =
                ShooterRoot
                and ShooterRoot:
                    FindFirstChild(
                        "HumanoidRootPart"
                    )

            local SourceDistance =
                ShooterRoot
                and (
                    ShooterRoot.Position
                    - Root.Position
                ).Magnitude
                or nil

            local Detail =
                Part.Name

            local SourceDistanceText =
                CombatLogRuntime.FormatDistance(
                    SourceDistance
                )

            if SourceDistanceText then
                Detail =
                    Detail
                    .. "  •  "
                    .. SourceDistanceText
                    .. " studs away"
            end

            CombatLogRuntime.Emit(
                "NearMiss",
                "Near miss from ["
                    .. CombatLogRuntime.GetDisplayName(
                        Player
                    )
                    .. "]  •  "
                    .. DistanceText
                    .. " studs",
                Detail
            )
        end
    )
end

function CombatLogRuntime.TrackEnemyShotObject(Object)
    if not Object
        or CombatLogRuntime.SeenEnemyShotObjects[
            Object
        ]
        or CombatLogRuntime.IsOwnVisual(
            Object
        )
    then
        return
    end

    if Object:IsA("Beam") then
        CombatLogRuntime.SeenEnemyShotObjects[
            Object
        ] = true

        task.delay(
            0.025,
            function()
                if not Object.Parent then
                    return
                end

                local Attachment0 =
                    Object.Attachment0

                local Attachment1 =
                    Object.Attachment1

                if not Attachment0
                    or not Attachment1
                then
                    return
                end

                local Origin =
                    Attachment0.WorldPosition

                local EndPosition =
                    Attachment1.WorldPosition

                if (
                    EndPosition
                    - Origin
                ).Magnitude < 2
                then
                    return
                end

                local Player =
                    CombatLogRuntime.ResolveEnemyShotSource(
                        Origin,
                        Object
                    )

                if Player then
                    CombatLogRuntime.RecordEnemyShot(
                        Player,
                        Origin,
                        EndPosition,
                        Object
                    )
                end
            end
        )

        return
    end

    if Object:IsA("BasePart") then
        local LowerName =
            string.lower(
                Object.Name
            )

        local LooksLikeShot =
            string.find(
                LowerName,
                "bullet",
                1,
                true
            )
            or string.find(
                LowerName,
                "tracer",
                1,
                true
            )
            or string.find(
                LowerName,
                "laser",
                1,
                true
            )

        if not LooksLikeShot then
            return
        end

        CombatLogRuntime.SeenEnemyShotObjects[
            Object
        ] = true

        local StartPosition =
            Object.Position

        task.delay(
            0.035,
            function()
                if not Object.Parent then
                    return
                end

                local EndPosition =
                    Object.Position

                if (
                    EndPosition
                    - StartPosition
                ).Magnitude < 1
                then
                    return
                end

                local Player =
                    CombatLogRuntime.ResolveEnemyShotSource(
                        StartPosition,
                        Object
                    )

                if Player then
                    CombatLogRuntime.RecordEnemyShot(
                        Player,
                        StartPosition,
                        EndPosition,
                        Object
                    )
                end
            end
        )
    end
end

function CombatLogRuntime.InstallEnemyShotTracking()
    if CombatLogRuntime.EnemyShotConnection then
        return
    end

    CombatLogRuntime.EnemyShotConnection =
        workspace.DescendantAdded:
            Connect(
                function(Object)
                    if CombatLogState.Enabled ~= true
                        or CombatLogState.NearMiss ~= true
                    then
                        return
                    end

                    if Object:IsA("Beam")
                        or Object:IsA("BasePart")
                    then
                        CombatLogRuntime.TrackEnemyShotObject(
                            Object
                        )
                    end
                end
            )

    CombatLogRuntime.EnemyShotConnections[
        #CombatLogRuntime.EnemyShotConnections + 1
    ] =
        CombatLogRuntime.EnemyShotConnection
end

function CombatLogRuntime.FindTaggedAttacker(Character, Humanoid)
    local Containers = {
        Character,
        Humanoid
    }

    local CharStats =
        ReplicatedStorage:
            FindFirstChild(
                "CharStats"
            )

    if CharStats
        and LocalPlayer
    then
        Containers[
            #Containers + 1
        ] =
            CharStats:
                FindFirstChild(
                    LocalPlayer.Name
                )
    end

    local Keywords = {
        "creator",
        "attacker",
        "damager",
        "damagefrom",
        "lastdamager",
        "lastattacker",
        "killer",
        "shooter",
        "source"
    }

    for _, Container in ipairs(Containers) do
        if Container then
            for _, Object in ipairs(
                Container:GetDescendants()
            ) do
                if Object:IsA("ObjectValue")
                    and Object.Value
                then
                    local LowerName =
                        string.lower(
                            Object.Name
                        )

                    local Match = false

                    for _, Keyword in ipairs(
                        Keywords
                    ) do
                        if string.find(
                            LowerName,
                            Keyword,
                            1,
                            true
                        )
                        then
                            Match = true
                            break
                        end
                    end

                    if Match then
                        if Object.Value:IsA("Player") then
                            if Object.Value ~= LocalPlayer then
                                return Object.Value
                            end
                        else
                            local Player =
                                CombatLogRuntime.ResolvePlayerFromObject(
                                    Object.Value
                                )

                            if Player
                                and Player ~= LocalPlayer
                            then
                                return Player
                            end
                        end
                    end
                end
            end
        end
    end

    return nil
end

function CombatLogRuntime.GetRecentEnemyShot()
    local CurrentTime =
        os.clock()

    local Best = nil

    for Index =
        #CombatLogRuntime.RecentEnemyShots,
        1,
        -1
    do
        local Shot =
            CombatLogRuntime.RecentEnemyShots[
                Index
            ]

        if not Shot
            or CurrentTime
                - (Shot.Time or 0)
                > 0.55
        then
            table.remove(
                CombatLogRuntime.RecentEnemyShots,
                Index
            )
        elseif not Best then
            Best = Shot
        end
    end

    return Best
end

function CombatLogRuntime.LogIncomingDamage(Character, Humanoid, Damage)
    if CombatLogState.Enabled ~= true
        or CombatLogState.Incoming ~= true
        or not Damage
        or Damage <= 0
    then
        return
    end

    CombatLogRuntime.RecentDamageAt =
        os.clock()

    local RecentShot =
        CombatLogRuntime.GetRecentEnemyShot()

    if RecentShot
        and (
            tonumber(
                RecentShot.MissDistance
            )
            or math.huge
        ) > 1.35
    then
        RecentShot = nil
    end

    local Attacker =
        CombatLogRuntime.FindTaggedAttacker(
            Character,
            Humanoid
        )

    if not Attacker
        and RecentShot
    then
        Attacker =
            RecentShot.Player
    end

    local LocalRoot =
        Character
        and Character:
            FindFirstChild(
                "HumanoidRootPart"
            )

    local AttackerCharacter =
        Attacker
        and ResolveTrackedCharacter(
            Attacker,
            Attacker.Character
        )

    local AttackerRoot =
        AttackerCharacter
        and AttackerCharacter:
            FindFirstChild(
                "HumanoidRootPart"
            )

    local Distance =
        LocalRoot
        and AttackerRoot
        and (
            LocalRoot.Position
            - AttackerRoot.Position
        ).Magnitude
        or LocalRoot
            and RecentShot
            and (
                LocalRoot.Position
                - RecentShot.Origin
            ).Magnitude
            or nil

    local PartName =
        RecentShot
        and RecentShot.Part
        and RecentShot.Part.Name
        or nil

    local RoundedDamage
    if math.abs(Damage - math.floor(Damage + 0.5)) <= 0.05 then
        RoundedDamage = math.max(math.floor(Damage + 0.5), 1)
    else
        RoundedDamage = math.max(math.floor(Damage * 10 + 0.5) / 10, 0.1)
    end

    local Message = "Damage taken: " .. tostring(RoundedDamage)

    if Attacker then
        Message =
            Message
            .. " from ["
            .. CombatLogRuntime.GetDisplayName(
                Attacker
            )
            .. "]"
    end

    local DetailParts = {}

    if PartName then
        DetailParts[
            #DetailParts + 1
        ] =
            PartName
    end

    local DistanceText =
        CombatLogRuntime.FormatDistance(
            Distance
        )

    if DistanceText then
        DetailParts[
            #DetailParts + 1
        ] =
            DistanceText
            .. " studs"
    end

    CombatLogRuntime.Emit(
        "Damage",
        Message,
        table.concat(
            DetailParts,
            "  •  "
        )
    )
end

function CombatLogRuntime.BindLocalDamage(Character)
    if CombatLogRuntime.LocalDamageConnection then
        CombatLogRuntime.LocalDamageConnection:
            Disconnect()

        CombatLogRuntime.LocalDamageConnection =
            nil
    end

    CombatLogRuntime.LocalCharacter =
        Character

    local Humanoid =
        Character
        and (
            Character:
                FindFirstChildOfClass(
                    "Humanoid"
                )
            or Character:
                WaitForChild(
                    "Humanoid",
                    5
                )
        )

    CombatLogRuntime.LocalHumanoid =
        Humanoid

    if not Humanoid then
        return
    end

    CombatLogRuntime.PreviousLocalHealth = Humanoid.Health
    CombatLogRuntime.DamageAccumulator = 0
    CombatLogRuntime.DamageAccumulatorVersion += 1
    CombatLogRuntime.DamageAccumulatorCharacter = Character
    CombatLogRuntime.DamageAccumulatorHumanoid = Humanoid

    CombatLogRuntime.LocalDamageConnection = Humanoid.HealthChanged:Connect(function(NewHealth)
        if CombatLogRuntime.LocalCharacter ~= Character then return end

        local PreviousHealth = CombatLogRuntime.PreviousLocalHealth
        CombatLogRuntime.PreviousLocalHealth = NewHealth
        if type(PreviousHealth) ~= "number" or type(NewHealth) ~= "number" then return end

        local Damage = PreviousHealth - NewHealth
        if Damage <= 0 then return end

        CombatLogRuntime.DamageAccumulator += Damage
        CombatLogRuntime.DamageAccumulatorCharacter = Character
        CombatLogRuntime.DamageAccumulatorHumanoid = Humanoid
        CombatLogRuntime.DamageAccumulatorVersion += 1
        local Version = CombatLogRuntime.DamageAccumulatorVersion

        task.delay(CombatLogRuntime.DamageAccumulatorWindow, function()
            if CombatLogRuntime.LocalCharacter ~= Character or CombatLogRuntime.DamageAccumulatorVersion ~= Version then return end
            local TotalDamage = CombatLogRuntime.DamageAccumulator
            CombatLogRuntime.DamageAccumulator = 0
            if TotalDamage > 0 then CombatLogRuntime.LogIncomingDamage(Character, Humanoid, TotalDamage) end
        end)
    end)
end

function CombatLogRuntime.ClassifyMiss(Shot)
    if type(Shot) ~= "table"
        or not Shot.Player
    then
        return "unconfirmed shot",
            nil
    end

    local Character,
        TargetPart =
        CombatLogRuntime.GetShotTargetPart(
            Shot
        )

    if not Character
        or not TargetPart
    then
        return "target lost",
            nil
    end

    local Origin =
        Shot.Origin

    local IntendedPosition =
        typeof(Shot.HitPosition) == "Vector3"
        and Shot.HitPosition
        or typeof(
            Shot.TargetPositionAtFire
        ) == "Vector3"
            and Shot.TargetPositionAtFire
            or TargetPart.Position

    local Distance =
        typeof(Origin) == "Vector3"
        and (
            IntendedPosition - Origin
        ).Magnitude
        or nil

    local Range =
        CombatLogRuntime.GetWeaponRange(
            Shot.Tool
        )

    if Range
        and Distance
        and Distance > Range * 1.02
    then
        return "distance",
            Distance
    end

    local PredictedCenter =
        typeof(Shot.PredictedCenter) == "Vector3"
        and Shot.PredictedCenter
        or nil

    if PredictedCenter then
        local PredictionError =
            (
                TargetPart.Position
                - PredictedCenter
            ).Magnitude

        if PredictionError
            > math.max(
                TargetPart.Size.Magnitude
                    * 0.34,
                0.85
            )
        then
            return "prediction error",
                Distance
        end
    end

    if Shot.Source == "RageBot" and Shot.RouteValidAtFire ~= true
        and typeof(Shot.Origin) == "Vector3" and typeof(Shot.HitPosition) == "Vector3"
    then
        local StillValid = RageBotAPI.ValidateRageRoute(Shot.Origin, Shot.HitPosition, TargetPart)
        if not StillValid then return "obstruction", Distance end
    end

    if Shot.Source ~= "RageBot"
        and typeof(Origin) == "Vector3"
        and typeof(Shot.Direction) == "Vector3"
    then
        local IntendedDelta =
            IntendedPosition - Origin

        if IntendedDelta.Magnitude > 0.001
            and Shot.Direction.Magnitude > 0.001
        then
            local Dot =
                math.clamp(
                    IntendedDelta.Unit:
                        Dot(
                            Shot.Direction.Unit
                        ),
                    -1,
                    1
                )

            local Angle =
                math.deg(
                    math.acos(
                        Dot
                    )
                )

            local WeaponData =
                type(GetBulletTracerWeaponData)
                    == "function"
                and GetBulletTracerWeaponData(
                    Shot.Tool
                )
                or nil

            local Spread =
                WeaponData
                and tonumber(
                    WeaponData.Spread
                )
                or 0

            local SpreadThreshold =
                math.max(
                    Spread * 0.35,
                    0.55
                )

            if Angle > SpreadThreshold then
                return "spread",
                    Distance
            end
        end
    end

    if typeof(Origin) == "Vector3"
        and typeof(IntendedPosition)
            == "Vector3"
        and Shot.Source ~= "RageBot"
    then
        RageBotAPI.RefreshRageRayParams(
            LocalPlayer
        )

        local Result =
            workspace:Raycast(
                Origin,
                IntendedPosition - Origin,
                RageWallbangRuntime.TraceParams
            )

        if Result
            and not Result.Instance:
                IsDescendantOf(
                    Character
                )
        then
            return "obstruction",
                Distance
        end
    end

    if Shot.AmmoConfirmed == true and Shot.SignalConfirmed == true then return "no damage confirmation", Distance end
    return "unconfirmed shot", Distance
end

function CombatLogRuntime.ScheduleMiss(Shot)
    if type(Shot) ~= "table"
        or Shot.MissScheduled
    then
        return
    end

    Shot.MissScheduled = true

    task.delay(
        math.max(
            tonumber(
                CombatLogState.ResolveDelay
            )
                or 1.15,
            0.20
        ),
        function()
            if CombatLogState.Enabled ~= true
                or CombatLogState.Misses ~= true
                or Shot.DamageConfirmed == true
                or Shot.MissLogged == true
                or Shot.AmmoConfirmed ~= true
                or not Shot.Player
            then
                return
            end

            Shot.MissLogged = true

            local Reason,
                Distance =
                CombatLogRuntime.ClassifyMiss(
                    Shot
                )

            local DetailParts = {
                CombatLogRuntime.GetShotSourceName(
                    Shot
                )
            }

            local DistanceText =
                CombatLogRuntime.FormatDistance(
                    Distance
                )

            if DistanceText then
                DetailParts[
                    #DetailParts + 1
                ] =
                    DistanceText
                    .. " studs"
            end

            CombatLogRuntime.Emit(
                "Miss",
                "Miss due to "
                    .. tostring(Reason),
                table.concat(
                    DetailParts,
                    "  •  "
                )
            )
        end
    )
end

local function CleanupAttackConfirmations()
    local CurrentTime = os.clock()
    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        local Expired = not Shot or CurrentTime - (Shot.Time or 0) > AttackConfirmationState.Window
        local Completed = Shot and Shot.DamageConfirmed and CurrentTime - (Shot.ConfirmedAt or Shot.Time or 0) > AttackConfirmationState.MergeWindow
        if Expired or Completed then table.remove(AttackConfirmationState.Shots, Index) end
    end
    while #AttackConfirmationState.Shots > AttackConfirmationState.MaximumShots do table.remove(AttackConfirmationState.Shots, 1) end
end

local function ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    TargetCharacter = TargetCharacter or GetHumanoidCharacterFromPart(TargetPart)
    local TargetPlayer = GetPlayerFromTrackedCharacter(TargetCharacter)
    if not TargetPlayer or TargetPlayer == LocalPlayer or not TargetCharacter then return nil, nil, nil, nil end
    local ResolvedCharacter = ResolveTrackedCharacter(TargetPlayer, TargetCharacter)
    if ResolvedCharacter then TargetCharacter = ResolvedCharacter end
    local PartName = TargetPart and TargetPart.Name or nil
    if TargetPart and not TargetPart:IsDescendantOf(TargetCharacter) then TargetPart = PartName and TargetCharacter:FindFirstChild(PartName, true) or nil end
    if not TargetPart then TargetPart = TargetCharacter:FindFirstChild("HumanoidRootPart") or TargetCharacter:FindFirstChild("Head") or TargetCharacter.PrimaryPart end
    if not TargetPart or not TargetPart:IsA("BasePart") then return TargetPlayer, TargetCharacter, nil, PartName end
    return TargetPlayer, TargetCharacter, TargetPart, TargetPart.Name
end

local IsVerifiedLocalFirearmTool

local function RegisterLocalAttack(TargetCharacter, TargetPart, ShotToken, Tool, Source, OriginPosition, Direction)
    if not Tool or not Tool:IsA("Tool") or type(IsVerifiedLocalFirearmTool) ~= "function" or not IsVerifiedLocalFirearmTool(Tool) then return nil end
    local Values =
        Tool:
            FindFirstChild(
                "Values"
            )

    local ServerAmmo =
        Values
        and (
            Values:
                FindFirstChild(
                    "SERVER_Ammo"
                )
            or Values:
                FindFirstChild(
                    "Ammo"
                )
        )

    if ServerAmmo
        and typeof(ServerAmmo.Value) == "number"
        and ServerAmmo.Value <= 0
    then
        return nil
    end

    local TargetPlayer, ResolvedCharacter, ResolvedPart, PartName = ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    CleanupAttackConfirmations()
    local CurrentTime = os.clock()

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Existing = AttackConfirmationState.Shots[Index]
        local SameToken = ShotToken ~= nil and Existing.Token ~= nil and tostring(Existing.Token) == tostring(ShotToken)
        local SameRemoteShot = Existing.Tool == Tool and CurrentTime - (Existing.Time or 0) <= 0.022
        if Existing.VerifiedFire and (SameToken or SameRemoteShot) then
            Existing.Time = CurrentTime
            Existing.Token = ShotToken or Existing.Token
            Existing.Source = Source or Existing.Source
            Existing.Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or Existing.Origin
            Existing.Direction = typeof(Direction) == "Vector3" and Direction or Existing.Direction
            if TargetPlayer and ResolvedCharacter then
                Existing.Player = TargetPlayer
                Existing.Character = ResolvedCharacter
                Existing.PartName = Existing.PartName == "Head" and "Head" or PartName
            end
            return Existing
        end
    end

    local Shot = {
        Time = CurrentTime,
        Player = TargetPlayer,
        Character = ResolvedCharacter,
        TargetPart = ResolvedPart,
        PartName = PartName,
        TargetPositionAtFire =
            ResolvedPart
            and ResolvedPart.Position
            or nil,
        TargetVelocityAtFire =
            ResolvedPart
            and ResolvedPart.AssemblyLinearVelocity
            or nil,
        Token = ShotToken,
        Tool = Tool,
        Source = Source or "Local",
        Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or nil,
        Direction = typeof(Direction) == "Vector3" and Direction or nil,
        AmmoAtFire = ServerAmmo and tonumber(ServerAmmo.Value) or nil,
        VerifiedFire = true,
        ConfirmedAt = nil,
        SignalConfirmed = false,
        AmmoConfirmed = false,
        DamageConfirmed = false,
        TracerSpawned = false
    }
    AttackConfirmationState.Shots[#AttackConfirmationState.Shots + 1] = Shot
    CombatLogRuntime.ScheduleMiss(Shot)
    return Shot
end

local function AttachAttackTarget(Shot, TargetCharacter, TargetPart)
    if not Shot or not Shot.VerifiedFire then return false end
    local TargetPlayer, ResolvedCharacter, ResolvedPart, PartName = ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    if not TargetPlayer or not ResolvedCharacter then return false end
    Shot.Player = TargetPlayer
    Shot.Character = ResolvedCharacter
    Shot.TargetPart = ResolvedPart
    Shot.TargetPositionAtFire =
        ResolvedPart
        and ResolvedPart.Position
        or Shot.TargetPositionAtFire
    Shot.TargetVelocityAtFire =
        ResolvedPart
        and ResolvedPart.AssemblyLinearVelocity
        or Shot.TargetVelocityAtFire
    Shot.PartName = Shot.PartName == "Head" and "Head" or PartName
    return true
end

local function FindAttackConfirmation(Character)
    CleanupAttackConfirmations()
    local CurrentTime = os.clock()
    local TargetPlayer = GetPlayerFromTrackedCharacter(Character)
    local BestShot, BestScore = nil, -math.huge

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        local MatchesTarget = Shot and (Shot.Character == Character or TargetPlayer and Shot.Player == TargetPlayer)
        if Shot and Shot.VerifiedFire and not Shot.DamageConfirmed and MatchesTarget then
            local Age = CurrentTime - (Shot.Time or 0)
            if Age <= AttackConfirmationState.DamageWindow then
                local Score = -Age
                if Shot.AmmoConfirmed == true then Score += 4 end
                if Shot.SignalConfirmed == true then Score += 3 end
                if tostring(Shot.Source or "") == "RageBot" then Score += 2 end
                if Shot.Token ~= nil then Score += 0.5 end
                if Score > BestScore then BestScore, BestShot = Score, Shot end
            end
        end
    end

    if BestShot then BestShot.ConfirmedAt = CurrentTime end
    return BestShot
end

local function GetActiveConfirmedCombatTarget()
    if RageBotEnabled and RageBotCurrentTarget then return RageBotCurrentTarget end
    local AimBot = S and S.AimBot
    if AimBot and AimBot.Enabled then return AimBot.CurrentTarget or AimBot.Target end
    return nil
end

local function FindTargetAwareAttackConfirmation(Player, Character)
    local Exact = FindAttackConfirmation(Character)
    if Exact then return Exact end

    CleanupAttackConfirmations()
    local CurrentTime = os.clock()
    local ActiveTarget = GetActiveConfirmedCombatTarget()

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        if Shot and Shot.VerifiedFire and not Shot.DamageConfirmed and CurrentTime - (Shot.Time or 0) <= AttackConfirmationState.DamageWindow then
            local Source = tostring(Shot.Source or "")
            local IsCombatShot = Source == "RageBot" or Source == "Remote" or Source == "Aimbot" or Source == "SilentAim" or Source == "SilentAimFallback" or Source == "Local"
            local TargetMatches = Shot.Player == Player or Shot.Character == Character
            local HasNoResolvedTarget = Shot.Player == nil or Shot.Character == nil
            local IsRecentLocalShot = CurrentTime - (Shot.Time or 0) <= 0.55
            if TargetMatches or IsCombatShot and HasNoResolvedTarget and (ActiveTarget == Player or IsRecentLocalShot) then
                Shot.Player = Player
                Shot.Character = Character
                Shot.PartName = Shot.PartName or (RageBotSettings.TargetPart or "Head")
                Shot.ConfirmedAt = CurrentTime
                return Shot
            end
        end
    end
    return nil
end

local function ConfirmMergedRageShots(PrimaryShot, Player, Character)
    if not PrimaryShot or tostring(PrimaryShot.Source or "") ~= "RageBot" then return 0 end
    local PrimaryTime = tonumber(PrimaryShot.Time) or 0
    local CurrentTime = os.clock()
    local Confirmed = 0

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        if Shot and Shot ~= PrimaryShot and not Shot.DamageConfirmed
            and tostring(Shot.Source or "") == "RageBot"
            and Shot.AmmoConfirmed == true and Shot.SignalConfirmed == true
            and (Shot.Player == Player or Shot.Character == Character)
        then
            local ShotTime = tonumber(Shot.Time) or 0
            if math.abs(ShotTime - PrimaryTime) <= AttackConfirmationState.MergeWindow
                and CurrentTime - ShotTime <= AttackConfirmationState.DamageWindow
            then
                Shot.DamageConfirmed = true
                Shot.ConfirmedAt = CurrentTime
                Shot.MergedDamageConfirmation = true
                Confirmed += 1
            end
        end
    end

    return Confirmed
end

local function GetHitFeedbackGuiParent()
    local CurrentPlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:FindFirstChild("PlayerGui") or PlayerGui
    if CurrentPlayerGui and CurrentPlayerGui.Parent then return CurrentPlayerGui end
    if type(gethui) == "function" then
        local Success, HiddenUi = AtramentaCallChecked(gethui)
        if Success and HiddenUi then return HiddenUi end
    end
    return nil
end

function GetBulletTracerWeaponData(Tool)
    if not Tool or not Tool:IsA("Tool") then return nil end

    local Cached = HitFeedbackRuntimeState.BulletTracerWeaponCache[Tool]
    if Cached and Cached.Tool == Tool and Tool.Parent then return Cached end

    local Values = Tool:FindFirstChild("Values")
    local AmmoValue = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    local StoredAmmo = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo"))
    local HasAmmo = AmmoValue and (AmmoValue:IsA("IntValue") or AmmoValue:IsA("NumberValue"))
    local HasStoredAmmo = StoredAmmo and (StoredAmmo:IsA("IntValue") or StoredAmmo:IsA("NumberValue"))

    if not HasAmmo then
        for _, Object in ipairs(Tool:GetDescendants()) do
            if (Object.Name == "Ammo" or Object.Name == "SERVER_Ammo") and (Object:IsA("IntValue") or Object:IsA("NumberValue")) then
                AmmoValue = Object
                HasAmmo = true
                break
            end
        end
    end

    local Config = nil
    local ConfigModule = Tool:FindFirstChild("Config", true)

    if ConfigModule and ConfigModule:IsA("ModuleScript") then
        local Success, Result = AtramentaCallChecked(require, ConfigModule)
        if Success and type(Result) == "table" then Config = Result end
    end

    if not Config then
        for _, Object in ipairs(Tool:GetDescendants()) do
            if Object:IsA("ModuleScript") and (Object.Name == "WeaponConfig" or Object.Name == "GunConfig") then
                local Success, Result = AtramentaCallChecked(require, Object)
                if Success and type(Result) == "table" then
                    Config = Result
                    break
                end
            end
        end
    end

    local MagSize = Config and tonumber(rawget(Config, "MagSize")) or nil
    local FireRate = Config and tonumber(rawget(Config, "FireRate")) or nil
    local Spread = Config and tonumber(rawget(Config, "Spread")) or nil
    local Recoil = Config and tonumber(rawget(Config, "Recoil")) or nil
    local Damage = Config and tonumber(rawget(Config, "Damage")) or nil
    local Range = Config and tonumber(rawget(Config, "Range")) or nil
    local BulletsPerShot = Config and tonumber(rawget(Config, "BulletsPerShot")) or nil
    local HasGunScript = Tool:FindFirstChild("Client", true) ~= nil
        or Tool:FindFirstChildWhichIsA("LocalScript", true) ~= nil
        or Tool:FindFirstChildWhichIsA("ModuleScript", true) ~= nil

    local HasHitmarker = Tool:FindFirstChild("Hitmarker", true) ~= nil

    local ConfigFirearm = MagSize and MagSize > 0
        and FireRate and FireRate > 0
        and (Spread ~= nil or Recoil ~= nil)
        and (HasAmmo or HasGunScript or HasHitmarker)

    local LegacyFirearm = HasAmmo and (HasStoredAmmo or HasGunScript or HasHitmarker)
    if not ConfigFirearm and not LegacyFirearm then return nil end

    local Data = {
        Tool = Tool,
        Config = Config,
        Ammo = AmmoValue,
        StoredAmmo = StoredAmmo,
        MagSize = MagSize,
        FireRate = FireRate,
        Spread = Spread,
        Recoil = Recoil,
        Damage = Damage,
        Range = Range,
        BulletsPerShot = BulletsPerShot,
        HasConfigSignature = ConfigFirearm == true
    }

    HitFeedbackRuntimeState.BulletTracerWeaponCache[Tool] = Data
    return Data
end

local function IsBulletTracerWeapon(Tool)
    return GetBulletTracerWeaponData(Tool) ~= nil
end

IsVerifiedLocalFirearmTool = function(Tool)
    local Character = LocalPlayer.Character
    if Tool == nil or not Tool:IsA("Tool") or Character == nil or Tool.Parent ~= Character then return false end
    if IsBulletTracerWeapon(Tool) then return true end
    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    return Ammo ~= nil or Tool:FindFirstChild("Hitmarker", true) ~= nil
end

local function IsLocalGunShotRemote(Remote)
    return typeof(Remote) == "Instance" and Remote:IsA("RemoteEvent") and Remote.Name == "GNX_S" and Remote:IsDescendantOf(ReplicatedStorage)
end

local function GetBulletTracerMuzzle(Tool)
    local Cached = HitFeedbackRuntimeState.BulletTracerMuzzleCache[Tool]
    if Cached and Cached.Parent and Cached:IsDescendantOf(Tool) then return Cached end
    local BestObject = nil
    local BestScore = -math.huge
    for Unused, Object in ipairs(Tool:GetDescendants()) do
        if Object:IsA("Attachment") or Object:IsA("BasePart") then
            local Name = string.lower(Object.Name)
            local Score = 0
            if string.find(Name, "muzzle", 1, true) then Score = Score + 100 end
            if string.find(Name, "firepoint", 1, true) or string.find(Name, "fire_point", 1, true) then Score = Score + 85 end
            if string.find(Name, "barrel", 1, true) then Score = Score + 65 end
            if string.find(Name, "tip", 1, true) then Score = Score + 45 end
            if Object:IsA("Attachment") then Score = Score + 15 end
            if Object.Name == "Handle" then Score = math.max(Score, 10) end
            if Score > BestScore then
                BestScore = Score
                BestObject = Object
            end
        end
    end
    HitFeedbackRuntimeState.BulletTracerMuzzleCache[Tool] = BestObject
    return BestObject
end

local function GetBulletTracerOrigin(Tool)
    local Muzzle = GetBulletTracerMuzzle(Tool)
    if Muzzle then
        if Muzzle:IsA("Attachment") then return Muzzle.WorldPosition end
        if Muzzle:IsA("BasePart") then return Muzzle.Position end
    end
    local CameraObject = GetCamera()
    if CameraObject then return CameraObject.CFrame.Position end
    local Character = LocalPlayer.Character
    local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    return RootPart and RootPart.Position or nil
end

local function GetBulletTracerVisualOrigin(Tool, PacketOrigin)
    local MuzzleOrigin =
        Tool
        and GetBulletTracerOrigin(Tool)
        or nil

    if typeof(MuzzleOrigin) == "Vector3" then
        return MuzzleOrigin
    end

    if typeof(PacketOrigin) == "Vector3" then
        return PacketOrigin
    end

    local CameraObject = GetCamera()

    if CameraObject then
        return CameraObject.CFrame.Position
    end

    local Character =
        LocalPlayer.Character

    local RootPart =
        Character
        and Character:
            FindFirstChild(
                "HumanoidRootPart"
            )

    return RootPart
        and RootPart.Position
        or nil
end

local function ShouldSpawnBulletTracerToken(Tool, ShotToken)
    local CurrentTime = os.clock()

    if ShotToken == nil then
        return ShouldSpawnBulletTracer(
            Tool,
            0.018
        )
    end

    local Key = tostring(ShotToken)
    local Previous =
        HitFeedbackRuntimeState.
            BulletTracerTokenCache[Key]
        or 0

    if CurrentTime - Previous < 0.55 then
        return false
    end

    HitFeedbackRuntimeState.
        BulletTracerTokenCache[Key] =
        CurrentTime

    task.delay(
        1.5,
        function()
            local Cache =
                HitFeedbackRuntimeState.
                    BulletTracerTokenCache

            if Cache
                and Cache[Key] == CurrentTime
            then
                Cache[Key] = nil
            end
        end
    )

    return true
end

local function ResolveBulletTracerExactTarget(
    Tool,
    PacketOrigin,
    Direction,
    ShotToken
)
    local Pending =
        RageBotRuntime
        and RageBotRuntime.PendingShot
        or nil

    if type(Pending) == "table"
        and ShotToken ~= nil
        and tostring(Pending.ShotId)
            == tostring(ShotToken)
        and typeof(Pending.HitPosition)
            == "Vector3"
    then
        return Pending.HitPosition
    end

    local Reported =
        RageBotAPI
        and RageBotAPI._ReportedShots
        and ShotToken ~= nil
        and RageBotAPI._ReportedShots[
            ShotToken
        ]
        or nil

    if type(Reported) == "table"
        and typeof(Reported.HitPosition)
            == "Vector3"
    then
        return Reported.HitPosition
    end

    if typeof(PacketOrigin) ~= "Vector3"
        or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude <= 0.001
    then
        return nil
    end

    return GetBulletTracerTargetFromDirection(
        PacketOrigin,
        Direction,
        Tool
    )
end

local function GetBulletTracerTarget(OriginPosition, Tool)
    if not OriginPosition then return nil end
    local AimPosition = nil
    if Mouse then
        local Success, MouseHit = AtramentaCallChecked(function() return Mouse.Hit end)
        if Success and MouseHit then AimPosition = MouseHit.Position end
    end
    local CameraObject = GetCamera()
    if not AimPosition and CameraObject then
        local MousePosition = UserInputService:GetMouseLocation()
        local Ray = CameraObject:ViewportPointToRay(MousePosition.X, MousePosition.Y)
        AimPosition = Ray.Origin + Ray.Direction * AttackConfirmationState.ShotRange
    end
    if not AimPosition then return nil end
    local Difference = AimPosition - OriginPosition
    if Difference.Magnitude < 0.1 then return nil end
    local MaximumDistance = math.min(Difference.Magnitude, AttackConfirmationState.ShotRange)
    local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true
    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded
    local Result = workspace:Raycast(OriginPosition, Difference.Unit * MaximumDistance, RaycastParameters)
    return Result and Result.Position or OriginPosition + Difference.Unit * MaximumDistance
end

local function CreateBulletTracerBeam(Parent, StartAttachment, EndAttachment, Name, Width, Transparency, Color, Texture, TextureSpeed, CurveSize)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = StartAttachment
    Beam.Attachment1 = EndAttachment
    Beam.FaceCamera = true
    Beam.Enabled = true
    Beam.Segments = 4
    Beam.Width0 = Width
    Beam.Width1 = Width
    Beam.LightEmission = 1
    Beam.LightInfluence = 0
    Beam.Color = ColorSequence.new(Color)
    Beam.Transparency = NumberSequence.new(Transparency)
    Beam.CurveSize0 = CurveSize or 0
    Beam.CurveSize1 = - (CurveSize or 0)
    if Texture then
        Beam.Texture = Texture
        Beam.TextureMode = Enum.TextureMode.Wrap
        Beam.TextureLength = 1.1
        Beam.TextureSpeed = TextureSpeed or 0
    end
    Beam.Parent = Parent
    return Beam
end

local function SpawnBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
    if not HitFeedbackState.BulletTracerEnabled or not OriginPosition or not TargetPosition then return end
    if not IsVerifiedLocalFirearmTool(Tool) then return end
    local Distance = (TargetPosition - OriginPosition).Magnitude
    if Distance < 0.5 then return end
    if HitFeedbackRuntimeState.ActiveBulletTracers >= 12 then return end
    local Terrain = workspace:FindFirstChildOfClass("Terrain")
    if not Terrain then return end
    HitFeedbackRuntimeState.ActiveBulletTracers = HitFeedbackRuntimeState.ActiveBulletTracers + 1
    HitFeedbackRuntimeState.BulletTracerSerial = HitFeedbackRuntimeState.BulletTracerSerial + 1
    local Serial = HitFeedbackRuntimeState.BulletTracerSerial
    local StartAttachment = Instance.new("Attachment")
    StartAttachment.Name = "AtramentaBulletTracerStart" .. Serial
    StartAttachment.Parent = Terrain
    StartAttachment.WorldPosition = OriginPosition
    local EndAttachment = Instance.new("Attachment")
    EndAttachment.Name = "AtramentaBulletTracerEnd" .. Serial
    EndAttachment.Parent = Terrain
    EndAttachment.WorldPosition = TargetPosition
    HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = true
    HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = true
    local Color = HitFeedbackState.BulletTracerColor
    local Duration = math.clamp(tonumber(HitFeedbackState.BulletTracerTime) or 0.32, 0.05, 2)
    local Width = math.clamp(tonumber(HitFeedbackState.BulletTracerWidth) or 0.10, 0.01, 0.5)
    local Glow = math.clamp(tonumber(HitFeedbackState.BulletTracerGlow) or 2, 0, 5)
    local Rate = math.clamp(tonumber(HitFeedbackState.BulletTracerRate) or 18, 0, 40)
    local Style = HitFeedbackState.BulletTracerStyle
    local CoreBeam = CreateBulletTracerBeam(StartAttachment, StartAttachment, EndAttachment, "Core", Width, 0.02, Color, Style == "Energy" and
        "rbxasset://textures/particles/sparkles_main.dds" or nil, Style == "Energy" and 7 or 0, Style == "Pulse" and math.min(Distance * 0.018, 4) or 0)
    local GlowBeam = nil
    if Glow > 0 then
        GlowBeam = CreateBulletTracerBeam(StartAttachment, StartAttachment, EndAttachment, "Glow", Width * (1.8 + Glow * 0.45), math.clamp(0.58 - Glow * 0.035, 0.30, 0.65), Color, nil, 0,
            Style == "Pulse" and -math.min(Distance * 0.012, 2.5) or 0)
    end
    local PulseBeam = nil
    if Style == "Pulse" then PulseBeam = CreateBulletTracerBeam(StartAttachment, StartAttachment, EndAttachment, "Pulse", Width * 0.42, 0.12, Color3.new(1, 1, 1), nil, 0, 0) end
    local ImpactEmitter = Instance.new("ParticleEmitter")
    ImpactEmitter.Name = "ImpactVfx"
    ImpactEmitter.Enabled = Rate > 0 and SuppressImpact ~= true
    ImpactEmitter.Rate = Rate
    ImpactEmitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
    ImpactEmitter.Color = ColorSequence.new(Color)
    ImpactEmitter.LightEmission = 1
    ImpactEmitter.LightInfluence = 0
    ImpactEmitter.Lifetime = NumberRange.new(math.min(Duration * 0.45, 0.18), math.min(Duration * 0.90, 0.42))
    ImpactEmitter.Speed = NumberRange.new(1.5, 4.5)
    ImpactEmitter.Drag = 5
    ImpactEmitter.SpreadAngle = Vector2.new(180, 180)
    ImpactEmitter.Rotation = NumberRange.new(0, 360)
    ImpactEmitter.RotSpeed = NumberRange.new(-180, 180)
    ImpactEmitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, Width * 3.5), NumberSequenceKeypoint.new(1, 0) })
    ImpactEmitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1) })
    ImpactEmitter.Parent = EndAttachment
    task.delay(
        Duration,
        function()
            HitFeedbackRuntimeState.ActiveObjects[
                StartAttachment
            ] = nil

            HitFeedbackRuntimeState.ActiveObjects[
                EndAttachment
            ] = nil

            if StartAttachment.Parent then
                StartAttachment:
                    Destroy()
            end

            if EndAttachment.Parent then
                EndAttachment:
                    Destroy()
            end

            HitFeedbackRuntimeState.ActiveBulletTracers =
                math.max(
                    HitFeedbackRuntimeState.ActiveBulletTracers
                        - 1,
                    0
                )
        end
    )
end

local function SpawnDirectionalBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
    if not HitFeedbackState.BulletTracerEnabled or not OriginPosition or not TargetPosition then return end
    if not IsVerifiedLocalFirearmTool(Tool) then return end
    SpawnBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
end

local function SpawnRageRouteTracer(
    Shot,
    VisualOrigin,
    TargetPosition,
    Tool
)
    if type(Shot) == "table"
        and Shot.Source == "RageBot"
        and typeof(Shot.Origin)
            == "Vector3"
        and typeof(Shot.PacketDirection)
            == "Vector3"
    then
        local Distance =
            typeof(Shot.HitPosition)
                == "Vector3"
            and (
                Shot.HitPosition
                - Shot.Origin
            ).Magnitude
            or 500

        local PacketEnd =
            Shot.Origin
            + Shot.PacketDirection
                * math.min(
                    math.max(
                        Distance,
                        1
                    ),
                    500
                )

        SpawnDirectionalBulletTracer(
            Shot.Origin,
            PacketEnd,
            Tool,
            true
        )

        return
    end

    if typeof(VisualOrigin)
            == "Vector3"
        and typeof(TargetPosition)
            == "Vector3"
    then
        SpawnDirectionalBulletTracer(
            VisualOrigin,
            TargetPosition,
            Tool,
            true
        )
    end
end

HitFeedbackRuntimeState.SpawnConfirmedTracer = function(Shot, TargetPart)
    if not HitFeedbackState.BulletTracerEnabled
        or not Shot
        or Shot.TracerSpawned
    then
        return false
    end

    local Tool = Shot.Tool

    if not IsVerifiedLocalFirearmTool(Tool) then
        return false
    end

    if not TargetPart
        or not TargetPart:IsA("BasePart")
        or not TargetPart.Parent
    then
        return false
    end

    local OriginPosition =
        typeof(Shot.VisualOrigin) == "Vector3"
        and Shot.VisualOrigin
        or GetBulletTracerVisualOrigin(
            Tool,
            Shot.Origin
        )

    local TargetPosition =
        typeof(Shot.HitPosition) == "Vector3"
        and Shot.HitPosition
        or TargetPart.Position

    if typeof(OriginPosition) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
        or (
            TargetPosition - OriginPosition
        ).Magnitude < 0.5
    then
        return false
    end

    local Token =
        Shot.Token

    if Token ~= nil
        and not ShouldSpawnBulletTracerToken(
            Tool,
            Token
        )
    then
        Shot.TracerSpawned = true
        return false
    end

    Shot.TracerSpawned = true

    SpawnRageRouteTracer(
        Shot,
        OriginPosition,
        TargetPosition,
        Tool
    )

    return true
end

local function ClearBulletTracers()
    for Object in pairs(HitFeedbackRuntimeState.ActiveObjects) do
        if Object and string.find(Object.Name, "AtramentaBulletTracer", 1, true) == 1 then
            HitFeedbackRuntimeState.ActiveObjects[Object] = nil
            if Object.Parent then Object:Destroy() end
        end
    end
    HitFeedbackRuntimeState.ActiveBulletTracers = 0
    table.clear(
        HitFeedbackRuntimeState.
            BulletTracerTokenCache
    )
end

function ShouldSpawnBulletTracer(Tool, MinimumGap)
    if not IsVerifiedLocalFirearmTool(Tool) then return false end

    local CurrentTime = os.clock()
    local PreviousTime = HitFeedbackRuntimeState.BulletTracerLastSpawn[Tool] or 0
    MinimumGap = tonumber(MinimumGap) or 0.025

    if CurrentTime - PreviousTime < MinimumGap then return false end
    HitFeedbackRuntimeState.BulletTracerLastSpawn[Tool] = CurrentTime
    return true
end

function GetBulletTracerTargetFromDirection(OriginPosition, Direction, Tool)
    if typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 0.01 then return nil end

    local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true

    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded

    local DirectionMagnitude = Direction.Magnitude
    local Distance = DirectionMagnitude > 5 and math.min(DirectionMagnitude, AttackConfirmationState.ShotRange) or AttackConfirmationState.ShotRange
    local Result = workspace:Raycast(OriginPosition, Direction.Unit * Distance, RaycastParameters)
    return Result and Result.Position or OriginPosition + Direction.Unit * Distance
end

function FindBulletTracerVectorInTable(Value, Depth)
    if type(Value) ~= "table" or (Depth or 0) > 2 then return nil end

    for _, NestedValue in pairs(Value) do
        if typeof(NestedValue) == "Vector3" and NestedValue.Magnitude > 0.001 then
            return NestedValue
        end

        if type(NestedValue) == "table" then
            local Found = FindBulletTracerVectorInTable(NestedValue, (Depth or 0) + 1)
            if Found then return Found end
        end
    end

    return nil
end

function ParseBulletTracerRemoteArguments(...)
    local Arguments = table.pack(...)
    local MarkerIndex = nil

    for Index = 1, Arguments.n do
        if Arguments[Index] == "FDS9I83" then
            MarkerIndex = Index
            break
        end
    end

    if not MarkerIndex then return nil end

    local Tool = nil
    local OriginPosition = nil
    local Direction = nil
    local ShotToken = MarkerIndex >= 3 and Arguments[MarkerIndex - 2] or nil

    for Index = 1, Arguments.n do
        local Value = Arguments[Index]
        if not Tool and typeof(Value) == "Instance" and Value:IsA("Tool") then Tool = Value end
    end

    for Index = MarkerIndex + 1, Arguments.n do
        local Value = Arguments[Index]
        if not OriginPosition and typeof(Value) == "Vector3" then
            OriginPosition = Value
        elseif not Direction and type(Value) == "table" then
            Direction = FindBulletTracerVectorInTable(Value, 0)
        elseif OriginPosition and not Direction and typeof(Value) == "Vector3" then
            Direction = Value
        end
    end

    if not Tool then Tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool") end
    if Tool and not OriginPosition then OriginPosition = GetBulletTracerOrigin(Tool) end
    return Tool, OriginPosition, Direction, ShotToken
end

function ResolveCapturedShotTarget(OriginPosition, Direction, Tool)
    if typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 0.01 then return nil, nil end
    local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true
    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded
    local DirectionMagnitude = Direction.Magnitude
    local Distance = DirectionMagnitude > 5 and math.min(DirectionMagnitude, AttackConfirmationState.ShotRange) or AttackConfirmationState.ShotRange
    local Result = workspace:Raycast(OriginPosition, Direction.Unit * Distance, RaycastParameters)
    if not Result then return nil, nil end
    local Character = GetHumanoidCharacterFromPart(Result.Instance)
    if not Character then return nil, nil end
    return Character, Result.Instance
end

function QueueBulletTracerRemotePacket(Tool, ShotToken, OriginPosition, Direction, Shot)
    if not Tool or not Tool:IsA("Tool") or ShotToken == nil then return nil end

    local Queue = HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool]
    if type(Queue) ~= "table" then
        Queue = {}
        HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool] = Queue
    end

    local CurrentTime = os.clock()

    for Index = #Queue, 1, -1 do
        local Packet = Queue[Index]
        if type(Packet) ~= "table" or CurrentTime - (tonumber(Packet.Time) or 0) > 0.65 then
            table.remove(Queue, Index)
        elseif tostring(Packet.Token) == tostring(ShotToken) then
            Packet.Time = CurrentTime
            Packet.Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or Packet.Origin
            Packet.Direction = typeof(Direction) == "Vector3" and Direction or Packet.Direction
            Packet.Shot = type(Shot) == "table" and Shot or Packet.Shot
            return Packet
        end
    end

    local Packet = {
        Time = CurrentTime,
        Token = ShotToken,
        Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or nil,
        Direction = typeof(Direction) == "Vector3" and Direction or nil,
        Shot = type(Shot) == "table" and Shot or nil
    }

    Queue[#Queue + 1] = Packet
    while #Queue > 12 do table.remove(Queue, 1) end
    return Packet
end

function TakeBulletTracerRemotePacket(Tool, MaximumAge)
    local Queue = Tool and HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool]
    if type(Queue) ~= "table" then return nil end

    local CurrentTime = os.clock()
    MaximumAge = tonumber(MaximumAge) or 0.45

    while #Queue > 0 do
        local Packet = table.remove(Queue, 1)
        if type(Packet) == "table"
            and CurrentTime - (tonumber(Packet.Time) or 0) <= MaximumAge
        then
            return Packet
        end
    end

    HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool] = nil
    return nil
end

function SpawnConfirmedRemoteBulletTracer(Tool, Packet)
    if not HitFeedbackState.BulletTracerEnabled
        or type(Packet) ~= "table"
        or not IsVerifiedLocalFirearmTool(Tool)
    then
        return false
    end

    local Shot = Packet.Shot
    local OriginPosition = Packet.Origin
    local Direction = Packet.Direction
    local ShotToken = Packet.Token

    if typeof(OriginPosition) ~= "Vector3"
        or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude < 0.01
        or ShotToken == nil
    then
        return false
    end

    if type(Shot) == "table" and Shot.TracerSpawned then
        Shot.AmmoConfirmed = true
        return true
    end

    if not ShouldSpawnBulletTracerToken(Tool, ShotToken) then
        return false
    end

    local VisualOrigin =
        type(Shot) == "table"
        and typeof(Shot.VisualOrigin) == "Vector3"
        and Shot.VisualOrigin
        or GetBulletTracerVisualOrigin(Tool, OriginPosition)

    local TargetPosition =
        type(Shot) == "table"
        and typeof(Shot.HitPosition) == "Vector3"
        and Shot.HitPosition
        or ResolveBulletTracerExactTarget(
            Tool,
            OriginPosition,
            Direction,
            ShotToken
        )

    if typeof(VisualOrigin) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
        or (TargetPosition - VisualOrigin).Magnitude < 0.5
    then
        return false
    end

    if type(Shot) == "table" then
        Shot.TracerSpawned = true
        Shot.AmmoConfirmed = true
    end

    SpawnRageRouteTracer(
        Shot,
        VisualOrigin,
        TargetPosition,
        Tool
    )

    return true
end

function DispatchBulletTracerRemoteShot(Remote, ...)
    if not IsLocalGunShotRemote(Remote) then return false end

    local Tool, OriginPosition, Direction, ShotToken =
        ParseBulletTracerRemoteArguments(...)

    if not IsVerifiedLocalFirearmTool(Tool)
        or ShotToken == nil
        or typeof(OriginPosition) ~= "Vector3"
        or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude < 0.01
    then
        return false
    end

    local CurrentTime = os.clock()
    HitFeedbackRuntimeState.BulletTracerLastRemoteShot[Tool] = CurrentTime

    local ReportedShots = RageBotAPI and RageBotAPI._ReportedShots
    local Shot =
        type(ReportedShots) == "table"
        and ReportedShots[ShotToken]
        or nil

    if type(Shot) ~= "table" then
        local TargetCharacter, TargetPart =
            ResolveCapturedShotTarget(
                OriginPosition,
                Direction,
                Tool
            )

        Shot = RegisterLocalAttack(
            TargetCharacter,
            TargetPart,
            ShotToken,
            Tool,
            "Remote",
            OriginPosition,
            Direction
        )
    end

    if not Shot then return false end
    Shot.SignalConfirmed = true
    Shot.RemoteConfirmedAt = CurrentTime

    if typeof(Shot.VisualOrigin) ~= "Vector3" then
        Shot.VisualOrigin =
            GetBulletTracerVisualOrigin(
                Tool,
                OriginPosition
            )
    end

    if typeof(Shot.HitPosition) ~= "Vector3" then
        Shot.HitPosition =
            ResolveBulletTracerExactTarget(
                Tool,
                OriginPosition,
                Direction,
                ShotToken
            )
    end

    QueueBulletTracerRemotePacket(
        Tool,
        ShotToken,
        OriginPosition,
        Direction,
        Shot
    )

    local LastAmmoDecrease =
        HitFeedbackRuntimeState.BulletTracerLastAmmoDecrease[Tool]
        or 0

    if CurrentTime - LastAmmoDecrease <= 0.085 then
        local Packet =
            TakeBulletTracerRemotePacket(
                Tool,
                0.12
            )

        if Packet then
            SpawnConfirmedRemoteBulletTracer(
                Tool,
                Packet
            )
        end
    end

    return true
end

function HasBulletTracerShootConstant(FunctionObject)
    if type(FunctionObject) ~= "function" then return false end

    if type(isourclosure) == "function" then
        local Success, IsOurs = AtramentaCallChecked(isourclosure, FunctionObject)
        if Success and IsOurs then return false end
    elseif type(isexecutorclosure) == "function" then
        local Success, IsOurs = AtramentaCallChecked(isexecutorclosure, FunctionObject)
        if Success and IsOurs then return false end
    end

    local Reader = type(getconstants) == "function" and getconstants or type(debug) == "table" and debug.getconstants
    if type(Reader) ~= "function" then return false end

    local Success, Constants = AtramentaCallChecked(Reader, FunctionObject)
    if not Success or type(Constants) ~= "table" then return false end

    for _, Constant in pairs(Constants) do
        if Constant == "FDS9I83" then return true end
    end

    return false
end

function HookBulletTracerShootFunction(FunctionObject, State)
    if not HasBulletTracerShootConstant(FunctionObject) then return false end
    if type(hookfunction) ~= "function" then return false end
    if State.ShootHooks[FunctionObject] then return false end

    local OriginalFunction

    local Success, Message = AtramentaCallChecked(function()
        OriginalFunction = hookfunction(FunctionObject, function(...)
            local Arguments = table.pack(...)
            local StartedAt = os.clock()
            local Results = table.pack(OriginalFunction(table.unpack(Arguments, 1, Arguments.n)))


            return table.unpack(Results, 1, Results.n)
        end)
    end)

    if not Success or not OriginalFunction then
        return false
    end

    State.ShootHooks[FunctionObject] = OriginalFunction
    return true
end

function ScanBulletTracerShootFunctions(State)
    if not State.Enabled or State.ScanningFunctions then return end

    State.ScanningFunctions = true

    AtramentaScanGarbage(false, function(Object)
        if type(Object) == "function" then HookBulletTracerShootFunction(Object, State) end
    end, 192)

    State.ScanningFunctions = false
    AtramentaStepGC(16)
end

function InstallBulletTracerFireServerHook(State)
    if State.FireServerVersion >= 1 or type(hookfunction) ~= "function" then return State.FireServerVersion >= 1 end

    local TemporaryRemote = Instance.new("RemoteEvent")
    local FireServerMethod = TemporaryRemote.FireServer
    TemporaryRemote:Destroy()

    local OldFireServer
    local Success = AtramentaCallChecked(function()
        OldFireServer = hookfunction(FireServerMethod, function(Self, ...)
            local Arguments = table.pack(...)
            local Results = table.pack(OldFireServer(Self, table.unpack(Arguments, 1, Arguments.n)))

            if State.Enabled then
                task.defer(DispatchBulletTracerRemoteShot, Self, table.unpack(Arguments, 1, Arguments.n))
            end

            return table.unpack(Results, 1, Results.n)
        end)
    end)

    if Success and OldFireServer then
        State.FireServerVersion = 1
        return true
    end

    return false
end

function InstallBulletTracerShotHook()
    local Environment = getgenv()
    local State = rawget(Environment, "AtramentaBulletTracerShotHook")

    if type(State) ~= "table" or State.TrackerVersion ~= 11 then
        if type(State) == "table" then State.Enabled = false end
        State = {}
        rawset(Environment, "AtramentaBulletTracerShotHook", State)
    end

    State.TrackerVersion = 11
    State.FireServerVersion = tonumber(State.FireServerVersion) or 0
    State.Enabled = IsShotTrackingEnabled()
    State.ShootHooks = setmetatable({}, { __mode = "k" })
    State.ScanningFunctions = false

    local FireServerInstalled = InstallBulletTracerFireServerHook(State)
    if type(InstallAtramentaSharedNamecallRouter) == "function" then InstallAtramentaSharedNamecallRouter() end
    return FireServerInstalled or true
end


function RefreshLocalShotTracking()
    InstallBulletTracerShotHook()
    local State = getgenv().AtramentaBulletTracerShotHook
    if type(State) == "table" then State.Enabled = IsShotTrackingEnabled() end
end

function SetBulletTracerShotHookEnabled(Value)
    HitFeedbackState.BulletTracerEnabled = Value == true
    RefreshLocalShotTracking()
end

local function GetBulletTracerAmmoValue(Tool)
    local Data = GetBulletTracerWeaponData(Tool)
    return Data and Data.Ammo or nil
end

local function BindBulletTracerAmmo(Tool, Connections)
    local AmmoValue = GetBulletTracerAmmoValue(Tool)

    if not AmmoValue
        or HitFeedbackRuntimeState.BulletTracerAmmoObjects[AmmoValue]
    then
        return false
    end

    HitFeedbackRuntimeState.BulletTracerAmmoObjects[AmmoValue] = true
    local PreviousValue = tonumber(AmmoValue.Value) or 0

    Connections[#Connections + 1] =
        AmmoValue.Changed:Connect(function(Value)
            local CurrentValue =
                tonumber(Value)
                or tonumber(AmmoValue.Value)
                or PreviousValue

            local Fired = CurrentValue < PreviousValue
            PreviousValue = CurrentValue

            if not Fired then return end

            HitFeedbackRuntimeState.BulletTracerLastAmmoDecrease[Tool] =
                os.clock()

            local AmmoConfirmedAt =
                os.clock()

            for Index =
                #AttackConfirmationState.Shots,
                1,
                -1
            do
                local Shot =
                    AttackConfirmationState.Shots[
                        Index
                    ]

                if Shot
                    and Shot.Tool == Tool
                    and not Shot.AmmoConfirmed
                    and AmmoConfirmedAt
                        - (Shot.Time or 0)
                        <= 0.55
                then
                    Shot.AmmoConfirmed = true
                    break
                end
            end

            local Packet =
                TakeBulletTracerRemotePacket(
                    Tool,
                    0.50
                )

            if Packet then
                SpawnConfirmedRemoteBulletTracer(
                    Tool,
                    Packet
                )
            end
        end)

    return true
end

local function GetConfirmedHitmarkerParent()
    local Holder = Library and Library.Holder
    local HolderInstance = Holder and (Holder.Instance or Holder)
    if typeof(HolderInstance) == "Instance" and HolderInstance:IsA("ScreenGui") and HolderInstance.Parent then
        return HolderInstance
    end

    local Existing = HitFeedbackRuntimeState.HitmarkerGui
    if Existing and Existing.Parent then return Existing end

    local Parent = GetHitFeedbackGuiParent()
    if not Parent then return nil end

    local Gui = Instance.new("ScreenGui")
    Gui.Name = "AtramentaConfirmedHitmarkerGui"
    Gui.IgnoreGuiInset = true
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 99999
    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    Gui.Parent = Parent
    HitFeedbackRuntimeState.HitmarkerGui = Gui
    HitFeedbackRuntimeState.ActiveObjects[Gui] = true
    return Gui
end

local function SpawnConfirmedHitmarker(IsHeadshot)
    if not HitFeedbackState.HitmarkerEnabled then return end
    local Parent = GetConfirmedHitmarkerParent()
    if not Parent then return end

    local Size = math.clamp(tonumber(HitFeedbackState.HitmarkerSize) or 28, 12, 60)
    local Duration = math.clamp(tonumber(HitFeedbackState.HitmarkerDuration) or 0.24, 0.08, 1)
    local Color = IsHeadshot and HitFeedbackState.HeadshotHitmarkerColor or HitFeedbackState.HitmarkerColor

    local Holder = Instance.new("Frame")
    Holder.Name = "AtramentaConfirmedHitmarker"
    Holder.AnchorPoint = Vector2.new(0.5, 0.5)
    Holder.Position = UDim2.fromScale(0.5, 0.5)
    Holder.Size = UDim2.fromOffset(Size * 2, Size * 2)
    Holder.BackgroundTransparency = 1
    Holder.BorderSizePixel = 0
    Holder.ZIndex = 10000
    Holder.Parent = Parent
    HitFeedbackRuntimeState.ActiveObjects[Holder] = true

    local Scale = Instance.new("UIScale")
    Scale.Scale = 0.68
    Scale.Parent = Holder

    local Thickness = math.max(math.floor(Size * 0.11 + 0.5), 2)
    local ArmLength = math.max(math.floor(Size * 0.48 + 0.5), 7)
    local Gap = math.max(math.floor(Size * 0.16 + 0.5), 3)

    local function CreateArm(Rotation, X, Y)
        local Arm = Instance.new("Frame")
        Arm.Name = "Arm"
        Arm.AnchorPoint = Vector2.new(0.5, 0.5)
        Arm.Position = UDim2.new(0.5, X * (Gap + ArmLength * 0.5), 0.5, Y * (Gap + ArmLength * 0.5))
        Arm.Size = UDim2.fromOffset(ArmLength, Thickness)
        Arm.Rotation = Rotation
        Arm.BackgroundColor3 = Color
        Arm.BackgroundTransparency = 0
        Arm.BorderSizePixel = 0
        Arm.ZIndex = 10001
        Arm.Parent = Holder
        return Arm
    end

    local Root = math.sqrt(0.5)
    local Arms = {
        CreateArm(45, Root, Root),
        CreateArm(45, -Root, -Root),
        CreateArm(-45, Root, -Root),
        CreateArm(-45, -Root, Root)
    }

    TweenService:Create(Scale, TweenInfo.new(math.min(Duration * 0.35, 0.10), Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    task.delay(math.min(Duration * 0.30, 0.08), function()
        if not Holder.Parent then return end
        TweenService:Create(Scale, TweenInfo.new(math.max(Duration * 0.70, 0.08), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1.16 }):Play()
        for _, Arm in ipairs(Arms) do
            TweenService:Create(Arm, TweenInfo.new(math.max(Duration * 0.70, 0.08), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 }):Play()
        end
    end)

    task.delay(Duration + 0.06, function()
        HitFeedbackRuntimeState.ActiveObjects[Holder] = nil
        if Holder.Parent then Holder:Destroy() end
    end)
end

local function PlayConfirmedHitSound()
    local SoundId = HitSounds[HitFeedbackState.HitSound]
    if type(SoundId) ~= "string" or SoundId == "" then return end

    local Sound = Instance.new("Sound")
    Sound.Name, Sound.SoundId = "AtramentaConfirmedHitSound", SoundId
    Sound.Volume = math.clamp(tonumber(HitFeedbackState.HitSoundVolume) or 1, 0, 5)
    Sound.PlaybackSpeed = math.clamp(tonumber(HitFeedbackState.HitSoundPlaybackSpeed) or 1, 0.5, 2)
    Sound.Parent = SoundService
    HitFeedbackRuntimeState.ActiveObjects[Sound] = true

    local Finished, EndedConnection = false, nil
    local function DestroySound()
        if Finished then return end
        Finished = true
        if EndedConnection then EndedConnection:Disconnect(); EndedConnection = nil end
        HitFeedbackRuntimeState.ActiveObjects[Sound] = nil
        if Sound.Parent then Sound:Destroy() end
    end

    EndedConnection = Sound.Ended:Connect(DestroySound)
    Sound:Play()
    task.delay(6, DestroySound)
end

local function SpawnDamageIndicator(TargetPart, Damage, IsHeadshot)
    if not HitFeedbackState.DamageIndicatorEnabled or not TargetPart or not TargetPart.Parent or not TargetPart:IsA("BasePart") or Damage <= 0 then return end
    local Parent = GetHitFeedbackGuiParent()
    if not Parent then return end
    local Anchor = Instance.new("Part")
    Anchor.Name = "AtramentaDamageAnchor"
    Anchor.Size = Vector3.new(0.05, 0.05, 0.05)
    Anchor.Transparency = 1
    Anchor.Anchored = true
    Anchor.CanCollide = false
    Anchor.CanTouch = false
    AtramentaCallChecked(function() Anchor.CanQuery = false end)
    Anchor.CFrame = CFrame.new(TargetPart.Position)
    Anchor.Parent = workspace
    HitFeedbackRuntimeState.ActiveObjects[Anchor] = true
    local Billboard = Instance.new("BillboardGui")
    Billboard.Name = "AtramentaDamageIndicator"
    Billboard.Adornee = Anchor
    Billboard.AlwaysOnTop = true
    Billboard.Enabled = true
    Billboard.Size = UDim2.fromOffset(150, 52)
    Billboard.StudsOffsetWorldSpace = Vector3.new(math.random(-35, 35) / 100, 2.1, math.random(-12, 12) / 100)
    Billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global
    AtramentaCallChecked(function()
        Billboard.MaxDistance = AttackConfirmationState.ShotRange
        Billboard.LightInfluence = 0
    end)
    Billboard.Parent = Parent
    HitFeedbackRuntimeState.ActiveObjects[Billboard] = true
    local Label = Instance.new("TextLabel")
    Label.Name = "Damage"
    Label.AnchorPoint = Vector2.new(0.5, 0.5)
    Label.Position = UDim2.fromScale(0.5, 0.5)
    Label.Size = UDim2.fromScale(1, 1)
    Label.BackgroundTransparency = 1
    Label.BorderSizePixel = 0
    Label.FontFace = UiFont
    Label.Text = tostring(math.max(math.floor(Damage + 0.5), 1))
    Label.TextSize = math.max(tonumber(HitFeedbackState.DamageTextSize) or 18, 10)
    Label.TextColor3 = IsHeadshot and HitFeedbackState.HeadshotDamageColor or HitFeedbackState.DamageColor
    Label.TextStrokeColor3 = Color3.new(0, 0, 0)
    Label.TextStrokeTransparency = 0.05
    Label.TextTransparency = 0
    Label.TextWrapped = false
    Label.ZIndex = 1002
    Label.Parent = Billboard
    local Scale = Instance.new("UIScale")
    Scale.Scale = 0.82
    Scale.Parent = Label
    local Duration = math.max(tonumber(HitFeedbackState.DamageDuration) or 0.85, 0.20)
    local Rise = math.max(tonumber(HitFeedbackState.DamageRise) or 2.8, 0)
    TweenService:Create(Scale, TweenInfo.new(math.min(Duration * 0.35, 0.18), Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    TweenService:Create(Anchor, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Position = Anchor.Position + Vector3.new(0, Rise, 0) }):Play()
    task.delay(math.min(0.12, Duration * 0.20), function()
        if not Label.Parent then return end
        TweenService:Create(Label, TweenInfo.new(math.max(Duration * 0.80, 0.12), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 1, TextStrokeTransparency = 1 })
            :Play()
    end)
    task.delay(Duration + 0.12, function()
        HitFeedbackRuntimeState.ActiveObjects[Billboard] = nil
        HitFeedbackRuntimeState.ActiveObjects[Anchor] = nil
        if Billboard.Parent then Billboard:Destroy() end
        if Anchor.Parent then Anchor:Destroy() end
    end)
end


