function SafeLocationController.IsEnabled(Self, Name)
    local Location = Self.Locations[Name]
    return Location and Location.Enabled or false
end

function SafeLocationController.SetEnabled(Self, Name, State)
    local Location = Self.Locations[Name]
    if not Location then return end
    State = State == true
    if Location.Enabled == State then return end
    Location.Enabled = State
    if Location.Connection then
        Location.Connection:Disconnect()
        Location.Connection = nil
    end
    if not State then return end
    Location.Connection = RunService.RenderStepped:Connect(function()
        if not Location.Enabled then return end
        local Character = LocalPlayer.Character
        if not Character then return end
        local RootPart = Character:FindFirstChild("HumanoidRootPart")
        local Humanoid = Character:FindFirstChildOfClass("Humanoid")
        if Humanoid and Humanoid.Health <= 0 then
            if AutoRespawnEnabled and type(RequestCharacterRespawn) == "function" then RequestCharacterRespawn() end
            return
        end
        if RootPart then RootPart.CFrame = CFrame.new(Location.Position) end
    end)
end

function SafeLocationController.DisableAll(Self)
    for Name in pairs(Self.Locations) do Self:SetEnabled(Name, false) end
end

local function GetDrawingTextFont()
    if Drawing and Drawing.Fonts then
        if Drawing.Fonts.UI ~= nil then return Drawing.Fonts.UI end
        if Drawing.Fonts.System ~= nil then return Drawing.Fonts.System end
        if Drawing.Fonts.Plex ~= nil then return Drawing.Fonts.Plex end
    end
    return 0
end

local function CreateDrawing(DrawingType, Properties)
    if not Drawing then return nil end
    local Constructor = Drawing.new or Drawing.New
    if type(Constructor) ~= "function" then return nil end
    local Success, Object = AtramentaCallChecked(Constructor, DrawingType)
    if not Success or not Object then
        Success, Object = AtramentaCallChecked(function() return Constructor(Drawing, DrawingType) end)
    end
    if not Success or not Object then return nil end
    for Property, Value in pairs(Properties or {}) do
        AtramentaCallChecked(function() Object[Property] = Value end)
    end
    return Object
end

local function RemoveDrawing(Object)
    if not Object then return end
    AtramentaCallChecked(function()
        Object.Visible = false
        Object:Remove()
    end)
end

local function DisconnectVisualConnection(Connection)
    if Connection then
        AtramentaCallChecked(function() Connection:Disconnect() end)
    end
end

local function RefreshPlayerCharacter(Data, Character)
    if Data.Player then Character = ResolveTrackedCharacter(Data.Player, Character) or Character end
    Data.Character = Character
    Data.Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") or nil
    Data.Root = Character and(Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")) or nil
    Data.Head = Character and Character:FindFirstChild("Head") or nil
    Data.ToolName = nil
    Data.NextToolScan = 0
    Data.LevelValue = nil
    Data.NextLevelScan = 0
    if type(Data.Chams) == "table" then
        for _, Entry in pairs(Data.Chams) do
            if typeof(Entry) == "Instance" then
                if Entry.Parent then
                    Entry:Destroy()
                end
            elseif type(Entry) == "table" then
                for _, Object in pairs(Entry) do
                    if typeof(Object) == "Instance"
                        and Object.Parent
                    then
                        Object:Destroy()
                    end
                end
            end
        end
    end

    if type(Data.ChamConnections) == "table" then
        for _, Connection in pairs(Data.ChamConnections) do
            if Connection
                and typeof(Connection)
                    == "RBXScriptConnection"
            then
                Connection:Disconnect()
            end
        end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Parent then
        Data.ChamsGlow:Destroy()
    end

    if Data.ChamsHolder and Data.ChamsHolder.Parent then
        Data.ChamsHolder:Destroy()
    end

    Data.Chams = {}
    Data.ChamConnections = {}
    Data.ChamsHolder = nil
    Data.ChamsGlow = nil
    Data.ChamsCharacter = nil

    if VisualState.Player.Chams.Enabled then
        task.defer(function()
            if Data.Character == Character then
                ApplyPlayerChamData(Data)
            end
        end)
    end
end

function GetPlayerESPPreviewOffset(Name)
    if type(Name) ~= "string"
        or type(Library) ~= "table"
        or type(Library.Flags) ~= "table"
    then
        return Vector2.zero
    end

    local Value =
        Library.Flags[
            "Player ESP "
            .. Name
            .. " Offset"
        ]

    if typeof(Value) ~= "Vector2" then
        return Vector2.zero
    end

    return Value
end

function ApplyPlayerESPPreviewOffset(
    BasePosition,
    Name
)
    if typeof(BasePosition) ~= "Vector2" then
        return BasePosition
    end

    return BasePosition
        + GetPlayerESPPreviewOffset(
            Name
        )
end

function RequestAtramentaProfileData(Url)
    if type(Url) ~= "string" or Url == "" then return nil end

    local Environment = type(getgenv) == "function" and getgenv() or _G
    local RequestFunctions = {
        Environment and Environment.request,
        Environment and Environment.http_request,
        type(syn) == "table" and syn.request or nil,
        type(http) == "table" and http.request or nil,
        type(fluxus) == "table" and fluxus.request or nil
    }

    for Index = 1, #RequestFunctions do
        local RequestFunction = RequestFunctions[Index]

        if type(RequestFunction) == "function" then
            local Success, Response = AtramentaCallChecked(
                RequestFunction,
                {
                    Url = Url,
                    Method = "GET",
                    Headers = {
                        ["Accept"] = "*/*",
                        ["User-Agent"] = "Atramenta.rip"
                    }
                }
            )

            local Body = Success and ExtractHttpBody(Response) or nil
            if type(Body) == "string" and #Body > 24 then return Body end
        end
    end

    local Success, Body = AtramentaCallChecked(function()
        return game:HttpGet(Url, true)
    end)

    if Success and type(Body) == "string" and #Body > 24 then return Body end
    return nil
end

function FetchAtramentaProfilePicture(UserId)
    UserId = tonumber(UserId)
    if not UserId or UserId <= 0 then return nil end

    local ApiUrl =
        "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
        .. tostring(math.floor(UserId))
        .. "&size=180x180&format=Png&isCircular=false"

    local Json = RequestAtramentaProfileData(ApiUrl)
    if type(Json) ~= "string" then return nil end

    local DecodeSuccess, Decoded = AtramentaCallChecked(function()
        return game:GetService("HttpService"):JSONDecode(Json)
    end)

    if not DecodeSuccess
        or type(Decoded) ~= "table"
        or type(Decoded.data) ~= "table"
        or type(Decoded.data[1]) ~= "table"
    then
        return nil
    end

    local ImageUrl = Decoded.data[1].imageUrl
    if type(ImageUrl) ~= "string" or ImageUrl == "" then return nil end

    local Data = RequestAtramentaProfileData(ImageUrl)
    if type(Data) ~= "string" or #Data <= 64 then return nil end
    return Data
end

function QueueAtramentaProfilePicture(Data)
    if type(Data) ~= "table" or not Data.Player then return end

    local UserId = tonumber(Data.Player.UserId)
    if not UserId or UserId <= 0 then return end

    local Cache = VisualState.Player.ProfilePictureCache
    local Entry = Cache[UserId]
    local CurrentTime = os.clock()

    if type(Entry) == "table" then
        if type(Entry.Data) == "string" and #Entry.Data > 64 then
            Data.ProfilePictureData = Entry.Data
            return
        end

        if Entry.Loading == true then return end
        if CurrentTime < (tonumber(Entry.RetryAt) or 0) then return end
    else
        Entry = {}
        Cache[UserId] = Entry
    end

    Entry.Loading = true

    task.spawn(function()
        local PictureData = FetchAtramentaProfilePicture(UserId)

        Entry.Loading = false
        Entry.Time = os.clock()

        if type(PictureData) == "string" and #PictureData > 64 then
            Entry.Data = PictureData
            Entry.RetryAt = 0

            if Data.Player and Data.Player.Parent then
                Data.ProfilePictureData = PictureData
                Data.ProfilePictureApplied = false
            end
        else
            Entry.RetryAt = os.clock() + 30
        end
    end)
end

local function CreatePlayerVisual(Player, WithDrawings)
    local Data = VisualState.Player.Objects[Player]
    if not Data then
        Data = { Player = Player, Character = nil, Humanoid = nil, Root = nil, Head = nil, ToolName = nil, NextToolScan = 0, LevelValue = nil, NextLevelScan = 0, ProfilePictureData = nil, ProfilePictureApplied = false, NextEspUpdate = 0, LastEspDistance = 0, ChamsCharacter = nil, ChamsHolder = nil, ChamsGlow = nil, Chams = {}, ChamConnections = {}, CharacterAddedConnection = nil,
            CharacterRemovingConnection = nil, Drawings = {}, DrawingsReady = false, ListIndex = 0 }
        VisualState.Player.Objects[Player] = Data
        Data.ListIndex = #VisualState.Player.List + 1
        VisualState.Player.List[Data.ListIndex] = Data
        Data.CharacterAddedConnection = Player.CharacterAdded:Connect(function(Character)
            task.spawn(function()
                local Deadline = os.clock() + 8
                local Resolved = ResolveTrackedCharacter(Player, Character)
                while Player.Parent and os.clock() < Deadline do
                    Resolved = ResolveTrackedCharacter(Player, Character)
                    if Resolved and Resolved:FindFirstChildOfClass("Humanoid") and(Resolved:FindFirstChild("HumanoidRootPart") or Resolved:FindFirstChild("Torso")) then break end
                    task.wait(0.12)
                end
                RefreshPlayerCharacter(Data, Resolved or Character)
            end)
        end)
        AtramentaCallChecked(function()
            Data.CharacterRemovingConnection = Player.CharacterRemoving:Connect(function(Character)
                if Data.Character == Character or(Data.Character and Data.Character.Name == Character.Name) then
                    task.delay(0.35, function()
                        if not Player.Parent then return end
                        local Resolved = ResolveTrackedCharacter(Player, Player.Character)
                        if Resolved and Resolved ~= Character then
                            RefreshPlayerCharacter(Data, Resolved)
                        else
                            RefreshPlayerCharacter(Data, nil)
                        end
                    end)
                end
            end)
        end)
        task.spawn(function()
            local Deadline = os.clock() + 6
            local Resolved = ResolveTrackedCharacter(Player, Player.Character)
            while Player.Parent and os.clock() < Deadline and(not Resolved or not Resolved:FindFirstChildOfClass("Humanoid")) do
                task.wait(0.15)
                Resolved = ResolveTrackedCharacter(Player, Player.Character)
            end
            RefreshPlayerCharacter(Data, Resolved or Player.Character)
        end)
    end
    if not WithDrawings or Data.DrawingsReady then return Data end
    Data.DrawingsReady = true
    local function Add(Name, DrawingType, Properties)
        local Object = CreateDrawing(DrawingType, Properties)
        Data.Drawings[Name] = Object
        return Object
    end
    Add("Fill", "Square", { Visible = false, Filled = true, Thickness = 1, Transparency = 0.18, ZIndex = 1 })
    Add("BoxOutline", "Square", { Visible = false, Filled = false, Thickness = 3, Color = Color3.new(0, 0, 0), Transparency = 0.95, ZIndex = 2 })
    Add("Box", "Square", { Visible = false, Filled = false, Thickness = 1, Transparency = 1, ZIndex = 3 })
    for Index = 1, 8 do
        Add("CornerOutline" .. Index, "Line", { Visible = false, Thickness = 3, Color = Color3.new(0, 0, 0), Transparency = 0.95, ZIndex = 2 })
        Add("Corner" .. Index, "Line", { Visible = false, Thickness = 1, Transparency = 1, ZIndex = 3 })
    end
    local DrawingFont = GetDrawingTextFont()
    Add("Name", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Forcefield", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 6 })
    Add("Weapon", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Distance", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Level", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("HealthBack", "Square", { Visible = false, Filled = true, Color = Color3.new(0, 0, 0), Transparency = 0.86, ZIndex = 3 })
    Add("Health", "Square", { Visible = false, Filled = true, Transparency = 1, ZIndex = 4 })
    Add("HealthText", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Tracer", "Line", { Visible = false, Thickness = 1, Transparency = 1, ZIndex = 2 })
    return Data
end

local function EnsureProfilePictureDrawings(Data)
    if not Data or not Data.DrawingsReady then return false end
    if Data.Drawings.ProfilePicture and Data.Drawings.ProfilePictureBack then return true end

    Data.Drawings.ProfilePictureBack = CreateDrawing("Square", {
        Visible = false,
        Filled = true,
        Color = Color3.new(0, 0, 0),
        Transparency = 0.92,
        ZIndex = 5
    })

    Data.Drawings.ProfilePicture = CreateDrawing("Image", {
        Visible = false,
        Transparency = 1,
        ZIndex = 6
    })

    return Data.Drawings.ProfilePicture ~= nil
end

local function EnsureCurvedTracerDrawings(Data)
    if Data.CurvedTracerReady then return end
    Data.CurvedTracerReady = true
    for Index = 1, 10 do Data.Drawings["TracerCurve" .. Index] = CreateDrawing("Line", { Visible = false, Thickness = 1, Transparency = 1, ZIndex = 2 }) end
end

local function HideTracerDrawings(Drawings)
    if Drawings.Tracer then Drawings.Tracer.Visible = false end
    for Index = 1, 10 do
        local Segment = Drawings["TracerCurve" .. Index]
        if Segment then Segment.Visible = false end
    end
end

local function HidePlayerVisual(Data)
    if not Data then return end
    for Unused, Object in pairs(Data.Drawings) do
        if Object then Object.Visible = false end
    end
end

local function DestroyPlayerVisual(Player)
    local Data = VisualState.Player.Objects[Player]
    if not Data then return end

    local UserId = Player and tonumber(Player.UserId) or nil
    if UserId then VisualState.Player.ProfilePictureCache[UserId] = nil end
    Data.ProfilePictureData = nil
    Data.ProfilePictureApplied = false
    DisconnectVisualConnection(Data.CharacterAddedConnection)
    DisconnectVisualConnection(Data.CharacterRemovingConnection)
    for Unused, Object in pairs(Data.Drawings) do RemoveDrawing(Object) end
    DestroyChams(Data)
    local Index = Data.ListIndex
    local Last = VisualState.Player.List[#VisualState.Player.List]
    if Index > 0 and Last then
        VisualState.Player.List[Index] = Last
        Last.ListIndex = Index
        VisualState.Player.List[#VisualState.Player.List] = nil
    end
    VisualState.Player.Objects[Player] = nil
end

local function ReconcilePlayerVisualCache()
    local ActivePlayers = {}
    for Unused, Player in ipairs(Players:GetPlayers()) do
        if Player ~= LocalPlayer then
            ActivePlayers[Player] = true
            local Data = VisualState.Player.Objects[Player]
            if not Data then Data = CreatePlayerVisual(Player, false) end
            local Resolved = ResolveTrackedCharacter(Player, Player.Character)
            if Data then
                local NeedsRefresh = false
                if Resolved and Data.Character ~= Resolved then
                    NeedsRefresh = true
                elseif not Data.Root or not Data.Root.Parent or not Data.Humanoid or not Data.Humanoid.Parent then
                    if Resolved then NeedsRefresh = true end
                end
                if NeedsRefresh then RefreshPlayerCharacter(Data, Resolved) end
            end
        end
    end
    local StalePlayers = {}
    for Player in pairs(VisualState.Player.Objects) do
        if not ActivePlayers[Player] or Player.Parent ~= Players then StalePlayers[#StalePlayers + 1] = Player end
    end
    for Unused, Player in ipairs(StalePlayers) do DestroyPlayerVisual(Player) end
end

local function EnsurePlayerCache()
    VisualState.Initialized = true
    ReconcilePlayerVisualCache()
    if not VisualState.PlayerAddedConnection then
        VisualState.PlayerAddedConnection = Players.PlayerAdded:Connect(function(Player)
            if Player ~= LocalPlayer then CreatePlayerVisual(Player, false) end
        end)
    end
    if not VisualState.PlayerRemovingConnection then
        VisualState.PlayerRemovingConnection = Players.PlayerRemoving:Connect(function(Player) DestroyPlayerVisual(Player) end)
    end
    if not VisualState.WorldCharactersBound then
        VisualState.WorldCharactersBound = true
        local function BindWorldCharactersFolder(Folder)
            if not Folder then return end
            for Unused, Character in ipairs(Folder:GetChildren()) do
                local Player = Players:FindFirstChild(Character.Name)
                if Player and Player:IsA("Player") and Player ~= LocalPlayer then
                    local Data = VisualState.Player.Objects[Player] or CreatePlayerVisual(Player, false)
                    if Data then RefreshPlayerCharacter(Data, Character) end
                end
            end
            Folder.ChildAdded:Connect(function(Character)
                local Player = Players:FindFirstChild(Character.Name)
                if Player and Player:IsA("Player") and Player ~= LocalPlayer then
                    task.defer(function()
                        local Data = VisualState.Player.Objects[Player] or CreatePlayerVisual(Player, false)
                        if Data then RefreshPlayerCharacter(Data, Character) end
                    end)
                end
            end)
        end
        local function BindWorldContainer(Container)
            if not Container then return end
            local Characters = Container:FindFirstChild("Characters")
            if Characters then BindWorldCharactersFolder(Characters) end
            Container.ChildAdded:Connect(function(Child)
                if Child.Name == "Characters" then BindWorldCharactersFolder(Child) end
            end)
        end
        BindWorldContainer(workspace:FindFirstChild("©"))
        workspace.ChildAdded:Connect(function(Child)
            if Child.Name == "©" then BindWorldContainer(Child) end
        end)
    end
end

local function GetCachedToolName(Data, CurrentTime)
    if CurrentTime < Data.NextToolScan then return Data.ToolName end
    Data.NextToolScan = CurrentTime + 0.25
    local Tool = Data.Character and Data.Character:FindFirstChildOfClass("Tool")
    Data.ToolName = Tool and Tool.Name or nil
    return Data.ToolName
end

local function ReadPlayerLevelObject(Object)
    if not Object then return nil end
    if Object:IsA("IntValue") or Object:IsA("NumberValue") or Object:IsA("StringValue") then
        local Value = tonumber(Object.Value)
        if Value and Value >= 0 then return math.floor(Value + 0.5) end
    end
    return nil
end

local function FindPlayerLevelInContainer(Container)
    if not Container then return nil end
    local Names = {"Level", "LEVEL", "Lvl", "LVL", "level"}
    for Index = 1, #Names do
        local Value = ReadPlayerLevelObject(Container:FindFirstChild(Names[Index]))
        if Value ~= nil then return Value end
    end
    for Index = 1, #Names do
        local Attribute = tonumber(Container:GetAttribute(Names[Index]))
        if Attribute and Attribute >= 0 then return math.floor(Attribute + 0.5) end
    end
    return nil
end

local function GetCachedPlayerLevel(Data, CurrentTime)
    if not Data or not Data.Player then return nil end
    if CurrentTime < (Data.NextLevelScan or 0) then return Data.LevelValue end
    Data.NextLevelScan = CurrentTime + 0.50

    local Player = Data.Player
    local Level = FindPlayerLevelInContainer(Player:FindFirstChild("leaderstats"))
        or FindPlayerLevelInContainer(Player:FindFirstChild("PlayerbaseData2"))
        or FindPlayerLevelInContainer(Player:FindFirstChild("Data"))
        or FindPlayerLevelInContainer(Player:FindFirstChild("Values"))
        or FindPlayerLevelInContainer(Player)

    if Level == nil then
        local ReplicatedData = ReplicatedStorage:FindFirstChild("PlayerbaseData2")
        Level = FindPlayerLevelInContainer(ReplicatedData and (ReplicatedData:FindFirstChild(Player.Name) or ReplicatedData:FindFirstChild(tostring(Player.UserId))))
    end

    if Level == nil then
        local CharStats = ReplicatedStorage:FindFirstChild("CharStats")
        Level = FindPlayerLevelInContainer(CharStats and (CharStats:FindFirstChild(Player.Name) or CharStats:FindFirstChild(tostring(Player.UserId))))
    end

    Data.LevelValue = Level
    return Level
end

local function GetPlayerBox(CameraObject, Data)
    local Root = Data.Root
    local Head = Data.Head

    if not Root
        or not Head
        or not Root.Parent
        or not Head.Parent
    then
        RefreshPlayerCharacter(
            Data,
            Data.Player.Character
        )

        Root = Data.Root
        Head = Data.Head
    end

    if not Root
        or not Head
    then
        return nil
    end

    local RootScreen,
        RootVisible =
        CameraObject:
            WorldToViewportPoint(
                Root.Position
            )

    if RootScreen.Z <= 0
        or not RootVisible
    then
        return nil
    end

    local TopScreen =
        CameraObject:
            WorldToViewportPoint(
                Head.Position
                + Vector3.new(
                    0,
                    0.72,
                    0
                )
            )

    local BottomScreen =
        CameraObject:
            WorldToViewportPoint(
                Root.Position
                - Vector3.new(
                    0,
                    3.15,
                    0
                )
            )

    if TopScreen.Z <= 0
        or BottomScreen.Z <= 0
    then
        return nil
    end

    local ViewportSize =
        CameraObject.ViewportSize

    local FieldOfView =
        math.rad(
            CameraObject.FieldOfView
        )

    local Depth =
        math.max(
            RootScreen.Z,
            0.35
        )

    local ExpectedHeight =
        (
            6.5
            * ViewportSize.Y
        ) / (
            2
            * math.tan(
                FieldOfView * 0.5
            )
            * Depth
        )

    local ProjectedHeight =
        math.abs(
            BottomScreen.Y
            - TopScreen.Y
        )

    local MinimumHeight =
        math.clamp(
            VisualState.Player.TextSize
                * 0.78,
            10,
            15
        )

    ExpectedHeight =
        math.clamp(
            ExpectedHeight,
            MinimumHeight,
            ViewportSize.Y * 1.35
        )

    local Ratio =
        ProjectedHeight
        / math.max(
            ExpectedHeight,
            0.001
        )

    local Height

    if ProjectedHeight < 2
        or Ratio < 0.56
        or Ratio > 1.80
    then
        Height =
            ExpectedHeight
    else
        Height =
            math.max(
                ProjectedHeight,
                ExpectedHeight * 0.82
            )
    end

    Height =
        math.clamp(
            Height,
            MinimumHeight,
            ViewportSize.Y * 1.35
        )

    -- When projection gets quantized at long range, rebuild around
    -- the stable root projection instead of accepting a 3-4 px box.
    if Height ~= ProjectedHeight
        or Depth > 500
    then
        TopScreen =
            Vector3.new(
                RootScreen.X,
                RootScreen.Y
                    - Height * 0.46,
                RootScreen.Z
            )

        BottomScreen =
            Vector3.new(
                RootScreen.X,
                TopScreen.Y
                    + Height,
                RootScreen.Z
            )
    end

    local Width =
        math.clamp(
            Height * 0.62,
            MinimumHeight * 0.54,
            ViewportSize.X * 1.10
        )

    return Vector2.new(
        RootScreen.X
            - Width * 0.5,
        TopScreen.Y
    ),
        Vector2.new(
            Width,
            Height
        ),
        RootScreen,
        Vector2.new(
            TopScreen.X,
            TopScreen.Y
        ),
        Vector2.new(
            BottomScreen.X,
            BottomScreen.Y
        )
end

local function SetLine(Line, From, To, Color, Visible, Thickness, Transparency)
    if not Line then return end
    Line.Visible = Visible
    if not Visible then return end
    Line.From = From
    Line.To = To
    Line.Color = Color
    if Thickness then Line.Thickness = Thickness end
    if Transparency then Line.Transparency = Transparency end
end

local function UpdateCornerBox(Data, Position, Size, Color, OutlineColor, Visible)
    local Width = Size.X
    local Height = Size.Y
    local CornerWidth = math.max(Width * 0.28, 4)
    local CornerHeight = math.max(Height * 0.20, 5)
    local X = Position.X
    local Y = Position.Y
    local Right = X + Width
    local Bottom = Y + Height
    local Segments = { { Vector2.new(X, Y), Vector2.new(X + CornerWidth, Y) }, { Vector2.new(X, Y), Vector2.new(X, Y + CornerHeight) }, { Vector2.new(Right, Y),
        Vector2.new(Right - CornerWidth, Y) }, { Vector2.new(Right, Y), Vector2.new(Right, Y + CornerHeight) }, { Vector2.new(X, Bottom), Vector2.new(X + CornerWidth, Bottom) },
        { Vector2.new(X, Bottom), Vector2.new(X, Bottom - CornerHeight) }, { Vector2.new(Right, Bottom), Vector2.new(Right - CornerWidth, Bottom) }, { Vector2.new(Right, Bottom),
        Vector2.new(Right, Bottom - CornerHeight) } }
    for Index, Segment in ipairs(Segments) do
        SetLine(Data.Drawings["CornerOutline" .. Index], Segment[1], Segment[2], OutlineColor, Visible, 3, 0.95)
        SetLine(Data.Drawings["Corner" .. Index], Segment[1], Segment[2], Color, Visible, 1, 1)
    end
end

local function GetTracerOrigin(ViewportSize)
    local Origin = VisualState.Player.TracerOrigin
    if Origin == "Top" then return Vector2.new(ViewportSize.X * 0.5, 2) end
    if Origin == "Center" then return Vector2.new(ViewportSize.X * 0.5, ViewportSize.Y * 0.5) end
    return Vector2.new(ViewportSize.X * 0.5, ViewportSize.Y - 2)
end

local function GetTracerEnd(Position, Size, RootScreen, HeadScreen, FeetScreen)
    local EndMode = VisualState.Player.TracerEnd
    if EndMode == "Head" then return HeadScreen end
    if EndMode == "Body" then return Vector2.new(RootScreen.X, Position.Y + Size.Y * 0.52) end
    return FeetScreen
end

local function QuadraticBezier(A, B, C, T)
    local Inverse = 1 - T
    return A * (Inverse * Inverse) + B * (2 * Inverse * T) + C * (T * T)
end

local function UpdateTracer(Data, ViewportSize, Position, Size, RootScreen, HeadScreen, FeetScreen)
    local Drawings = Data.Drawings
    if not VisualState.Player.Tracers then
        HideTracerDrawings(Drawings)
        return
    end
    local From = GetTracerOrigin(ViewportSize)
    local To = GetTracerEnd(Position, Size, RootScreen, HeadScreen, FeetScreen)
    local Color = VisualState.Player.TracerColor
    local Thickness = VisualState.Player.TracerThickness
    local Transparency = 1 - VisualState.Player.TracerTransparency
    if VisualState.Player.TracerStyle == "Straight" then
        SetLine(Drawings.Tracer, From, To, Color, true, Thickness, Transparency)
        for Index = 1, 10 do
            local Segment = Drawings["TracerCurve" .. Index]
            if Segment then Segment.Visible = false end
        end
        return
    end
    if Drawings.Tracer then Drawings.Tracer.Visible = false end
    EnsureCurvedTracerDrawings(Data)
    local Delta = To - From
    local Direction = Delta.X >= 0 and 1 or -1
    local Control = Vector2.new(From.X + Delta.X * 0.46 + Direction * math.min(math.abs(Delta.Y) * 0.12, 90), From.Y + Delta.Y * 0.42)
    local Previous = From
    for Index = 1, 10 do
        local T = Index / 10
        local Current = QuadraticBezier(From, Control, To, T)
        SetLine(Drawings["TracerCurve" .. Index], Previous, Current, Color, true, Thickness, Transparency)
        Previous = Current
    end
end

function HideTargetSnapline()
    local State = VisualState.Snapline

    if State.Line then State.Line.Visible = false end
    for _, Segment in ipairs(State.Curve) do
        if Segment then Segment.Visible = false end
    end
end

function EnsureTargetSnaplineDrawings()
    local State = VisualState.Snapline

    if not State.Line then
        State.Line = CreateDrawing("Line", {
            Visible = false,
            Thickness = State.Thickness,
            Transparency = 1 - State.Transparency,
            Color = State.Color,
            ZIndex = 8
        })
    end

    if #State.Curve == 0 then
        for Index = 1, 12 do
            State.Curve[Index] = CreateDrawing("Line", {
                Visible = false,
                Thickness = State.Thickness,
                Transparency = 1 - State.Transparency,
                Color = State.Color,
                ZIndex = 8
            })
        end
    end
end

function IsTargetSnaplinePlayerValid(Player)
    if not Player or Player == LocalPlayer or not Player.Parent then return false end

    local Character = Player.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    if not Character or not Humanoid or Humanoid.Health <= 0 or not Root then return false end

    if VisualState.Player.TeamCheck and LocalPlayer.Team and Player.Team == LocalPlayer.Team then return false end

    local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if LocalRoot and (Root.Position - LocalRoot.Position).Magnitude > VisualState.Player.MaxDistance then return false end

    return true
end

function GetClosestSnaplinePlayerToCursor()
    local CameraObject = GetCamera()
    if not CameraObject then return nil end

    local MousePosition = UserInputService:GetMouseLocation()
    local BestPlayer = nil
    local BestDistance = math.huge

    for _, Player in ipairs(Players:GetPlayers()) do
        if IsTargetSnaplinePlayerValid(Player) then
            local Character = Player.Character
            local Part = Character and (Character:FindFirstChild("Head") or Character:FindFirstChild("HumanoidRootPart"))
            if Part then
                local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(Part.Position)
                if OnScreen and ScreenPosition.Z > 0 then
                    local Distance = (Vector2.new(ScreenPosition.X, ScreenPosition.Y) - MousePosition).Magnitude
                    if Distance < BestDistance then
                        BestDistance = Distance
                        BestPlayer = Player
                    end
                end
            end
        end
    end

    return BestPlayer
end

function GetTargetSnaplinePlayer()
    local State = VisualState.Snapline

    if State.Source == "Closest to Cursor" then
        return GetClosestSnaplinePlayerToCursor()
    end

    if RageBotEnabled and IsTargetSnaplinePlayerValid(RageBotCurrentTarget) then
        return RageBotCurrentTarget
    end

    local AimTarget = S and S.AimBot and (S.AimBot.CurrentTarget or S.AimBot.Target)
    if S and S.AimBot and S.AimBot.Enabled and IsTargetSnaplinePlayerValid(AimTarget) then
        return AimTarget
    end

    return nil
end

function GetTargetSnaplineWorldPosition(Character)
    if not Character then return nil end

    local TargetPart = VisualState.Snapline.TargetPart

    if TargetPart == "Head" then
        local Head = Character:FindFirstChild("Head")
        return Head and Head.Position or nil
    end

    if TargetPart == "Body" then
        local Body = Character:FindFirstChild("HumanoidRootPart")
            or Character:FindFirstChild("UpperTorso")
            or Character:FindFirstChild("Torso")

        return Body and Body.Position or nil
    end

    local Root = Character:FindFirstChild("HumanoidRootPart")
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Root then return nil end

    return Root.Position - Vector3.new(0, Humanoid and Humanoid.HipHeight + 1.7 or 3.2, 0)
end

function UpdateTargetSnapline()
    local State = VisualState.Snapline

    if not State.Enabled then
        HideTargetSnapline()
        return
    end

    EnsureTargetSnaplineDrawings()

    local CameraObject = GetCamera()
    local Target = GetTargetSnaplinePlayer()
    local Character = Target and Target.Character
    local WorldPosition = GetTargetSnaplineWorldPosition(Character)

    if not CameraObject or not WorldPosition then
        HideTargetSnapline()
        return
    end

    local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(WorldPosition)
    if not OnScreen or ScreenPosition.Z <= 0 then
        HideTargetSnapline()
        return
    end

    local From = UserInputService:GetMouseLocation()
    local To = Vector2.new(ScreenPosition.X, ScreenPosition.Y)
    local Transparency = 1 - math.clamp(State.Transparency, 0, 1)

    if State.Style == "Straight" then
        SetLine(State.Line, From, To, State.Color, true, State.Thickness, Transparency)

        for _, Segment in ipairs(State.Curve) do
            if Segment then Segment.Visible = false end
        end

        return
    end

    if State.Line then State.Line.Visible = false end

    local Delta = To - From
    local Direction = Delta.X >= 0 and 1 or -1
    local Control = Vector2.new(
        From.X + Delta.X * 0.5 + Direction * math.min(math.abs(Delta.Y) * 0.18, 80),
        From.Y + Delta.Y * 0.42
    )

    local Previous = From

    for Index = 1, 12 do
        local Current = QuadraticBezier(From, Control, To, Index / 12)
        SetLine(State.Curve[Index], Previous, Current, State.Color, true, State.Thickness, Transparency)
        Previous = Current
    end
end

local function ShouldRenderPlayer(Data, LocalRoot, HasEnemyTargets)
    if not Data.Character
        or not Data.Humanoid
        or not Data.Root
        or Data.Humanoid.Health <= 0
    then
        return false
    end

    if HasEnemyTargets == true
        and EnemyTable[Data.Player] ~= true
    then
        return false
    end

    if VisualState.Player.TeamCheck
        and LocalPlayer.Team
        and Data.Player.Team
            == LocalPlayer.Team
    then
        return false
    end

    local Delta =
        Data.Root.Position
        - LocalRoot.Position

    local DistanceSquared =
        Delta:Dot(
            Delta
        )

    local MaximumDistance =
        math.max(
            tonumber(
                VisualState.Player.MaxDistance
            )
                or 1200,
            1
        )

    if DistanceSquared
        > MaximumDistance
            * MaximumDistance
    then
        return false
    end

    return true,
        math.sqrt(
            DistanceSquared
        )
end

local function UpdatePlayerESP()
    local CameraObject = GetCamera()
    local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if not CameraObject or not LocalRoot then
        for Unused, Data in ipairs(VisualState.Player.List) do HidePlayerVisual(Data) end
        return
    end
    local CurrentTime = os.clock()
    local HasEnemyTargets = AtramentaHasEnemyTargets()

    for Unused, Data in ipairs(VisualState.Player.List) do
        if not Data.DrawingsReady then CreatePlayerVisual(Data.Player, true) end
        if not Data.Root or not Data.Root.Parent or not Data.Humanoid or not Data.Humanoid.Parent or not Data.Character or not Data.Character.Parent then
            RefreshPlayerCharacter(Data, Data.Player and Data.Player.Character)
        end
        local ShouldRender, Distance = ShouldRenderPlayer(
            Data,
            LocalRoot,
            HasEnemyTargets
        )
        if not ShouldRender then
            HidePlayerVisual(Data)
            Data.NextEspUpdate = 0
            continue
        end

        local EspInterval =
            Distance >= 900
            and 1 / 30
            or Distance >= 500
                and 1 / 40
            or VisualState.Player.UpdateInterval

        if CurrentTime
            < (
                Data.NextEspUpdate
                or 0
            )
        then
            continue
        end

        Data.NextEspUpdate =
            CurrentTime
            + EspInterval

        Data.LastEspDistance =
            Distance

        local Position, Size, RootScreen, HeadScreen, FeetScreen = GetPlayerBox(CameraObject, Data)
        if not Position then
            HidePlayerVisual(Data)
            continue
        end
        local Drawings = Data.Drawings
        local FullBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Full"
        local CornerBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Corners"
        if Drawings.BoxOutline then
            Drawings.BoxOutline.Visible = FullBox
            Drawings.BoxOutline.Position = Position
            Drawings.BoxOutline.Size = Size
            Drawings.BoxOutline.Color = VisualState.Player.OutlineColor
        end
        if Drawings.Box then
            Drawings.Box.Visible = FullBox
            Drawings.Box.Position = Position
            Drawings.Box.Size = Size
            Drawings.Box.Color = VisualState.Player.BoxColor
        end
        UpdateCornerBox(Data, Position, Size, VisualState.Player.BoxColor, VisualState.Player.OutlineColor, CornerBox)
        if Drawings.Fill then
            Drawings.Fill.Visible = VisualState.Player.Fill
            Drawings.Fill.Position = Position
            Drawings.Fill.Size = Size
            Drawings.Fill.Color = VisualState.Player.FillColor
            Drawings.Fill.Transparency = 1 - VisualState.Player.FillTransparency
        end
        if Drawings.Name then
            Drawings.Name.Visible = VisualState.Player.Names
            Drawings.Name.Text = Data.Player.DisplayName ~= Data.Player.Name and(Data.Player.DisplayName .. " [" .. Data.Player.Name .. "]") or Data.Player.Name
            Drawings.Name.Size = VisualState.Player.TextSize
            Drawings.Name.Color = VisualState.Player.TextColor
            Drawings.Name.Position =
                ApplyPlayerESPPreviewOffset(
                    Vector2.new(
                        Position.X
                            + Size.X * 0.5,
                        Position.Y
                            - VisualState.Player.TextSize
                            - 2
                    ),
                    "Name"
                )
        end

        local ShowProfilePicture = VisualState.Player.ProfilePicture == true

        if ShowProfilePicture and not Drawings.ProfilePicture then
            EnsureProfilePictureDrawings(Data)
        end

        if Drawings.ProfilePicture then

            if ShowProfilePicture and type(Data.ProfilePictureData) ~= "string" then
                QueueAtramentaProfilePicture(Data)
            end

            if ShowProfilePicture
                and type(Data.ProfilePictureData) == "string"
                and #Data.ProfilePictureData > 64
            then
                if Data.ProfilePictureApplied ~= true then
                    local Applied = AtramentaCallChecked(function()
                        Drawings.ProfilePicture.Data = Data.ProfilePictureData
                    end)

                    Data.ProfilePictureApplied = Applied == true
                end

                local PictureSize = math.clamp(
                    tonumber(VisualState.Player.ProfilePictureSize) or 28,
                    16,
                    48
                )

                local PicturePosition = Vector2.new(
                    Position.X + Size.X + 5,
                    Position.Y
                )

                Drawings.ProfilePicture.Position = PicturePosition
                Drawings.ProfilePicture.Size = Vector2.new(PictureSize, PictureSize)
                Drawings.ProfilePicture.Transparency = 1
                Drawings.ProfilePicture.Visible = Data.ProfilePictureApplied == true

                if Drawings.ProfilePictureBack then
                    Drawings.ProfilePictureBack.Position = PicturePosition - Vector2.new(1, 1)
                    Drawings.ProfilePictureBack.Size = Vector2.new(PictureSize + 2, PictureSize + 2)
                    Drawings.ProfilePictureBack.Visible = Data.ProfilePictureApplied == true
                end
            else
                Drawings.ProfilePicture.Visible = false
                if Drawings.ProfilePictureBack then Drawings.ProfilePictureBack.Visible = false end
            end
        elseif Drawings.ProfilePictureBack then
            Drawings.ProfilePictureBack.Visible = false
        end

        if Drawings.Forcefield then
            local HasForcefield =
                VisualState.Player.Forcefield.Enabled
                and Data.Character ~= nil
                and Data.Character:FindFirstChildWhichIsA("ForceField") ~= nil

            Drawings.Forcefield.Visible = HasForcefield

            if HasForcefield then
                Drawings.Forcefield.Text = "[Forcefield]"
                Drawings.Forcefield.Size = math.max(VisualState.Player.TextSize - 1, 10)
                Drawings.Forcefield.Color = VisualState.Player.Forcefield.Color

                local NameOffset =
                    VisualState.Player.Names
                    and (VisualState.Player.TextSize + 3)
                    or 0

                Drawings.Forcefield.Position =
                    ApplyPlayerESPPreviewOffset(
                        Vector2.new(
                            Position.X
                                + Size.X * 0.5,
                            Position.Y
                                - VisualState.Player.TextSize
                                - 3
                                - NameOffset
                        ),
                        "Name"
                    )
            end
        end
        local BottomCenter =
            Vector2.new(
                Position.X
                    + Size.X * 0.5,
                Position.Y
                    + Size.Y
                    + 2
            )

        local ToolName =
            VisualState.Player.Weapon
            and GetCachedToolName(
                Data,
                CurrentTime
            )
            or nil

        if Drawings.Weapon then
            Drawings.Weapon.Visible =
                VisualState.Player.Weapon
                and ToolName ~= nil

            if Drawings.Weapon.Visible then
                Drawings.Weapon.Text =
                    ToolName

                Drawings.Weapon.Size =
                    math.max(
                        VisualState.Player.TextSize
                            - 1,
                        10
                    )

                Drawings.Weapon.Color =
                    VisualState.Player.TextColor

                Drawings.Weapon.Position =
                    ApplyPlayerESPPreviewOffset(
                        BottomCenter,
                        "Weapon"
                    )
            end
        end

        if Drawings.Distance then
            Drawings.Distance.Visible =
                VisualState.Player.Distance

            if Drawings.Distance.Visible then
                Drawings.Distance.Text =
                    tostring(
                        math.floor(
                            Distance + 0.5
                        )
                    )
                    .. "m"

                Drawings.Distance.Size =
                    math.max(
                        VisualState.Player.TextSize
                            - 2,
                        9
                    )

                Drawings.Distance.Color =
                    VisualState.Player.TextColor

                local DistanceOffset = VisualState.Player.Weapon and ToolName ~= nil and (math.max(VisualState.Player.TextSize, 11) + 2) or 0
                Drawings.Distance.Position =
                    ApplyPlayerESPPreviewOffset(
                        BottomCenter + Vector2.new(0, DistanceOffset),
                        "Distance"
                    )
            end
        end

        if Drawings.Level then
            local LevelValue = VisualState.Player.Level and GetCachedPlayerLevel(Data, CurrentTime) or nil
            Drawings.Level.Visible = VisualState.Player.Level and LevelValue ~= nil

            if Drawings.Level.Visible then
                Drawings.Level.Text = "Level " .. tostring(LevelValue)
                Drawings.Level.Size = math.max(VisualState.Player.TextSize - 1, 10)
                Drawings.Level.Color = VisualState.Player.LevelColor

                local LineHeight = math.max(VisualState.Player.TextSize, 11) + 2
                local LevelOffset = 0
                if VisualState.Player.Weapon and ToolName ~= nil then LevelOffset += LineHeight end
                if VisualState.Player.Distance then LevelOffset += LineHeight end

                Drawings.Level.Position =
                    ApplyPlayerESPPreviewOffset(
                        BottomCenter + Vector2.new(0, LevelOffset),
                        "Level"
                    )
            end
        end

        local HealthPercent = math.clamp(Data.Humanoid.Health / math.max(Data.Humanoid.MaxHealth, 1), 0, 1)
        local HealthColor = VisualState.Player.HealthLowColor:Lerp(VisualState.Player.HealthHighColor, HealthPercent)
        if Drawings.HealthBack then
            Drawings.HealthBack.Visible = VisualState.Player.HealthBar
            Drawings.HealthBack.Position =
                ApplyPlayerESPPreviewOffset(
                    Vector2.new(
                        Position.X - 6,
                        Position.Y
                    ),
                    "Health Bar"
                )
            Drawings.HealthBack.Size = Vector2.new(3, Size.Y)
        end
        if Drawings.Health then
            Drawings.Health.Visible = VisualState.Player.HealthBar
            local HealthHeight = Size.Y * HealthPercent
            local HealthBarOffset =
                GetPlayerESPPreviewOffset(
                    "Health Bar"
                )

            Drawings.Health.Position =
                Vector2.new(
                    Position.X - 6,
                    Position.Y
                        + Size.Y
                        - HealthHeight
                )
                + HealthBarOffset

            Drawings.Health.Size = Vector2.new(3, HealthHeight)
            Drawings.Health.Color = HealthColor
        end
        if Drawings.HealthText then
            Drawings.HealthText.Visible = VisualState.Player.HealthText
            Drawings.HealthText.Text = tostring(math.floor(Data.Humanoid.Health + 0.5))
            Drawings.HealthText.Size = math.max(VisualState.Player.TextSize - 2, 9)
            Drawings.HealthText.Color = HealthColor
            Drawings.HealthText.Position =
                ApplyPlayerESPPreviewOffset(
                    Vector2.new(
                        Position.X - 16,
                        Position.Y
                            + Size.Y
                                * (
                                    1
                                    - HealthPercent
                                )
                            - 4
                    ),
                    "Health Value"
                )
        end
        UpdateTracer(Data, CameraObject.ViewportSize, Position, Size, RootScreen, HeadScreen, FeetScreen)
    end
end

ChamsGlowRuntime = ChamsGlowRuntime or {
    Bloom = nil
}

function UpdateChamsBloom()
    local Bloom = ChamsGlowRuntime and ChamsGlowRuntime.Bloom
    if Bloom and Bloom.Parent then Bloom:Destroy() end
    if ChamsGlowRuntime then ChamsGlowRuntime.Bloom = nil end
end


function DisconnectNiggahackChamConnection(Connection)
    if Connection
        and typeof(Connection)
            == "RBXScriptConnection"
    then
        Connection:Disconnect()
    end
end

function DestroyNiggahackChamObject(Object)
    if Object and Object.Parent then
        Object:Destroy()
    end
end

function DestroyChams(Data)
    if not Data then return end

    if type(Data.Chams) == "table" then
        for _, Object in pairs(Data.Chams) do
            DestroyNiggahackChamObject(
                Object
            )
        end
    end

    if type(Data.ChamConnections) == "table" then
        for _, Connection in pairs(
            Data.ChamConnections
        ) do
            DisconnectNiggahackChamConnection(
                Connection
            )
        end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Parent then Data.ChamsGlow:Destroy() end

    if type(Data.ChamsGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsGlowShells) do
            if Shell and Shell.Parent then Shell:Destroy() end
        end
    end

    if Data.ChamsHolder
        and Data.ChamsHolder.Parent
    then
        Data.ChamsHolder:Destroy()
    end

    Data.Chams = {}
    Data.ChamConnections = {}
    Data.ChamsHolder = nil
    Data.ChamsGlow = nil
    Data.ChamsGlowShells = {}
    Data.ChamsCharacter = nil
end

function MakeNiggahackAdornment(Data, Part)
    if not Data
        or not Part
        or not Part:IsA("BasePart")
        or Part.Name == "HumanoidRootPart"
    then
        return
    end

    if not Data.ChamsHolder
        or not Data.ChamsHolder.Parent
        or Data.Chams[Part]
    then
        return
    end

    local Inner

    if Part.Name == "Head" then
        Inner = Instance.new(
            "CylinderHandleAdornment"
        )

        Inner.Adornee = Part
        Inner.ZIndex = 2
        Inner.Height = 0.87
        Inner.Radius = 0.5
        Inner.CFrame = CFrame.new(
            Vector3.new(),
            Vector3.new(0, 1, 0)
        )
    else
        Inner = Instance.new(
            "BoxHandleAdornment"
        )

        Inner.Adornee = Part
        Inner.ZIndex = 2
        Inner.Size =
            Part.Size
            + Vector3.new(
                -0.05,
                -0.05,
                -0.05
            )
    end

    Inner.AlwaysOnTop = true
    Inner.Visible = false
    Inner.Parent = Data.ChamsHolder
    Data.Chams[Part] = Inner
    MakePlayerChamGlowShell(Data, Part)

    Data.ChamConnections[Part] =
        Part:GetPropertyChangedSignal(
            "Size"
        ):Connect(function()
            if Inner
                and Inner.Parent
                and Inner:IsA(
                    "BoxHandleAdornment"
                )
            then
                local Expansion =
                    GetPlayerChamDistanceExpansion(
                        Data
                    )

                Inner.Size =
                    Part.Size
                    + Vector3.new(
                        -0.05 + Expansion,
                        -0.05 + Expansion,
                        -0.05 + Expansion
                    )
            end
        end)
end

function MakePlayerChamGlowShell(Data, Part)
    if not Data or not Part or not Part:IsA("BasePart") or Part.Name == "HumanoidRootPart" then return nil end
    Data.ChamsGlowShells = Data.ChamsGlowShells or {}
    local Existing = Data.ChamsGlowShells[Part]
    if Existing and Existing.Parent then return Existing end

    local Shell
    if Part.Name == "Head" then
        Shell = Instance.new("CylinderHandleAdornment")
        Shell.Height, Shell.Radius = 0.95, 0.55
        Shell.CFrame = CFrame.new(Vector3.zero, Vector3.new(0, 1, 0))
    else
        Shell = Instance.new("BoxHandleAdornment")
        Shell.Size = Part.Size + Vector3.new(0.08, 0.08, 0.08)
    end

    Shell.Name = "AtramentaPlayerGlowShell"
    Shell.Adornee = Part
    Shell.AlwaysOnTop = true
    Shell.ZIndex = 1
    Shell.Visible = false
    Shell.Parent = Data.ChamsHolder
    Data.ChamsGlowShells[Part] = Shell
    return Shell
end

function GetPlayerChamDistanceExpansion(Data)
    if not Data then
        return 0
    end

    local LocalRoot =
        LocalPlayer.Character
        and LocalPlayer.Character:
            FindFirstChild(
                "HumanoidRootPart"
            )

    local TargetRoot =
        Data.Root

    if not LocalRoot
        or not TargetRoot
    then
        return 0
    end

    local Distance =
        (
            TargetRoot.Position
            - LocalRoot.Position
        ).Magnitude

    local Settings =
        VisualState.Player.Chams

    local StartDistance =
        math.max(
            tonumber(
                Settings.DistanceScaleStart
            )
                or 320,
            100
        )

    if Distance <= StartDistance then
        return 0
    end

    local MaximumExpansion =
        math.clamp(
            tonumber(
                Settings.DistanceScaleMax
            )
                or 0.34,
            0.08,
            0.48
        )

    local Alpha =
        math.clamp(
            (
                Distance
                - StartDistance
            ) / 900,
            0,
            1
        )

    -- Smooth compensation only. It keeps the original body proportions
    -- and just prevents HandleAdornments from collapsing into sub-pixel lines.
    Alpha =
        Alpha
        * Alpha
        * (
            3
            - 2 * Alpha
        )

    return MaximumExpansion
        * Alpha
end

function UpdatePlayerChamGlowShell(Data, Part, Shell, DistanceExpansion)
    if not Shell
        or not Shell.Parent
        or not Part
        or not Part.Parent
    then
        return
    end

    local Settings =
        VisualState.Player.Chams

    local GlowSize =
        math.clamp(
            tonumber(
                Settings.GlowSize
            )
                or 28,
            8,
            56
        )

    local GlowStrength =
        math.clamp(
            tonumber(
                Settings.GlowIntensity
            )
                or 1.35,
            0.2,
            3
        )

    DistanceExpansion =
        math.max(
            tonumber(
                DistanceExpansion
            )
                or 0,
            0
        )

    local Expansion =
        0.035
        + (
            (GlowSize - 8)
            / 48
        ) * 0.32
        + DistanceExpansion * 0.82

    local BaseTransparency =
        math.clamp(
            tonumber(
                Settings.GlowTransparency
            )
                or 0.05,
            0,
            1
        )

    local Transparency =
        math.clamp(
            0.88
            - GlowStrength * 0.12
            + BaseTransparency * 0.22,
            0.18,
            0.96
        )

    Shell.Color3 =
        Settings.GlowColor

    Shell.Transparency =
        Transparency

    Shell.Visible =
        Settings.Enabled
        and Settings.GlowEnabled

    if Shell:IsA(
        "BoxHandleAdornment"
    )
    then
        local Size =
            Part.Size
            + Vector3.new(
                Expansion,
                Expansion,
                Expansion
            )

        if Shell.Size ~= Size then
            Shell.Size = Size
        end
    elseif Shell:IsA(
        "CylinderHandleAdornment"
    )
    then
        local Height =
            0.87
            + Expansion * 0.92

        local Radius =
            0.5
            + Expansion * 0.46

        if Shell.Height ~= Height then
            Shell.Height = Height
        end

        if Shell.Radius ~= Radius then
            Shell.Radius = Radius
        end
    end
end


function EnsurePlayerChamGlow(Data)
    local Character = Data and Data.Character
    if not Character or not Character.Parent then return nil end

    local Glow = Data.ChamsGlow
    if Glow and Glow.Parent and Glow.Adornee == Character then return Glow end
    if Glow and Glow.Parent then Glow:Destroy() end

    Glow = Instance.new("Highlight")
    Glow.Name = "AtramentaPlayerGlow"
    Glow.Adornee = Character
    Glow.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    Glow.FillTransparency = 1
    Glow.OutlineTransparency = 1
    Glow.Enabled = false
    Glow.Parent = Character
    Data.ChamsGlow = Glow
    return Glow
end

function BindNiggahackChams(Data)
    if not Data then return end

    local Character = Data.Character

    if not Character
        or not Character.Parent
    then
        DestroyChams(Data)
        return
    end

    if Data.ChamsCharacter == Character
        and Data.ChamsHolder
        and Data.ChamsHolder.Parent
    then
        return
    end

    DestroyChams(Data)

    Data.Chams = {}
    Data.ChamsGlowShells = {}
    Data.ChamConnections = {}
    Data.ChamsCharacter = Character

    local Holder = Instance.new("Folder")
    Holder.Name = "Chams"
    Holder.Parent = Character
    Data.ChamsHolder = Holder

    for _, Part in ipairs(
        Character:GetChildren()
    ) do
        if Part:IsA("BasePart")
            and Part.Name
                ~= "HumanoidRootPart"
        then
            MakeNiggahackAdornment(
                Data,
                Part
            )
        end
    end

    if Data.ChamsGlow
        and Data.ChamsGlow.Parent
    then
        Data.ChamsGlow:Destroy()
        Data.ChamsGlow = nil
    end

    Data.ChamConnections.ChildAdded =
        Character.ChildAdded:Connect(
            function(Child)
                if Child:IsA("BasePart")
                    and Child.Name
                        ~= "HumanoidRootPart"
                then
                    MakeNiggahackAdornment(
                        Data,
                        Child
                    )
                end
            end
        )

    Data.ChamConnections.ChildRemoved =
        Character.ChildRemoved:Connect(
            function(Child)
                if not Child:IsA("BasePart") then
                    return
                end

                local Object =
                    Data.Chams[Child]

                if Object then
                    DestroyNiggahackChamObject(Object)
                    Data.Chams[Child] = nil
                end

                local GlowShell = Data.ChamsGlowShells and Data.ChamsGlowShells[Child]
                if GlowShell then
                    DestroyNiggahackChamObject(GlowShell)
                    Data.ChamsGlowShells[Child] = nil
                end

                local Connection =
                    Data.ChamConnections[
                        Child
                    ]

                if Connection then
                    DisconnectNiggahackChamConnection(
                        Connection
                    )

                    Data.ChamConnections[
                        Child
                    ] = nil
                end
            end
        )
end

function SetNiggahackChamsVisible(Data, Visible)
    if not Data then return end

    if type(Data.Chams) == "table" then
        for _, Object in pairs(
            Data.Chams
        ) do
            if Object then
                Object.Visible = Visible
            end
        end
    end

    if Data.ChamsGlow then Data.ChamsGlow.Enabled = false end
    if type(Data.ChamsGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsGlowShells) do
            if Shell then Shell.Visible = Visible and VisualState.Player.Chams.GlowEnabled end
        end
    end
end

function ApplyPlayerChamData(Data)
    if not Data then
        return
    end

    local Settings =
        VisualState.Player.Chams

    local Character =
        Data.Character

    local Humanoid =
        Data.Humanoid

    local PlayerObject =
        Data.Player

    local TeamBlocked =
        VisualState.Player.TeamCheck
        and PlayerObject
        and PlayerObject.Team ~= nil
        and PlayerObject.Team
            == LocalPlayer.Team

    if not Settings.Enabled
        or not Character
        or not Character.Parent
        or not Humanoid
        or not Humanoid.Parent
        or Humanoid.Health <= 0
        or TeamBlocked
    then
        SetNiggahackChamsVisible(
            Data,
            false
        )

        if Data.ChamsGlow
            and Data.ChamsGlow.Parent
        then
            Data.ChamsGlow.Enabled = false
        end

        return
    end

    -- No Highlight LOD. Near and far players always use the same
    -- per-part chams system so the visual style never changes.
    if Data.ChamsGlow
        and Data.ChamsGlow.Parent
    then
        Data.ChamsGlow:Destroy()
        Data.ChamsGlow = nil
    end

    BindNiggahackChams(
        Data
    )

    local DistanceExpansion =
        GetPlayerChamDistanceExpansion(
            Data
        )

    local NormalTransparency =
        math.clamp(
            tonumber(
                Settings.NormalTransparency
            )
                or 0.8,
            0,
            1
        )

    for Part, Object in pairs(
        Data.Chams
    ) do
        if Object
            and Object.Parent
            and Part
            and Part.Parent
        then
            if Object.Color3
                ~= Settings.NormalColor
            then
                Object.Color3 =
                    Settings.NormalColor
            end

            if Object.Transparency
                ~= NormalTransparency
            then
                Object.Transparency =
                    NormalTransparency
            end

            if not Object.Visible then
                Object.Visible = true
            end

            if Object:IsA(
                "BoxHandleAdornment"
            )
            then
                local Expansion =
                    DistanceExpansion

                local DesiredSize =
                    Part.Size
                    + Vector3.new(
                        -0.05 + Expansion,
                        -0.05 + Expansion,
                        -0.05 + Expansion
                    )

                DesiredSize =
                    Vector3.new(
                        math.max(
                            DesiredSize.X,
                            0.05
                        ),
                        math.max(
                            DesiredSize.Y,
                            0.05
                        ),
                        math.max(
                            DesiredSize.Z,
                            0.05
                        )
                    )

                if Object.Size
                    ~= DesiredSize
                then
                    Object.Size =
                        DesiredSize
                end
            elseif Object:IsA(
                "CylinderHandleAdornment"
            )
            then
                local Height =
                    0.87
                    + DistanceExpansion
                        * 0.82

                local Radius =
                    0.5
                    + DistanceExpansion
                        * 0.42

                if Object.Height
                    ~= Height
                then
                    Object.Height =
                        Height
                end

                if Object.Radius
                    ~= Radius
                then
                    Object.Radius =
                        Radius
                end
            end
        end
    end

    Data.ChamsGlowShells =
        Data.ChamsGlowShells
        or {}

    for Part in pairs(
        Data.Chams
    ) do
        local Shell =
            MakePlayerChamGlowShell(
                Data,
                Part
            )

        UpdatePlayerChamGlowShell(
            Data,
            Part,
            Shell,
            DistanceExpansion
        )
    end

    UpdateChamsBloom()
end

function UpdatePlayerChams()
    for _, Data in ipairs(
        VisualState.Player.List
    ) do
        ApplyPlayerChamData(Data)
    end
end

function SyncPlayerChams()
    UpdatePlayerChams()
end


local function SaveWorldOriginal()
    if VisualState.World.Original then return end

    local Atmospheres = {}
    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Atmosphere") and Object ~= VisualState.World.Atmosphere then
            Atmospheres[#Atmospheres + 1] = {
                Object = Object,
                Density = Object.Density,
                Offset = Object.Offset,
                Color = Object.Color,
                Decay = Object.Decay,
                Glare = Object.Glare,
                Haze = Object.Haze
            }
        end
    end

    VisualState.World.Original = {
        Ambient = Lighting.Ambient,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        FogColor = Lighting.FogColor,
        FogStart = Lighting.FogStart,
        FogEnd = Lighting.FogEnd,
        Atmospheres = Atmospheres
    }
end

local function SetWorldProperty(Object, Property, Value)
    if Object[Property] ~= Value then Object[Property] = Value end
end


function RestoreAtramentaAtmospheres()
    local Atmosphere = VisualState.World.Atmosphere
    if Atmosphere and Atmosphere.Parent then Atmosphere:Destroy() end
    VisualState.World.Atmosphere = nil
    VisualState.World.AtmospheresSuppressed = false

    local Original = VisualState.World.Original
    local Entries = Original and Original.Atmospheres
    if type(Entries) ~= "table" then return end

    for _, Entry in ipairs(Entries) do
        local Object = Entry.Object
        if Object and Object.Parent then
            AtramentaCallChecked(function()
                Object.Density = Entry.Density
                Object.Offset = Entry.Offset
                Object.Color = Entry.Color
                Object.Decay = Entry.Decay
                Object.Glare = Entry.Glare
                Object.Haze = Entry.Haze
            end)
        end
    end
end

function EnsureAtramentaAtmosphere()
    if not VisualState.World.FogEnabled then
        RestoreAtramentaAtmospheres()
        return
    end

    local Original = VisualState.World.Original
    local Entries = Original and Original.Atmospheres
    if type(Entries) == "table" then
        for _, Entry in ipairs(Entries) do
            local Object = Entry.Object
            if Object and Object.Parent and Object ~= VisualState.World.Atmosphere then
                SetWorldProperty(Object, "Density", 0)
                SetWorldProperty(Object, "Haze", 0)
                SetWorldProperty(Object, "Glare", 0)
            end
        end

        VisualState.World.AtmospheresSuppressed = true
    end

    local Atmosphere = VisualState.World.Atmosphere
    if not Atmosphere or not Atmosphere.Parent then
        Atmosphere = Instance.new("Atmosphere")
        Atmosphere.Name = "AtramentaFogAtmosphere"
        Atmosphere.Parent = Lighting
        VisualState.World.Atmosphere = Atmosphere
    end

    SetWorldProperty(Atmosphere, "Density", math.clamp(tonumber(VisualState.World.FogDensity) or 0.42, 0, 1))
    SetWorldProperty(Atmosphere, "Offset", math.clamp(tonumber(VisualState.World.FogOffset) or 0, -1, 1))
    SetWorldProperty(Atmosphere, "Color", VisualState.World.FogColor)
    SetWorldProperty(Atmosphere, "Decay", VisualState.World.FogDecay)
    SetWorldProperty(Atmosphere, "Glare", math.clamp(tonumber(VisualState.World.FogGlare) or 0.12, 0, 10))
    SetWorldProperty(Atmosphere, "Haze", math.clamp(tonumber(VisualState.World.FogHaze) or 2.4, 0, 10))
end

function EnsureWorldEffects()
    local ColorCorrection = VisualState.World.ColorCorrection
    if not ColorCorrection or not ColorCorrection.Parent then
        ColorCorrection = Instance.new("ColorCorrectionEffect")
        ColorCorrection.Name = "AtramentaWorldColor"
        ColorCorrection.Parent = Lighting
        VisualState.World.ColorCorrection = ColorCorrection
    end
    SetWorldProperty(ColorCorrection, "Saturation", VisualState.World.Saturation)
    SetWorldProperty(ColorCorrection, "Contrast", VisualState.World.Contrast)
    SetWorldProperty(ColorCorrection, "TintColor", VisualState.World.TintColor)
    local Bloom = VisualState.World.BloomEffect
    if VisualState.World.Bloom then
        if not Bloom or not Bloom.Parent then
            Bloom = Instance.new("BloomEffect")
            Bloom.Name = "AtramentaWorldBloom"
            Bloom.Parent = Lighting
            VisualState.World.BloomEffect = Bloom
        end
        SetWorldProperty(Bloom, "Intensity", 0.28)
        SetWorldProperty(Bloom, "Size", 28)
        SetWorldProperty(Bloom, "Threshold", 1.15)
    elseif Bloom then
        Bloom:Destroy()
        VisualState.World.BloomEffect = nil
    end
    EnsureAtramentaAtmosphere()
end

function ApplyWorldLightingCore()
    if not VisualState.World.Enabled then return end

    SetWorldProperty(
        Lighting,
        "Ambient",
        VisualState.World.Ambient
    )
    SetWorldProperty(
        Lighting,
        "OutdoorAmbient",
        VisualState.World.OutdoorAmbient
    )
    SetWorldProperty(
        Lighting,
        "Brightness",
        VisualState.World.Brightness
    )
    SetWorldProperty(
        Lighting,
        "ClockTime",
        VisualState.World.ClockTime
    )

    if VisualState.World.FogEnabled then
        local FogDistance = math.max(
            tonumber(VisualState.World.FogDistance) or 900,
            25
        )
        local FogStart = math.clamp(
            tonumber(VisualState.World.FogStart) or 20,
            0,
            math.max(FogDistance - 1, 0)
        )

        SetWorldProperty(
            Lighting,
            "FogColor",
            VisualState.World.FogColor
        )
        SetWorldProperty(
            Lighting,
            "FogStart",
            FogStart
        )
        SetWorldProperty(
            Lighting,
            "FogEnd",
            FogDistance
        )
    else
        SetWorldProperty(Lighting, "FogStart", 0)
        SetWorldProperty(Lighting, "FogEnd", 1000000)
    end
end

function ApplyWorldVisuals()
    if not VisualState.World.Enabled
        or VisualState.World.Applying
    then
        return
    end

    VisualState.World.Applying = true

    local Success = AtramentaCallChecked(function()
        SaveWorldOriginal()
        ApplyWorldLightingCore()
        EnsureWorldEffects()
        VisualState.World.Dirty = false
    end)

    VisualState.World.Applying = false
    return Success
end

local WorldVisualApplyGeneration = 0

function QueueWorldVisualApply()
    if not VisualState.World.Enabled then return end

    VisualState.World.Dirty = true
    WorldVisualApplyGeneration += 1

    local Generation = WorldVisualApplyGeneration

    task.delay(0.03, function()
        if Generation ~= WorldVisualApplyGeneration
            or not VisualState.World.Enabled
        then
            return
        end

        ApplyWorldVisuals()
    end)
end

function DisconnectWorldOverrideSignals()
    if type(
        VisualState.World.PropertyConnections
    ) == "table"
    then
        for _, Connection in ipairs(
            VisualState.World.PropertyConnections
        ) do
            if Connection
                and typeof(Connection)
                    == "RBXScriptConnection"
            then
                Connection:
                    Disconnect()
            end
        end
    end

    VisualState.World.PropertyConnections =
        {}

    if type(
        VisualState.World.ChildConnections
    ) == "table"
    then
        for _, Connection in ipairs(
            VisualState.World.ChildConnections
        ) do
            if Connection
                and typeof(Connection)
                    == "RBXScriptConnection"
            then
                Connection:
                    Disconnect()
            end
        end
    end

    VisualState.World.ChildConnections =
        {}
end

function QueueWorldOverrideCorrection()
    if not VisualState.World.Enabled
        or VisualState.World.Applying
    then
        return
    end

    if VisualState.World.Dirty then
        return
    end

    VisualState.World.Dirty = true

    task.defer(function()
        if VisualState.World.Enabled
            and VisualState.World.Dirty
        then
            ApplyWorldVisuals()
        end
    end)
end

function BindWorldAtmosphereSignals(Object)
    if not Object
        or not Object:IsA(
            "Atmosphere"
        )
        or Object
            == VisualState.World.Atmosphere
    then
        return
    end

    for _, Property in ipairs({
        "Density",
        "Haze",
        "Glare",
        "Offset",
        "Color",
        "Decay"
    }) do
        local Connection =
            Object:
                GetPropertyChangedSignal(
                    Property
                ):
                Connect(
                    QueueWorldOverrideCorrection
                )

        VisualState.World.PropertyConnections[
            #VisualState.World.PropertyConnections
            + 1
        ] = Connection
    end
end

function BindWorldOverrideSignals()
    DisconnectWorldOverrideSignals()

    for _, Property in ipairs({
        "Ambient",
        "OutdoorAmbient",
        "Brightness",
        "ClockTime",
        "FogColor",
        "FogStart",
        "FogEnd"
    }) do
        local Connection =
            Lighting:
                GetPropertyChangedSignal(
                    Property
                ):
                Connect(
                    QueueWorldOverrideCorrection
                )

        VisualState.World.PropertyConnections[
            #VisualState.World.PropertyConnections
            + 1
        ] = Connection
    end

    for _, Object in ipairs(
        Lighting:GetChildren()
    ) do
        BindWorldAtmosphereSignals(
            Object
        )
    end

    VisualState.World.ChildConnections[1] =
        Lighting.ChildAdded:
            Connect(function(Object)
                if not VisualState.World.Enabled
                    or VisualState.World.Applying
                then
                    return
                end

                if Object:IsA("Atmosphere") then
                    BindWorldAtmosphereSignals(
                        Object
                    )

                    QueueWorldOverrideCorrection()
                elseif Object:IsA(
                    "ColorCorrectionEffect"
                )
                    or Object:IsA(
                        "BloomEffect"
                    )
                then
                    QueueWorldOverrideCorrection()
                end
            end)

    VisualState.World.ChildConnections[2] =
        Lighting.ChildRemoved:
            Connect(function(Object)
                if not VisualState.World.Enabled
                    or VisualState.World.Applying
                then
                    return
                end

                if Object
                        == VisualState.World.Atmosphere
                    or Object
                        == VisualState.World.ColorCorrection
                    or Object
                        == VisualState.World.BloomEffect
                    or Object:IsA(
                        "Atmosphere"
                    )
                then
                    QueueWorldOverrideCorrection()
                end
            end)
end

function StartWorldOverride()
    if FullBrightEnabled
        and type(FullBrightDisable)
            == "function"
    then
        AtramentaCallChecked(
            FullBrightDisable
        )
    end

    SaveWorldOriginal()

    AtramentaCallChecked(function()
        RunService:
            UnbindFromRenderStep(
                VisualState.World.
                    RenderStepName
            )
    end)

    if VisualState.World.Connection then
        AtramentaCallChecked(function()
            VisualState.World.Connection:
                Disconnect()
        end)

        VisualState.World.Connection =
            nil
    end

    DisconnectWorldOverrideSignals()

    VisualState.World.Accumulator = 0
    VisualState.World.Bound = true
    VisualState.World.Dirty = true

    ApplyWorldVisuals()
    BindWorldOverrideSignals()

    -- Property signals handle normal game resets instantly.
    -- This heartbeat is only a low-frequency safety verification.
    VisualState.World.Connection =
        RunService.Heartbeat:
            Connect(function(DeltaTime)
                if not VisualState.World.Enabled then
                    return
                end

                VisualState.World.Accumulator +=
                    math.clamp(
                        DeltaTime,
                        0,
                        0.10
                    )

                if VisualState.World.Accumulator
                    < (
                        VisualState.World.ApplyInterval
                        or 0.35
                    )
                then
                    return
                end

                VisualState.World.Accumulator = 0

                if VisualState.World.Dirty then
                    ApplyWorldVisuals()
                    return
                end

                -- Cheap safety pass. SetWorldProperty only writes
                -- values that the game actually changed.
                VisualState.World.Applying =
                    true

                AtramentaCallChecked(function()
                    ApplyWorldLightingCore()
                end)

                VisualState.World.Applying =
                    false
            end)
end

function RestoreWorldVisuals()
    AtramentaCallChecked(function() RunService:UnbindFromRenderStep(VisualState.World.RenderStepName) end)
    DisconnectWorldOverrideSignals()
    if VisualState.World.Connection then
        AtramentaCallChecked(function() VisualState.World.Connection:Disconnect() end)
        VisualState.World.Connection = nil
    end
    VisualState.World.Accumulator = 0
    VisualState.World.Bound = false
    local Original = VisualState.World.Original
    if Original then
        AtramentaCallChecked(function()
            Lighting.Ambient = Original.Ambient
            Lighting.OutdoorAmbient = Original.OutdoorAmbient
            Lighting.Brightness = Original.Brightness
            Lighting.ClockTime = Original.ClockTime
            Lighting.FogColor = Original.FogColor
            Lighting.FogStart = Original.FogStart
            Lighting.FogEnd = Original.FogEnd
        end)
    end
    RestoreAtramentaAtmospheres()
    if VisualState.World.ColorCorrection then
        VisualState.World.ColorCorrection:Destroy()
        VisualState.World.ColorCorrection = nil
    end
    if VisualState.World.BloomEffect then
        VisualState.World.BloomEffect:Destroy()
        VisualState.World.BloomEffect = nil
    end
    VisualState.World.Original = nil
    VisualState.World.Applying = false
    VisualState.World.Dirty = false
end

function GetWorldAdornee(Object)
    if Object:IsA("BasePart") then return Object end
    if Object:IsA("Model") then return Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart", true) end
    return Object:FindFirstChildWhichIsA("BasePart", true)
end

function GetWorldObjectBrokenState(Object)
    local Values = Object and Object:FindFirstChild("Values")
    local Broken = Values and Values:FindFirstChild("Broken")
    if Broken and Broken:IsA("ValueBase") then return Broken.Value == true, true end
    return false, false
end

function GetWorldObjectColor(Object, Kind)
    local IsBroken = GetWorldObjectBrokenState(Object)
    if IsBroken then return VisualState.WorldESP.BrokenColor end
    if Kind == "SAFE" then return VisualState.WorldESP.SafeColor end
    return VisualState.WorldESP.CashColor
end

local function GetSafeDisplayName(Object)
    local Name = string.lower(Object.Name)
    if string.find(Name, "register", 1, true) then return "Register" end
    if string.find(Name, "small", 1, true) then return "Small Safe" end
    if string.find(Name, "medium", 1, true) then return "Medium Safe" end
    if string.find(Name, "large", 1, true) then return "Large Safe" end
    return "Safe"
end

function GetWorldObjectText(Object, Kind)
    if Kind == "SAFE" then return GetSafeDisplayName(Object) end
    return "Cash"
end

function CreateWorldLabel(Object, Kind)
    local Adornee = GetWorldAdornee(Object)
    if not Adornee then return nil end
    local Billboard = Instance.new("BillboardGui")
    Billboard.Name = "AtramentaWorld" .. Kind
    Billboard.AlwaysOnTop = true
    Billboard.Size = UDim2.new(0, 190, 0, 24)
    Billboard.StudsOffset = Vector3.new(0, 2.25, 0)
    Billboard.MaxDistance = VisualState.WorldESP.MaxDistance
    local CurrentPlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or PlayerGui
    if not CurrentPlayerGui then
        Billboard:Destroy()
        return nil
    end

    Billboard.Adornee = Adornee
    Billboard.Parent = CurrentPlayerGui
    local Label = Instance.new("TextLabel")
    Label.Name = "Label"
    Label.Size = UDim2.new(1, 0, 1, 0)
    Label.BackgroundTransparency = 1
    Label.FontFace = UiFont
    Label.TextSize = 13
    Label.TextStrokeTransparency = 0.25
    Label.TextColor3 = GetWorldObjectColor(Object, Kind)
    Label.Parent = Billboard
    local Data = { Object = Object, Kind = Kind, Billboard = Billboard, Label = Label, Adornee = Adornee, LastColor = Label.TextColor3, LastText = nil, LastMaxDistance = VisualState.WorldESP.MaxDistance }
    VisualState.WorldESP.Objects[Object] = Data
    return Data
end

function GetWorldObjects()
    local Objects = {}
    if VisualState.WorldESP.Safes then
        local Map = workspace:FindFirstChild("Map")
        local Folder = Map and Map:FindFirstChild("BredMakurz")
        if Folder then
            for Unused, Object in ipairs(Folder:GetChildren()) do
                local Name = string.lower(Object.Name)
                if string.find(Name, "safe", 1, true) or string.find(Name, "register", 1, true) then Objects[Object] = "SAFE" end
            end
        end
    end
    if VisualState.WorldESP.Cash then
        local Filter = workspace:FindFirstChild("Filter")
        local Folder = Filter and Filter:FindFirstChild("SpawnedBread")
        if Folder then
            for Unused, Object in ipairs(Folder:GetChildren()) do Objects[Object] = "CASH" end
        end
    end
    return Objects
end

function ClearWorldESPLabels()
    for Object, Data in pairs(VisualState.WorldESP.Objects) do
        if Data and Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
        VisualState.WorldESP.Objects[Object] = nil
    end
end

function RefreshWorldESP(Force)
    if Force == true then
        VisualState.WorldESP.LastScan = 0
        VisualState.WorldClock = 0
    end

    if VisualState.WorldESP.Safes or VisualState.WorldESP.Cash then
        UpdateWorldESP()
    elseif next(VisualState.WorldESP.Objects) then
        ClearWorldESPLabels()
    end
end

function UpdateWorldESP()
    local CurrentTime = os.clock()
    if CurrentTime - VisualState.WorldESP.LastScan < 0.20 then return end
    VisualState.WorldESP.LastScan = CurrentTime

    local Current = GetWorldObjects()

    for Object, Data in pairs(VisualState.WorldESP.Objects) do
        local Remove = not Current[Object] or not Object or not Object.Parent

        if not Remove then
            local Adornee = GetWorldAdornee(Object)
            Remove =
                not Adornee
                or not Adornee.Parent
                or not Data
                or not Data.Billboard
                or not Data.Billboard.Parent
                or not Data.Label
                or not Data.Label.Parent
                or Data.Adornee ~= Adornee
                or Data.Billboard.Adornee ~= Adornee
        end

        if Remove then
            if Data and Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
            VisualState.WorldESP.Objects[Object] = nil
        end
    end

    for Object, Kind in pairs(Current) do
        local Data = VisualState.WorldESP.Objects[Object]

        if not Data then
            Data = CreateWorldLabel(Object, Kind)
        end

        if Data and Data.Billboard and Data.Billboard.Parent and Data.Label and Data.Label.Parent then
            local Adornee = GetWorldAdornee(Object)

            if Adornee and Adornee.Parent then
                if Data.Adornee ~= Adornee or Data.Billboard.Adornee ~= Adornee then
                    Data.Adornee = Adornee
                    Data.Billboard.Adornee = Adornee
                end

                local MaximumDistance = VisualState.WorldESP.MaxDistance
                if Data.LastMaxDistance ~= MaximumDistance then
                    Data.Billboard.MaxDistance = MaximumDistance
                    Data.LastMaxDistance = MaximumDistance
                end

                local Color = GetWorldObjectColor(Object, Kind)
                if Data.LastColor ~= Color then
                    Data.Label.TextColor3 = Color
                    Data.LastColor = Color
                end

                local LabelText = GetWorldObjectText(Object, Kind)
                if Data.LastText ~= LabelText then
                    Data.Label.Text = LabelText
                    Data.LastText = LabelText
                end
            else
                if Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
                VisualState.WorldESP.Objects[Object] = nil
            end
        end
    end
end



local function EnsureVisualEngine()
    EnsurePlayerCache()
    if VisualState.ChamsRenderConnection then
        VisualState.ChamsRenderConnection:Disconnect()
        VisualState.ChamsRenderConnection = nil
    end
    if VisualState.Connection then return end
    VisualState.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
        DeltaTime = math.clamp(DeltaTime, 0, 0.05)
        VisualState.CacheClock = VisualState.CacheClock + DeltaTime
        if VisualState.CacheClock >= 0.50 then
            VisualState.CacheClock = 0
            ReconcilePlayerVisualCache()
        end
        VisualState.PlayerClock = VisualState.PlayerClock + DeltaTime
        if VisualState.Player.Enabled and VisualState.PlayerClock >= VisualState.Player.UpdateInterval then
            VisualState.PlayerClock = VisualState.PlayerClock % VisualState.Player.UpdateInterval
            UpdatePlayerESP()
        end

        VisualState.Snapline.Clock = VisualState.Snapline.Clock + DeltaTime
        if VisualState.Snapline.Clock >= VisualState.Snapline.UpdateInterval then
            VisualState.Snapline.Clock = VisualState.Snapline.Clock % VisualState.Snapline.UpdateInterval
            UpdateTargetSnapline()
        end
        VisualState.ChamsClock =
            VisualState.ChamsClock + DeltaTime

        if VisualState.ChamsClock >= 0.25 then
            VisualState.ChamsClock = 0

            UpdatePlayerChams()
        end
        VisualState.WorldClock = VisualState.WorldClock + DeltaTime
        if VisualState.WorldClock >= 0.50 then
            VisualState.WorldClock = 0
            if VisualState.WorldESP.Safes or VisualState.WorldESP.Cash then
                UpdateWorldESP()
            elseif next(VisualState.WorldESP.Objects) then
                ClearWorldESPLabels()
            end
        end
    end)
end

