HideHeadController = HideHeadController or {
    Enabled = false,
    CharacterConnection = nil,
    PreviewConnection = nil,
    Character = nil,
    Neck = nil,
    OriginalTransform = nil,
    Down = 0.94,
    Back = 0.34,
    PreviewDown = 0.48,
    PreviewBack = 0.10,
    PreviewPitch = math.rad(-108)
}

function GetHideHeadNetworkDirection(Direction)
    if typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.001 then return Direction end

    local Flat = Vector3.new(Direction.X, 0, Direction.Z)
    if Flat.Magnitude <= 0.001 then Flat = Vector3.new(0, 0, -1) else Flat = Flat.Unit end

    local Down = math.clamp(tonumber(HideHeadController.Down) or 0.94, 0.75, 0.995)
    local Back = math.clamp(tonumber(HideHeadController.Back) or 0.34, 0.08, 0.60)
    return (-Flat * Back + Vector3.new(0, -Down, 0)).Unit
end

function GetHideHeadNeck(Character)
    if not Character then return nil end
    local Neck = Character:FindFirstChild("Neck", true)
    return Neck and Neck:IsA("Motor6D") and Neck or nil
end

function ApplyHideHeadLocalPreview()
    if not HideHeadEnabled then return end
    local Character = LocalPlayer.Character
    if not Character or not Character.Parent then return end

    local Neck = HideHeadController.Neck
    if not Neck or not Neck.Parent or not Neck:IsDescendantOf(Character) then
        Neck = GetHideHeadNeck(Character)
        HideHeadController.Neck = Neck
        HideHeadController.OriginalTransform = Neck and Neck.Transform or nil
    end
    if not Neck then return end

    Neck.Transform = CFrame.new(
        0,
        -(tonumber(HideHeadController.PreviewDown) or 0.48),
        tonumber(HideHeadController.PreviewBack) or 0.10
    ) * CFrame.Angles(
        tonumber(HideHeadController.PreviewPitch) or math.rad(-108),
        0,
        0
    )
end

function RestoreHideHeadLocalPreview()
    local Neck = HideHeadController.Neck
    if Neck and Neck.Parent then
        Neck.Transform = typeof(HideHeadController.OriginalTransform) == "CFrame"
            and HideHeadController.OriginalTransform
            or CFrame.new()
    end
    HideHeadController.Neck = nil
    HideHeadController.OriginalTransform = nil
end

function BindHideHeadCharacter(Character)
    HideHeadController.Character = Character
    HideHeadController.Neck = nil
    HideHeadController.OriginalTransform = nil

    task.defer(function()
        for _ = 1, 30 do
            if Character ~= LocalPlayer.Character or not Character.Parent then return end
            local Neck = GetHideHeadNeck(Character)
            if Neck then
                HideHeadController.Neck = Neck
                HideHeadController.OriginalTransform = Neck.Transform
                ApplyHideHeadLocalPreview()
                return
            end
            task.wait(0.05)
        end
    end)
end

function SetHideHeadEnabled(Value)
    HideHeadEnabled = Value == true
    HideHeadController.Enabled = HideHeadEnabled

    if not HideHeadController.CharacterConnection then
        HideHeadController.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
            if HideHeadEnabled then BindHideHeadCharacter(Character) end
        end)
    end

    if HideHeadEnabled then
        if LocalPlayer.Character then BindHideHeadCharacter(LocalPlayer.Character) end
        if not HideHeadController.PreviewConnection then
            HideHeadController.PreviewConnection = RunService.RenderStepped:Connect(ApplyHideHeadLocalPreview)
        end
    else
        if HideHeadController.PreviewConnection then
            HideHeadController.PreviewConnection:Disconnect()
            HideHeadController.PreviewConnection = nil
        end
        RestoreHideHeadLocalPreview()
    end

    return HideHeadEnabled
end

function ShutdownHideHeadController()
    HideHeadEnabled = false
    HideHeadController.Enabled = false

    if HideHeadController.PreviewConnection then
        HideHeadController.PreviewConnection:Disconnect()
        HideHeadController.PreviewConnection = nil
    end

    if HideHeadController.CharacterConnection then
        HideHeadController.CharacterConnection:Disconnect()
        HideHeadController.CharacterConnection = nil
    end

    RestoreHideHeadLocalPreview()
    HideHeadController.Character = nil
end

function AntiAFKEnable()
    if AntiAFKEnabled then return end
    AntiAFKEnabled = true
    if AntiAFKConnection then
        AntiAFKConnection:Disconnect()
        AntiAFKConnection = nil
    end
    AntiAFKTimer = 0
    AntiAFKConnection = RunService.Heartbeat:Connect(function(DeltaTime)
        if not AntiAFKEnabled then return end
        AntiAFKTimer = AntiAFKTimer + DeltaTime
        if AntiAFKTimer >= 120 then
            AntiAFKTimer = 0
            SendKeyPress(Enum.KeyCode.W, 0.1)
        end
    end)
end

function AntiAFKDisable()
    if not AntiAFKEnabled then return end
    AntiAFKEnabled = false
    if AntiAFKConnection then
        AntiAFKConnection:Disconnect()
        AntiAFKConnection = nil
    end
    AntiAFKTimer = 0
end

function CrowbarAuraEnable()

    CrowbarAuraEnabled = false
end

function CrowbarAuraDisable()
    CrowbarAuraEnabled = false
    if CrowbarAuraCoroutine then
        task.cancel(CrowbarAuraCoroutine)
        CrowbarAuraCoroutine = nil
    end
end

local SharedAuraTick = 0

function MeleeAuraEnable()
    if MeleeAuraEnabled then return end

    MeleeAuraEnabled = true

    MeleeAuraCoroutine = task.spawn(function()
        while MeleeAuraEnabled do
            if tick() - SharedAuraTick > 0.15 then
                local CharacterModel = LocalPlayer.Character

                if CharacterModel then
                    local RootPart =
                        CharacterModel:FindFirstChild(
                            "HumanoidRootPart"
                        )

                    local ToolObject =
                        CharacterModel:FindFirstChildOfClass(
                            "Tool"
                        )

                    if RootPart and ToolObject then
                        local Events =
                            ReplicatedStorage:
                                FindFirstChild(
                                    "Events"
                                )

                        local PrimaryRemote =
                            Events
                            and Events:
                                FindFirstChild(
                                    "XMHH.2"
                                )

                        local SecondaryRemote =
                            Events
                            and Events:
                                FindFirstChild(
                                    "XMHH2.2"
                                )

                        if PrimaryRemote
                            and SecondaryRemote
                        then
                            local BestPlayer = nil
                            local BestCharacter = nil
                            local BestHead = nil
                            local BestDistance = math.huge
                            local BestTier = -1
                            local MaximumDistance =
                                math.clamp(
                                    tonumber(MeleeAuraDistance)
                                        or 15,
                                    1,
                                    15
                                )

                            for _, PlayerObject in ipairs(
                                Players:GetPlayers()
                            ) do
                                if not IsAtramentaCombatTargetAllowed(
                                    PlayerObject
                                ) then
                                    continue
                                end

                                local TargetCharacter =
                                    PlayerObject.Character

                                local TargetRootPart =
                                    TargetCharacter
                                    and TargetCharacter:
                                        FindFirstChild(
                                            "HumanoidRootPart"
                                        )

                                local TargetHead =
                                    TargetCharacter
                                    and TargetCharacter:
                                        FindFirstChild(
                                            "Head"
                                        )

                                local TargetHum =
                                    TargetCharacter
                                    and TargetCharacter:
                                        FindFirstChildOfClass(
                                            "Humanoid"
                                        )

                                if TargetRootPart
                                    and TargetHead
                                    and TargetHum
                                    and TargetHum.Health > 0
                                    and not TargetCharacter:
                                        FindFirstChildOfClass(
                                            "ForceField"
                                        )
                                then
                                    local DistanceValue =
                                        (
                                            RootPart.Position
                                            - TargetRootPart.Position
                                        ).Magnitude

                                    local Tier =
                                        GetAtramentaCombatTargetTier(
                                            PlayerObject
                                        )

                                    if DistanceValue <= MaximumDistance
                                        and (
                                            Tier > BestTier
                                            or Tier == BestTier
                                                and DistanceValue < BestDistance
                                        )
                                    then
                                        BestTier = Tier
                                        BestDistance = DistanceValue
                                        BestPlayer = PlayerObject
                                        BestCharacter = TargetCharacter
                                        BestHead = TargetHead
                                    end
                                end
                            end

                            if BestPlayer
                                and BestCharacter
                                and BestHead
                            then
                                SharedAuraTick = tick()

                                local FirstArgument = {
                                    [1] = "🍞",
                                    [2] = tick(),
                                    [3] = ToolObject,
                                    [4] = "43TRFWX",
                                    [5] = "Normal",
                                    [6] = tick(),
                                    [7] = true
                                }

                                local Success1,
                                    OperationResult =
                                    AtramentaCallChecked(
                                        function()
                                            return PrimaryRemote:
                                                InvokeServer(
                                                    unpack(
                                                        FirstArgument
                                                    )
                                                )
                                        end
                                    )

                                if Success1 then
                                    local Handle =
                                        ToolObject:
                                            FindFirstChild(
                                                "WeaponHandle"
                                            )
                                        or ToolObject:
                                            FindFirstChild(
                                                "Handle"
                                            )
                                        or CharacterModel:
                                            FindFirstChild(
                                                "Right Arm"
                                            )

                                    if Handle then
                                        local SecondArgument = {
                                            [1] = "🍞",
                                            [2] = tick(),
                                            [3] = ToolObject,
                                            [4] = "2389ZFX34",
                                            [5] = OperationResult,
                                            [6] = false,
                                            [7] = Handle,
                                            [8] = BestHead,
                                            [9] = BestCharacter,
                                            [10] = RootPart.Position,
                                            [11] = BestHead.Position
                                        }

                                        AtramentaCallChecked(
                                            function()
                                                SecondaryRemote:
                                                    FireServer(
                                                        unpack(
                                                            SecondArgument
                                                        )
                                                    )
                                            end
                                        )
                                    end
                                end
                            end
                        end
                    end
                end
            end

            task.wait(0.1)
        end
    end)
end

function MeleeAuraDisable()
    MeleeAuraEnabled = false
    if MeleeAuraCoroutine then
        task.cancel(MeleeAuraCoroutine)
        MeleeAuraCoroutine = nil
    end
end

function GetWeaponShaderTarget()
    local Character = LocalPlayer.Character
    if not Character then
        return nil
    end

    local Equipped = nil

    for _, Object in ipairs(Character:GetChildren()) do
        if Object:IsA("Tool") then
            Equipped = Object
            break
        end
    end

    return Equipped
end

function ScoreCameraViewModelCandidate(Object)
    if not Object
        or not Object.Parent
        or (
            not Object:IsA("Model")
            and not Object:IsA("Folder")
        )
    then
        return -math.huge
    end

    local Name =
        string.lower(
            tostring(Object.Name)
        )

    local Score = 0

    if Name == "viewmodel"
        or Name == "view model"
    then
        Score += 100
    elseif Name == "arms"
        or Name == "armmodel"
        or Name == "viewarms"
    then
        Score += 78
    elseif Name:find(
        "viewmodel",
        1,
        true
    )
    then
        Score += 72
    elseif Name:find(
        "arms",
        1,
        true
    )
    then
        Score += 48
    end

    local BasePartCount = 0
    local ArmCount = 0
    local HolderCount = 0
    local WeaponLikeCount = 0

    for _, Descendant in ipairs(
        Object:GetDescendants()
    ) do
        if Descendant:IsA("BasePart") then
            BasePartCount += 1

            local DescendantName =
                string.lower(
                    Descendant.Name
                )

            if DescendantName == "right arm"
                or DescendantName == "left arm"
                or DescendantName == "rightarm"
                or DescendantName == "leftarm"
            then
                ArmCount += 1
            end

            if DescendantName == "rarmholder"
                or DescendantName == "larmholder"
            then
                HolderCount += 1
            end

            if DescendantName:find(
                    "handle",
                    1,
                    true
                )
                or DescendantName:find(
                    "receiver",
                    1,
                    true
                )
                or DescendantName:find(
                    "barrel",
                    1,
                    true
                )
                or DescendantName:find(
                    "slide",
                    1,
                    true
                )
                or DescendantName:find(
                    "mag",
                    1,
                    true
                )
            then
                WeaponLikeCount += 1
            end
        end
    end

    Score += math.min(
        BasePartCount,
        18
    ) * 0.75

    Score +=
        ArmCount * 12
        + HolderCount * 14
        + math.min(
            WeaponLikeCount,
            8
        ) * 2.5

    if ArmCount == 0
        and HolderCount == 0
        and WeaponLikeCount == 0
        and Score < 60
    then
        return -math.huge
    end

    return Score
end

function GetArmsViewModel()
    local CameraObject =
        GetCamera()

    if not CameraObject then
        return nil
    end

    local Direct =
        CameraObject:
            FindFirstChild(
                "ViewModel"
            )
        or CameraObject:
            FindFirstChild(
                "viewmodel"
            )
        or CameraObject:
            FindFirstChild(
                "Viewmodel"
            )

    if Direct
        and (
            Direct:IsA("Model")
            or Direct:IsA("Folder")
        )
    then
        return Direct
    end

    local Best = nil
    local BestScore = -math.huge

    for _, Object in ipairs(
        CameraObject:GetChildren()
    ) do
        if Object ~= LocalPlayer.Character
            and (
                Object:IsA("Model")
                or Object:IsA("Folder")
            )
        then
            local Score =
                ScoreCameraViewModelCandidate(
                    Object
                )

            if Score > BestScore then
                BestScore = Score
                Best = Object
            end
        end
    end

    if Best
        and BestScore >= 48
    then
        return Best
    end

    return nil
end

function IsViewModelFirstPerson()
    local CameraObject = GetCamera()
    if not CameraObject then return false end

    if LocalPlayer.CameraMode
        == Enum.CameraMode.LockFirstPerson
    then
        return true
    end

    local Distance =
        (
            CameraObject.CFrame.Position
            - CameraObject.Focus.Position
        ).Magnitude

    return Distance <= 1.25
end
function GetActiveFirstPersonWeaponRoot()
    if not IsViewModelFirstPerson() then
        return nil
    end

    local ViewModel =
        GetArmsViewModel()

    if not ViewModel
        or not ViewModel.Parent
    then
        return nil
    end

    return ViewModel
end


function IsViewModelArmPart(Part)
    if not Part
        or not Part:IsA("BasePart")
    then
        return false
    end

    local Name = Part.Name

    return Name == "Right Arm"
        or Name == "Left Arm"
        or Name == "RightArm"
        or Name == "LeftArm"
end

function IsViewModelExcludedPart(Part, ViewModel)
    if not Part
        or not Part:IsA("BasePart")
    then
        return true
    end

    local Name = Part.Name

    if Name == "HumanoidRootPart"
        or Name == "RArmHolder"
        or Name == "LArmHolder"
    then
        return true
    end

    local Parent = Part.Parent

    while Parent
        and Parent ~= ViewModel
    do
        local ParentName = Parent.Name

        if ParentName == "RArmHolder"
            or ParentName == "LArmHolder"
        then
            return true
        end

        Parent = Parent.Parent
    end

    return false
end

function IsViewModelWeaponPart(Part, ViewModel)
    return Part
        and Part:IsA("BasePart")
        and not IsViewModelArmPart(Part)
        and not IsViewModelExcludedPart(
            Part,
            ViewModel
        )
end

function StoreViewModelPartOriginal(Part)
    if ViewModelChamsRuntime.Original[
        Part
    ] then
        return
    end

    ViewModelChamsRuntime.Original[
        Part
    ] = {
        Material = Part.Material,
        Color = Part.Color,
        Transparency = Part.Transparency,
        LocalTransparencyModifier =
            Part.LocalTransparencyModifier
    }
end

function RestoreViewModelPart(Part)
    local Original =
        ViewModelChamsRuntime.Original[
            Part
        ]

    if Original
        and Part
        and Part.Parent
    then
        Part.Material =
            Original.Material

        Part.Color =
            Original.Color

        Part.Transparency =
            Original.Transparency

        Part.LocalTransparencyModifier =
            Original.LocalTransparencyModifier
    end

    local Highlight =
        ViewModelChamsRuntime.Highlights[
            Part
        ]

    if Highlight
        and Highlight.Parent
    then
        Highlight:Destroy()
    end

    ViewModelChamsRuntime.Original[
        Part
    ] = nil

    ViewModelChamsRuntime.Highlights[
        Part
    ] = nil

    ViewModelChamsRuntime.Categories[
        Part
    ] = nil
end

function RestoreViewModelChams(Category)
    local Parts = {}

    for Part, CurrentCategory in pairs(
        ViewModelChamsRuntime.Categories
    ) do
        if not Category
            or CurrentCategory == Category
        then
            Parts[#Parts + 1] = Part
        end
    end

    for _, Part in ipairs(Parts) do
        RestoreViewModelPart(Part)
    end

    if not Category then
        ViewModelChamsRuntime.ViewModel = nil
    end
end

function EnsureViewModelHighlight(Part, ViewModel)
    local Highlight =
        ViewModelChamsRuntime.Highlights[
            Part
        ]

    if Highlight
        and Highlight.Parent
        and Highlight.Adornee == Part
    then
        return Highlight
    end

    if Highlight
        and Highlight.Parent
    then
        Highlight:Destroy()
    end

    Highlight = Instance.new("Highlight")
    Highlight.Name =
        "AtramentaViewModelCham"

    Highlight.Adornee = Part
    Highlight.DepthMode =
        Enum.HighlightDepthMode.AlwaysOnTop
    Highlight.Enabled = true
    Highlight.Parent = ViewModel

    ViewModelChamsRuntime.Highlights[
        Part
    ] = Highlight

    return Highlight
end

function ApplyViewModelChamPart(
    Part,
    ViewModel,
    Category,
    Settings
)
    StoreViewModelPartOriginal(Part)

    ViewModelChamsRuntime.Categories[
        Part
    ] = Category

    Part.Material =
        Enum.Material.ForceField

    Part.Color =
        Settings.Color

    Part.Transparency =
        math.clamp(
            tonumber(
                Settings.Transparency
            )
            or 0.30,
            0,
            0.95
        )

    Part.LocalTransparencyModifier = 0

    local Highlight =
        EnsureViewModelHighlight(
            Part,
            ViewModel
        )

    Highlight.FillColor =
        Settings.Color

    Highlight.FillTransparency =
        math.clamp(
            tonumber(
                Settings.HighlightTransparency
            )
            or 0.30,
            0,
            1
        )

    Highlight.OutlineColor =
        Settings.OutlineColor

    Highlight.OutlineTransparency =
        math.clamp(
            tonumber(
                Settings.OutlineTransparency
            )
            or 0.05,
            0,
            1
        )

    Highlight.Enabled = true
end

function UpdateViewModelChams()
    if not IsViewModelFirstPerson() then
        if next(ViewModelChamsRuntime.Categories) ~= nil
            or ViewModelChamsRuntime.ViewModel
        then
            RestoreViewModelChams()
        end

        return
    end

    local ViewModel =
        GetArmsViewModel()

    if not ViewModel
        or not ViewModel.Parent
    then
        if ViewModelChamsRuntime.ViewModel then
            RestoreViewModelChams()
        end

        return
    end

    if ViewModelChamsRuntime.ViewModel
        ~= ViewModel
    then
        RestoreViewModelChams()
        ViewModelChamsRuntime.ViewModel =
            ViewModel
    end

    local Active =
        setmetatable(
            {},
            { __mode = "k" }
        )

    for _, Part in ipairs(
        ViewModel:GetDescendants()
    ) do
        if Part:IsA("BasePart") then
            local Category
            local Settings

            if ArmsChamsEnabled
                and IsViewModelArmPart(
                    Part
                )
            then
                Category = "Arms"
                Settings =
                    ArmsChamsSettings
            elseif WeaponChamsEnabled
                and IsViewModelWeaponPart(
                    Part,
                    ViewModel
                )
            then
                Category = "Weapon"
                Settings =
                    WeaponChamsSettings
            end

            if Category then
                ApplyViewModelChamPart(
                    Part,
                    ViewModel,
                    Category,
                    Settings
                )

                Active[Part] = true
            end
        end
    end

    local Stale = {}

    for Part in pairs(
        ViewModelChamsRuntime.Categories
    ) do
        if not Active[Part]
            or not Part
            or not Part.Parent
            or not Part:IsDescendantOf(
                ViewModel
            )
        then
            Stale[#Stale + 1] =
                Part
        end
    end

    for _, Part in ipairs(Stale) do
        RestoreViewModelPart(Part)
    end
end

function EnsureViewModelChamsRender()
    local Enabled =
        ArmsChamsEnabled
        or WeaponChamsEnabled

    local RenderName =
        ViewModelChamsRuntime.RenderName

    if not Enabled then
        if RenderName then
            AtramentaCallChecked(
                function()
                    RunService:
                        UnbindFromRenderStep(
                            RenderName
                        )
                end
            )
        end

        ViewModelChamsRuntime.RenderName =
            nil

        RestoreViewModelChams()
        return
    end

    if RenderName then
        return
    end

    RenderName =
        "AtramentaViewModelChams_"
        .. tostring(
            LocalPlayer.UserId
        )

    ViewModelChamsRuntime.RenderName =
        RenderName

    AtramentaCallChecked(
        function()
            RunService:
                UnbindFromRenderStep(
                    RenderName
                )
        end
    )

    RunService:BindToRenderStep(
        RenderName,
        Enum.RenderPriority.Last.Value
            + 200,
        function()
            if not ArmsChamsEnabled
                and not WeaponChamsEnabled
            then
                return
            end

            UpdateViewModelChams()
        end
    )
end

function ApplyArmsChams()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
end

function RestoreArmsChams()
    RestoreViewModelChams(
        "Arms"
    )
end

function ArmsChamsEnable()
    ArmsChamsEnabled = true
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
end

function ArmsChamsDisable()
    ArmsChamsEnabled = false
    RestoreArmsChams()
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
end

function RestoreWeaponShaderMesh(Object)
    local Original = WeaponShaderSettings.MeshOriginal[Object]
    if Original == nil then return end
    if Object and Object.Parent then
        if Object:IsA("MeshPart") then Object.TextureID = Original
        elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then Object.TextureId = Original end
    end
    WeaponShaderSettings.MeshOriginal[Object] = nil
    WeaponShaderSettings.MeshActive[Object] = nil
end

function RestoreWeaponShaderSurface(Surface)
    local Original = WeaponShaderSettings.SurfaceOriginal[Surface]
    if Original == nil then return end
    if Surface and Surface.Parent then
        AtramentaCallChecked(function() Surface.ColorMap = Original.ColorMap end)
        AtramentaCallChecked(function() Surface.NormalMap = Original.NormalMap end)
        AtramentaCallChecked(function() Surface.MetalnessMap = Original.MetalnessMap end)
        AtramentaCallChecked(function() Surface.RoughnessMap = Original.RoughnessMap end)
        if Original.AlphaMode ~= nil then
            AtramentaCallChecked(function() Surface.AlphaMode = Original.AlphaMode end)
        end
    end
    WeaponShaderSettings.SurfaceOriginal[Surface] = nil
    WeaponShaderSettings.SurfaceActive[Surface] = nil
end

function DisconnectWeaponShaderCharacterSignals()
    for _, Connection in ipairs(
        WeaponShaderSettings.CharacterConnections
    ) do
        if Connection
            and typeof(Connection)
                == "RBXScriptConnection"
        then
            Connection:Disconnect()
        end
    end

    WeaponShaderSettings.CharacterConnections = {}
end

function BindWeaponShaderCharacterSignals(Character)
    DisconnectWeaponShaderCharacterSignals()

    if not Character then
        return
    end

    local function DirtyCharacter()
        if not WeaponShaderSettings.Enabled then
            return
        end

        WeaponShaderSettings.Dirty = true
        WeaponShaderSettings.NextRootCheck = 0
    end

    WeaponShaderSettings.CharacterConnections[1] =
        Character.ChildAdded:
            Connect(function(Object)
                if Object:IsA("Tool")
                    or Object:IsA("BasePart")
                then
                    DirtyCharacter()
                end
            end)

    WeaponShaderSettings.CharacterConnections[2] =
        Character.ChildRemoved:
            Connect(function(Object)
                if Object:IsA("Tool")
                    or Object:IsA("BasePart")
                then
                    DirtyCharacter()
                end
            end)
end

function DisconnectWeaponShaderCameraSignals()
    if WeaponShaderSettings.CameraAddedConnection then
        WeaponShaderSettings.CameraAddedConnection:
            Disconnect()

        WeaponShaderSettings.CameraAddedConnection =
            nil
    end

    if WeaponShaderSettings.CameraRemovedConnection then
        WeaponShaderSettings.CameraRemovedConnection:
            Disconnect()

        WeaponShaderSettings.CameraRemovedConnection =
            nil
    end

    WeaponShaderSettings.BoundCamera =
        nil
end

function BindWeaponShaderCameraSignals(CameraObject)
    if WeaponShaderSettings.BoundCamera
            == CameraObject
        and WeaponShaderSettings.CameraAddedConnection
        and WeaponShaderSettings.CameraRemovedConnection
    then
        return
    end

    DisconnectWeaponShaderCameraSignals()

    if not CameraObject then
        return
    end

    WeaponShaderSettings.BoundCamera =
        CameraObject

    local function DirtyCamera(Object)
        if not WeaponShaderSettings.Enabled then
            return
        end

        if Object:IsA("Model")
            or Object:IsA("Folder")
            or Object:IsA("Tool")
            or Object:IsA("BasePart")
        then
            WeaponShaderSettings.Dirty = true
            WeaponShaderSettings.NextRootCheck = 0

            task.defer(function()
                if WeaponShaderSettings.Enabled
                    and CameraObject
                        == GetCamera()
                then
                    RefreshWeaponShaders(true)
                end
            end)
        end
    end

    WeaponShaderSettings.CameraAddedConnection =
        CameraObject.ChildAdded:
            Connect(DirtyCamera)

    WeaponShaderSettings.CameraRemovedConnection =
        CameraObject.ChildRemoved:
            Connect(DirtyCamera)
end

function ResetWeaponShaderRespawnState()
    WeaponShaderSettings.RespawnSerial += 1

    DisconnectWeaponShaderRoots()
    DisconnectWeaponShaderCharacterSignals()

    local Textures = {}
    local Meshes = {}
    local Surfaces = {}

    for Texture in pairs(
        WeaponShaderSettings.Textures
    ) do
        Textures[#Textures + 1] =
            Texture
    end

    for Object in pairs(
        WeaponShaderSettings.MeshOriginal
    ) do
        Meshes[#Meshes + 1] =
            Object
    end

    for Surface in pairs(
        WeaponShaderSettings.SurfaceOriginal
    ) do
        Surfaces[#Surfaces + 1] =
            Surface
    end

    for _, Texture in ipairs(
        Textures
    ) do
        if Texture
            and Texture.Parent
        then
            Texture:Destroy()
        end
    end

    for _, Object in ipairs(
        Meshes
    ) do
        RestoreWeaponShaderMesh(
            Object
        )
    end

    for _, Surface in ipairs(
        Surfaces
    ) do
        RestoreWeaponShaderSurface(
            Surface
        )
    end

    WeaponShaderSettings.Textures =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.MeshOriginal =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.MeshActive =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.SurfaceOriginal =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.SurfaceActive =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.FaceTextures =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.IndexedParts =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.IndexedMeshes =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.IndexedSurfaces =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0
    WeaponShaderSettings.LastAnimate = 0
end

function RebindWeaponShadersAfterRespawn(Character)
    if not WeaponShaderSettings.Enabled
        or not Character
    then
        return
    end

    local Serial =
        WeaponShaderSettings.RespawnSerial

    BindWeaponShaderCharacterSignals(
        Character
    )

    BindWeaponShaderCameraSignals(
        GetCamera()
    )

    EnsureWeaponShaderRender()

    local Delays = {
        0,
        0.04,
        0.10,
        0.20,
        0.38,
        0.65,
        1.00
    }

    for _, Delay in ipairs(Delays) do
        task.delay(
            Delay,
            function()
                if not WeaponShaderSettings.Enabled
                    or Serial
                        ~= WeaponShaderSettings.RespawnSerial
                    or Character
                        ~= LocalPlayer.Character
                then
                    return
                end

                BindWeaponShaderCameraSignals(
                    GetCamera()
                )

                local Roots =
                    GetWeaponShaderRoots()

                if not WeaponShaderRootsEqual(
                    Roots,
                    WeaponShaderSettings.Roots
                )
                then
                    BindWeaponShaderRoots(
                        Roots
                    )
                end

                WeaponShaderSettings.NextRootCheck = 0

                if WeaponShaderSettings.Dirty then
                    RefreshWeaponShaders(
                        true
                    )
                end
            end
        )
    end
end

function DisconnectWeaponShaderLifecycle()
    if WeaponShaderSettings.CharacterAddedConnection then
        WeaponShaderSettings.CharacterAddedConnection:
            Disconnect()

        WeaponShaderSettings.CharacterAddedConnection =
            nil
    end

    if WeaponShaderSettings.CharacterRemovingConnection then
        WeaponShaderSettings.CharacterRemovingConnection:
            Disconnect()

        WeaponShaderSettings.CharacterRemovingConnection =
            nil
    end

    DisconnectWeaponShaderCharacterSignals()
    DisconnectWeaponShaderCameraSignals()
end

function BindWeaponShaderLifecycle()
    DisconnectWeaponShaderLifecycle()

    WeaponShaderSettings.CharacterAddedConnection =
        LocalPlayer.CharacterAdded:
            Connect(function(Character)
                if not WeaponShaderSettings.Enabled then
                    return
                end

                ResetWeaponShaderRespawnState()
                RebindWeaponShadersAfterRespawn(
                    Character
                )
            end)

    WeaponShaderSettings.CharacterRemovingConnection =
        LocalPlayer.CharacterRemoving:
            Connect(function()
                if not WeaponShaderSettings.Enabled then
                    return
                end

                ResetWeaponShaderRespawnState()
            end)

    if LocalPlayer.Character then
        BindWeaponShaderCharacterSignals(
            LocalPlayer.Character
        )
    end

    BindWeaponShaderCameraSignals(
        GetCamera()
    )
end

function DisconnectWeaponShaderRoots()
    for _, Connection in ipairs(
        WeaponShaderSettings.RootConnections
    ) do
        if Connection then
            Connection:Disconnect()
        end
    end

    WeaponShaderSettings.RootConnections = {}
    WeaponShaderSettings.Roots = {}

    WeaponShaderSettings.IndexedParts =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.IndexedMeshes =
        setmetatable(
            {},
            { __mode = "k" }
        )

    WeaponShaderSettings.IndexedSurfaces =
        setmetatable(
            {},
            { __mode = "k" }
        )
end

function IndexWeaponShaderObject(Object, RootData)
    if not Object
        or not RootData
        or not RootData.Root
    then
        return
    end

    if Object:IsA("BasePart") then
        if IsWeaponShaderPartAllowed(
            Object,
            RootData
        )
        then
            WeaponShaderSettings.IndexedParts[
                Object
            ] = RootData
        end

        return
    end

    if Object:IsA("SpecialMesh")
        or Object:IsA("FileMesh")
    then
        local Part =
            Object:
                FindFirstAncestorWhichIsA(
                    "BasePart"
                )

        if Part
            and IsWeaponShaderPartAllowed(
                Part,
                RootData
            )
        then
            WeaponShaderSettings.IndexedMeshes[
                Object
            ] = RootData
        end

        return
    end

    if Object:IsA("SurfaceAppearance") then
        local Part =
            Object:
                FindFirstAncestorWhichIsA(
                    "BasePart"
                )

        if Part
            and IsWeaponShaderPartAllowed(
                Part,
                RootData
            )
        then
            WeaponShaderSettings.IndexedSurfaces[
                Object
            ] = RootData
        end
    end
end

function UnindexWeaponShaderObject(Object)
    WeaponShaderSettings.IndexedParts[
        Object
    ] = nil

    WeaponShaderSettings.IndexedMeshes[
        Object
    ] = nil

    WeaponShaderSettings.IndexedSurfaces[
        Object
    ] = nil
end

function GetWeaponShaderRoots()
    local Roots = {}

    if IsViewModelFirstPerson() then
        local ViewModel =
            GetArmsViewModel()

        if ViewModel
            and ViewModel.Parent
        then
            Roots[1] = {
                Root = ViewModel,
                ViewModel = true
            }
        end

        return Roots
    end

    local Tool =
        GetWeaponShaderTarget()

    if Tool
        and Tool.Parent
    then
        Roots[1] = {
            Root = Tool,
            ViewModel = false
        }
    end

    return Roots
end

function WeaponShaderRootsEqual(A, B)
    if type(A) ~= "table"
        or type(B) ~= "table"
        or #A ~= #B
    then
        return false
    end

    for Index = 1, #A do
        if not A[Index]
            or not B[Index]
            or A[Index].Root ~= B[Index].Root
            or A[Index].ViewModel ~= B[Index].ViewModel
        then
            return false
        end
    end

    return true
end

function IsWeaponShaderPartAllowed(Part, RootData)
    if not Part
        or not Part:IsA("BasePart")
        or not RootData
        or not RootData.Root
    then
        return false
    end

    if RootData.ViewModel then
        return IsViewModelWeaponPart(
            Part,
            RootData.Root
        )
    end

    return Part:IsDescendantOf(
        RootData.Root
    )
end

function BindWeaponShaderRoots(Roots)
    DisconnectWeaponShaderRoots()

    WeaponShaderSettings.Roots =
        Roots

    for _, RootData in ipairs(Roots) do
        local Root =
            RootData.Root

        if Root
            and Root.Parent
        then
            for _, Object in ipairs(
                Root:GetDescendants()
            ) do
                IndexWeaponShaderObject(
                    Object,
                    RootData
                )
            end

            WeaponShaderSettings.RootConnections[
                #WeaponShaderSettings.RootConnections + 1
            ] =
                Root.DescendantAdded:
                    Connect(function(Object)
                        IndexWeaponShaderObject(
                            Object,
                            RootData
                        )

                        if Object:IsA("BasePart")
                            or Object:IsA("SpecialMesh")
                            or Object:IsA("FileMesh")
                            or Object:IsA("SurfaceAppearance")
                        then
                            WeaponShaderSettings.Dirty =
                                true

                            WeaponShaderSettings.NextRootCheck =
                                0
                        end
                    end)

            WeaponShaderSettings.RootConnections[
                #WeaponShaderSettings.RootConnections + 1
            ] =
                Root.DescendantRemoving:
                    Connect(function(Object)
                        UnindexWeaponShaderObject(
                            Object
                        )

                        if Object:IsA("BasePart")
                            or Object:IsA("SpecialMesh")
                            or Object:IsA("FileMesh")
                            or Object:IsA("SurfaceAppearance")
                        then
                            WeaponShaderSettings.Dirty =
                                true

                            WeaponShaderSettings.NextRootCheck =
                                0
                        end
                    end)
        end
    end

    WeaponShaderSettings.Dirty = true
end

function ApplyWeaponShaderSurface(Surface, Asset)
    if not Surface
        or not Surface.Parent
        or not Surface:IsA(
            "SurfaceAppearance"
        )
        or not Asset
    then
        return false
    end

    if WeaponShaderSettings.SurfaceOriginal[
        Surface
    ] == nil
    then
        local Original = {}

        AtramentaCallChecked(function()
            Original.ColorMap =
                Surface.ColorMap
        end)

        AtramentaCallChecked(function()
            Original.NormalMap =
                Surface.NormalMap
        end)

        AtramentaCallChecked(function()
            Original.MetalnessMap =
                Surface.MetalnessMap
        end)

        AtramentaCallChecked(function()
            Original.RoughnessMap =
                Surface.RoughnessMap
        end)

        WeaponShaderSettings.SurfaceOriginal[
            Surface
        ] = Original
    end

    AtramentaCallChecked(function()
        if Surface.ColorMap ~= Asset then
            Surface.ColorMap = Asset
        end

        if Surface.NormalMap ~= "" then
            Surface.NormalMap = ""
        end

        if Surface.MetalnessMap ~= "" then
            Surface.MetalnessMap = ""
        end

        if Surface.RoughnessMap ~= "" then
            Surface.RoughnessMap = ""
        end
    end)

    WeaponShaderSettings.SurfaceActive[
        Surface
    ] = true

    return true
end

function ApplyWeaponShaderMesh(Object, Asset)
    if not Object or not Object.Parent or not Asset then return false end
    if Object:IsA("MeshPart") then
        if WeaponShaderSettings.MeshOriginal[Object] == nil then WeaponShaderSettings.MeshOriginal[Object] = Object.TextureID end
        if Object.TextureID ~= Asset then Object.TextureID = Asset end
    elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
        if WeaponShaderSettings.MeshOriginal[Object] == nil then WeaponShaderSettings.MeshOriginal[Object] = Object.TextureId end
        if Object.TextureId ~= Asset then Object.TextureId = Asset end
    else
        return false
    end
    WeaponShaderSettings.MeshActive[Object] = true
    return true
end
function WeaponShaderPartNeedsFaceTextures(Part)
    if not Part or not Part:IsA("BasePart") then return false end
    if Part:IsA("MeshPart") or Part:IsA("UnionOperation") or Part:FindFirstChildWhichIsA("SpecialMesh") or Part:FindFirstChildWhichIsA("FileMesh") then return true end
    local Name = string.lower(Part.Name)
    if string.find(Name, "handle", 1, true) or string.find(Name, "receiver", 1, true) or string.find(Name, "slide", 1, true) or string.find(Name, "barrel", 1, true)
        or string.find(Name, "bolt", 1, true) or string.find(Name, "mag", 1, true) or string.find(Name, "stock", 1, true) or string.find(Name, "grip", 1, true)
        or string.find(Name, "trigger", 1, true) or string.find(Name, "sight", 1, true) then return true end
    return Part.Transparency < 0.98
end

function ApplyWeaponShaderFaceTextures(Part, Asset)
    if not Part
        or not Part:IsA("BasePart")
        or not Asset
    then
        return
    end

    local Map =
        WeaponShaderSettings.FaceTextures[
            Part
        ]

    if type(Map) ~= "table" then
        Map = {}

        for _, Child in ipairs(
            Part:GetChildren()
        ) do
            if Child:IsA("Texture")
                and Child.Name
                    == "AtramentaWeaponShader"
            then
                Map[Child.Face] =
                    Child

                WeaponShaderSettings.Textures[
                    Child
                ] = true
            end
        end

        WeaponShaderSettings.FaceTextures[
            Part
        ] = Map
    end

    local Tile =
        math.max(
            tonumber(
                WeaponShaderSettings.Tile
            )
                or 2.5,
            0.1
        )

    local Offset =
        WeaponShaderSettings.Time
        % 2048

    for _, Face in ipairs(
        WeaponShaderSettings.Faces
    ) do
        local Texture =
            Map[Face]

        if not Texture
            or not Texture.Parent
        then
            Texture =
                Instance.new(
                    "Texture"
                )

            Texture.Name =
                "AtramentaWeaponShader"

            Texture.Face =
                Face

            Texture.Transparency =
                0

            Texture.Color3 =
                Color3.new(
                    1,
                    1,
                    1
                )

            Texture.Parent =
                Part

            Map[Face] =
                Texture
        end

        if Texture.Texture ~= Asset then
            Texture.Texture =
                Asset
        end

        if Texture.StudsPerTileU
            ~= Tile
        then
            Texture.StudsPerTileU =
                Tile
        end

        if Texture.StudsPerTileV
            ~= Tile
        then
            Texture.StudsPerTileV =
                Tile
        end

        Texture.OffsetStudsU =
            Offset

        Texture.OffsetStudsV =
            Offset * 0.63

        WeaponShaderSettings.Textures[
            Texture
        ] = true
    end
end

function ClearWeaponShaders()
    if type(WeaponShaderSettings) ~= "table" then return end

    WeaponShaderSettings.RespawnSerial = (tonumber(WeaponShaderSettings.RespawnSerial) or 0) + 1

    local RenderName = WeaponShaderSettings.RenderName
    if type(RenderName) == "string" and RenderName ~= "" then
        RunService:UnbindFromRenderStep(RenderName)
    end
    WeaponShaderSettings.RenderName = nil

    if type(DisconnectWeaponShaderLifecycle) == "function" then DisconnectWeaponShaderLifecycle() end
    if type(DisconnectWeaponShaderRoots) == "function" then DisconnectWeaponShaderRoots() end
    if type(DisconnectWeaponShaderCharacterSignals) == "function" then DisconnectWeaponShaderCharacterSignals() end
    if type(DisconnectWeaponShaderCameraSignals) == "function" then DisconnectWeaponShaderCameraSignals() end

    local Textures = {}
    local Meshes = {}
    local Surfaces = {}

    if type(WeaponShaderSettings.Textures) == "table" then
        for Texture in pairs(WeaponShaderSettings.Textures) do Textures[#Textures + 1] = Texture end
    end

    if type(WeaponShaderSettings.MeshOriginal) == "table" then
        for Object in pairs(WeaponShaderSettings.MeshOriginal) do Meshes[#Meshes + 1] = Object end
    end

    if type(WeaponShaderSettings.SurfaceOriginal) == "table" then
        for Surface in pairs(WeaponShaderSettings.SurfaceOriginal) do Surfaces[#Surfaces + 1] = Surface end
    end

    for Index = 1, #Textures do
        local Texture = Textures[Index]
        if Texture and Texture.Parent then Texture:Destroy() end
    end

    for Index = 1, #Meshes do
        local Object = Meshes[Index]
        if type(RestoreWeaponShaderMesh) == "function" then RestoreWeaponShaderMesh(Object) end
    end

    for Index = 1, #Surfaces do
        local Surface = Surfaces[Index]
        if type(RestoreWeaponShaderSurface) == "function" then RestoreWeaponShaderSurface(Surface) end
    end

    WeaponShaderSettings.Textures = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.MeshOriginal = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.MeshActive = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.SurfaceOriginal = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.SurfaceActive = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.FaceTextures = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedParts = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedMeshes = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedSurfaces = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.Roots = {}
    WeaponShaderSettings.RootConnections = {}
    WeaponShaderSettings.CharacterConnections = {}
    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.BoundCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0
    WeaponShaderSettings.LastAnimate = 0
    WeaponShaderSettings.Time = 0
end

function RefreshWeaponShaderAppearance()
    if not WeaponShaderSettings.Enabled then
        return
    end

    local Asset =
        WeaponShaderSettings.Assets[
            WeaponShaderSettings.Preset
        ]
        or WeaponShaderSettings.Assets.Galaxy

    local Tile =
        math.max(
            tonumber(
                WeaponShaderSettings.Tile
            )
                or 2.5,
            0.1
        )

    for Texture in pairs(
        WeaponShaderSettings.Textures
    ) do
        if Texture
            and Texture.Parent
        then
            if Texture.Texture
                ~= Asset
            then
                Texture.Texture =
                    Asset
            end

            if Texture.StudsPerTileU
                ~= Tile
            then
                Texture.StudsPerTileU =
                    Tile
            end

            if Texture.StudsPerTileV
                ~= Tile
            then
                Texture.StudsPerTileV =
                    Tile
            end
        end
    end

    for Object in pairs(
        WeaponShaderSettings.MeshActive
    ) do
        if Object
            and Object.Parent
        then
            ApplyWeaponShaderMesh(
                Object,
                Asset
            )
        end
    end

    for Surface in pairs(
        WeaponShaderSettings.SurfaceActive
    ) do
        if Surface
            and Surface.Parent
        then
            ApplyWeaponShaderSurface(
                Surface,
                Asset
            )
        end
    end
end

function RefreshWeaponShaders(Force)
    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        return
    end

    local Roots =
        GetWeaponShaderRoots()

    if not WeaponShaderRootsEqual(
        Roots,
        WeaponShaderSettings.Roots
    )
    then
        BindWeaponShaderRoots(
            Roots
        )

        Force = true
    end

    if not Force
        and not WeaponShaderSettings.Dirty
    then
        return
    end

    WeaponShaderSettings.Dirty = false

    local Asset =
        WeaponShaderSettings.Assets[
            WeaponShaderSettings.Preset
        ]
        or WeaponShaderSettings.Assets.Galaxy

    local ActiveParts = {}
    local ActiveTextures = {}
    local ActiveMeshes = {}
    local ActiveSurfaces = {}

    for Part, RootData in pairs(
        WeaponShaderSettings.IndexedParts
    ) do
        if Part
            and Part.Parent
            and IsWeaponShaderPartAllowed(
                Part,
                RootData
            )
        then
            ActiveParts[Part] =
                true

            if Part:IsA("MeshPart")
                and ApplyWeaponShaderMesh(
                    Part,
                    Asset
                )
            then
                ActiveMeshes[Part] =
                    true
            end

            if WeaponShaderPartNeedsFaceTextures(
                Part
            )
            then
                ApplyWeaponShaderFaceTextures(
                    Part,
                    Asset
                )
            end
        end
    end

    for Object, RootData in pairs(
        WeaponShaderSettings.IndexedMeshes
    ) do
        if Object
            and Object.Parent
        then
            local Part =
                Object:
                    FindFirstAncestorWhichIsA(
                        "BasePart"
                    )

            if Part
                and IsWeaponShaderPartAllowed(
                    Part,
                    RootData
                )
                and ApplyWeaponShaderMesh(
                    Object,
                    Asset
                )
            then
                ActiveMeshes[Object] =
                    true
            end
        end
    end

    for Surface, RootData in pairs(
        WeaponShaderSettings.IndexedSurfaces
    ) do
        if Surface
            and Surface.Parent
        then
            local Part =
                Surface:
                    FindFirstAncestorWhichIsA(
                        "BasePart"
                    )

            if Part
                and IsWeaponShaderPartAllowed(
                    Part,
                    RootData
                )
                and ApplyWeaponShaderSurface(
                    Surface,
                    Asset
                )
            then
                ActiveSurfaces[
                    Surface
                ] = true
            end
        end
    end

    for Texture in pairs(
        WeaponShaderSettings.Textures
    ) do
        if Texture
            and Texture.Parent
            and ActiveParts[
                Texture.Parent
            ]
        then
            ActiveTextures[
                Texture
            ] = true
        end
    end

    local StaleTextures = {}
    local StaleMeshes = {}
    local StaleSurfaces = {}

    for Texture in pairs(
        WeaponShaderSettings.Textures
    ) do
        if not ActiveTextures[
            Texture
        ]
        then
            StaleTextures[
                #StaleTextures + 1
            ] = Texture
        end
    end

    for Object in pairs(
        WeaponShaderSettings.MeshOriginal
    ) do
        if not ActiveMeshes[
            Object
        ]
        then
            StaleMeshes[
                #StaleMeshes + 1
            ] = Object
        end
    end

    for Surface in pairs(
        WeaponShaderSettings.SurfaceOriginal
    ) do
        if not ActiveSurfaces[
            Surface
        ]
        then
            StaleSurfaces[
                #StaleSurfaces + 1
            ] = Surface
        end
    end

    for _, Texture in ipairs(
        StaleTextures
    ) do
        if Texture
            and Texture.Parent
        then
            Texture:Destroy()
        end

        WeaponShaderSettings.Textures[
            Texture
        ] = nil
    end

    for _, Object in ipairs(
        StaleMeshes
    ) do
        RestoreWeaponShaderMesh(
            Object
        )
    end

    for _, Surface in ipairs(
        StaleSurfaces
    ) do
        RestoreWeaponShaderSurface(
            Surface
        )
    end
end

function EnsureWeaponShaderRender()
    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        return
    end

    if WeaponShaderSettings.RenderName then
        return
    end

    local RenderName =
        "AtramentaWeaponShaders_"
        .. tostring(
            LocalPlayer.UserId
        )

    WeaponShaderSettings.RenderName =
        RenderName

    RunService:UnbindFromRenderStep(
        RenderName
    )

    RunService:BindToRenderStep(
        RenderName,
        Enum.RenderPriority.Last.Value + 210,
        function(DeltaTime)
            if not WeaponShaderSettings.Enabled then
                return
            end

            local CurrentTime =
                os.clock()

            local CameraObject =
                GetCamera()

            local FirstPerson =
                IsViewModelFirstPerson()

            local CameraChanged =
                WeaponShaderSettings.LastCamera
                    ~= CameraObject

            local PerspectiveChanged =
                WeaponShaderSettings.LastFirstPerson
                    ~= FirstPerson

            if CameraChanged then
                WeaponShaderSettings.LastCamera =
                    CameraObject

                BindWeaponShaderCameraSignals(
                    CameraObject
                )
            end

            if PerspectiveChanged then
                WeaponShaderSettings.LastFirstPerson =
                    FirstPerson
            end

            if CameraChanged
                or PerspectiveChanged
            then
                WeaponShaderSettings.Dirty = true
                WeaponShaderSettings.NextRootCheck = 0
            end


            WeaponShaderSettings.Time +=
                DeltaTime
                * math.max(
                    tonumber(
                        WeaponShaderSettings.Speed
                    )
                        or 1,
                    0.01
                )

            local ViewModel =
                FirstPerson
                and GetArmsViewModel()
                or nil

            local RootInterval =
                FirstPerson
                and not ViewModel
                and 0.04
                or (
                    WeaponShaderSettings.RootCheckInterval
                    or 0.18
                )

            if CurrentTime
                >= (
                    WeaponShaderSettings.NextRootCheck
                    or 0
                )
            then
                WeaponShaderSettings.NextRootCheck =
                    CurrentTime
                    + RootInterval

                local Roots =
                    GetWeaponShaderRoots()

                if not WeaponShaderRootsEqual(
                    Roots,
                    WeaponShaderSettings.Roots
                )
                then
                    BindWeaponShaderRoots(
                        Roots
                    )
                end

                if WeaponShaderSettings.Dirty then
                    RefreshWeaponShaders(true)
                end
            end

            if CurrentTime
                - (
                    WeaponShaderSettings.LastAnimate
                    or 0
                )
                < (
                    WeaponShaderSettings.AnimateInterval
                    or 1 / 30
                )
            then
                return
            end

            WeaponShaderSettings.LastAnimate =
                CurrentTime

            local Offset =
                WeaponShaderSettings.Time
                % 2048

            local Dead = nil

            for Texture in pairs(
                WeaponShaderSettings.Textures
            ) do
                if Texture
                    and Texture.Parent
                then
                    Texture.OffsetStudsU =
                        Offset

                    Texture.OffsetStudsV =
                        Offset * 0.63
                else
                    Dead =
                        Dead
                        or {}

                    Dead[
                        #Dead + 1
                    ] = Texture
                end
            end

            if Dead then
                for _, Texture in ipairs(
                    Dead
                ) do
                    WeaponShaderSettings.Textures[
                        Texture
                    ] = nil
                end
            end
        end
    )
end

function SetWeaponShaderEnabled(Value)
    if type(WeaponShaderSettings) ~= "table" then return end
    WeaponShaderSettings.Enabled = Value == true

    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        return
    end

    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0

    if type(BindWeaponShaderLifecycle) == "function" then BindWeaponShaderLifecycle() end
    if type(EnsureWeaponShaderRender) == "function" then EnsureWeaponShaderRender() end

    local Character = LocalPlayer and LocalPlayer.Character
    if Character and Character.Parent then
        if type(RebindWeaponShadersAfterRespawn) == "function" then RebindWeaponShadersAfterRespawn(Character) end
    elseif type(RefreshWeaponShaders) == "function" then
        RefreshWeaponShaders(true)
    end
end

function ApplyWeaponChams()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
    if WeaponShaderSettings.Enabled then WeaponShaderSettings.Dirty = true; RefreshWeaponShaders(true) end
end

function RestoreWeaponChams()
    RestoreViewModelChams(
        "Weapon"
    )
end

function SyncWeaponChams()
    UpdateViewModelChams()
end

function PurgeLegacyWeaponChams()
end

function WeaponChamsEnable()
    WeaponChamsEnabled = true
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
end

function WeaponChamsDisable()
    WeaponChamsEnabled = false
    RestoreWeaponChams()
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
end

function GetFinishAuraTarget(LocalRoot)
    if not LocalRoot then return nil end

    local CharStats =
        ReplicatedStorage:
            FindFirstChild(
                "CharStats"
            )

    local ClosestCharacter = nil
    local ClosestDistance =
        math.clamp(
            tonumber(FinishAuraDistance) or 15,
            1,
            15
        )

    local BestTier = -1

    for _, PlayerObject in ipairs(
        Players:GetPlayers()
    ) do
        if not IsAtramentaCombatTargetAllowed(
            PlayerObject
        ) then
            continue
        end

        local Character =
            PlayerObject.Character

        local Root =
            Character
            and Character:
                FindFirstChild(
                    "HumanoidRootPart"
                )

        local Head =
            Character
            and Character:
                FindFirstChild(
                    "Head"
                )

        local Humanoid =
            Character
            and Character:
                FindFirstChildOfClass(
                    "Humanoid"
                )

        local Stats =
            CharStats
            and CharStats:
                FindFirstChild(
                    PlayerObject.Name
                )

        local Downed =
            Stats
            and Stats:
                FindFirstChild(
                    "Downed"
                )

        if Root
            and Head
            and Humanoid
            and Humanoid.Health > 0
            and Downed
            and Downed.Value == true
            and not Character:
                FindFirstChildOfClass(
                    "ForceField"
                )
        then
            local Distance =
                (
                    LocalRoot.Position
                    - Root.Position
                ).Magnitude

            local Tier =
                GetAtramentaCombatTargetTier(
                    PlayerObject
                )

            if Distance <= FinishAuraDistance
                and (
                    Tier > BestTier
                    or Tier == BestTier
                        and Distance < ClosestDistance
                )
            then
                BestTier = Tier
                ClosestDistance = Distance
                ClosestCharacter = Character
            end
        end
    end

    return ClosestCharacter
end

function ExecuteFinishAura(TargetCharacter)
    if FinishAuraBusy
        or not FinishAuraEnabled
        or not TargetCharacter
    then
        return
    end

    local Character = LocalPlayer.Character
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    local RightLeg = Character and (
        Character:FindFirstChild("Right Leg")
        or Character:FindFirstChild("RightLowerLeg")
        or Character:FindFirstChild("RightFoot")
    )
    local TargetHead = TargetCharacter:FindFirstChild("Head")

    local Events = ReplicatedStorage:FindFirstChild("Events")
    local InvokeRemote = Events and Events:FindFirstChild("XMHH.2")
    local FireRemote = Events and Events:FindFirstChild("XMHH2.2")

    if not Character
        or not Tool
        or not RightLeg
        or not TargetHead
        or not InvokeRemote
        or not FireRemote
    then
        return
    end

    FinishAuraBusy = true

    task.spawn(function()
        local Success, InvokeResult = AtramentaCallChecked(function()
            return InvokeRemote:InvokeServer(
                "\240\159\141\158",
                tick(),
                Tool,
                "EXECQX"
            )
        end)

        if Success
            and InvokeResult
            and FinishAuraEnabled
            and TargetCharacter.Parent
            and TargetHead.Parent
        then
            task.wait(0.25)

            if FinishAuraEnabled
                and Tool.Parent
                and TargetCharacter.Parent
                and TargetHead.Parent
            then
                AtramentaCallChecked(function()
                    FireRemote:FireServer(
                        "\240\159\141\158",
                        tick(),
                        Tool,
                        "2389ZFX34",
                        InvokeResult,
                        false,
                        RightLeg,
                        TargetHead,
                        TargetCharacter,
                        TargetHead.Position,
                        TargetHead.Position
                    )
                end)
            end
        end

        FinishAuraBusy = false
    end)
end

function FinishAuraEnable()
    if FinishAuraEnabled then return end

    FinishAuraEnabled = true
    FinishAuraBusy = false

    if FinishAuraConnection then
        FinishAuraConnection:Disconnect()
        FinishAuraConnection = nil
    end

    FinishAuraConnection = RunService.RenderStepped:Connect(function()
        if not FinishAuraEnabled or FinishAuraBusy then
            return
        end

        local Character = LocalPlayer.Character
        local Root = Character and Character:FindFirstChild("HumanoidRootPart")
        local Tool = Character and Character:FindFirstChildOfClass("Tool")

        if not Root or not Tool then
            return
        end

        local TargetCharacter = GetFinishAuraTarget(Root)
        if TargetCharacter then
            ExecuteFinishAura(TargetCharacter)
        end
    end)
end

function FinishAuraDisable()
    FinishAuraEnabled = false
    FinishAuraBusy = false

    if FinishAuraConnection then
        FinishAuraConnection:Disconnect()
        FinishAuraConnection = nil
    end
end


