        State.Patches = {}
        State.DisabledConnections = {}
        State.PatchLookup = setmetatable({}, { __mode = "k" })
        State.ConnectionLookup = setmetatable({}, { __mode = "k" })
        StepGarbageCollector()
    end
    local function ApplyNoFallCharacterState()
        if not NoFallDamageEnabled then return end
        local Character = LocalPlayer.Character
        if not Character then return end
        local CharacterStats = Character:FindFirstChild("CharStats")
        if not CharacterStats then return end
        local PlayerStats = CharacterStats:FindFirstChild(LocalPlayer.Name)
            or CharacterStats:FindFirstChild(tostring(LocalPlayer.UserId))
            or CharacterStats
        local RagdollSwitch = PlayerStats:FindFirstChild("RagdollSwitch")
            or CharacterStats:FindFirstChild("RagdollSwitch", true)
        local RagdollTime = PlayerStats:FindFirstChild("RagdollTime")
            or CharacterStats:FindFirstChild("RagdollTime", true)
        if RagdollSwitch and RagdollSwitch:IsA("BoolValue") then
            RagdollSwitch.Value = false
        end
        if RagdollTime and (RagdollTime:IsA("NumberValue") or RagdollTime:IsA("IntValue")) then
            RagdollTime.Value = 0
        end
    end
    function NoFallDamageEnable()
        if NoFallDamageEnabled then return end
        NoFallDamageEnabled = true
        local Environment = type(getgenv) == "function" and getgenv() or _G
        Environment.CV2_NoFall = true
        if type(InstallAtramentaSharedNamecallRouter) == "function" then
            InstallAtramentaSharedNamecallRouter()
        end
        if State.CharacterConnection then
            State.CharacterConnection:Disconnect()
            State.CharacterConnection = nil
        end
        State.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function()
            ApplyNoFallCharacterState()
        end)
        if State.HeartbeatConnection then
            State.HeartbeatConnection:Disconnect()
            State.HeartbeatConnection = nil
        end
        State.HeartbeatConnection = RunService.Heartbeat:Connect(function()
            if not NoFallDamageEnabled then return end
            Environment.CV2_NoFall = true
            ApplyNoFallCharacterState()
        end)
        ApplyNoFallCharacterState()
    end
    function NoFallDamageDisable()
        if not NoFallDamageEnabled then return end
        NoFallDamageEnabled = false
        local Environment = type(getgenv) == "function" and getgenv() or _G
        Environment.CV2_NoFall = false
        if State.CharacterConnection then
            State.CharacterConnection:Disconnect()
            State.CharacterConnection = nil
        end
        if State.HeartbeatConnection then
            State.HeartbeatConnection:Disconnect()
            State.HeartbeatConnection = nil
        end
    end
end)()

local ProtectionDescendantConnection = nil
function EnsureProtectionDescendantHook()
    if ProtectionDescendantConnection then return end
    ProtectionDescendantConnection = workspace.DescendantAdded:Connect(function(obj)
        if AntiFlashbangEnabled then
            if obj:IsA("BlurEffect") or obj:IsA("ColorCorrectionEffect") or obj.Name == "BlindEffect" then
                task.defer(function()
                    if obj and obj.Parent then obj.Enabled = false end
                end)
            end
        end
        if AntiSmokeEnabled then
            if obj.Name == "Smoke" or obj.Name == "SmokeExplosion" then
                task.defer(function()
                    if obj and obj.Parent then obj:Destroy() end
                end)
            end
        end
    end)
end

function AntiFlashbangEnable()
    AntiFlashbangEnabled = true
    EnsureProtectionDescendantHook()
end
function AntiFlashbangDisable()
    AntiFlashbangEnabled = false
end
function AntiSmokeEnable()
    AntiSmokeEnabled = true
    EnsureProtectionDescendantHook()
end
function AntiSmokeDisable()
    AntiSmokeEnabled = false
end
function AntiBarbwireEnable()
    AntiBarbwireEnabled = true
    local Environment = type(getgenv) == "function" and getgenv() or _G
    Environment.AtramentaAntiBarrier = true
    if type(InstallAtramentaSharedNamecallRouter) == "function" then InstallAtramentaSharedNamecallRouter() end
end

function AntiBarbwireDisable()
    AntiBarbwireEnabled = false
    local Environment = type(getgenv) == "function" and getgenv() or _G
    Environment.AtramentaAntiBarrier = false
end

PepperAuraLastHit = PepperAuraLastHit or setmetatable({}, { __mode = "k" })
PepperAuraLastTick = tonumber(PepperAuraLastTick) or 0
PepperAuraSpraying = PepperAuraSpraying == true
PepperAuraTickRate = 0.12
PepperAuraHitRate = 0.30

function PepperAuraEnable()
    if PepperAuraEnabled then
        return
    end

    PepperAuraEnabled = true

    if PepperAuraConnection then
        PepperAuraConnection:Disconnect()
        PepperAuraConnection = nil
    end

    PepperAuraConnection =
        RunService.Heartbeat:Connect(
            function()
                if not PepperAuraEnabled then
                    return
                end

                local Now =
                    os.clock()

                if Now - PepperAuraLastTick
                    < PepperAuraTickRate
                then
                    return
                end

                PepperAuraLastTick =
                    Now

                local Character =
                    LocalPlayer.Character

                local Root =
                    Character
                    and Character:
                        FindFirstChild(
                            "HumanoidRootPart"
                        )

                local Pepper =
                    Character
                    and Character:
                        FindFirstChild(
                            "Pepper-spray"
                        )

                local Remote =
                    Pepper
                    and Pepper:
                        FindFirstChild(
                            "RemoteEvent"
                        )

                if not Root
                    or not Pepper
                    or not Remote
                    or not Remote:IsA("RemoteEvent")
                then
                    PepperAuraSpraying =
                        false

                    return
                end

                if PepperAuraInfinite then
                    local Ammo =
                        Pepper:
                            FindFirstChild(
                                "Ammo"
                            )

                    if Ammo then
                        Ammo.Value = 100
                    end
                end

                local MaximumDistance =
                    math.clamp(
                        tonumber(
                            PepperAuraDistance
                        )
                        or 15,
                        1,
                        15
                    )

                local Targets = {}

                for _, PlayerObject in ipairs(
                    Players:GetPlayers()
                ) do
                    if IsAtramentaCombatTargetAllowed(PlayerObject) then
                        local TargetCharacter =
                            PlayerObject.Character

                        local TargetRoot =
                            TargetCharacter
                            and TargetCharacter:
                                FindFirstChild(
                                    "HumanoidRootPart"
                                )

                        local Humanoid =
                            TargetCharacter
                            and TargetCharacter:
                                FindFirstChildOfClass(
                                    "Humanoid"
                                )

                        if TargetRoot
                            and Humanoid
                            and Humanoid.Health > 0
                            and not TargetCharacter:
                                GetAttribute(
                                    "Downed"
                                )
                            and (
                                Root.Position
                                - TargetRoot.Position
                            ).Magnitude
                                <= MaximumDistance
                        then
                            Targets[
                                #Targets + 1
                            ] =
                                TargetCharacter
                        end
                    end
                end

                local HasTarget =
                    #Targets > 0

                if HasTarget
                    and not PepperAuraSpraying
                then
                    Remote:FireServer(
                        "Spray",
                        true
                    )

                    PepperAuraSpraying =
                        true
                elseif not HasTarget
                    and PepperAuraSpraying
                then
                    Remote:FireServer(
                        "Spray",
                        false
                    )

                    PepperAuraSpraying =
                        false
                end

                for _, TargetCharacter in ipairs(
                    Targets
                ) do
                    local LastHit =
                        tonumber(
                            PepperAuraLastHit[
                                TargetCharacter
                            ]
                        )
                        or 0

                    if Now - LastHit
                        >= PepperAuraHitRate
                    then
                        PepperAuraLastHit[
                            TargetCharacter
                        ] =
                            Now

                        Remote:FireServer(
                            "Hit",
                            TargetCharacter
                        )
                    end
                end
            end
        )
end

function PepperAuraDisable()
    PepperAuraEnabled = false

    if PepperAuraConnection then
        PepperAuraConnection:Disconnect()
        PepperAuraConnection = nil
    end

    if PepperAuraSpraying then
        local Character =
            LocalPlayer.Character

        local Pepper =
            Character
            and Character:
                FindFirstChild(
                    "Pepper-spray"
                )

        local Remote =
            Pepper
            and Pepper:
                FindFirstChild(
                    "RemoteEvent"
                )

        if Remote
            and Remote:IsA("RemoteEvent")
        then
            Remote:FireServer(
                "Spray",
                false
            )
        end
    end

    PepperAuraSpraying = false
    PepperAuraLastHit =
        setmetatable({}, { __mode = "k" })
end


