RageWeaponConfigCache = RageWeaponConfigCache or setmetatable({}, {__mode = "k"})
RageFireRateOriginal = RageFireRateOriginal or setmetatable({}, {__mode = "k"})

function GetRageWeaponConfig(Tool)
    if not Tool then return nil end
    local Cached = RageWeaponConfigCache[Tool]
    if type(Cached) == "table" then return Cached end
    local ConfigModule = Tool:FindFirstChild("Config")
    if not ConfigModule or not ConfigModule:IsA("ModuleScript") then return nil end
    local Success, Config = AtramentaCallChecked(require, ConfigModule)
    if Success and type(Config) == "table" then
        RageWeaponConfigCache[Tool] = Config
        return Config
    end
    return nil
end

function RageBotAPI.GetServerTimestamp(Tool, Config)
    Config = type(Config) == "table" and Config or GetRageWeaponConfig(Tool)
    local SharedValues = ReplicatedStorage:FindFirstChild("Values")
    local ServerTick = SharedValues and SharedValues:FindFirstChild("ServerTick")

    if ServerTick and typeof(ServerTick.Value) == "number" then
        local Salt = type(Config) == "table" and tonumber(Config.IntSalt or Config.Salt) or nil
        if Salt then return ServerTick.Value - Salt end
        return ServerTick.Value
    end

    local ToolValues = Tool and Tool:FindFirstChild("Values")
    local ToolServerTick = ToolValues and ToolValues:FindFirstChild("ServerTick")
    if ToolServerTick and typeof(ToolServerTick.Value) == "number" then return ToolServerTick.Value end
    return tick()
end

function GetRageProtocolTimestamp(Tool)
    return RageBotAPI.GetServerTimestamp(Tool, GetRageWeaponConfig(Tool))
end

function RageBotAPI.GetRageRemoteKey(Tool, Config)
    local Value = RageBotAPI.GetServerTimestamp(Tool, Config)
    return typeof(Value) == "number" and Value or tick()
end

function GetRageCharacter(Player)
    if not Player then return nil end
    if type(ResolveTrackedCharacter) == "function" then
        local Character = ResolveTrackedCharacter(Player, Player.Character)
        if Character then return Character end
    end
    return Player.Character
end

function GetRageRootPart(Character)
    if not Character then return nil end
    return Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
end

function ResetRageReloadState(Tool)
    RageReloadState.Tool = Tool
end

function RageBotAPI.RageRandomString(Length)
    local Characters = table.create(Length)
    for Index = 1, Length do Characters[Index] = string.char(math.random(65, 122)) end
    return table.concat(Characters)
end

function GetClosestPlayerToMouse(PartName)
    local Camera = workspace.CurrentCamera
    if not Camera then return {math.huge, nil} end

    local CurrentMouse = LocalPlayer:GetMouse()
    local MousePosition = Vector2.new(CurrentMouse.X, CurrentMouse.Y)
    local ClosestDistance = math.huge
    local ClosestPlayer = nil
    local ClosestUserId = math.huge
    local CharStats = getgenv().DownedCheck ~= false and ReplicatedStorage:FindFirstChild("CharStats") or nil

    for _, Player in ipairs(Players:GetPlayers()) do
        if Player == LocalPlayer then continue end

        local ScreenCharacter = Player.Character or GetRageCharacter(Player)
        local TargetCharacter = GetRageCharacter(Player) or ScreenCharacter
        local Humanoid = TargetCharacter and TargetCharacter:FindFirstChildOfClass("Humanoid")
        local RootPart = ScreenCharacter and (ScreenCharacter:FindFirstChild("HumanoidRootPart") or ScreenCharacter:FindFirstChild("Torso") or ScreenCharacter:FindFirstChild("UpperTorso"))
        local AimPart = TargetCharacter and TargetCharacter:FindFirstChild(PartName)
        if not Humanoid or Humanoid.Health <= 0 or not RootPart or not RootPart:IsA("BasePart") or not AimPart or not AimPart:IsA("BasePart") then continue end
        if TargetCharacter:FindFirstChildWhichIsA("ForceField") then continue end

        local PlayerStats = CharStats and CharStats:FindFirstChild(Player.Name)
        local Downed = PlayerStats and PlayerStats:FindFirstChild("Downed")
        if getgenv().DownedCheck ~= false and Downed and Downed.Value == true then continue end

        local ScreenPosition, OnScreen = Camera:WorldToScreenPoint(RootPart.Position)
        if not OnScreen or ScreenPosition.Z <= 0 then continue end

        local Distance = (MousePosition - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
        local UserId = tonumber(Player.UserId) or math.huge
        if Distance < ClosestDistance - 0.001 or (math.abs(Distance - ClosestDistance) <= 0.001 and UserId < ClosestUserId) then
            ClosestDistance = Distance
            ClosestPlayer = Player
            ClosestUserId = UserId
        end
    end

    return {ClosestDistance, ClosestPlayer}
end

