if #RageCrimEngine.SphereTemplate ~= RageCrimEngine.SphereCount then
    table.clear(RageCrimEngine.SphereTemplate)
    for Index = 1, RageCrimEngine.SphereCount do
        local Y = 1 - 2 * ((Index - 0.5) / RageCrimEngine.SphereCount)
        local Radius = math.sqrt(math.max(0, 1 - Y * Y))
        local Angle = Index * RageCrimEngine.GoldenAngle
        RageCrimEngine.SphereTemplate[Index] = Vector3.new(
            math.cos(Angle) * Radius,
            Y,
            math.sin(Angle) * Radius
        )
    end
end

if #RageCrimEngine.SpiralTemplate ~= RageCrimEngine.SpiralCount then
    table.clear(RageCrimEngine.SpiralTemplate)
    for Index = 1, RageCrimEngine.SpiralCount do
        local T = Index / RageCrimEngine.SpiralCount
        local Angle = Index * RageCrimEngine.GoldenAngle
        local Radius = math.sqrt(T)
        local Axial = (T - 0.5) * 0.34
        local Sample = Vector3.new(math.cos(Angle) * Radius, math.sin(Angle) * Radius, Axial)
        if Sample.Magnitude > 1 then Sample = Sample.Unit end
        RageCrimEngine.SpiralTemplate[Index] = Sample
    end
end

if #RageCrimEngine.RingTemplate ~= #RageCrimEngine.RingLevels * RageCrimEngine.RingCount then
    table.clear(RageCrimEngine.RingTemplate)
    for LevelIndex = 1, #RageCrimEngine.RingLevels do
        local Radius = RageCrimEngine.RingLevels[LevelIndex]
        for Index = 1, RageCrimEngine.RingCount do
            local Angle = ((Index - 1) / RageCrimEngine.RingCount) * math.pi * 2 + LevelIndex * RageCrimEngine.GoldenAngle * 0.25
            local Axial = ((Index - 1) % 3 - 1) * 0.06 * (1 - Radius * 0.35)
            local Sample = Vector3.new(math.cos(Angle) * Radius, math.sin(Angle) * Radius, Axial)
            if Sample.Magnitude > 1 then Sample = Sample.Unit end
            RageCrimEngine.RingTemplate[#RageCrimEngine.RingTemplate + 1] = Sample
        end
    end
end

