    if type(Flags) == "table" then
        if Flags["Rage Magic Bullet"] ~= nil then RageBotSettings.MagicBullet = Flags["Rage Magic Bullet"] == true end
        if Flags["Rage Prediction"] ~= nil then RageBotSettings.Prediction = math.clamp(tonumber(Flags["Rage Prediction"]) or 72, 0, 400) end
        if Flags["Rage Prediction Divisor X"] ~= nil then RageBotSettings.PredictionDivisorX = math.max(tonumber(Flags["Rage Prediction Divisor X"]) or 1, 0.1) end
        if Flags["Rage Prediction Divisor Y"] ~= nil then RageBotSettings.PredictionDivisorY = math.max(tonumber(Flags["Rage Prediction Divisor Y"]) or 1.05, 0.1) end
    end

    RageBotSettings.TargetPart = "Head"
    RageBotSettings.OriginMode = "Root"
    RageBotSettings.WallbangOriginDistance = RageCrimEngine.PreferredOriginDistance
