    if getgenv().DownedCheck == nil then getgenv().DownedCheck = true end
end

function RageBotAPI.GetRageBaseOrigin(LocalRoot)
    return LocalRoot and LocalRoot.Position or nil
end

function RageBotAPI.CriminologyGetDirectionBasisFromPositions(Origin, Target)
    local Forward = Target - Origin
    if Forward.Magnitude <= 0.001 then Forward = Vector3.new(0, 0, -1) else Forward = Forward.Unit end

    local Reference = math.abs(Forward.Y) > 0.93 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
    local Right = Forward:Cross(Reference)
    if Right.Magnitude <= 0.001 then Right = Vector3.new(1, 0, 0) else Right = Right.Unit end

    local Up = Right:Cross(Forward)
    if Up.Magnitude <= 0.001 then Up = Vector3.new(0, 1, 0) else Up = Up.Unit end
    return Forward, Right, Up
end

function RageBotAPI.CriminologyOriginDirections(BaseOrigin, TargetPosition)
    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(BaseOrigin, TargetPosition)
    return {
        Right, -Right, Up, -Up,
        (Right + Up).Unit, (Right - Up).Unit,
        (-Right + Up).Unit, (-Right - Up).Unit,
        Forward, -Forward
    }
end

function RageSetExpectedTarget(TargetPart, Position)
    if TargetPart and typeof(Position) == "Vector3" then
        RageWallbangRuntime.ExpectedTarget[TargetPart] = {Position = Position, Time = os.clock()}
    end
end

function RageGetExpectedTarget(TargetPart)
    local Data = TargetPart and RageWallbangRuntime.ExpectedTarget[TargetPart]
    if type(Data) == "table" and typeof(Data.Position) == "Vector3" and os.clock() - (tonumber(Data.Time) or 0) <= 0.30 then
        return Data.Position
    end
    return TargetPart and TargetPart.Position or nil
end

function RagePointInsideExpectedHitbox(TargetPart, Position)
    if not TargetPart or typeof(Position) ~= "Vector3" then return false end
    local Center = RageGetExpectedTarget(TargetPart) or TargetPart.Position
    local LocalPosition = TargetPart.CFrame:PointToObjectSpace(Position - Center + TargetPart.Position)
    local Half = TargetPart.Size * 0.5 + Vector3.new(0.18, 0.18, 0.18)
    return math.abs(LocalPosition.X) <= Half.X and math.abs(LocalPosition.Y) <= Half.Y and math.abs(LocalPosition.Z) <= Half.Z
end

function RageCrimEngine.RefreshRayParams()
    local Ignore = {}
    local Character = LocalPlayer.Character
    local Characters = workspace:FindFirstChild("Characters")
    local Debris = workspace:FindFirstChild("Debris")

    if Character then Ignore[#Ignore + 1] = Character end
    if Characters then Ignore[#Ignore + 1] = Characters end
    if Debris then Ignore[#Ignore + 1] = Debris end

    RageCrimEngine.RayParams.FilterDescendantsInstances = Ignore
    return RageCrimEngine.RayParams
end

function RageCrimEngine.RayCheckDetailed(Origin, HitPosition, TargetPart)
    if typeof(Origin) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then
        return false, nil
    end

    local Delta = HitPosition - Origin
    local Distance = Delta.Magnitude
    if Distance <= 0.001 then return true, nil end

    local Params = RageCrimEngine.RefreshRayParams()
    local Result = workspace:Raycast(Origin, Delta, Params)

    if not Result then return true, nil end

    if TargetPart and Result.Instance and Result.Instance:IsDescendantOf(TargetPart.Parent) then
        return true, Result
    end

    local Direction = Delta.Unit
    local RetryOrigin = Origin + Direction * 0.035
    local RetryDelta = HitPosition - RetryOrigin

    if RetryDelta.Magnitude > 0.001 then
        local Retry = workspace:Raycast(RetryOrigin, RetryDelta, Params)

        if not Retry then return true, nil end

        if TargetPart and Retry.Instance and Retry.Instance:IsDescendantOf(TargetPart.Parent) then
            return true, Retry
        end

        if Retry.Instance and Retry.Instance:IsA("BasePart") then
            return false, Retry
        end
    end

    return false, Result
end

function RageCrimEngine.RayCheck(Origin, HitPosition, TargetPart)
    local Clear = RageCrimEngine.RayCheckDetailed(
        Origin,
        HitPosition,
        TargetPart
    )

    return Clear == true
end

function RageRayCheck(LocalPlayerObject, Origin, HitPosition, TargetPart)
    return RageCrimEngine.RayCheck(Origin, HitPosition, TargetPart)
end

function RageBotAPI.RefreshRageRayParams()
    return RageCrimEngine.RefreshRayParams()
end

function RageCrimEngine.GetHeadHitpointSteps(TargetPart, DesiredPosition, BaseOrigin, BlockerCount)
    if not TargetPart or not TargetPart:IsA("BasePart") then return {} end

    local Center = typeof(DesiredPosition) == "Vector3" and DesiredPosition or TargetPart.Position
    local Frame = TargetPart.CFrame - TargetPart.Position + Center
    local Half = TargetPart.Size * 0.5
    local Origin = typeof(BaseOrigin) == "Vector3" and BaseOrigin or nil

    if not Origin then
        local Character = LocalPlayer.Character
        local Root = Character and Character:FindFirstChild("HumanoidRootPart")
        Origin = Root and Root.Position or Center
    end

    local Distance = (Center - Origin).Magnitude
    local Speed = TargetPart.AssemblyLinearVelocity.Magnitude
    local Obstacles = math.max(math.floor(tonumber(BlockerCount) or 0), 0)

    local MaximumScale = math.clamp(tonumber(RageCrimEngine.HeadScale) or 0.88, 0.54, 0.94)
    if Distance > 500 then
        MaximumScale -= 0.08
    elseif Distance > 300 then
        MaximumScale -= 0.045
    elseif Distance < 120 then
        MaximumScale += 0.025
    end

    if Speed > 24 then
        MaximumScale -= 0.045
    elseif Speed < 3 and Obstacles > 0 then
        MaximumScale += 0.018
    end

    MaximumScale = math.clamp(MaximumScale, 0.68, 0.92)

    local RingCount
    if Distance < 150 then
        RingCount = 10
    elseif Distance < 380 then
        RingCount = 8
    else
        RingCount = 6
    end

    if Obstacles >= 2 then RingCount = math.min(RingCount + 2, 10) end
    if Speed > 22 then RingCount = math.max(RingCount - 2, 6) end

    local X = Half.X * MaximumScale
    local Y = Half.Y * MaximumScale
    local Z = Half.Z * MaximumScale
    local Inner = math.clamp(tonumber(RageCrimEngine.HeadInnerScale) or 0.34, 0.12, 0.48)
    local Middle = math.clamp(tonumber(RageCrimEngine.HeadMiddleScale) or 0.62, Inner + 0.08, 0.76)
    local Outer = math.clamp(tonumber(RageCrimEngine.HeadOuterScale) or 0.84, Middle + 0.06, 0.94)

    local Steps = {
        {Name = "center", Points = {Center}},
        {Name = "inner", Points = {}},
        {Name = "middle", Points = {}},
        {Name = "surface", Points = {}},
        {Name = "corners", Points = {}}
    }

    local function World(NX, NY, NZ)
        return Frame:PointToWorldSpace(Vector3.new(X * NX, Y * NY, Z * NZ))
    end

    local InnerPoints = Steps[2].Points
    InnerPoints[#InnerPoints + 1] = World( Inner, 0, 0)
    InnerPoints[#InnerPoints + 1] = World(-Inner, 0, 0)
    InnerPoints[#InnerPoints + 1] = World(0,  Inner, 0)
    InnerPoints[#InnerPoints + 1] = World(0, -Inner, 0)
    InnerPoints[#InnerPoints + 1] = World(0, 0,  Inner)
    InnerPoints[#InnerPoints + 1] = World(0, 0, -Inner)

    local MiddlePoints = Steps[3].Points
    for Index = 1, RingCount do
        local Angle = ((Index - 1) / RingCount) * math.pi * 2
        MiddlePoints[#MiddlePoints + 1] = World(
            math.cos(Angle) * Middle,
            math.sin(Angle) * Middle,
            0
        )
    end
    MiddlePoints[#MiddlePoints + 1] = World(0, 0,  Middle)
    MiddlePoints[#MiddlePoints + 1] = World(0, 0, -Middle)

    local SurfacePoints = Steps[4].Points
    SurfacePoints[#SurfacePoints + 1] = World( Outer, 0, 0)
    SurfacePoints[#SurfacePoints + 1] = World(-Outer, 0, 0)
    SurfacePoints[#SurfacePoints + 1] = World(0,  Outer, 0)
    SurfacePoints[#SurfacePoints + 1] = World(0, -Outer, 0)
    SurfacePoints[#SurfacePoints + 1] = World(0, 0,  Outer)
    SurfacePoints[#SurfacePoints + 1] = World(0, 0, -Outer)

    local FaceRing = Outer * (Distance > 400 and 0.60 or 0.68)
    local Depth = Outer * (Speed > 20 and 0.58 or 0.68)

    for Index = 1, RingCount do
        local Angle = ((Index - 1) / RingCount) * math.pi * 2
        local RX = math.cos(Angle) * FaceRing
        local RY = math.sin(Angle) * FaceRing
        SurfacePoints[#SurfacePoints + 1] = World(RX, RY,  Depth)
        SurfacePoints[#SurfacePoints + 1] = World(RX, RY, -Depth)
    end

    local CornerPoints = Steps[5].Points
    local Corner = Outer * (Distance > 450 and 0.70 or 0.78)
    for SX = -1, 1, 2 do
        for SY = -1, 1, 2 do
            for SZ = -1, 1, 2 do
                CornerPoints[#CornerPoints + 1] = World(
                    Corner * SX,
                    Corner * SY,
                    Corner * SZ
                )
            end
        end
    end

    return Steps
end

function RageCrimEngine.GetHitCandidates(TargetPart, DesiredPosition)
    local Steps = RageCrimEngine.GetHeadHitpointSteps(TargetPart, DesiredPosition)
    local Result = {}

    for StepIndex = 1, #Steps do
        local Points = Steps[StepIndex].Points
        for PointIndex = 1, #Points do
            Result[#Result + 1] = Points[PointIndex]
        end
    end

    return Result
end

function RageCrimEngine.GetCachedHeadPoint(TargetPart, TargetPosition)
    local Cached = TargetPart and RageCrimEngine.HeadPointCache[TargetPart]
    if type(Cached) ~= "table"
        or typeof(Cached.Offset) ~= "Vector3"
        or os.clock() - (tonumber(Cached.Time) or 0) > RageCrimEngine.HeadPointCacheLifetime
    then
        return nil
    end

    return TargetPosition + Cached.Offset, Cached.Step
end

function RageCrimEngine.CacheHeadPoint(TargetPart, TargetPosition, HitPosition, Step)
    if not TargetPart or typeof(TargetPosition) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then return end

    RageCrimEngine.HeadPointCache[TargetPart] = {
        Offset = HitPosition - TargetPosition,
        Step = tonumber(Step) or 1,
        Time = os.clock()
    }
end


function RageCrimEngine.GetBankName(Stage)
    Stage = tostring(Stage or "")
    if Stage:sub(1, 7) == "blocker" then return "blocker" end
    if Stage:sub(1, 6) == "sphere" then return "sphere" end
    if Stage:sub(1, 6) == "spiral" then return "spiral" end
    if Stage:sub(1, 5) == "rings" then return "rings" end
    return nil
end

function RageCrimEngine.GetBankContextKey(BaseOrigin, TargetPosition)
    local Delta = TargetPosition - BaseOrigin
    local Distance = Delta.Magnitude
    local DistanceBucket = Distance < 140 and 1 or Distance < 320 and 2 or Distance < 650 and 3 or 4
    local Vertical = math.abs(Delta.Y)
    local VerticalBucket = Vertical < 12 and 1 or Vertical < 45 and 2 or 3
    local CellX = math.floor(BaseOrigin.X / 220)
    local CellZ = math.floor(BaseOrigin.Z / 220)
    return table.concat({CellX, CellZ, DistanceBucket, VerticalBucket}, ":")
end

function RageCrimEngine.GetBankState(ContextKey)
    local State = RageCrimEngine.BankStats[ContextKey]
    if type(State) ~= "table" then
        State = {
            sphere = {Value = 0, Hits = 0, Misses = 0, Time = 0},
            spiral = {Value = 0, Hits = 0, Misses = 0, Time = 0},
            rings = {Value = 0, Hits = 0, Misses = 0, Time = 0},
            blocker = {Value = 0, Hits = 0, Misses = 0, Time = 0}
        }
        RageCrimEngine.BankStats[ContextKey] = State
    elseif type(State.blocker) ~= "table" then
        State.blocker = {Value = 0, Hits = 0, Misses = 0, Time = 0}
    end
    return State
end

function RageCrimEngine.DecayBankState(Bank)
    if type(Bank) ~= "table" then return end
    local Now = os.clock()
    local Last = tonumber(Bank.Time) or Now
    local Age = Now - Last
    if Age > RageCrimEngine.BankFeedbackLifetime then
        Bank.Value = (tonumber(Bank.Value) or 0) * 0.45
        Bank.Hits = math.floor((tonumber(Bank.Hits) or 0) * 0.5)
        Bank.Misses = math.floor((tonumber(Bank.Misses) or 0) * 0.5)
        Bank.Time = Now
    end
end

function RageCrimEngine.GetBankOrder(Banks, ContextKey)
    local State = RageCrimEngine.GetBankState(ContextKey)
    local Ordered = table.create(#Banks)

    for Index = 1, #Banks do
        local Bank = Banks[Index]
        local Feedback = State[Bank.Name]
        if type(Feedback) ~= "table" then
            Feedback = {Value = 0, Hits = 0, Misses = 0, Time = 0}
            State[Bank.Name] = Feedback
        end

        RageCrimEngine.DecayBankState(Feedback)

        Ordered[Index] = {
            Bank = Bank,
            Score = tonumber(Feedback.Value) or 0,
            Hits = tonumber(Feedback.Hits) or 0,
            Misses = tonumber(Feedback.Misses) or 0,
            BaseIndex = Index
        }
    end

    table.sort(Ordered, function(A, B)
        if math.abs(A.Score - B.Score) > 0.001 then return A.Score > B.Score end
        local ARate = A.Hits / math.max(A.Hits + A.Misses, 1)
        local BRate = B.Hits / math.max(B.Hits + B.Misses, 1)
        if math.abs(ARate - BRate) > 0.001 then return ARate > BRate end
        return A.BaseIndex < B.BaseIndex
    end)

    return Ordered
end

function RageCrimEngine.RecordBankFeedback(ContextKey, Stage, Hit)
    local BankName = RageCrimEngine.GetBankName(Stage)
    if not BankName or not ContextKey then return end

    local State = RageCrimEngine.GetBankState(ContextKey)
    local Bank = State[BankName]
    if type(Bank) ~= "table" then return end

    RageCrimEngine.DecayBankState(Bank)

    if Hit == true then
        Bank.Hits = (tonumber(Bank.Hits) or 0) + 1
        Bank.Value = math.clamp((tonumber(Bank.Value) or 0) * 0.88 + 1.0, -4, 7)
    else
        Bank.Misses = (tonumber(Bank.Misses) or 0) + 1
        Bank.Value = math.clamp((tonumber(Bank.Value) or 0) * 0.90 - 0.72, -4, 7)
    end

    Bank.Time = os.clock()
end

function RageCrimEngine.TransformSample(BaseOrigin, Forward, Right, Up, Sample, Radius)
    local Offset = Right * Sample.X + Up * Sample.Y + Forward * Sample.Z
    if Offset.Magnitude <= 0.001 then return BaseOrigin, 0 end
    if Offset.Magnitude > 1 then Offset = Offset.Unit end

    local WorldOffset = Offset * Radius
    local Magnitude = WorldOffset.Magnitude
    if Magnitude > Radius then
        WorldOffset = WorldOffset.Unit * Radius
        Magnitude = Radius
    end

    return BaseOrigin + WorldOffset, Magnitude
end

function RageCrimEngine.GetFirstBlocker(BaseOrigin, HitPosition)
    if typeof(BaseOrigin) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then return nil end
    local Delta = HitPosition - BaseOrigin
    if Delta.Magnitude <= 0.001 then return nil end

    local Params = RageCrimEngine.RefreshRayParams()
    local Result = workspace:Raycast(BaseOrigin, Delta, Params)
    if Result and Result.Instance and Result.Instance:IsA("BasePart") then return Result end
    return nil
end

function RageCrimEngine.GetBlockerChain(BaseOrigin, HitPosition, TargetPart)
    if typeof(BaseOrigin) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then return {} end

    local Delta = HitPosition - BaseOrigin
    if Delta.Magnitude <= 0.001 then return {} end

    local Ignore = {}
    local Character = LocalPlayer.Character
    local Characters = workspace:FindFirstChild("Characters")
    local Debris = workspace:FindFirstChild("Debris")

    if Character then Ignore[#Ignore + 1] = Character end
    if Characters then Ignore[#Ignore + 1] = Characters end
    if Debris then Ignore[#Ignore + 1] = Debris end

    local Params = RaycastParams.new()
    Params.FilterType = Enum.RaycastFilterType.Exclude
    Params.IgnoreWater = true

    local Chain = {}
    local Seen = {}

    for Depth = 1, math.max(math.floor(tonumber(RageCrimEngine.BlockerChainDepth) or 5), 1) do
        Params.FilterDescendantsInstances = Ignore
        local Result = workspace:Raycast(BaseOrigin, Delta, Params)
        if not Result or not Result.Instance then break end

        if TargetPart and Result.Instance:IsDescendantOf(TargetPart.Parent) then break end

        local Instance = Result.Instance
        if not Instance:IsA("BasePart") or Seen[Instance] then break end

        Seen[Instance] = true
        Chain[#Chain + 1] = Result
        Ignore[#Ignore + 1] = Instance
    end

    return Chain
end

function RageCrimEngine.GetPartGeometry(Part)
    if not Part or not Part:IsA("BasePart") then return nil end

    local Cached = RageCrimEngine.PartGeometryCache[Part]
    local Size = Part.Size
    local Frame = Part.CFrame

    if type(Cached) == "table" and Cached.Size == Size and Cached.CFrame == Frame then
        Cached.Time = os.clock()
        return Cached
    end

    local Half = Size * 0.5
    local Corners = table.create(8)
    local Index = 0

    for X = -1, 1, 2 do
        for Y = -1, 1, 2 do
            for Z = -1, 1, 2 do
                Index += 1
                Corners[Index] = Frame:PointToWorldSpace(
                    Vector3.new(Half.X * X, Half.Y * Y, Half.Z * Z)
                )
            end
        end
    end

    Cached = {
        Size = Size,
        CFrame = Frame,
        Corners = Corners,
        Time = os.clock()
    }

    RageCrimEngine.PartGeometryCache[Part] = Cached
    return Cached
end

function RageCrimEngine.GetProjectionBounds(BaseOrigin, TargetPosition, Part)
    local Geometry = RageCrimEngine.GetPartGeometry(Part)
    if not Geometry then return nil end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local MinRight, MaxRight = math.huge, -math.huge
    local MinUp, MaxUp = math.huge, -math.huge
    local MinAlong, MaxAlong = math.huge, -math.huge

    for Index = 1, #Geometry.Corners do
        local Relative = Geometry.Corners[Index] - BaseOrigin
        local R = Relative:Dot(Right)
        local U = Relative:Dot(Up)
        local A = Relative:Dot(Forward)

        MinRight = math.min(MinRight, R)
        MaxRight = math.max(MaxRight, R)
        MinUp = math.min(MinUp, U)
        MaxUp = math.max(MaxUp, U)
        MinAlong = math.min(MinAlong, A)
        MaxAlong = math.max(MaxAlong, A)
    end

    return {
        Part = Part,
        MinRight = MinRight,
        MaxRight = MaxRight,
        MinUp = MinUp,
        MaxUp = MaxUp,
        MinAlong = MinAlong,
        MaxAlong = MaxAlong,
        CenterAlong = (MinAlong + MaxAlong) * 0.5
    }
end

function RageCrimEngine.GetPartSurfaceAxis(Part)
    if not Part or not Part:IsA("BasePart") then return nil, 1 end

    local Size = Part.Size
    local Minimum = math.min(Size.X, Size.Y, Size.Z)
    local Maximum = math.max(Size.X, Size.Y, Size.Z)
    local Thinness = Minimum / math.max(Maximum, 0.001)
    local Axis

    if Minimum == Size.X then
        Axis = Part.CFrame.RightVector
    elseif Minimum == Size.Y then
        Axis = Part.CFrame.UpVector
    else
        Axis = Part.CFrame.LookVector
    end

    return Axis, Thinness
end

function RageCrimEngine.GetNearbyClusterParts(Part, BaseOrigin, TargetPosition)
    if not Part or not Part:IsA("BasePart") then return {} end

    local Direction = TargetPosition - BaseOrigin
    if Direction.Magnitude > 0.001 then Direction = Direction.Unit else Direction = Vector3.zAxis end
    local DirectionKey =
        tostring(math.floor(Direction.X * 5 + 0.5))
        .. ":" .. tostring(math.floor(Direction.Y * 5 + 0.5))
        .. ":" .. tostring(math.floor(Direction.Z * 5 + 0.5))

    local Cached = RageCrimEngine.ClusterExpansionCache[Part]
    if type(Cached) == "table"
        and Cached.CFrame == Part.CFrame
        and Cached.Size == Part.Size
        and Cached.DirectionKey == DirectionKey
        and os.clock() - (tonumber(Cached.Time) or 0) <= RageCrimEngine.ClusterCacheLifetime
    then
        Cached.Time = os.clock()
        return Cached.Parts
    end

    local Expansion = math.max(tonumber(RageCrimEngine.BlockerClusterExpansion) or 5, 1)
    local Parameters = OverlapParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.MaxParts = math.max(math.floor(tonumber(RageCrimEngine.BlockerClusterPartLimit) or 28), 8)

    local Ignore = {}
    local Character = LocalPlayer.Character
    local Characters = workspace:FindFirstChild("Characters")
    local Debris = workspace:FindFirstChild("Debris")

    if Character then Ignore[#Ignore + 1] = Character end
    if Characters then Ignore[#Ignore + 1] = Characters end
    if Debris then Ignore[#Ignore + 1] = Debris end
    Parameters.FilterDescendantsInstances = Ignore

    local Candidates = workspace:GetPartBoundsInBox(
        Part.CFrame,
        Part.Size + Vector3.new(Expansion * 2, Expansion * 2, Expansion * 2),
        Parameters
    )

    local AnchorBounds = RageCrimEngine.GetProjectionBounds(BaseOrigin, TargetPosition, Part)
    local Result = {Part}
    local Seen = {[Part] = true}

    if AnchorBounds then
        for Index = 1, #Candidates do
            local Candidate = Candidates[Index]

            if Candidate
                and Candidate ~= Part
                and Candidate:IsA("BasePart")
                and Candidate.CanCollide
                and not Seen[Candidate]
            then
                local Bounds = RageCrimEngine.GetProjectionBounds(
                    BaseOrigin,
                    TargetPosition,
                    Candidate
                )

                if Bounds then
                    local AlongGap = math.max(
                        AnchorBounds.MinAlong - Bounds.MaxAlong,
                        Bounds.MinAlong - AnchorBounds.MaxAlong,
                        0
                    )

                    local RightGap = math.max(
                        AnchorBounds.MinRight - Bounds.MaxRight,
                        Bounds.MinRight - AnchorBounds.MaxRight,
                        0
                    )

                    local UpGap = math.max(
                        AnchorBounds.MinUp - Bounds.MaxUp,
                        Bounds.MinUp - AnchorBounds.MaxUp,
                        0
                    )

                    local AnchorAxis, AnchorThinness = RageCrimEngine.GetPartSurfaceAxis(Part)
                    local CandidateAxis, CandidateThinness = RageCrimEngine.GetPartSurfaceAxis(Candidate)
                    local OrientationCompatible = true

                    if AnchorAxis and CandidateAxis
                        and AnchorThinness <= 0.38
                        and CandidateThinness <= 0.38
                    then
                        OrientationCompatible = math.abs(AnchorAxis:Dot(CandidateAxis)) >= 0.48
                    end

                    if OrientationCompatible
                        and AlongGap <= Expansion * 1.8
                        and RightGap <= Expansion * 1.15
                        and UpGap <= Expansion * 1.15
                    then
                        Seen[Candidate] = true
                        Result[#Result + 1] = Candidate
                    end
                end
            end
        end
    end

    RageCrimEngine.ClusterExpansionCache[Part] = {
        Parts = Result,
        CFrame = Part.CFrame,
        Size = Part.Size,
        DirectionKey = DirectionKey,
        Time = os.clock()
    }

    return Result
end

function RageCrimEngine.BuildBlockerClusters(BaseOrigin, TargetPosition, Blockers)
    if type(Blockers) ~= "table" or #Blockers == 0 then return {} end

    local Clusters = {}
    local GlobalSeen = {}

    for BlockerIndex = 1, #Blockers do
        local Blocker = Blockers[BlockerIndex]
        local Anchor = Blocker and Blocker.Instance

        if Anchor and Anchor:IsA("BasePart") then
            local Parts = RageCrimEngine.GetNearbyClusterParts(
                Anchor,
                BaseOrigin,
                TargetPosition
            )

            local Cluster = {
                Parts = {},
                Hits = {Blocker},
                MinRight = math.huge,
                MaxRight = -math.huge,
                MinUp = math.huge,
                MaxUp = -math.huge,
                MinAlong = math.huge,
                MaxAlong = -math.huge
            }

            for PartIndex = 1, #Parts do
                local Part = Parts[PartIndex]

                if Part and Part.Parent and not GlobalSeen[Part] then
                    local Bounds = RageCrimEngine.GetProjectionBounds(
                        BaseOrigin,
                        TargetPosition,
                        Part
                    )

                    if Bounds then
                        GlobalSeen[Part] = true
                        Cluster.Parts[#Cluster.Parts + 1] = Part
                        Cluster.MinRight = math.min(Cluster.MinRight, Bounds.MinRight)
                        Cluster.MaxRight = math.max(Cluster.MaxRight, Bounds.MaxRight)
                        Cluster.MinUp = math.min(Cluster.MinUp, Bounds.MinUp)
                        Cluster.MaxUp = math.max(Cluster.MaxUp, Bounds.MaxUp)
                        Cluster.MinAlong = math.min(Cluster.MinAlong, Bounds.MinAlong)
                        Cluster.MaxAlong = math.max(Cluster.MaxAlong, Bounds.MaxAlong)
                    end
                end
            end

            if #Cluster.Parts > 0 then
                Cluster.CenterAlong = (Cluster.MinAlong + Cluster.MaxAlong) * 0.5
                Clusters[#Clusters + 1] = Cluster
            end
        end
    end

    local Merged = {}
    local Used = {}

    for Index = 1, #Clusters do
        if not Used[Index] then
            local A = Clusters[Index]
            local Out = {
                Parts = {},
                Hits = {},
                MinRight = A.MinRight,
                MaxRight = A.MaxRight,
                MinUp = A.MinUp,
                MaxUp = A.MaxUp,
                MinAlong = A.MinAlong,
                MaxAlong = A.MaxAlong
            }

            for PartIndex = 1, #A.Parts do Out.Parts[#Out.Parts + 1] = A.Parts[PartIndex] end
            for HitIndex = 1, #A.Hits do Out.Hits[#Out.Hits + 1] = A.Hits[HitIndex] end
            Used[Index] = true

            for OtherIndex = Index + 1, #Clusters do
                if not Used[OtherIndex] then
                    local B = Clusters[OtherIndex]
                    local AlongGap = math.max(Out.MinAlong - B.MaxAlong, B.MinAlong - Out.MaxAlong, 0)
                    local RightGap = math.max(Out.MinRight - B.MaxRight, B.MinRight - Out.MaxRight, 0)
                    local UpGap = math.max(Out.MinUp - B.MaxUp, B.MinUp - Out.MaxUp, 0)

                    if AlongGap <= 10 and RightGap <= 4.5 and UpGap <= 4.5 then
                        Used[OtherIndex] = true
                        Out.MinRight = math.min(Out.MinRight, B.MinRight)
                        Out.MaxRight = math.max(Out.MaxRight, B.MaxRight)
                        Out.MinUp = math.min(Out.MinUp, B.MinUp)
                        Out.MaxUp = math.max(Out.MaxUp, B.MaxUp)
                        Out.MinAlong = math.min(Out.MinAlong, B.MinAlong)
                        Out.MaxAlong = math.max(Out.MaxAlong, B.MaxAlong)

                        for PartIndex = 1, #B.Parts do Out.Parts[#Out.Parts + 1] = B.Parts[PartIndex] end
                        for HitIndex = 1, #B.Hits do Out.Hits[#Out.Hits + 1] = B.Hits[HitIndex] end
                    end
                end
            end

            Out.CenterAlong = (Out.MinAlong + Out.MaxAlong) * 0.5
            Merged[#Merged + 1] = Out
        end
    end

    return Merged
end

function RageCrimEngine.GetRouteFamily(Stage)
    Stage = tostring(Stage or "")
    local Source = Stage:match("^blocker%-([^%-]+)") or Stage:match("^([^%-]+)")
    return Source or "unknown"
end

function RageCrimEngine.GetOriginSide(BaseOrigin, Origin, TargetPosition)
    if typeof(BaseOrigin) ~= "Vector3" or typeof(Origin) ~= "Vector3" then return "center" end

    local Offset = Origin - BaseOrigin
    if Offset.Magnitude <= 0.15 then return "center" end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local X = Offset:Dot(Right)
    local Y = Offset:Dot(Up)
    local Z = Offset:Dot(Forward)
    local AX, AY, AZ = math.abs(X), math.abs(Y), math.abs(Z)

    if AX >= AY and AX >= AZ then return X >= 0 and "right" or "left" end
    if AY >= AX and AY >= AZ then return Y >= 0 and "up" or "down" end
    return Z >= 0 and "forward" or "back"
end

function RageCrimEngine.GetRouteFeedbackKey(ContextKey, BlockerSignature, Stage, HitStep, Side)
    return table.concat({
        tostring(ContextKey or "none"),
        tostring(BlockerSignature or "none"),
        tostring(RageCrimEngine.GetRouteFamily(Stage)),
        tostring(math.floor(tonumber(HitStep) or 1)),
        tostring(Side or "center")
    }, "#")
end

function RageCrimEngine.PruneTimedCache(Cache, MaximumAge, MaximumEntries)
    if type(Cache) ~= "table" then return 0 end

    local CurrentTime = os.clock()
    local Entries = {}
    local Count = 0

    for Key, Value in pairs(Cache) do
        local Time = type(Value) == "table" and tonumber(Value.Time) or 0
        local Expired =
            MaximumAge
            and MaximumAge > 0
            and Time > 0
            and CurrentTime - Time > MaximumAge

        if Expired then
            Cache[Key] = nil
        else
            Count += 1
            Entries[#Entries + 1] = {
                Key = Key,
                Time = Time
            }
        end
    end

    MaximumEntries = math.max(math.floor(tonumber(MaximumEntries) or 0), 0)

    if MaximumEntries > 0 and Count > MaximumEntries then
        table.sort(Entries, function(A, B)
            return (tonumber(A.Time) or 0) < (tonumber(B.Time) or 0)
        end)

        local RemoveCount = Count - MaximumEntries

        for Index = 1, RemoveCount do
            Cache[Entries[Index].Key] = nil
        end

        Count = MaximumEntries
    end

    return Count
end

function RageCrimEngine.MaintainRuntimeCaches(Force)
    local CurrentTime = os.clock()

    if Force ~= true
        and CurrentTime < (tonumber(RageCrimEngine.NextCacheMaintenance) or 0)
    then
        return
    end

    RageCrimEngine.NextCacheMaintenance =
        CurrentTime
        + math.max(tonumber(RageCrimEngine.CacheMaintenanceInterval) or 4, 1)

    RageCrimEngine.PruneTimedCache(
        RageCrimEngine.PartGeometryCache,
        math.max(tonumber(RageCrimEngine.GeometryCacheLifetime) or 30, 5),
        math.max(math.floor(tonumber(RageCrimEngine.GeometryCacheMaximum) or 420), 64)
    )

    RageCrimEngine.PruneTimedCache(
        RageCrimEngine.ClusterExpansionCache,
        math.max(tonumber(RageCrimEngine.GeometryCacheLifetime) or 30, 5),
        math.max(math.floor(tonumber(RageCrimEngine.ClusterCacheMaximum) or 120), 32)
    )

    RageCrimEngine.PruneTimedCache(
        RageCrimEngine.RouteFeedbackStats,
        math.max(tonumber(RageCrimEngine.RouteFeedbackLifetime) or 90, 15),
        math.max(math.floor(tonumber(RageCrimEngine.RouteFeedbackMaximum) or 256), 64)
    )
end

function RageCrimEngine.GetRouteFeedbackValue(Key)
    if not Key then return 0 end
    local Data = RageCrimEngine.RouteFeedbackStats[Key]
    if type(Data) ~= "table" then return 0 end

    local Age = os.clock() - (tonumber(Data.Time) or 0)
    if Age > RageCrimEngine.RouteFeedbackLifetime then
        RageCrimEngine.RouteFeedbackStats[Key] = nil
        return 0
    end

    return tonumber(Data.Value) or 0
end

function RageCrimEngine.RecordRouteFeedback(Key, Hit)
    if not Key then return end

    local Data = RageCrimEngine.RouteFeedbackStats[Key]
    if type(Data) ~= "table" then
        Data = {Value = 0, Hits = 0, Misses = 0, Time = os.clock()}
        RageCrimEngine.RouteFeedbackStats[Key] = Data
    end

    RageCrimEngine.GetRouteFeedbackValue(Key)

    if Hit == true then
        Data.Hits = (tonumber(Data.Hits) or 0) + 1
        Data.Value = math.clamp((tonumber(Data.Value) or 0) * 0.84 + 1.15, -5, 8)
    else
        Data.Misses = (tonumber(Data.Misses) or 0) + 1
        Data.Value = math.clamp((tonumber(Data.Value) or 0) * 0.90 - 0.86, -5, 8)
    end

    Data.Time = os.clock()
end

function RageCrimEngine.GetExposureScore(BaseOrigin, Origin, HitPosition, TargetPosition, Clusters)
    if type(Clusters) ~= "table" or #Clusters == 0 then return 1 end
    if typeof(BaseOrigin) ~= "Vector3"
        or typeof(Origin) ~= "Vector3"
        or typeof(HitPosition) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
    then
        return 0
    end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local OriginRelative = Origin - BaseOrigin
    local HitRelative = HitPosition - BaseOrigin
    local OriginAlong = OriginRelative:Dot(Forward)
    local HitAlong = HitRelative:Dot(Forward)

    if math.abs(HitAlong - OriginAlong) <= 0.001 then return 0 end

    local OriginRight = OriginRelative:Dot(Right)
    local OriginUp = OriginRelative:Dot(Up)
    local HitRight = HitRelative:Dot(Right)
    local HitUp = HitRelative:Dot(Up)
    local MinimumExposure = 1

    for Index = 1, #Clusters do
        local Cluster = Clusters[Index]
        local Along = Cluster.CenterAlong
        local T = (Along - OriginAlong) / (HitAlong - OriginAlong)

        if T > 0 and T < 1 then
            local LineRight = OriginRight + (HitRight - OriginRight) * T
            local LineUp = OriginUp + (HitUp - OriginUp) * T
            local Margin = 0.22

            local OutsideRight = math.max(
                Cluster.MinRight - LineRight,
                LineRight - Cluster.MaxRight,
                0
            )

            local OutsideUp = math.max(
                Cluster.MinUp - LineUp,
                LineUp - Cluster.MaxUp,
                0
            )

            local Exposure

            if OutsideRight <= 0 and OutsideUp <= 0 then
                Exposure = 0
            else
                Exposure = math.clamp(math.max(OutsideRight, OutsideUp) / (1.4 + Margin), 0, 1)
            end

            MinimumExposure = math.min(MinimumExposure, Exposure)
            if MinimumExposure <= 0 then break end
        end
    end

    return MinimumExposure
end

function RageCrimEngine.GetCorridorStability(Origin, HitPosition, TargetPart)
    if typeof(Origin) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then return 0, 0 end

    local Delta = HitPosition - Origin
    if Delta.Magnitude <= 0.001 then return 1, 0 end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        Origin,
        HitPosition
    )

    local Amount = math.max(tonumber(RageCrimEngine.CorridorOffset) or 0.13, 0.05)
    local Offsets = {
        Right * Amount,
        -Right * Amount,
        Up * Amount,
        -Up * Amount
    }

    local Clear, Tests = 0, 0

    for Index = 1, #Offsets do
        local Offset = Offsets[Index]
        local CandidateHit = HitPosition + Offset * 0.68

        if RagePointInsideExpectedHitbox(TargetPart, CandidateHit) then
            Tests += 1
            if RageCrimEngine.RayCheck(Origin + Offset, CandidateHit, TargetPart) then
                Clear += 1
            end
        end
    end

    if Tests <= 0 then return 0.5, 0 end
    return Clear / Tests, Tests
end

function RageCrimEngine.GetAdaptiveRouteCacheLifetime(TargetPart)
    local TargetSpeed = TargetPart and TargetPart:IsA("BasePart")
        and TargetPart.AssemblyLinearVelocity.Magnitude
        or 0

    local Character = LocalPlayer.Character
    local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    local LocalSpeed = Root and Root.AssemblyLinearVelocity.Magnitude or 0
    local Speed = math.max(TargetSpeed, LocalSpeed)

    if Speed < 2.5 then return 1.30 end
    if Speed < 8 then return 0.90 end
    if Speed < 17 then return 0.58 end
    if Speed < 28 then return 0.38 end
    return 0.24
end

function RageCrimEngine.GetSearchBudget(BaseOrigin, TargetPosition, ClusterCount)
    local Distance = (TargetPosition - BaseOrigin).Magnitude
    local Count = math.max(math.floor(tonumber(ClusterCount) or 0), 0)
    local Budget

    if Count == 0 then
        Budget = 72
    elseif Count == 1 then
        Budget = Distance < 250 and 108 or 124
    elseif Count == 2 then
        Budget = Distance < 350 and 142 or 158
    else
        Budget = 182
    end

    if Distance > 650 then Budget += 8 end
    return math.min(Budget, math.max(math.floor(tonumber(RageCrimEngine.MaximumRayTests) or 190), 64))
end

function RageCrimEngine.RefineOriginNeighborhood(BaseOrigin, Origin, HitPosition, TargetPosition, TargetPart)
    if typeof(BaseOrigin) ~= "Vector3"
        or typeof(Origin) ~= "Vector3"
        or typeof(HitPosition) ~= "Vector3"
    then
        return Origin, HitPosition
    end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local BestOrigin = Origin
    local BestHit = HitPosition
    local BestStability = RageCrimEngine.GetCorridorStability(
        Origin,
        HitPosition,
        TargetPart
    )
    local BestMagnitude = (Origin - BaseOrigin).Magnitude
    local CandidateTests = 0
    local CandidateLimit = math.max(
        math.floor(tonumber(RageCrimEngine.LocalRefineCandidateLimit) or 8),
        4
    )

    for LevelIndex = 1, #RageCrimEngine.LocalRefineOffsets do
        local Amount = RageCrimEngine.LocalRefineOffsets[LevelIndex]
        local Offsets = {
            Right * Amount,
            -Right * Amount,
            Up * Amount,
            -Up * Amount,
            (Right + Up).Unit * Amount,
            (Right - Up).Unit * Amount,
            (-Right + Up).Unit * Amount,
            (-Right - Up).Unit * Amount
        }

        for Index = 1, #Offsets do
            if CandidateTests >= CandidateLimit then break end
            CandidateTests += 1

            local CandidateOrigin = Origin + Offsets[Index]
            local Magnitude = (CandidateOrigin - BaseOrigin).Magnitude

            if Magnitude <= RageCrimEngine.MaximumOriginDistance
                and RageCrimEngine.RayCheck(CandidateOrigin, HitPosition, TargetPart)
            then
                local Stability = RageCrimEngine.GetCorridorStability(
                    CandidateOrigin,
                    HitPosition,
                    TargetPart
                )

                if Stability > BestStability + 0.001
                    or math.abs(Stability - BestStability) <= 0.001 and Magnitude < BestMagnitude
                then
                    BestOrigin = CandidateOrigin
                    BestMagnitude = Magnitude
                    BestStability = Stability
                end
            end
        end

        if BestStability >= RageCrimEngine.CorridorExcellent
            or CandidateTests >= CandidateLimit
        then
            break
        end
    end

    return BestOrigin, BestHit
end

function RageCrimEngine.EstimateRequiredRadiusChain(BaseOrigin, TargetPosition, Blockers)
    if type(Blockers) ~= "table" or #Blockers == 0 then
        return RageCrimEngine.EstimateRequiredRadius(BaseOrigin, TargetPosition, nil)
    end

    local Required = RageCrimEngine.MinimumOriginDistance

    for Index = 1, #Blockers do
        local Estimate = RageCrimEngine.EstimateRequiredRadius(
            BaseOrigin,
            TargetPosition,
            Blockers[Index]
        )

        Required = math.max(Required, Estimate + math.max(Index - 1, 0) * 1.65)
    end

    return math.clamp(
        Required,
        RageCrimEngine.MinimumOriginDistance,
        RageCrimEngine.MaximumOriginDistance
    )
end

function RageCrimEngine.GetBlockerBasis(BaseOrigin, TargetPosition, Blocker)
    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(BaseOrigin, TargetPosition)
    if not Blocker or not Blocker.Instance or not Blocker.Instance:IsA("BasePart") then
        return Forward, Right, Up, nil
    end

    local Part = Blocker.Instance
    local CenterDelta = Part.Position - BaseOrigin
    local Along = CenterDelta:Dot(Forward)
    local Lateral = CenterDelta - Forward * Along

    if Lateral.Magnitude > 0.15 then
        local BlockerRight = Lateral.Unit
        local BlockerUp = Forward:Cross(BlockerRight)
        if BlockerUp.Magnitude > 0.001 then
            BlockerUp = BlockerUp.Unit
            return Forward, BlockerRight, BlockerUp, Part
        end
    end

    return Forward, Right, Up, Part
end

function RageCrimEngine.EstimateRequiredRadius(BaseOrigin, TargetPosition, Blocker)
    local Distance = (TargetPosition - BaseOrigin).Magnitude
    if not Blocker or not Blocker.Instance or not Blocker.Instance:IsA("BasePart") then
        if Distance < 150 then return 16 end
        if Distance < 350 then return 20 end
        return 25
    end

    local Part = Blocker.Instance
    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(BaseOrigin, TargetPosition)
    local Half = Part.Size * 0.5
    local CFrame = Part.CFrame

    local MaxRight, MaxUp = 0, 0
    for X = -1, 1, 2 do
        for Y = -1, 1, 2 do
            for Z = -1, 1, 2 do
                local Corner = CFrame:PointToWorldSpace(Vector3.new(Half.X * X, Half.Y * Y, Half.Z * Z))
                local Relative = Corner - BaseOrigin
                MaxRight = math.max(MaxRight, math.abs(Relative:Dot(Right)))
                MaxUp = math.max(MaxUp, math.abs(Relative:Dot(Up)))
            end
        end
    end

    local Along = math.max((Part.Position - BaseOrigin):Dot(Forward), 1)
    local TargetAlong = math.max((TargetPosition - BaseOrigin):Dot(Forward), Along + 1)
    local Ratio = TargetAlong / Along
    local Need = math.min(MaxRight, MaxUp) * math.clamp(Ratio * 0.42, 0.55, 1.25)

    if Part.Size.Magnitude > 120 then Need *= 1.18 end
    if Distance > 550 then Need *= 1.10 end

    return math.clamp(Need + 2.5, RageCrimEngine.MinimumOriginDistance, RageCrimEngine.MaximumOriginDistance)
end

function RageCrimEngine.BuildRadiusOrder(TargetPart, BaseOrigin, TargetPosition, Blockers)
    local Estimated = RageCrimEngine.EstimateRequiredRadiusChain(BaseOrigin, TargetPosition, Blockers)
    local Cached = TargetPart and RageCrimEngine.RadiusCache[TargetPart]
    local CachedRadius = type(Cached) == "table" and tonumber(Cached.Radius) or nil
    local Candidates, Seen = {}, {}

    local function Push(Value, Priority)
        Value = math.clamp(
            tonumber(Value) or RageCrimEngine.PreferredOriginDistance,
            RageCrimEngine.MinimumOriginDistance,
            RageCrimEngine.MaximumOriginDistance
        )

        local Rounded = math.floor(Value + 0.5)
        if Seen[Rounded] then return end
        Seen[Rounded] = true

        Candidates[#Candidates + 1] = {
            Radius = Rounded,
            Priority = tonumber(Priority) or 0,
            Distance = math.abs(Rounded - Estimated)
        }
    end

    if CachedRadius and os.clock() - (tonumber(Cached.Time) or 0) <= 1.2 then
        Push(CachedRadius, -4)
    end

    Push(Estimated, -3)

    local Lower, Upper = nil, nil
    for Index = 1, #RageCrimEngine.RadiusLadder do
        local Radius = RageCrimEngine.RadiusLadder[Index]

        if Radius <= Estimated then
            Lower = Radius
        elseif not Upper then
            Upper = Radius
        end
    end

    if Lower then Push(Lower, -2) end
    if Upper then Push(Upper, -1) end

    if Estimated > 46 then Push(RageCrimEngine.MaximumOriginDistance, 0) end
    Push(RageCrimEngine.PreferredOriginDistance, 1)

    table.sort(Candidates, function(A, B)
        if A.Priority ~= B.Priority then return A.Priority < B.Priority end
        if math.abs(A.Distance - B.Distance) > 0.001 then return A.Distance < B.Distance end
        return A.Radius < B.Radius
    end)

    local Limit = math.min(
        #Candidates,
        math.max(math.floor(tonumber(RageCrimEngine.SearchRadiusLimit) or 4), 2)
    )

    local Ordered = table.create(Limit)
    for Index = 1, Limit do Ordered[Index] = Candidates[Index].Radius end
    return Ordered, Estimated
end

function RageCrimEngine.GetProjectedBlockerData(BaseOrigin, TargetPosition, Blocker)
    if type(Blocker) == "table"
        and type(Blocker.Parts) == "table"
        and #Blocker.Parts > 0
        and type(Blocker.MinRight) == "number"
    then
        local TargetDistance = (TargetPosition - BaseOrigin).Magnitude
        if TargetDistance <= 0.001 then return nil end

        local Along = tonumber(Blocker.CenterAlong) or 0
        if Along <= 0.05 or Along >= TargetDistance - 0.05 then return nil end

        local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
            BaseOrigin,
            TargetPosition
        )

        local Ratio = math.clamp(Along / TargetDistance, 0.02, 0.97)
        local Leverage = math.max(1 - Ratio, 0.035)

        return {
            Blocker = Blocker,
            Part = Blocker.Parts[1],
            Forward = Forward,
            Right = Right,
            Up = Up,
            Along = Along,
            Ratio = Ratio,
            Leverage = Leverage,
            CenterRight = (Blocker.MinRight + Blocker.MaxRight) * 0.5,
            CenterUp = (Blocker.MinUp + Blocker.MaxUp) * 0.5,
            ExtentRight = (Blocker.MaxRight - Blocker.MinRight) * 0.5,
            ExtentUp = (Blocker.MaxUp - Blocker.MinUp) * 0.5
        }
    end

    if not Blocker or not Blocker.Instance or not Blocker.Instance:IsA("BasePart") then return nil end

    local Delta = TargetPosition - BaseOrigin
    local TargetDistance = Delta.Magnitude
    if TargetDistance <= 0.001 then return nil end

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local Bounds = RageCrimEngine.GetProjectionBounds(
        BaseOrigin,
        TargetPosition,
        Blocker.Instance
    )
    if not Bounds then return nil end

    local Along = Bounds.CenterAlong
    if Along <= 0.05 or Along >= TargetDistance - 0.05 then return nil end

    local Ratio = math.clamp(Along / TargetDistance, 0.02, 0.97)
    local Leverage = math.max(1 - Ratio, 0.035)

    return {
        Blocker = Blocker,
        Part = Blocker.Instance,
        Forward = Forward,
        Right = Right,
        Up = Up,
        Along = Along,
        Ratio = Ratio,
        Leverage = Leverage,
        CenterRight = (Bounds.MinRight + Bounds.MaxRight) * 0.5,
        CenterUp = (Bounds.MinUp + Bounds.MaxUp) * 0.5,
        ExtentRight = (Bounds.MaxRight - Bounds.MinRight) * 0.5,
        ExtentUp = (Bounds.MaxUp - Bounds.MinUp) * 0.5
    }
end

function RageCrimEngine.GetBlockerSignature(Blockers, BaseOrigin, TargetPosition)
    if type(Blockers) ~= "table" then return "none" end

    local Quantize = math.max(tonumber(RageCrimEngine.BlockerSignatureQuantize) or 2, 0.5)
    local Parts = {
        tostring(math.floor(BaseOrigin.X / 12)),
        tostring(math.floor(BaseOrigin.Y / 12)),
        tostring(math.floor(BaseOrigin.Z / 12)),
        tostring(math.floor(TargetPosition.X / 12)),
        tostring(math.floor(TargetPosition.Y / 12)),
        tostring(math.floor(TargetPosition.Z / 12)),
        tostring(#Blockers)
    }

    for Index = 1, #Blockers do
        local Blocker = Blockers[Index]

        if type(Blocker) == "table" and type(Blocker.Parts) == "table" then
            Parts[#Parts + 1] = tostring(#Blocker.Parts)
            Parts[#Parts + 1] = tostring(math.floor((Blocker.MinRight or 0) / Quantize + 0.5))
            Parts[#Parts + 1] = tostring(math.floor((Blocker.MaxRight or 0) / Quantize + 0.5))
            Parts[#Parts + 1] = tostring(math.floor((Blocker.MinUp or 0) / Quantize + 0.5))
            Parts[#Parts + 1] = tostring(math.floor((Blocker.MaxUp or 0) / Quantize + 0.5))
            Parts[#Parts + 1] = tostring(math.floor((Blocker.CenterAlong or 0) / Quantize + 0.5))
        else
            local Instance = Blocker and Blocker.Instance
            local Position = Blocker and Blocker.Position

            if Instance and typeof(Position) == "Vector3" then
                Parts[#Parts + 1] = tostring(Instance)
                Parts[#Parts + 1] = tostring(math.floor(Position.X / Quantize + 0.5))
                Parts[#Parts + 1] = tostring(math.floor(Position.Y / Quantize + 0.5))
                Parts[#Parts + 1] = tostring(math.floor(Position.Z / Quantize + 0.5))
            end
        end
    end

    return table.concat(Parts, "|")
end

function RageCrimEngine.FlattenHeadSteps(HitSteps)
    local Points = {}

    for StepIndex = 1, #HitSteps do
        local Step = HitSteps[StepIndex]
        local StepPoints = Step.Points

        for PointIndex = 1, #StepPoints do
            Points[#Points + 1] = {
                Position = StepPoints[PointIndex],
                Step = StepIndex,
                PointIndex = PointIndex
            }
        end
    end

    return Points
end

function RageCrimEngine.OrderHitpointsForOrigin(HitSteps, BaseOrigin, Origin, TargetPosition, Clusters)
    local Points = RageCrimEngine.FlattenHeadSteps(HitSteps)
    local Offset = Origin - BaseOrigin
    local OffsetMagnitude = Offset.Magnitude

    for Index = 1, #Points do
        local Point = Points[Index]
        local HitOffset = Point.Position - TargetPosition
        local Alignment = 0

        if OffsetMagnitude > 0.05 and HitOffset.Magnitude > 0.001 then
            Alignment = HitOffset.Unit:Dot(Offset.Unit)
        end

        Point.Exposure = RageCrimEngine.GetExposureScore(
            BaseOrigin,
            Origin,
            Point.Position,
            TargetPosition,
            Clusters
        )

        Point.OrderScore =
            Point.Step * 0.16
            - Point.Exposure * 0.72
            - math.max(Alignment, 0) * 0.30
            + HitOffset.Magnitude * 0.015
    end

    table.sort(Points, function(A, B)
        if math.abs(A.OrderScore - B.OrderScore) > 0.001 then
            return A.OrderScore < B.OrderScore
        end
        if A.Step ~= B.Step then return A.Step < B.Step end
        return A.PointIndex < B.PointIndex
    end)

    return Points
end

function RageCrimEngine.RefineSuccessfulRoute(
    BaseOrigin,
    Origin,
    TargetPosition,
    HitPosition,
    TargetPart
)
    if typeof(BaseOrigin) ~= "Vector3"
        or typeof(Origin) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
        or typeof(HitPosition) ~= "Vector3"
    then
        return Origin, HitPosition
    end

    local RefinedOrigin = Origin
    local RefinedHit = HitPosition
    local Offset = Origin - BaseOrigin
    local Magnitude = Offset.Magnitude

    if Magnitude > RageCrimEngine.MinimumRefinedOrigin + 0.1 then
        local Low = math.clamp(
            (tonumber(RageCrimEngine.MinimumRefinedOrigin) or 6) / Magnitude,
            0,
            1
        )
        local High = 1

        for _ = 1, math.max(math.floor(tonumber(RageCrimEngine.RouteRefineIterations) or 4), 0) do
            local Alpha = (Low + High) * 0.5
            local CandidateOrigin = BaseOrigin + Offset * Alpha

            if RageCrimEngine.RayCheck(CandidateOrigin, RefinedHit, TargetPart) then
                RefinedOrigin = CandidateOrigin
                High = Alpha
            else
                Low = Alpha
            end
        end
    end

    if (RefinedHit - TargetPosition).Magnitude > 0.02 then
        local Best = RefinedHit
        local Low = 0
        local High = 1

        for _ = 1, math.max(math.floor(tonumber(RageCrimEngine.HitRefineIterations) or 3), 0) do
            local Alpha = (Low + High) * 0.5
            local CandidateHit = RefinedHit:Lerp(TargetPosition, Alpha)

            if RagePointInsideExpectedHitbox(TargetPart, CandidateHit)
                and RageCrimEngine.RayCheck(RefinedOrigin, CandidateHit, TargetPart)
            then
                Best = CandidateHit
                Low = Alpha
            else
                High = Alpha
            end
        end

        RefinedHit = Best
    end

    return RefinedOrigin, RefinedHit
end

function RageCrimEngine.GetSmartOriginCandidates(BaseOrigin, TargetPosition, Blockers, MaximumDistance)
    if type(Blockers) ~= "table" or #Blockers == 0 then return {} end

    MaximumDistance = math.clamp(
        tonumber(MaximumDistance) or RageCrimEngine.MaximumOriginDistance,
        RageCrimEngine.MinimumOriginDistance,
        RageCrimEngine.MaximumOriginDistance
    )

    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local Margin = math.max(tonumber(RageCrimEngine.SmartMargin) or 1.10, 0.25)
    local Candidates, Seen = {}, {}
    local CombinedRight, CombinedLeft = -math.huge, math.huge
    local CombinedUp, CombinedDown = -math.huge, math.huge

    local function PushXY(X, Y, Source, Priority)
        if type(X) ~= "number" or type(Y) ~= "number" then return end
        if X ~= X or Y ~= Y then return end

        local Offset = Right * X + Up * Y
        local Magnitude = Offset.Magnitude

        if Magnitude <= 0.05 or Magnitude > MaximumDistance + 0.001 then return end

        local Key =
            tostring(math.floor(X * 3 + 0.5))
            .. ":" .. tostring(math.floor(Y * 3 + 0.5))

        if Seen[Key] then return end
        Seen[Key] = true

        Candidates[#Candidates + 1] = {
            Origin = BaseOrigin + Offset,
            Magnitude = Magnitude,
            Source = Source or "smart",
            Priority = tonumber(Priority) or 0,
            Quality = Magnitude + math.abs(X) * 0.015 + math.abs(Y) * 0.015
        }
    end

    for Index = 1, #Blockers do
        local Data = RageCrimEngine.GetProjectedBlockerData(
            BaseOrigin,
            TargetPosition,
            Blockers[Index]
        )

        if Data then
            local RightEdge = (Data.CenterRight + Data.ExtentRight + Margin) / Data.Leverage
            local LeftEdge = (Data.CenterRight - Data.ExtentRight - Margin) / Data.Leverage
            local UpEdge = (Data.CenterUp + Data.ExtentUp + Margin) / Data.Leverage
            local DownEdge = (Data.CenterUp - Data.ExtentUp - Margin) / Data.Leverage
            local CenterX = Data.CenterRight / Data.Leverage
            local CenterY = Data.CenterUp / Data.Leverage

            CombinedRight = math.max(CombinedRight, RightEdge)
            CombinedLeft = math.min(CombinedLeft, LeftEdge)
            CombinedUp = math.max(CombinedUp, UpEdge)
            CombinedDown = math.min(CombinedDown, DownEdge)

            -- Exact silhouette escape points plus two tiny safety expansions.
            local EdgeScales = {1.00, 1.045, 1.09}

            for ScaleIndex = 1, #EdgeScales do
                local Scale = EdgeScales[ScaleIndex]
                local Priority = Index + (ScaleIndex - 1) * 0.12

                PushXY(RightEdge * Scale, CenterY, "edge-r", Priority)
                PushXY(LeftEdge * Scale, CenterY, "edge-l", Priority)
                PushXY(CenterX, UpEdge * Scale, "edge-u", Priority)
                PushXY(CenterX, DownEdge * Scale, "edge-d", Priority)
            end

            PushXY(RightEdge, UpEdge, "corner-ru", Index + 0.08)
            PushXY(RightEdge, DownEdge, "corner-rd", Index + 0.08)
            PushXY(LeftEdge, UpEdge, "corner-lu", Index + 0.08)
            PushXY(LeftEdge, DownEdge, "corner-ld", Index + 0.08)

            -- Surface tangent hints are cheap and useful for rotated walls.
            local CurrentBlocker = Blockers[Index]
            local Normal =
                CurrentBlocker
                and CurrentBlocker.Normal
                or CurrentBlocker
                    and type(CurrentBlocker.Hits) == "table"
                    and CurrentBlocker.Hits[1]
                    and CurrentBlocker.Hits[1].Normal

            if typeof(Normal) == "Vector3" and Normal.Magnitude > 0.05 then
                local Tangent = Forward:Cross(Normal)

                if Tangent.Magnitude > 0.05 then
                    Tangent = Tangent.Unit
                    local TangentX = Tangent:Dot(Right)
                    local TangentY = Tangent:Dot(Up)
                    local HintRadius = math.min(
                        MaximumDistance,
                        math.max(
                            RageCrimEngine.MinimumOriginDistance,
                            math.min(
                                math.abs(RightEdge),
                                math.abs(LeftEdge),
                                math.abs(UpEdge),
                                math.abs(DownEdge)
                            )
                        )
                    )

                    PushXY(TangentX * HintRadius, TangentY * HintRadius, "tangent", Index + 0.2)
                    PushXY(-TangentX * HintRadius, -TangentY * HintRadius, "tangent", Index + 0.2)
                end
            end
        end
    end

    -- Combined constraints solve several walls at once.
    if CombinedRight > -math.huge then
        PushXY(CombinedRight, 0, "combined-r", -4)
        PushXY(CombinedLeft, 0, "combined-l", -4)
        PushXY(0, CombinedUp, "combined-u", -4)
        PushXY(0, CombinedDown, "combined-d", -4)

        PushXY(CombinedRight, CombinedUp, "combined-ru", -3)
        PushXY(CombinedRight, CombinedDown, "combined-rd", -3)
        PushXY(CombinedLeft, CombinedUp, "combined-lu", -3)
        PushXY(CombinedLeft, CombinedDown, "combined-ld", -3)
    end

    table.sort(Candidates, function(A, B)
        if math.abs(A.Priority - B.Priority) > 0.001 then return A.Priority < B.Priority end
        if math.abs((A.Quality or A.Magnitude) - (B.Quality or B.Magnitude)) > 0.001 then
            return (A.Quality or A.Magnitude) < (B.Quality or B.Magnitude)
        end
        return A.Magnitude < B.Magnitude
    end)

    local Limit = math.min(
        #Candidates,
        math.max(math.floor(tonumber(RageCrimEngine.SmartCandidateLimit) or 52), 12)
    )

    while #Candidates > Limit do table.remove(Candidates) end
    return Candidates
end

function RageCrimEngine.GetGenericOriginCandidates(BaseOrigin, TargetPosition, Radius)
    local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
        BaseOrigin,
        TargetPosition
    )

    local Candidates = {}
    local Limit = math.max(math.floor(tonumber(RageCrimEngine.GenericCandidateLimit) or 24), 8)

    local function SampleTemplate(Template, Stage, Count)
        if #Template == 0 or Count <= 0 then return end
        local Step = math.max(math.floor(#Template / Count), 1)
        local Index = 1
        local Added = 0

        while Index <= #Template and Added < Count do
            local Origin, Magnitude = RageCrimEngine.TransformSample(
                BaseOrigin,
                Forward,
                Right,
                Up,
                Template[Index],
                Radius
            )

            Candidates[#Candidates + 1] = {
                Origin = Origin,
                Magnitude = Magnitude,
                Source = Stage
            }

            Added += 1
            Index += Step
        end
    end

    local SphereBudget = math.floor(Limit * 0.42)
    local RingBudget = math.floor(Limit * 0.38)
    local SpiralBudget = math.max(Limit - SphereBudget - RingBudget, 1)

    SampleTemplate(RageCrimEngine.SphereTemplate, "sphere", SphereBudget)
    SampleTemplate(RageCrimEngine.RingTemplate, "rings", RingBudget)
    SampleTemplate(RageCrimEngine.SpiralTemplate, "spiral", SpiralBudget)

    return Candidates
end

function RageCrimEngine.GetOriginBanks(BaseOrigin, TargetPosition, Radius, Blockers)
    local PrimaryBlocker = type(Blockers) == "table" and Blockers[1] or Blockers
    local Forward, Right, Up = RageCrimEngine.GetBlockerBasis(BaseOrigin, TargetPosition, PrimaryBlocker)

    local Banks = {
        {Name = "sphere", Points = table.create(#RageCrimEngine.SphereTemplate)},
        {Name = "spiral", Points = table.create(#RageCrimEngine.SpiralTemplate)},
        {Name = "rings", Points = table.create(#RageCrimEngine.RingTemplate)},
        {Name = "blocker", Points = {}}
    }

    for Index = 1, #RageCrimEngine.SphereTemplate do
        local Origin, Magnitude = RageCrimEngine.TransformSample(
            BaseOrigin, Forward, Right, Up, RageCrimEngine.SphereTemplate[Index], Radius
        )
        Banks[1].Points[Index] = {Origin = Origin, Magnitude = Magnitude}
    end

    for Index = 1, #RageCrimEngine.SpiralTemplate do
        local Origin, Magnitude = RageCrimEngine.TransformSample(
            BaseOrigin, Forward, Right, Up, RageCrimEngine.SpiralTemplate[Index], Radius
        )
        Banks[2].Points[Index] = {Origin = Origin, Magnitude = Magnitude}
    end

    for Index = 1, #RageCrimEngine.RingTemplate do
        local Origin, Magnitude = RageCrimEngine.TransformSample(
            BaseOrigin, Forward, Right, Up, RageCrimEngine.RingTemplate[Index], Radius
        )
        Banks[3].Points[Index] = {Origin = Origin, Magnitude = Magnitude}
    end

    local BlockerPoints = Banks[4].Points
    local SeenDirections = {}

    local function PushDirection(Direction, Level, ForwardBias)
        if typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.05 then return end
        Direction = Direction.Unit

        local Key =
            tostring(math.floor(Direction.X * 14 + 0.5)) .. ":"
            .. tostring(math.floor(Direction.Y * 14 + 0.5)) .. ":"
            .. tostring(math.floor(Direction.Z * 14 + 0.5)) .. ":"
            .. tostring(math.floor((Level or 1) * 20 + 0.5))

        if SeenDirections[Key] then return end
        SeenDirections[Key] = true

        local Offset =
            Direction * Radius * math.clamp(Level or 1, 0.45, 1)
            + Forward * Radius * math.clamp(ForwardBias or 0, -0.10, 0.10)

        if Offset.Magnitude > Radius then Offset = Offset.Unit * Radius end

        BlockerPoints[#BlockerPoints + 1] = {
            Origin = BaseOrigin + Offset,
            Magnitude = Offset.Magnitude
        }
    end

    if type(Blockers) == "table" then
        for BlockerIndex = 1, #Blockers do
            local Blocker = Blockers[BlockerIndex]
            local Part = Blocker and Blocker.Instance

            if Part and Part:IsA("BasePart") then
                local PartFrame = Part.CFrame
                local Half = Part.Size * 0.5
                local Levels =
                    BlockerIndex == 1
                    and RageCrimEngine.BlockerArcLevels
                    or RageCrimEngine.SecondaryBlockerLevels

                -- Exact obstacle corners, projected into origin space.
                for X = -1, 1, 2 do
                    for Y = -1, 1, 2 do
                        for Z = -1, 1, 2 do
                            local Corner = PartFrame:PointToWorldSpace(
                                Vector3.new(Half.X * X, Half.Y * Y, Half.Z * Z)
                            )

                            local ToCorner = Corner - BaseOrigin
                            local Lateral = ToCorner - Forward * ToCorner:Dot(Forward)

                            if Lateral.Magnitude > 0.10 then
                                for LevelIndex = 1, #Levels do
                                    PushDirection(
                                        Lateral,
                                        Levels[LevelIndex],
                                        (BlockerIndex - 1) * 0.012
                                    )
                                end
                            end
                        end
                    end
                end

                -- Tangents derived from the actual surface hit normal.
                local Normal = Blocker.Normal
                if typeof(Normal) == "Vector3" and Normal.Magnitude > 0.05 then
                    local Tangent = Forward:Cross(Normal)
                    if Tangent.Magnitude > 0.05 then
                        Tangent = Tangent.Unit
                        for _, Level in ipairs({0.72, 0.88, 1.00}) do
                            PushDirection(Tangent, Level, 0)
                            PushDirection(-Tangent, Level, 0)
                        end
                    end

                    local VerticalTangent = Normal:Cross(Tangent)
                    if typeof(VerticalTangent) == "Vector3" and VerticalTangent.Magnitude > 0.05 then
                        for _, Level in ipairs({0.78, 1.00}) do
                            PushDirection(VerticalTangent, Level, 0)
                            PushDirection(-VerticalTangent, Level, 0)
                        end
                    end
                end
            end
        end

        -- Blend escape directions between consecutive blockers.
        for Index = 1, #Blockers - 1 do
            local A = Blockers[Index]
            local B = Blockers[Index + 1]

            if A and B and typeof(A.Position) == "Vector3" and typeof(B.Position) == "Vector3" then
                local LA = A.Position - BaseOrigin
                local LB = B.Position - BaseOrigin
                LA -= Forward * LA:Dot(Forward)
                LB -= Forward * LB:Dot(Forward)

                if LA.Magnitude > 0.05 and LB.Magnitude > 0.05 then
                    local Blend = LA.Unit + LB.Unit
                    if Blend.Magnitude > 0.05 then
                        PushDirection(Blend, 0.84, 0)
                        PushDirection(Blend, 1.00, 0)
                        PushDirection(-Blend, 0.92, 0)
                    end
                end
            end
        end
    end

    -- Primary circular arcs remain useful when the blocker is centered.
    if PrimaryBlocker then
        for LevelIndex = 1, #RageCrimEngine.BlockerArcLevels do
            local Level = RageCrimEngine.BlockerArcLevels[LevelIndex]

            for Index = 1, RageCrimEngine.BlockerArcCount do
                local Angle = ((Index - 1) / RageCrimEngine.BlockerArcCount) * math.pi * 2
                local SideDirection = Right * math.cos(Angle) + Up * math.sin(Angle)
                PushDirection(
                    SideDirection,
                    Level,
                    (((Index - 1) % 3) - 1) * 0.045
                )
            end
        end
    end

    return Banks
end

function RageCrimEngine.ScoreCandidate(BaseOrigin, TargetPosition, Origin, HitPosition, Stage, Radius)
    local Offset = Origin - BaseOrigin
    local Magnitude = Offset.Magnitude
    if Magnitude > RageCrimEngine.MaximumOriginDistance + 0.001 then return math.huge end

    local Forward = TargetPosition - BaseOrigin
    if Forward.Magnitude <= 0.001 then Forward = Vector3.new(0, 0, -1) else Forward = Forward.Unit end

    local HitError = (HitPosition - TargetPosition).Magnitude
    local Axial = math.abs(Offset:Dot(Forward))
    local StagePenalty = Stage == "blocker" and -0.025
        or Stage == "sphere" and 0
        or Stage == "rings" and 0.008
        or Stage == "spiral" and 0.012
        or Stage == "direct-point" and -0.04
        or 0.02

    local PreferredPenalty = math.max(Magnitude - RageCrimEngine.PreferredOriginDistance, 0) * 0.012
    local RadiusPenalty = math.max((tonumber(Radius) or Magnitude) - RageCrimEngine.PreferredOriginDistance, 0) * 0.004

    return Magnitude / math.max(RageCrimEngine.PreferredOriginDistance, 1)
        + HitError * 0.16
        + Axial / math.max(RageCrimEngine.PreferredOriginDistance, 1) * 0.09
        + PreferredPenalty
        + RadiusPenalty
        + StagePenalty
end

function RageCrimEngine.SelectBest(TargetPart, MaximumDistance, BaseOrigin, DesiredPosition)
    RageCrimEngine.MaintainRuntimeCaches(false)

    if not TargetPart or not TargetPart:IsA("BasePart") or typeof(BaseOrigin) ~= "Vector3" then
        return nil, nil, nil
    end

    local TargetPosition = typeof(DesiredPosition) == "Vector3" and DesiredPosition or TargetPart.Position
    MaximumDistance = math.clamp(
        tonumber(MaximumDistance) or RageCrimEngine.MaximumOriginDistance,
        RageCrimEngine.MinimumOriginDistance,
        RageCrimEngine.MaximumOriginDistance
    )

    local InitialCenter = TargetPosition
    local RawBlockers = RageCrimEngine.GetBlockerChain(BaseOrigin, InitialCenter, TargetPart)
    local KnownBlockers = {}
    local DiscoveredTotal = 0
    local DiscoveredPending = 0
    local DiscoveryGeneration = 0

    for Index = 1, #RawBlockers do
        local Result = RawBlockers[Index]
        if Result and Result.Instance then KnownBlockers[Result.Instance] = true end
    end

    local Clusters = RageCrimEngine.BuildBlockerClusters(
        BaseOrigin,
        TargetPosition,
        RawBlockers
    )

    local HitSteps = RageCrimEngine.GetHeadHitpointSteps(
        TargetPart,
        TargetPosition,
        BaseOrigin,
        #Clusters
    )
    if #HitSteps == 0 then return nil, nil, nil end

    local Center = HitSteps[1].Points[1]
    local ContextKey = RageCrimEngine.GetBankContextKey(BaseOrigin, TargetPosition)
    local BlockerSignature = RageCrimEngine.GetBlockerSignature(
        Clusters,
        BaseOrigin,
        TargetPosition
    )

    local RadiusOrder, EstimatedRadius = RageCrimEngine.BuildRadiusOrder(
        TargetPart,
        BaseOrigin,
        TargetPosition,
        RawBlockers
    )

    local BestOrigin, BestHit, BestScore, BestStage, BestMagnitude, BestRadius, BestHitStep
    local BestStability, BestExposure, BestFeedbackKey, BestSide = 0, 0, nil, "center"
    local Tested = 0
    local SuccessCount = 0
    local MaximumTests = RageCrimEngine.GetSearchBudget(
        BaseOrigin,
        TargetPosition,
        #Clusters
    )
    local FamilyStats = {}

    local function RegisterDiscoveredBlocker(Result)
        if DiscoveredTotal >= math.max(
            math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryMaximum) or 14),
            1
        ) then
            return false
        end

        local Instance = Result and Result.Instance
        if not Instance or not Instance:IsA("BasePart") or KnownBlockers[Instance] then
            return false
        end

        if TargetPart and Instance:IsDescendantOf(TargetPart.Parent) then return false end

        KnownBlockers[Instance] = true
        RawBlockers[#RawBlockers + 1] = Result
        DiscoveredTotal += 1
        DiscoveredPending += 1
        return true
    end

    local function RefreshDiscoveredGeometry()
        if DiscoveredPending <= 0 then return false end

        DiscoveryGeneration += 1
        DiscoveredPending = 0

        Clusters = RageCrimEngine.BuildBlockerClusters(
            BaseOrigin,
            TargetPosition,
            RawBlockers
        )

        HitSteps = RageCrimEngine.GetHeadHitpointSteps(
            TargetPart,
            TargetPosition,
            BaseOrigin,
            #Clusters
        )

        if #HitSteps > 0 and #HitSteps[1].Points > 0 then
            Center = HitSteps[1].Points[1]
        end

        BlockerSignature = RageCrimEngine.GetBlockerSignature(
            Clusters,
            BaseOrigin,
            TargetPosition
        )

        RadiusOrder, EstimatedRadius = RageCrimEngine.BuildRadiusOrder(
            TargetPart,
            BaseOrigin,
            TargetPosition,
            RawBlockers
        )

        MaximumTests = math.min(
            math.max(math.floor(tonumber(RageCrimEngine.MaximumRayTests) or 190), 64),
            math.max(
                MaximumTests,
                RageCrimEngine.GetSearchBudget(
                    BaseOrigin,
                    TargetPosition,
                    #Clusters
                )
                + DiscoveryGeneration
                    * math.max(
                        math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryBudgetBoost) or 18),
                        0
                    )
            )
        )

        return true
    end

    local function Consider(Origin, Hit, Stage, Radius, HitStep)
        if Tested >= MaximumTests then return false end
        if typeof(Origin) ~= "Vector3" or typeof(Hit) ~= "Vector3" then return false end
        if not RagePointInsideExpectedHitbox(TargetPart, Hit) then return false end

        local Magnitude = (Origin - BaseOrigin).Magnitude
        if Magnitude > MaximumDistance + 0.001 then return false end

        local Direct = Stage == "direct" or tostring(Stage):sub(1, 11) == "direct-step"
        local Side = RageCrimEngine.GetOriginSide(BaseOrigin, Origin, TargetPosition)
        local Exposure = Direct and 1 or RageCrimEngine.GetExposureScore(
            BaseOrigin,
            Origin,
            Hit,
            TargetPosition,
            Clusters
        )

        local Family = RageCrimEngine.GetRouteFamily(Stage) .. ":" .. Side
        local Stat = FamilyStats[Family]

        if type(Stat) ~= "table" then
            Stat = {Tests = 0, Hits = 0}
            FamilyStats[Family] = Stat
        end

        if not Direct and #Clusters > 0 then
            if Exposure < RageCrimEngine.ExposureThreshold then return false end

            if Stat.Tests >= RageCrimEngine.FamilyPruneTests
                and Stat.Hits <= 0
                and Exposure < RageCrimEngine.FamilyPruneExposure
            then
                return false
            end
        end

        local FeedbackKey = not Direct and RageCrimEngine.GetRouteFeedbackKey(
            ContextKey,
            BlockerSignature,
            Stage,
            HitStep,
            Side
        ) or nil
        local FeedbackValue = RageCrimEngine.GetRouteFeedbackValue(FeedbackKey)

        if not Direct and FeedbackValue <= -3.4 and Exposure < 0.34 then
            return false
        end

        Tested += 1
        Stat.Tests += 1

        local Clear, BlockingResult = RageCrimEngine.RayCheckDetailed(
            Origin,
            Hit,
            TargetPart
        )

        if not Clear then
            RegisterDiscoveredBlocker(BlockingResult)
            return false
        end

        Stat.Hits += 1
        SuccessCount += 1

        local Stability, CorridorTests

        if Direct then
            Stability = 1
            CorridorTests = 0
        else
            Stability, CorridorTests = RageCrimEngine.GetCorridorStability(
                Origin,
                Hit,
                TargetPart
            )
            Stability = tonumber(Stability) or 0
            CorridorTests = math.max(math.floor(tonumber(CorridorTests) or 0), 0)
        end

        Tested += CorridorTests

        local Score = RageCrimEngine.ScoreCandidate(
            BaseOrigin,
            TargetPosition,
            Origin,
            Hit,
            Stage,
            Radius
        )

        local HeadRadius = math.max(TargetPart.Size.Magnitude * 0.5, 0.5)
        local CenterDistance = (Hit - TargetPosition).Magnitude / HeadRadius

        Score += math.max((tonumber(HitStep) or 1) - 1, 0) * 0.0032
        Score += (1 - Stability) * 0.080
        Score += CenterDistance * 0.015
        Score += math.max(#Clusters - 1, 0) * 0.0025
        Score -= Exposure * 0.022
        Score -= math.clamp(FeedbackValue, -5, 8) * 0.014

        local HitOffset = Hit - TargetPosition
        local OriginOffset = Origin - BaseOrigin

        if HitOffset.Magnitude > 0.001 and OriginOffset.Magnitude > 0.001 then
            local Alignment = HitOffset.Unit:Dot(OriginOffset.Unit)
            Score -= math.max(Alignment, 0) * 0.016
        end

        local BankName = RageCrimEngine.GetBankName(Stage)
        if BankName then
            local BankState = RageCrimEngine.GetBankState(ContextKey)[BankName]
            Score -= math.clamp(tonumber(BankState.Value) or 0, -3, 5) * 0.014
        end

        if BestScore == nil
            or Score < BestScore - 0.001
            or math.abs(Score - BestScore) <= 0.001 and Stability > BestStability + 0.001
            or math.abs(Score - BestScore) <= 0.001
                and math.abs(Stability - BestStability) <= 0.001
                and Magnitude < (BestMagnitude or math.huge)
        then
            BestOrigin = Origin
            BestHit = Hit
            BestScore = Score
            BestStage = Stage
            BestMagnitude = Magnitude
            BestRadius = Radius
            BestHitStep = HitStep
            BestStability = Stability
            BestExposure = Exposure
            BestFeedbackKey = FeedbackKey
            BestSide = Side
        end

        if Direct then return true end
        if Stability >= RageCrimEngine.CorridorExcellent then return true end
        if SuccessCount >= 3 and Stability >= RageCrimEngine.CorridorMinimumStable then return true end
        return false
    end

    local function Commit()
        if not BestOrigin or not BestHit then return nil, nil, nil end

        if BestStage ~= "direct" and tostring(BestStage):sub(1, 11) ~= "direct-step" then
            BestOrigin, BestHit = RageCrimEngine.RefineOriginNeighborhood(
                BaseOrigin,
                BestOrigin,
                BestHit,
                TargetPosition,
                TargetPart
            )
        end

        local RefinedOrigin, RefinedHit = RageCrimEngine.RefineSuccessfulRoute(
            BaseOrigin,
            BestOrigin,
            TargetPosition,
            BestHit,
            TargetPart
        )

        if typeof(RefinedOrigin) == "Vector3"
            and typeof(RefinedHit) == "Vector3"
            and RageCrimEngine.RayCheck(RefinedOrigin, RefinedHit, TargetPart)
        then
            BestOrigin = RefinedOrigin
            BestHit = RefinedHit
            BestMagnitude = (BestOrigin - BaseOrigin).Magnitude
        end

        local FinalStability = BestStage == "direct"
            and 1
            or RageCrimEngine.GetCorridorStability(
                BestOrigin,
                BestHit,
                TargetPart
            )

        BestStability = math.max(BestStability, FinalStability)

        local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
            BaseOrigin,
            TargetPosition
        )
        local OriginOffset = BestOrigin - BaseOrigin
        local OriginLocal = Vector3.new(
            OriginOffset:Dot(Right),
            OriginOffset:Dot(Up),
            OriginOffset:Dot(Forward)
        )
        local HitLocal = TargetPart.CFrame:VectorToObjectSpace(BestHit - TargetPosition)
        local CacheLifetime = RageCrimEngine.GetAdaptiveRouteCacheLifetime(TargetPart)

        RageCrimEngine.RadiusCache[TargetPart] = {
            Radius = BestRadius or BestMagnitude or RageCrimEngine.PreferredOriginDistance,
            Magnitude = BestMagnitude,
            Time = os.clock()
        }

        RageCrimEngine.RouteCache[TargetPart] = {
            OriginLocal = OriginLocal,
            HitLocal = HitLocal,
            Stage = BestStage,
            Radius = BestRadius,
            HitStep = BestHitStep,
            BlockerSignature = BlockerSignature,
            Lifetime = CacheLifetime,
            Time = os.clock()
        }

        RageCrimEngine.CacheHeadPoint(
            TargetPart,
            TargetPosition,
            BestHit,
            BestHitStep
        )

        return BestOrigin, BestHit, {
            Stage = BestStage,
            HitStep = BestHitStep,
            Score = BestScore,
            Shift = BestMagnitude,
            Magnitude = BestMagnitude,
            Radius = BestRadius or BestMagnitude,
            EstimatedRadius = EstimatedRadius,
            Blockers = #Clusters,
            RawBlockers = #RawBlockers,
            DiscoveryGeneration = DiscoveryGeneration,
            DiscoveredBlockers = DiscoveredTotal,
            Tested = Tested,
            ContextKey = ContextKey,
            BlockerSignature = BlockerSignature,
            RouteFeedbackKey = BestFeedbackKey,
            OriginSide = BestSide,
            Stability = BestStability,
            Exposure = BestExposure,
            Confirmed = true
        }
    end

    if Consider(BaseOrigin, Center, "direct", 0, 1) then return Commit() end

    local CachedRoute = RageCrimEngine.RouteCache[TargetPart]

    if type(CachedRoute) == "table"
        and CachedRoute.BlockerSignature == BlockerSignature
        and typeof(CachedRoute.OriginLocal) == "Vector3"
        and typeof(CachedRoute.HitLocal) == "Vector3"
    then
        local CacheLifetime = math.min(
            tonumber(CachedRoute.Lifetime) or RageCrimEngine.RouteCacheLifetime,
            RageCrimEngine.GetAdaptiveRouteCacheLifetime(TargetPart)
        )

        if os.clock() - (tonumber(CachedRoute.Time) or 0) <= CacheLifetime then
            local Forward, Right, Up = RageBotAPI.CriminologyGetDirectionBasisFromPositions(
                BaseOrigin,
                TargetPosition
            )

            local LocalOffset = CachedRoute.OriginLocal
            local CachedOrigin =
                BaseOrigin
                + Right * LocalOffset.X
                + Up * LocalOffset.Y
                + Forward * LocalOffset.Z

            local CachedHit =
                TargetPosition
                + TargetPart.CFrame:VectorToWorldSpace(CachedRoute.HitLocal)

            if Consider(
                CachedOrigin,
                CachedHit,
                tostring(CachedRoute.Stage or "blocker"),
                tonumber(CachedRoute.Radius) or LocalOffset.Magnitude,
                tonumber(CachedRoute.HitStep) or 1
            ) then
                return Commit()
            end
        end
    end

    local CachedHeadPoint, CachedHeadStep = RageCrimEngine.GetCachedHeadPoint(
        TargetPart,
        TargetPosition
    )

    if CachedHeadPoint
        and Consider(
            BaseOrigin,
            CachedHeadPoint,
            "direct-cached-point",
            0,
            CachedHeadStep or 1
        )
    then
        return Commit()
    end

    local DirectTests = 0
    local DirectLimit = math.max(math.floor(tonumber(RageCrimEngine.DirectStepLimit) or 24), 8)

    for StepIndex = 2, #HitSteps do
        local Points = HitSteps[StepIndex].Points

        for PointIndex = 1, #Points do
            DirectTests += 1

            if Consider(
                BaseOrigin,
                Points[PointIndex],
                "direct-step" .. tostring(StepIndex),
                0,
                StepIndex
            ) then
                return Commit()
            end

            if Tested >= MaximumTests or DirectTests >= DirectLimit then break end
        end

        if Tested >= MaximumTests or DirectTests >= DirectLimit then break end
    end

    RefreshDiscoveredGeometry()

    local GuidedLimit = math.max(math.floor(tonumber(RageCrimEngine.GuidedHitpointLimit) or 20), 8)
    local MaximumGenerations = math.max(
        math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryGenerations) or 4),
        1
    )

    for Generation = 1, MaximumGenerations do
        local GenerationStartDiscovered = DiscoveredTotal
        local GenerationDiscoveries = 0
        local Smart = RageCrimEngine.GetSmartOriginCandidates(
            BaseOrigin,
            TargetPosition,
            Clusters,
            MaximumDistance
        )

        for CandidateIndex = 1, #Smart do
            local Candidate = Smart[CandidateIndex]
            local OrderedPoints = RageCrimEngine.OrderHitpointsForOrigin(
                HitSteps,
                BaseOrigin,
                Candidate.Origin,
                TargetPosition,
                Clusters
            )

            local PairLimit = math.min(
                #OrderedPoints,
                CandidateIndex <= 8
                    and GuidedLimit
                    or math.max(math.floor(GuidedLimit * 0.45), 6)
            )

            for PointIndex = 1, PairLimit do
                local Point = OrderedPoints[PointIndex]

                if Point.Exposure >= RageCrimEngine.ExposureThreshold then
                    local BeforeDiscovered = DiscoveredTotal

                    if Consider(
                        Candidate.Origin,
                        Point.Position,
                        "blocker-g" .. tostring(Generation)
                            .. "-" .. tostring(Candidate.Source or "smart")
                            .. "-step" .. tostring(Point.Step),
                        Candidate.Magnitude,
                        Point.Step
                    ) then
                        return Commit()
                    end

                    if DiscoveredTotal > BeforeDiscovered then
                        GenerationDiscoveries += DiscoveredTotal - BeforeDiscovered

                        if GenerationDiscoveries >= math.max(
                            math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryPerGeneration) or 6),
                            1
                        ) then
                            break
                        end
                    end
                end

                if Tested >= MaximumTests then break end
            end

            if Tested >= MaximumTests
                or GenerationDiscoveries >= math.max(
                    math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryPerGeneration) or 6),
                    1
                )
            then
                break
            end
        end

        if BestOrigin and BestStability >= RageCrimEngine.CorridorMinimumStable then
            return Commit()
        end

        if Tested >= MaximumTests then break end

        if DiscoveredTotal <= GenerationStartDiscovered then
            break
        end

        if not RefreshDiscoveredGeometry() then
            break
        end
    end

    if BestOrigin and BestStability >= RageCrimEngine.CorridorMinimumStable then
        return Commit()
    end

    for RadiusIndex = 1, #RadiusOrder do
        local Radius = math.min(RadiusOrder[RadiusIndex], MaximumDistance)
        local Generic = RageCrimEngine.GetGenericOriginCandidates(
            BaseOrigin,
            TargetPosition,
            Radius
        )

        for CandidateIndex = 1, #Generic do
            local Candidate = Generic[CandidateIndex]
            local OrderedPoints = RageCrimEngine.OrderHitpointsForOrigin(
                HitSteps,
                BaseOrigin,
                Candidate.Origin,
                TargetPosition,
                Clusters
            )

            local PairLimit = math.min(
                #OrderedPoints,
                math.max(math.floor(GuidedLimit * 0.45), 7)
            )

            for PointIndex = 1, PairLimit do
                local Point = OrderedPoints[PointIndex]

                if Point.Exposure >= RageCrimEngine.ExposureThreshold then
                    if Consider(
                        Candidate.Origin,
                        Point.Position,
                        tostring(Candidate.Source) .. "-guided-step" .. tostring(Point.Step),
                        Radius,
                        Point.Step
                    ) then
                        return Commit()
                    end
                end

                if Tested >= MaximumTests then break end
            end

            if Tested >= MaximumTests then break end
        end

        if BestOrigin and BestStability >= RageCrimEngine.CorridorMinimumStable then
            return Commit()
        end

        if Tested >= MaximumTests then break end
    end

    if BestOrigin then return Commit() end

    if DiscoveredPending > 0
        and DiscoveryGeneration < math.max(
            math.floor(tonumber(RageCrimEngine.ProgressiveDiscoveryGenerations) or 4),
            1
        )
        and Tested < MaximumTests
    then
        RefreshDiscoveredGeometry()

        local Rescue = RageCrimEngine.GetSmartOriginCandidates(
            BaseOrigin,
            TargetPosition,
            Clusters,
            MaximumDistance
        )

        local RescueLimit = math.min(#Rescue, 24)

        for CandidateIndex = 1, RescueLimit do
            local Candidate = Rescue[CandidateIndex]
            local OrderedPoints = RageCrimEngine.OrderHitpointsForOrigin(
                HitSteps,
                BaseOrigin,
                Candidate.Origin,
                TargetPosition,
                Clusters
            )

            local PairLimit = math.min(#OrderedPoints, 12)

            for PointIndex = 1, PairLimit do
                local Point = OrderedPoints[PointIndex]

                if Point.Exposure >= RageCrimEngine.ExposureThreshold
                    and Consider(
                        Candidate.Origin,
                        Point.Position,
                        "blocker-rescue-step" .. tostring(Point.Step),
                        Candidate.Magnitude,
                        Point.Step
                    )
                then
                    return Commit()
                end

                if Tested >= MaximumTests then break end
            end

            if Tested >= MaximumTests then break end
        end
    end

    if BestOrigin then return Commit() end

    RageSetWallbangDiagnostic(
        "blocked",
        "progressive-no-route-g" .. tostring(DiscoveryGeneration)
            .. "-d" .. tostring(DiscoveredTotal),
        Tested,
        EstimatedRadius
    )
    return nil, nil, nil
end

function RageMapEngine.Solve(TargetPart, MaximumRadius, BaseOrigin, DesiredPosition)
    return RageCrimEngine.SelectBest(
        TargetPart,
        math.min(tonumber(MaximumRadius) or RageCrimEngine.MaximumOriginDistance, RageCrimEngine.MaximumOriginDistance),
        BaseOrigin,
        DesiredPosition
    )
end

function RageRayPoints(TargetPart, MaxOriginDistance, BaseOrigin, DesiredPosition)
    local Character = LocalPlayer.Character
    local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    BaseOrigin = typeof(BaseOrigin) == "Vector3" and BaseOrigin or Root and Root.Position or nil
    if not BaseOrigin then return nil, nil, nil end

    return RageCrimEngine.SelectBest(
        TargetPart,
        math.min(
            tonumber(MaxOriginDistance) or RageCrimEngine.MaximumOriginDistance,
            RageCrimEngine.MaximumOriginDistance
        ),
        BaseOrigin,
        DesiredPosition
    )
end

RageBotAPI.ValidateRageRoute = function(Origin, HitPosition, TargetPart)
    return RageCrimEngine.RayCheck(Origin, HitPosition, TargetPart)
end

RageBotAPI.RageRayPointsExport = RageRayPoints

function RageBotAPI.RejectRageRoute(Shot)
    if type(Shot) ~= "table" then return end
    RageCrimEngine.RecordBankFeedback(Shot.BankContextKey, Shot.WallbangStage, false)
    RageCrimEngine.RecordRouteFeedback(Shot.RouteFeedbackKey, false)
end

function RageBotAPI.ConfirmRageRoute(Shot)
    if type(Shot) ~= "table" then return end
    RageCrimEngine.RecordBankFeedback(Shot.BankContextKey, Shot.WallbangStage, true)
    RageCrimEngine.RecordRouteFeedback(Shot.RouteFeedbackKey, true)
end

function RageBotAPI.CrimGetToolConfig(Tool)
    return GetRageWeaponConfig(Tool)
end

function RageBotAPI.GetRageToolData(Tool)
    if not Tool or not Tool:IsA("Tool") then return nil end
    local Cached = RageHotCache.ToolData[Tool]
    if type(Cached) == "table" and Cached.Tool == Tool and Tool.Parent and Cached.Values and Cached.Values.Parent == Tool and Cached.Ammo and Cached.Ammo.Parent == Cached.Values then return Cached end
    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values and Values:FindFirstChild("SERVER_Ammo")
    local Data = {Tool = Tool, Values = Values, Ammo = Ammo, Config = GetRageWeaponConfig(Tool)}
    RageHotCache.ToolData[Tool] = Data
    return Data
end

function RageBotAPI.GetRageRemote(Name)
    local Events = RageHotCache.Events
    if not Events or not Events.Parent then
        Events = ReplicatedStorage:FindFirstChild("Events")
        RageHotCache.Events = Events
        table.clear(RageHotCache.Remotes)
    end
    if not Events then return nil end

    local Remote = RageHotCache.Remotes[Name]
    if not Remote or Remote.Parent ~= Events then
        Remote = Events:FindFirstChild(Name)
        RageHotCache.Remotes[Name] = Remote
    end
    return Remote
end

function RageBotAPI.CrimGetFireDelay(Tool, Config)
    Config = type(Config) == "table" and Config or GetRageWeaponConfig(Tool)
    local Delay = math.clamp(tonumber(RageBotSettings.Delay) or 0.03, 0.01, 0.5)
    local Rate = Config and tonumber(Config.FireRate) or nil
    local Modes = Config and Config.FireModeSettings or nil
    if type(Modes) == "table" then
        if tostring(Modes.SwitchTo or "") == "Burst" and tonumber(Modes.BurstRate) then Rate = tonumber(Modes.BurstRate)
        elseif tonumber(Modes.SemiRate) then Rate = tonumber(Modes.SemiRate) end
    end
    return Rate and Rate > 0 and math.max(Delay, 1 / Rate) or Delay
end

function RageBotAPI.CrimReload(Tool)
    if RageBotSettings.AutoReload ~= true or not Tool then return false end
    local Remote = RageBotAPI.GetRageRemote("GNX_R")
    if not Remote or not Remote:IsA("RemoteEvent") then return false end
    for _ = 1, 2 do
        local Key = RageBotAPI.GetRageRemoteKey(Tool, GetRageWeaponConfig(Tool))
        if typeof(Key) == "number" then Remote:FireServer(Key, "KLWE89U0", Tool) end
    end
    return true
end

function RageBotAPI.ResetCrimSearchState()
    if RageWallbangRuntime then
        if RageWallbangRuntime.Cache then table.clear(RageWallbangRuntime.Cache) end
        if RageWallbangRuntime.NextScan then table.clear(RageWallbangRuntime.NextScan) end
        if RageWallbangRuntime.ExpectedTarget then table.clear(RageWallbangRuntime.ExpectedTarget) end
        if RageWallbangRuntime.BadRoutes then table.clear(RageWallbangRuntime.BadRoutes) end
        if RageWallbangRuntime.StableRoutes then table.clear(RageWallbangRuntime.StableRoutes) end
    end

    if RageCrimEngine and RageCrimEngine.RadiusCache then
        table.clear(RageCrimEngine.RadiusCache)
    end

    if RageCrimEngine and RageCrimEngine.RouteCache then
        table.clear(RageCrimEngine.RouteCache)
    end

    if RageCrimEngine and RageCrimEngine.HeadPointCache then
        table.clear(RageCrimEngine.HeadPointCache)
    end

    if RageCrimEngine and RageCrimEngine.ClusterExpansionCache then
        table.clear(RageCrimEngine.ClusterExpansionCache)
    end

    if RageBotRuntime and RageBotRuntime.MotionHistory then table.clear(RageBotRuntime.MotionHistory) end
    if RageBotRuntime and RageBotRuntime.PeekGuard then table.clear(RageBotRuntime.PeekGuard) end

    if RageHotCache then
        if RageHotCache.PlayerStats then table.clear(RageHotCache.PlayerStats) end
        if RageHotCache.DownedValues then table.clear(RageHotCache.DownedValues) end
        if RageHotCache.ScanParts then table.clear(RageHotCache.ScanParts) end
        if RageHotCache.CharacterData then table.clear(RageHotCache.CharacterData) end
        if RageHotCache.ToolData then table.clear(RageHotCache.ToolData) end
        RageHotCache.PlayerList = {}
        RageHotCache.PlayerListCount = -1
        RageHotCache.PlayerListTime = 0
    end

    RageCrimEngine.RefreshRayParams()
end

function RageBotAPI.CrimRageRayPoints(TargetPart, MaximumDistance, BaseOrigin, DesiredPosition)
    return RageRayPoints(TargetPart, MaximumDistance, BaseOrigin, DesiredPosition)
end

RageBotAPI.RageRayPointsExport = RageRayPoints

function RageBotAPI.IsRageTargetDowned(Player)
    if getgenv().DownedCheck == false or not Player then return false end

    local CharStats = RageHotCache.CharStats
    if not CharStats or not CharStats.Parent then
        CharStats = ReplicatedStorage:FindFirstChild("CharStats")
        RageHotCache.CharStats = CharStats
        table.clear(RageHotCache.PlayerStats)
        table.clear(RageHotCache.DownedValues)
    end
    if not CharStats then return false end

    local PlayerStats = RageHotCache.PlayerStats[Player]
    if not PlayerStats or PlayerStats.Parent ~= CharStats then
        PlayerStats = CharStats:FindFirstChild(Player.Name)
        RageHotCache.PlayerStats[Player] = PlayerStats
        RageHotCache.DownedValues[Player] = nil
    end
    if not PlayerStats then return false end

    local Downed = RageHotCache.DownedValues[Player]
    if not Downed or Downed.Parent ~= PlayerStats then
        Downed = PlayerStats:FindFirstChild("Downed")
        RageHotCache.DownedValues[Player] = Downed
    end

    return Downed ~= nil and Downed.Value == true
end

function IsRageDowned(Player)
    return RageBotAPI.IsRageTargetDowned(Player)
end

RageBotAPI.IsTargetDowned = RageBotAPI.IsRageTargetDowned

function IsRageFirearm(Tool)
    if not Tool or not Tool:IsA("Tool") then return false end
    local Values = Tool:FindFirstChild("Values")
    if Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo")) then return true end
    if Tool:FindFirstChild("Hitmarker") then return true end
    local ConfigModule = Tool:FindFirstChild("Config")
    return ConfigModule ~= nil and ConfigModule:IsA("ModuleScript")
end

function GetRageMagazineSize(Tool)
    if not Tool then return nil end
    local Names = {"MagSize", "MagazineSize", "ClipSize", "MaxAmmo", "AmmoCapacity"}
    local Values = Tool:FindFirstChild("Values")
    for _, Name in ipairs(Names) do
        local Object = Values and Values:FindFirstChild(Name) or Tool:FindFirstChild(Name, true)
        if Object and (Object:IsA("NumberValue") or Object:IsA("IntValue")) then return tonumber(Object.Value) end
        local ValueAttribute = Values and Values:GetAttribute(Name)
        if type(ValueAttribute) == "number" then return ValueAttribute end
        local ToolAttribute = Tool:GetAttribute(Name)
        if type(ToolAttribute) == "number" then return ToolAttribute end
    end
    local Config = GetRageWeaponConfig(Tool)
    if type(Config) == "table" then
        for _, Name in ipairs(Names) do
            if type(Config[Name]) == "number" then return tonumber(Config[Name]) end
        end
    end
    return nil
end

function RageBotAPI.GetRageTargetPart(Character)
    if not Character then return nil end

    local PartName = tostring(RageBotSettings.TargetPart or "Head")
    local TargetPart = Character:FindFirstChild(PartName)

    if TargetPart and TargetPart:IsA("BasePart") then
        return TargetPart
    end

    if PartName == "Torso" then
        TargetPart =
            Character:FindFirstChild("UpperTorso")
            or Character:FindFirstChild("LowerTorso")
    end

    if TargetPart and TargetPart:IsA("BasePart") then
        return TargetPart
    end

    TargetPart =
        Character:FindFirstChild("Head")
        or Character:FindFirstChild("HumanoidRootPart")
        or Character.PrimaryPart

    return TargetPart and TargetPart:IsA("BasePart")
        and TargetPart
        or nil
end

local function RageHorizontal(Vector)
    return typeof(Vector) == "Vector3" and Vector3.new(Vector.X, 0, Vector.Z) or Vector3.zero
end

function RageBotAPI.GetRageMotionSnapshot(TargetPlayer, TargetCharacter)
    if not TargetCharacter then return nil end

    local Root = ResolverGetRoot(TargetCharacter)
    if not Root or not Root:IsA("BasePart") then return nil end

    local Key = TargetPlayer or TargetCharacter
    local Now = os.clock()
    local Position = Root.Position
    local Reported = Root.AssemblyLinearVelocity or Root.Velocity or Vector3.zero
    local Humanoid = TargetCharacter:FindFirstChildOfClass("Humanoid")
    local WalkSpeed = Humanoid and math.max(tonumber(Humanoid.WalkSpeed) or 16, 0) or 16
    local MoveDirection = Humanoid and Humanoid.MoveDirection or Vector3.zero
    local Intent = RageHorizontal(MoveDirection) * WalkSpeed

    local State = RageBotRuntime.MotionHistory[Key]
    if type(State) ~= "table" then
        State = {
            Position = Position,
            Velocity = Reported,
            SmoothedVelocity = Reported,
            ObservedVelocity = Reported,
            Acceleration = Vector3.zero,
            IntentVelocity = Vector3.new(Intent.X, Reported.Y, Intent.Z),
            Time = Now,
            StableSince = Now,
            LastBaitTime = -math.huge,
            BaitScore = 0,
            SampleCount = 1
        }
        RageBotRuntime.MotionHistory[Key] = State
        return State
    end

    local DeltaTime = Now - (tonumber(State.Time) or Now)
    if DeltaTime > 0 and DeltaTime < 1 / 240 then return State end
    DeltaTime = math.clamp(DeltaTime, 1 / 240, 0.18)

    local Observed = typeof(State.Position) == "Vector3" and (Position - State.Position) / DeltaTime or Reported
    local Previous = typeof(State.SmoothedVelocity) == "Vector3" and State.SmoothedVelocity or Reported
    local ObservedHorizontal = RageHorizontal(Observed)
    local ReportedHorizontal = RageHorizontal(Reported)
    local PreviousHorizontal = RageHorizontal(Previous)
    local InstantHorizontal = ObservedHorizontal.Magnitude >= 2.5 and ObservedHorizontal or ReportedHorizontal

    local Alignment = 1
    if PreviousHorizontal.Magnitude >= 3.5 and InstantHorizontal.Magnitude >= 3.5 then
        Alignment = PreviousHorizontal.Unit:Dot(InstantHorizontal.Unit)
    end

    local IntentAlignment = 1
    if InstantHorizontal.Magnitude >= 3.5 and Intent.Magnitude >= 2 then
        IntentAlignment = InstantHorizontal.Unit:Dot(Intent.Unit)
    end

    local Reversed = PreviousHorizontal.Magnitude >= 4.5 and InstantHorizontal.Magnitude >= 3.5 and Alignment < -0.04
    local HardBrake = PreviousHorizontal.Magnitude >= 8 and InstantHorizontal.Magnitude <= math.max(2.2, PreviousHorizontal.Magnitude * 0.34)
    local SharpChange = (InstantHorizontal - PreviousHorizontal).Magnitude >= 12.5
    local IntentReversal = InstantHorizontal.Magnitude >= 4 and Intent.Magnitude >= 2 and IntentAlignment < -0.04
    local IntentBrake = InstantHorizontal.Magnitude >= 8 and Intent.Magnitude <= 1.15

    local BaitEvent = Reversed or HardBrake or SharpChange or IntentReversal or IntentBrake
    local PreviousBait = tonumber(State.BaitScore) or 0
    local Decay = math.exp(-DeltaTime * 8.5)
    local BaitScore = PreviousBait * Decay

    if Reversed then BaitScore += 2.2 end
    if IntentReversal then BaitScore += 1.9 end
    if HardBrake then BaitScore += 1.5 end
    if SharpChange then BaitScore += 0.9 end
    if IntentBrake then BaitScore += 1.2 end
    BaitScore = math.clamp(BaitScore, 0, 6)

    if BaitEvent then
        State.LastBaitTime = Now
        State.StableSince = Now
    elseif InstantHorizontal.Magnitude <= 1.25 and PreviousHorizontal.Magnitude <= 1.5 then
        State.StableSince = math.min(tonumber(State.StableSince) or Now, Now)
    end

    local Blend = BaitScore >= 2.5 and 0.72 or 0.46
    local CurrentVelocity = Vector3.new(InstantHorizontal.X, Reported.Y, InstantHorizontal.Z)
    local Smoothed = Previous:Lerp(CurrentVelocity, Blend)

    local PreviousObserved = typeof(State.ObservedVelocity) == "Vector3" and State.ObservedVelocity or Observed
    local Acceleration = (Observed - PreviousObserved) / DeltaTime
    if Acceleration.Magnitude > 90 then Acceleration = Acceleration.Unit * 90 end

    State.Position = Position
    State.Velocity = Reported
    State.ObservedVelocity = Observed
    State.InstantVelocity = CurrentVelocity
    State.SmoothedVelocity = Smoothed
    State.Acceleration = Acceleration
    State.IntentVelocity = Vector3.new(Intent.X, Reported.Y, Intent.Z)
    State.Alignment = Alignment
    State.IntentAlignment = IntentAlignment
    State.Reversed = Reversed
    State.HardBrake = HardBrake
    State.SharpChange = SharpChange
    State.IntentReversal = IntentReversal
    State.IntentBrake = IntentBrake
    State.BaitScore = BaitScore
    State.Unstable = BaitScore >= 1.35 or Now - (tonumber(State.LastBaitTime) or -math.huge) < 0.055
    State.SampleCount = math.min((tonumber(State.SampleCount) or 1) + 1, 64)
    State.Time = Now
    return State
end

function RageBotAPI.ResetPeekGuard(TargetPlayer)
    if TargetPlayer then RageBotRuntime.PeekGuard[TargetPlayer] = nil end
end

function RageBotAPI.PeekCommitReady(TargetPlayer, TargetCharacter, TargetPart)
    if not TargetPlayer or not TargetCharacter or not TargetPart or not TargetPart:IsA("BasePart") then return true end
    RageBotAPI.GetRageMotionSnapshot(TargetPlayer, TargetCharacter)
    return true
end

function RageBotAPI.GetRagePredictedPosition(TargetPlayer, TargetCharacter, TargetPart)
    if not TargetPart or not TargetPart:IsA("BasePart") then return nil end

    local PredictionTime = math.clamp((tonumber(RageBotSettings.Prediction) or 0) / 1000, 0, 0.32)
    if PredictionTime <= 0 or type(ResolveCombatPosition) ~= "function" then return TargetPart.Position end

    local Position, ResolverData = ResolveCombatPosition(
        TargetPlayer,
        TargetCharacter,
        TargetPart,
        PredictionTime,
        {Resolver = true, AdaptiveExtrapolation = true, ServerTickRate = 60, MaxExtrapolationTicks = 6}
    )

    if typeof(Position) ~= "Vector3" then Position = TargetPart.Position end

    local Motion = RageBotAPI.GetRageMotionSnapshot(TargetPlayer, TargetCharacter)
    local DirectionChanges = type(ResolverData) == "table" and tonumber(ResolverData.DirectionChanges) or 0
    local ResolverVelocity = type(ResolverData) == "table" and ResolverData.ResolvedVelocity or nil
    local InstantVelocity = Motion and (Motion.InstantVelocity or Motion.Velocity) or (TargetPart.AssemblyLinearVelocity or TargetPart.Velocity or Vector3.zero)
    local InstantHorizontal = RageHorizontal(InstantVelocity)
    local ResolverHorizontal = RageHorizontal(ResolverVelocity)

    local ResolverOpposed = false
    if InstantHorizontal.Magnitude >= 4 and ResolverHorizontal.Magnitude >= 5 then
        ResolverOpposed = InstantHorizontal.Unit:Dot(ResolverHorizontal.Unit) < 0.08
    end

    local Unstable = Motion and Motion.Unstable == true or DirectionChanges >= 1 or ResolverOpposed
    if Unstable then
        local PingSeconds = math.clamp(tonumber(LocalPlayer:GetNetworkPing()) or 0, 0, 0.35)
        local IntentReversal = Motion and Motion.IntentReversal == true
        local IntentBrake = Motion and Motion.IntentBrake == true
        local ShortLead = math.clamp(PredictionTime * 0.08 + PingSeconds * 0.10, 0, 0.026)

        if IntentReversal or IntentBrake or Motion and Motion.HardBrake then
            ShortLead = 0
            Position = TargetPart.Position
        else
            Position = TargetPart.Position + InstantVelocity * ShortLead
        end

        RageWallbangRuntime.Cache[TargetPart] = nil
        RageWallbangRuntime.NextScan[TargetPart] = 0
        if Motion and Motion.Reversed then RageWallbangRuntime.StableRoutes[TargetPart] = nil end
    end

    local DivisorX = math.max(tonumber(RageBotSettings.PredictionDivisorX) or 1, 0.05)
    local DivisorY = math.max(tonumber(RageBotSettings.PredictionDivisorY) or 1, 0.05)
    local Offset = Position - TargetPart.Position
    local Adjusted = Vector3.new(Offset.X / DivisorX, Offset.Y / DivisorY, Offset.Z / DivisorX)

    local Velocity = TargetPart.AssemblyLinearVelocity or TargetPart.Velocity or Vector3.zero
    local DynamicMaximum = math.max(0.80, Velocity.Magnitude * PredictionTime * (Unstable and 0.62 or 1.35) + (Unstable and 0.28 or 0.65))
    local MaximumOffset = math.min(math.clamp(3 + PredictionTime * 52, 3, 16), DynamicMaximum)
    if Adjusted.Magnitude > MaximumOffset and Adjusted.Magnitude > 0 then Adjusted = Adjusted.Unit * MaximumOffset end

    return TargetPart.Position + Adjusted
end

function RageBotAPI.GetRageFOVPosition()
    return UserInputService:GetMouseLocation()
end

function RageBotAPI.GetRageScreenPoint(
    CameraObject,
    WorldPosition
)
    if not CameraObject
        or typeof(WorldPosition)
            ~= "Vector3"
    then
        return nil, false
    end

    local ScreenPosition,
        OnScreen =
        CameraObject:
            WorldToScreenPoint(
                WorldPosition
            )

    if typeof(ScreenPosition)
        ~= "Vector3"
    then
        return nil, false
    end

    return ScreenPosition,
        OnScreen == true
end

function RageBotAPI.RemoveRageDrawing(Object)
    if not Object then return end

    AtramentaCallChecked(function()
        Object.Visible = false
        Object:Remove()
    end)
end

function RageBotAPI.DestroyRageFOV()
    RageBotAPI.RemoveRageDrawing(
        RageBotFOVCircle
    )
    RageBotFOVCircle = nil

    for _, Circle in ipairs(
        RageBotFOVGlowCircles
        or {}
    ) do
        RageBotAPI.RemoveRageDrawing(
            Circle
        )
    end

    for _, Line in ipairs(
        RageBotFOVGradientLines
        or {}
    ) do
        RageBotAPI.RemoveRageDrawing(
            Line
        )
    end

    RageBotFOVGlowCircles = {}
    RageBotFOVGradientLines = {}
end

function RageBotAPI.CreateRageFOVCircle(
    Color,
    Thickness,
    Transparency
)
    if type(Drawing) ~= "table"
        or type(Drawing.new) ~= "function"
    then
        return nil
    end

    local Circle = Drawing.new("Circle")
    Circle.Filled = false
    Circle.NumSides = 96
    Circle.Color = Color
    Circle.Thickness = Thickness
    Circle.Transparency = Transparency
    Circle.Radius =
        math.clamp(
            tonumber(RageBotSettings.FOV)
            or 140,
            10,
            700
        )

    return Circle
end

function RageBotAPI.CreateRageFOVGlow()
    RageBotFOVGlowCircles = {}

    if RageBotSettings.FOVGlow ~= true then
        return
    end

    local BaseThickness =
        math.clamp(
            tonumber(
                RageBotSettings.FOVGlowThickness
            )
            or 8,
            3,
            24
        )

    local BaseTransparency =
        math.clamp(
            tonumber(
                RageBotSettings.FOVGlowTransparency
            )
            or 0.20,
            0,
            1
        )

    local Layers = {
        {2.25, 0.22},
        {1.62, 0.44},
        {1.08, 0.72}
    }

    for Index, Layer in ipairs(Layers) do
        local Circle =
            RageBotAPI.CreateRageFOVCircle(
                RageBotSettings.FOVGlowColor,
                math.max(
                    BaseThickness * Layer[1],
                    1
                ),
                math.clamp(
                    BaseTransparency * Layer[2],
                    0.02,
                    1
                )
            )

        if Circle then
            RageBotFOVGlowCircles[Index] =
                Circle
        end
    end
end

function RageBotAPI.CreateRageFOVGradient()
    RageBotFOVGradientLines = {}

    if RageBotSettings.FOVGradient ~= true
        or type(Drawing) ~= "table"
        or type(Drawing.new) ~= "function"
    then
        return
    end

    local SegmentCount = 64

    for Index = 1, SegmentCount do
        local Line = Drawing.new("Line")
        Line.Thickness = 2
        Line.Transparency =
            math.clamp(
                tonumber(
                    RageBotSettings.FOVTransparency
                )
                or 0.72,
                0,
                1
            )

        RageBotFOVGradientLines[Index] =
            Line
    end
end

function RageBotAPI.EnsureRageFOV()
    if not RageBotFOVCircle then
        RageBotFOVCircle =
            RageBotAPI.CreateRageFOVCircle(
                RageBotSettings.FOVColor,
                2,
                RageBotSettings.FOVTransparency
            )
    end

    if RageBotSettings.FOVGlow == true
        and #RageBotFOVGlowCircles == 0
    then
        RageBotAPI.CreateRageFOVGlow()
    elseif RageBotSettings.FOVGlow ~= true
        and #RageBotFOVGlowCircles > 0
    then
        for _, Circle in ipairs(
            RageBotFOVGlowCircles
        ) do
            RageBotAPI.RemoveRageDrawing(
                Circle
            )
        end
        RageBotFOVGlowCircles = {}
    end

    if RageBotSettings.FOVGradient == true
        and #RageBotFOVGradientLines == 0
    then
        RageBotAPI.CreateRageFOVGradient()
    elseif RageBotSettings.FOVGradient ~= true
        and #RageBotFOVGradientLines > 0
    then
        for _, Line in ipairs(
            RageBotFOVGradientLines
        ) do
            RageBotAPI.RemoveRageDrawing(
                Line
            )
        end
        RageBotFOVGradientLines = {}
    end
end

function RageBotAPI.UpdateRageFOV()
    local Visible =
        RageBotEnabled
        and RageBotSettings.TargetSelection
            == "FOV"
        and RageBotSettings.ShowFOV == true

    if not Visible then
        if RageBotFOVCircle then
            RageBotFOVCircle.Visible = false
        end

        for _, Circle in ipairs(
            RageBotFOVGlowCircles
            or {}
        ) do
            Circle.Visible = false
        end

        for _, Line in ipairs(
            RageBotFOVGradientLines
            or {}
        ) do
            Line.Visible = false
        end

        return
    end

    RageBotAPI.EnsureRageFOV()

    local Position =
        RageBotAPI.GetRageFOVPosition()

    local Radius =
        math.clamp(
            tonumber(RageBotSettings.FOV)
            or 140,
            10,
            700
        )

    local MainColor =
        RageBotSettings.FOVColor
        or Color3.fromRGB(
            255,
            255,
            255
        )

    local GradientColor =
        RageBotSettings.FOVGradientColor
        or Color3.fromRGB(
            54,
            218,
            145
        )

    local Alpha =
        math.clamp(
            tonumber(
                RageBotSettings.FOVTransparency
            )
            or 0.72,
            0,
            1
        )

    if RageBotFOVCircle then
        RageBotFOVCircle.Position = Position
        RageBotFOVCircle.Radius = Radius
        RageBotFOVCircle.Color = MainColor
        RageBotFOVCircle.Thickness =
            RageBotSettings.FOVGradient
            and 1
            or 2
        RageBotFOVCircle.Transparency =
            RageBotSettings.FOVGradient
            and math.min(
                Alpha * 0.32,
                0.28
            )
            or Alpha
        RageBotFOVCircle.Visible = true
    end

    local BaseThickness =
        math.clamp(
            tonumber(
                RageBotSettings.FOVGlowThickness
            )
            or 8,
            3,
            24
        )

    local GlowAlpha =
        math.clamp(
            tonumber(
                RageBotSettings.FOVGlowTransparency
            )
            or 0.20,
            0,
            1
        )

    local GlowLayers = {
        {2.25, 0.22},
        {1.62, 0.44},
        {1.08, 0.72}
    }

    for Index, Circle in ipairs(
        RageBotFOVGlowCircles
        or {}
    ) do
        local Layer =
            GlowLayers[Index]
            or GlowLayers[
                #GlowLayers
            ]

        Circle.Position = Position
        Circle.Radius = Radius
        Circle.Color =
            RageBotSettings.FOVGlowColor
            or GradientColor
        Circle.Thickness =
            math.max(
                BaseThickness * Layer[1],
                1
            )
        Circle.Transparency =
            math.clamp(
                GlowAlpha * Layer[2],
                0.02,
                1
            )
        Circle.Visible =
            RageBotSettings.FOVGlow == true
    end

    local Lines =
        RageBotFOVGradientLines
        or {}

    local SegmentCount = #Lines

    if RageBotSettings.FOVGradient == true
        and SegmentCount > 0
    then
        for Index, Line in ipairs(Lines) do
            local T0 =
                (Index - 1)
                / SegmentCount

            local T1 =
                Index
                / SegmentCount

            local Angle0 =
                T0 * math.pi * 2

            local Angle1 =
                T1 * math.pi * 2

            Line.From =
                Position
                + Vector2.new(
                    math.cos(Angle0)
                        * Radius,
                    math.sin(Angle0)
                        * Radius
                )

            Line.To =
                Position
                + Vector2.new(
                    math.cos(Angle1)
                        * Radius,
                    math.sin(Angle1)
                        * Radius
                )

            local Wave =
                0.5
                - 0.5
                    * math.cos(
                        T0
                        * math.pi
                        * 2
                    )

            Line.Color =
                MainColor:Lerp(
                    GradientColor,
                    Wave
                )

            Line.Thickness = 2
            Line.Transparency = Alpha
            Line.Visible = true
        end
    end
end

function RageBotAPI.RefreshRageFOV()
    local ShouldRun =
        RageBotEnabled
        and RageBotSettings.TargetSelection == "FOV"

    if ShouldRun then
        if not RageBotFOVConnection then
            RageBotFOVConnection =
                RunService.RenderStepped:Connect(
                    RageBotAPI.UpdateRageFOV
                )
        end

        RageBotAPI.UpdateRageFOV()
    else
        if RageBotFOVConnection then
            RageBotFOVConnection:Disconnect()
            RageBotFOVConnection = nil
        end

        RageBotAPI.DestroyRageFOV()
    end
end

function RageBotAPI.GetRagePlayerList()
    local Count = tonumber(Players.NumPlayers) or 0
    local Cached = RageHotCache.PlayerList
    local Now = os.clock()
    local Refresh = type(Cached) ~= "table" or RageHotCache.PlayerListCount ~= Count or Now - (tonumber(RageHotCache.PlayerListTime) or 0) > 1.25

    if not Refresh then
        for Index = 1, #Cached do
            local Player = Cached[Index]
            if not Player or Player.Parent ~= Players then Refresh = true; break end
        end
    end

    if Refresh then
        Cached = Players:GetPlayers()
        RageHotCache.PlayerList = Cached
        RageHotCache.PlayerListCount = #Cached
        RageHotCache.PlayerListTime = Now
    end

    return Cached
end

function RageBotAPI.GetRageCharacterData(Player)
    if not Player then return nil end

    local ResolvedCharacter = GetRageCharacter(Player)
    local VisualCharacter = ResolvedCharacter or Player.Character
    if not VisualCharacter or not VisualCharacter.Parent then return nil end

    local Cached = RageHotCache.CharacterData[Player]
    if type(Cached) == "table" and Cached.Character == VisualCharacter and VisualCharacter.Parent then
        local Humanoid = Cached.Humanoid
        if Humanoid and Humanoid.Parent == VisualCharacter then return Cached end
    end

    local Data = {
        Character = VisualCharacter,
        ResolvedCharacter = ResolvedCharacter,
        Humanoid = VisualCharacter:FindFirstChildOfClass("Humanoid"),
        Head = VisualCharacter:FindFirstChild("Head", true),
        Root = VisualCharacter:FindFirstChild("HumanoidRootPart", true),
        UpperTorso = VisualCharacter:FindFirstChild("UpperTorso", true),
        LowerTorso = VisualCharacter:FindFirstChild("LowerTorso", true),
        Torso = VisualCharacter:FindFirstChild("Torso", true),
        NamedParts = {}
    }

    RageHotCache.CharacterData[Player] = Data
    return Data
end

function RageBotAPI.GetCachedRagePart(Data, Name)
    if type(Data) ~= "table" or type(Name) ~= "string" or Name == "" then return nil end
    if Name == "Head" then return Data.Head end
    if Name == "HumanoidRootPart" then return Data.Root end
    if Name == "UpperTorso" then return Data.UpperTorso end
    if Name == "LowerTorso" then return Data.LowerTorso end
    if Name == "Torso" then return Data.Torso or Data.UpperTorso or Data.LowerTorso end

    local Cached = Data.NamedParts[Name]
    if Cached and Cached.Parent and Cached:IsDescendantOf(Data.Character) then return Cached end
    Cached = Data.Character:FindFirstChild(Name, true)
    if Cached and Cached:IsA("BasePart") then Data.NamedParts[Name] = Cached; return Cached end
    return nil
end

function RageBotAPI.CreateRageSelectionContext(LocalRoot)
    local CameraObject = workspace.CurrentCamera
    if not CameraObject or not LocalRoot then return nil end
    local Mode = tostring(RageBotSettings.TargetSelection or "Mouse")
    local CameraCFrame = CameraObject.CFrame
    local MousePosition = RageBotAPI.GetRageFOVPosition()
    local FOV = math.clamp(tonumber(RageBotSettings.FOV) or 140, 10, 700)

    return {
        Now = os.clock(),
        Camera = CameraObject,
        CameraCFrame = CameraCFrame,
        CameraPosition = CameraCFrame.Position,
        MousePosition = MousePosition,
        FOV = FOV,
        FOVSquared = FOV * FOV,
        Mode = Mode,
        BaseOrigin = RageBotAPI.GetRageBaseOrigin(LocalRoot) or LocalRoot.Position,
        HasEnemyTargets = AtramentaHasEnemyTargets()
    }
end

local function RageTargetAllowedFast(Player, HasEnemyTargets)
    if not Player or Player == LocalPlayer or Player.Parent ~= Players or WhitelistTable[Player] == true then return false end
    return HasEnemyTargets ~= true or EnemyTable[Player] == true
end

local function RageTargetTierFast(Player)
    if EnemyTable[Player] == true then return 3 end
    if PriorityTable[Player] == true then return 2 end
    return 1
end

function RageBotAPI.GetRageVisualCharacter(Player)
    if not Player then
        return nil
    end

    local Character =
        GetRageCharacter(
            Player
        )

    if Character
        and Character.Parent
    then
        return Character
    end

    Character =
        Player.Character

    if Character
        and Character.Parent
    then
        return Character
    end

    return nil
end

function RageBotAPI.GetRageVisualPart(
    Player,
    PreferredName
)
    local Character =
        RageBotAPI.GetRageVisualCharacter(
            Player
        )

    if not Character then
        return nil, nil
    end

    local Part = nil

    if type(PreferredName) == "string"
        and PreferredName ~= ""
    then
        Part =
            Character:
                FindFirstChild(
                    PreferredName
                )
    end

    if not Part
        or not Part:IsA("BasePart")
    then
        Part =
            RageBotAPI.GetRageTargetPart(
                Character
            )
    end

    if not Part
        or not Part:IsA("BasePart")
    then
        return Character, nil
    end

    return Character, Part
end

function RageBotAPI.GetRageScreenState(Player, PreferredName, Context)
    if not Player then return nil end

    Context = type(Context) == "table" and Context or nil
    local CameraObject = Context and Context.Camera or workspace.CurrentCamera
    if not CameraObject then return nil end

    local Data = RageBotAPI.GetRageCharacterData(Player)
    local Character = Data and Data.Character
    local Humanoid = Data and Data.Humanoid
    if not Character or not Character.Parent or not Humanoid or Humanoid.Health <= 0
        or Character:FindFirstChildOfClass("ForceField")
        or RageBotAPI.IsRageTargetDowned(Player)
    then
        return nil
    end

    local MousePosition = Context and Context.MousePosition or RageBotAPI.GetRageFOVPosition()
    local PreferredPart = type(PreferredName) == "string" and PreferredName ~= ""
        and RageBotAPI.GetCachedRagePart(Data, PreferredName)
        or nil

    local function ScreenState(Part)
        if not Part or not Part:IsA("BasePart") or not Part:IsDescendantOf(Character) then return nil end
        local ScreenPosition = CameraObject:WorldToViewportPoint(Part.Position)
        if typeof(ScreenPosition) ~= "Vector3" or ScreenPosition.Z <= 0.01 then return nil end

        local DX = ScreenPosition.X - MousePosition.X
        local DY = ScreenPosition.Y - MousePosition.Y
        local DistanceSquared = DX * DX + DY * DY
        return {
            Character = Character,
            Part = Part,
            ScreenDistanceSquared = DistanceSquared,
            ScreenDistance = math.sqrt(DistanceSquared)
        }
    end

    local PreferredState = ScreenState(PreferredPart)
    if PreferredState then return PreferredState end

    local Fallbacks = {Data.Head, Data.Root, Data.UpperTorso, Data.Torso, Data.LowerTorso}
    local BestState = nil

    for Index = 1, #Fallbacks do
        local State = ScreenState(Fallbacks[Index])
        if State and (not BestState or State.ScreenDistanceSquared < BestState.ScreenDistanceSquared) then
            BestState = State
        end
    end

    return BestState
end

function RageBotAPI.IsRageSelectionValid(Player, PreferredName, Mode, Context)
    local HasEnemyTargets = type(Context) == "table" and Context.HasEnemyTargets
    if HasEnemyTargets == nil then HasEnemyTargets = AtramentaHasEnemyTargets() end
    if not RageTargetAllowedFast(Player, HasEnemyTargets) then return false end

    Mode = tostring(Mode or RageBotSettings.TargetSelection or "Mouse")

    if Mode == "Nearest" then
        local Data = RageBotAPI.GetRageCharacterData(Player)
        local Character = Data and Data.Character
        local Humanoid = Data and Data.Humanoid
        return Character ~= nil and Humanoid ~= nil and Humanoid.Health > 0
            and not Character:FindFirstChildOfClass("ForceField")
            and not RageBotAPI.IsRageTargetDowned(Player)
    end

    local State = RageBotAPI.GetRageScreenState(Player, PreferredName, Context)
    if not State then return false end

    if Mode == "FOV" then
        local FOVSquared = type(Context) == "table" and Context.FOVSquared
        if not FOVSquared then
            local FOV = math.clamp(tonumber(RageBotSettings.FOV) or 140, 10, 700)
            FOVSquared = FOV * FOV
        end
        if State.ScreenDistanceSquared > FOVSquared then return false end
    end

    return true, State
end

function RageBotAPI.ResolveRageShotTarget(Player, VisualCharacter, VisualPart)
    if not Player or not VisualCharacter or not VisualPart then return nil, nil end

    local Data = RageBotAPI.GetRageCharacterData(Player)
    local ShotCharacter = Data and (Data.ResolvedCharacter or Data.Character)
    if not ShotCharacter or not ShotCharacter.Parent then return VisualCharacter, VisualPart end

    local ShotPart = RageBotAPI.GetCachedRagePart(Data, VisualPart.Name)
    if not ShotPart or not ShotPart:IsA("BasePart") then ShotPart = RageBotAPI.GetRageTargetPart(ShotCharacter) end
    if not ShotPart or not ShotPart:IsA("BasePart") then return VisualCharacter, VisualPart end

    if ShotCharacter ~= VisualCharacter and (ShotPart.Position - VisualPart.Position).Magnitude > 18 then return VisualCharacter, VisualPart end
    return ShotCharacter, ShotPart
end

function RageBotAPI.GetLockedRageTarget(Mode, Context)
    if RageBotSettings.Sticky ~= true
        or not RageBotStickyTarget
        or RageBotStickyTarget == LocalPlayer
    then
        return nil, nil, nil
    end

    local Player =
        RageBotStickyTarget

    Mode =
        tostring(
            Mode
            or RageBotSettings.TargetSelection
            or "Mouse"
        )

    local VisualCharacter = nil
    local VisualPart = nil

    if Mode == "Nearest" then
        local Valid =
            RageBotAPI.IsRageSelectionValid(
                Player,
                RageBotSettings.TargetPart,
                Mode,
                Context
            )

        if not Valid then
            RageBotStickyTarget = nil
            return nil, nil, nil
        end

        VisualCharacter =
            GetRageCharacter(Player)

        VisualPart =
            RageBotAPI.GetRageTargetPart(
                VisualCharacter
            )
    else
        local Valid,
            State =
            RageBotAPI.IsRageSelectionValid(
                Player,
                RageBotSettings.TargetPart,
                Mode,
                Context
            )

        if not Valid
            or type(State) ~= "table"
        then
            RageBotStickyTarget = nil
            return nil, nil, nil
        end

        VisualCharacter =
            State.Character

        VisualPart =
            State.Part
    end

    if not VisualCharacter
        or not VisualPart
    then
        RageBotStickyTarget = nil
        return nil, nil, nil
    end

    local ShotCharacter,
        ShotPart =
        RageBotAPI.ResolveRageShotTarget(
            Player,
            VisualCharacter,
            VisualPart
        )

    if not ShotCharacter
        or not ShotPart
    then
        RageBotStickyTarget = nil
        return nil, nil, nil
    end

    return Player,
        ShotCharacter,
        ShotPart
end

function RageBotAPI.GetRageTargetReadiness(Character, TargetPart, Context)
    if not Character or not TargetPart or not TargetPart:IsA("BasePart") or type(Context) ~= "table"
        or typeof(Context.BaseOrigin) ~= "Vector3"
    then
        return 0
    end

    RageBotAPI.RefreshRageRayParams(LocalPlayer)

    local Delta = TargetPart.Position - Context.BaseOrigin
    if Delta.Magnitude > 0.001 then
        local Result = workspace:Raycast(Context.BaseOrigin, Delta, RageWallbangRuntime.RayParams)
        if not Result or Result.Instance and Result.Instance:IsDescendantOf(Character) then return 4 end
    end

    local Now = Context.Now or os.clock()
    local Stable = RageWallbangRuntime.StableRoutes[TargetPart]
    if type(Stable) == "table"
        and Now - (tonumber(Stable.Time) or 0) <= 1.10
        and typeof(Stable.Origin) == "Vector3"
        and typeof(Stable.Hit) == "Vector3"
    then
        return 3
    end

    local Cached = RageWallbangRuntime.Cache[TargetPart]
    if type(Cached) == "table"
        and Now - (tonumber(Cached.Time) or 0) <= RageWallbangRuntime.CacheLifetime
        and typeof(Cached.Origin) == "Vector3"
        and typeof(Cached.Hit) == "Vector3"
    then
        return 2
    end

    return 1
end

function RageBotAPI.AcquireRageTarget(LocalRoot, Context)
    Context = Context or RageBotAPI.CreateRageSelectionContext(LocalRoot)
    if not Context then return nil, nil, nil end

    local Mode = tostring(RageBotSettings.TargetSelection or "Mouse")
    local CameraObject = Context.Camera or workspace.CurrentCamera
    local Mouse = LocalPlayer:GetMouse()
    local MousePosition = Vector2.new(Mouse.X, Mouse.Y)
    local BestPlayer, BestCharacter, BestPart, BestScore = nil, nil, nil, math.huge
    local WallBang = getgenv().WallBang == true

    local RayParams = RageCrimEngine.RefreshRayParams()

    for _, Player in ipairs(RageBotAPI.GetRagePlayerList()) do
        if Player ~= LocalPlayer and RageTargetAllowedFast(Player, Context.HasEnemyTargets) then
            local Character = GetRageCharacter(Player) or Player.Character
            local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
            local Head = Character and Character:FindFirstChild("Head")

            if Humanoid and Humanoid.Health > 0 and Head and Head:IsA("BasePart")
                and not Character:FindFirstChildWhichIsA("ForceField")
                and (getgenv().DownedCheck == false or not RageBotAPI.IsRageTargetDowned(Player))
            then
                local Score

                if Mode == "Nearest" then
                    local Delta = Head.Position - LocalRoot.Position
                    Score = Delta:Dot(Delta)
                else
                    local Screen, OnScreen = CameraObject:WorldToViewportPoint(Head.Position)
                    if OnScreen and Screen.Z > 0 then
                        local Delta = MousePosition - Vector2.new(Screen.X, Screen.Y)
                        Score = Delta:Dot(Delta)
                        if Mode == "FOV" and Score > Context.FOVSquared then Score = nil end
                    end
                end

                if Score ~= nil and Score < BestScore then
                    local Visible = true
                    if not WallBang then
                        local Origin = CameraObject.CFrame.Position
                        local Result = workspace:Raycast(Origin, Head.Position - Origin, RayParams)
                        Visible = Result == nil or Result.Instance ~= nil and Result.Instance:IsDescendantOf(Character)
                    end

                    if Visible then
                        BestScore = Score
                        BestPlayer, BestCharacter, BestPart = Player, Character, Head
                    end
                end
            end
        end
    end

    return BestPlayer, BestCharacter, BestPart
end

function RageBotAPI.SetConfigNumber(Config, Field, Value)
    if type(Config) ~= "table" or type(Field) ~= "string" then
        return false
    end

    if type(Value) ~= "number" then
        return false
    end

    local Current = rawget(Config, Field)
    if Current == Value then
        return true
    end

    local WasReadonly =
        type(isreadonly) == "function"
        and type(setreadonly) == "function"
        and isreadonly(Config)

    if WasReadonly then
        AtramentaCallChecked(setreadonly, Config, false)
    end

    local Success = AtramentaCallChecked(function()
        Config[Field] = Value
    end)

    if WasReadonly then
        AtramentaCallChecked(setreadonly, Config, true)
    end

    return Success == true
end

function RageBotAPI.GetWeaponCycleDelay(Tool)
    local Config =
        GetRageWeaponConfig(Tool)

    if type(Config) ~= "table" then
        return nil
    end

    local FireRate =
        tonumber(
            rawget(
                Config,
                "FireRate"
            )
        )

    if not FireRate
        or FireRate <= 0
    then
        return nil
    end

    local Delay =
        1 / FireRate

    local FireMode =
        rawget(
            Config,
            "FireModeSettings"
        )

    if type(FireMode) == "table"
        and FireMode.CanSwitch
    then
        local SwitchTo =
            rawget(
                FireMode,
                "SwitchTo"
            )

        if SwitchTo == "Burst" then
            local BurstRate =
                tonumber(
                    rawget(
                        FireMode,
                        "BurstRate"
                    )
                )

            if BurstRate
                and BurstRate > 0
            then
                Delay =
                    1 / (
                        BurstRate * 3
                    )
            else
                Delay =
                    1 / (
                        FireRate * 3
                    )
            end
        else
            local SemiRate =
                tonumber(
                    rawget(
                        FireMode,
                        "SemiRate"
                    )
                )

            if SemiRate
                and SemiRate > 0
            then
                Delay =
                    1 / SemiRate
            end
        end
    end

    if Tool
        and Tool.Name == "TEC-9"
    then
        Delay =
            math.max(
                Delay,
                0.3
            )
    end

    return math.clamp(
        Delay,
        0.001,
        2
    )
end

function RageBotAPI.ApplyRageFireRate(Tool, Delay)
    return RageBotAPI.GetWeaponCycleDelay(
        Tool
    )
end

function RageBotAPI.RestoreRageFireRate(Tool)
    if not Tool then
        return
    end

    local Config = GetRageWeaponConfig(Tool)
    if type(Config) ~= "table" then
        return
    end

    local Original = RageFireRateOriginal[Config]
    if type(Original) ~= "table" then
        return
    end

    if Original.FireRate ~= nil then
        RageBotAPI.SetConfigNumber(Config, "FireRate", Original.FireRate)
    end

    local FireMode = rawget(Config, "FireModeSettings")
    if type(FireMode) == "table" then
        if Original.BurstRate ~= nil then
            RageBotAPI.SetConfigNumber(
                FireMode,
                "BurstRate",
                Original.BurstRate
            )
        end

        if Original.SemiRate ~= nil then
            RageBotAPI.SetConfigNumber(
                FireMode,
                "SemiRate",
                Original.SemiRate
            )
        end
    end
end

function RageBotAPI.RestoreAllRageFireRates()
    for Config, Original in pairs(RageFireRateOriginal) do
        if type(Config) == "table" and type(Original) == "table" then
            if Original.FireRate ~= nil then
                RageBotAPI.SetConfigNumber(
                    Config,
                    "FireRate",
                    Original.FireRate
                )
            end

            local FireMode = rawget(Config, "FireModeSettings")
            if type(FireMode) == "table" then
                if Original.BurstRate ~= nil then
                    RageBotAPI.SetConfigNumber(
                        FireMode,
                        "BurstRate",
                        Original.BurstRate
                    )
                end

                if Original.SemiRate ~= nil then
                    RageBotAPI.SetConfigNumber(
                        FireMode,
                        "SemiRate",
                        Original.SemiRate
                    )
                end
            end
        end
    end

    table.clear(RageFireRateOriginal)
end

function RageBotAPI.GetRageFireDelay(Tool)
    local UserDelay =
        math.clamp(
            tonumber(
                RageBotSettings.Delay
            )
            or 0.15,
            0.01,
            0.5
        )

    local WeaponDelay =
        RageBotAPI.GetWeaponCycleDelay(
            Tool
        )

    if type(WeaponDelay) ~= "number"
        or WeaponDelay <= 0
    then
        return UserDelay
    end

    return math.max(
        UserDelay,
        WeaponDelay
    )
end

function RageBotAPI.RageRequestReload(Tool, Ammo)
    if RageBotSettings.AutoReload ~= true or not Tool or not Ammo or typeof(Ammo.Value) ~= "number" or Ammo.Value > 1 then return end
    local ReloadRemote = RageBotAPI.GetRageRemote("GNX_R")
    if not ReloadRemote then return end
    local Config = GetRageWeaponConfig(Tool)
    for _ = 1, 2 do ReloadRemote:FireServer(RageBotAPI.GetRageRemoteKey(Tool, Config), "KLWE89U0", Tool) end
end

RageBotRuntime.WallbangPending = RageBotRuntime.WallbangPending or {}

function RageBotAPI.CanFireWallbangTarget(TargetPlayer)
    return true
end

function RageBotAPI.RageFireShot(TargetPlayer, TargetCharacter, TargetPart, LocalRoot, Tool)
    local LocalCharacter = GetRageCharacter(LocalPlayer) or LocalPlayer.Character
    LocalRoot = LocalRoot or GetRageRootPart(LocalCharacter)
    Tool = Tool or (LocalCharacter and LocalCharacter:FindFirstChildWhichIsA("Tool"))
    TargetCharacter = TargetCharacter or (TargetPlayer and (GetRageCharacter(TargetPlayer) or TargetPlayer.Character))
    TargetPart = TargetCharacter and TargetCharacter:FindFirstChild("Head") or TargetPart

    if not TargetPlayer or TargetPlayer == LocalPlayer or not TargetCharacter or not TargetPart or not LocalRoot or not Tool then
        RageSetWallbangDiagnostic("blocked", "invalid-shot-state", 0, 0)
        return false
    end
    if not TargetPart:IsA("BasePart") then
        RageSetWallbangDiagnostic("blocked", "invalid-target-part", 0, 0)
        return false
    end

    local Humanoid = TargetCharacter:FindFirstChildOfClass("Humanoid")
    if not Humanoid or Humanoid.Health <= 0 or TargetCharacter:FindFirstChildWhichIsA("ForceField") then
        RageSetWallbangDiagnostic("blocked", "target-state", 0, 0)
        return false
    end
    if getgenv().DownedCheck ~= false and RageBotAPI.IsRageTargetDowned(TargetPlayer) then
        RageSetWallbangDiagnostic("blocked", "target-downed", 0, 0)
        return false
    end

    local ToolData = RageBotAPI.GetRageToolData(Tool)
    local Ammo = ToolData and ToolData.Ammo
    local Config = ToolData and ToolData.Config or RageBotAPI.CrimGetToolConfig(Tool)
    if not Ammo or typeof(Ammo.Value) ~= "number" or type(Config) ~= "table" then
        RageSetWallbangDiagnostic("blocked", "weapon-data", 0, 0)
        return false
    end
    if Ammo.Value <= 0 then
        RageSetWallbangDiagnostic("blocked", "reload", 0, 0)
        RageBotAPI.CrimReload(Tool)
        return false
    end

    local UserId = TargetPlayer.UserId
    local Now = os.clock()
    if (RageCooldown[UserId] or 0) > Now then
        RageSetWallbangDiagnostic("waiting", "fire-rate", 0, math.max((RageCooldown[UserId] or 0) - Now, 0))
        return false
    end
    if RageTargetFlags[UserId] then
        RageSetWallbangDiagnostic("waiting", "shot-lock", 0, 0)
        return false
    end
    RageTargetFlags[UserId] = true

    local BaseOrigin = LocalRoot.Position
    local PredictedPosition = RageBotAPI.GetRagePredictedPosition(TargetPlayer, TargetCharacter, TargetPart) or TargetPart.Position
    RageSetExpectedTarget(TargetPart, PredictedPosition)
    local ShotOrigin, HitPosition, Route = RageRayPoints(TargetPart, RageCrimEngine.MaximumOriginDistance, BaseOrigin, PredictedPosition)

    if typeof(ShotOrigin) ~= "Vector3" or typeof(HitPosition) ~= "Vector3" then
        RageTargetFlags[UserId] = nil
        RageSetWallbangDiagnostic("blocked", "crim-no-route", 0, 0)
        return false
    end

    local DirectionDelta = TargetPart.Position - LocalRoot.Position
    if DirectionDelta.Magnitude <= 0.001 then
        RageTargetFlags[UserId] = nil
        return false
    end
    local Direction = DirectionDelta.Unit

    if not RageRayCheck(LocalPlayer, ShotOrigin, HitPosition, TargetPart) then
        RageTargetFlags[UserId] = nil
        RageSetWallbangDiagnostic("blocked", "crim-final-ray", 0, (ShotOrigin - BaseOrigin).Magnitude)
        return false
    end

    local ShootRemote = RageBotAPI.GetRageRemote("GNX_S")
    if not ShootRemote or not ShootRemote:IsA("RemoteEvent") then
        RageTargetFlags[UserId] = nil
        RageSetWallbangDiagnostic("blocked", "shoot-remote", 0, 0)
        return false
    end

    local Environment = getgenv()
    if typeof(Environment.CurShots) ~= "number" then Environment.CurShots = 0 end
    local Timestamp = RageBotAPI.GetRageRemoteKey(Tool, Config)
    if typeof(Timestamp) ~= "number" then
        RageTargetFlags[UserId] = nil
        RageSetWallbangDiagnostic("blocked", "remote-key", 0, 0)
        return false
    end

    local ShotId = RageBotAPI.RageRandomString(30) .. tostring(Environment.CurShots)
    local Attack = RegisterLocalAttack(TargetCharacter, TargetPart, ShotId, Tool, "RageBot", ShotOrigin, Direction)

    if Attack then
        Attack.HitPosition = HitPosition
        Attack.TargetPositionAtFire = TargetPart.Position
        Attack.TargetVelocityAtFire = TargetPart.AssemblyLinearVelocity
        Attack.VisualOrigin = ShotOrigin
        Attack.PacketDirection = Direction
        Attack.WallbangStage = type(Route) == "table" and Route.Stage or "crim"
        Attack.WallbangScore = type(Route) == "table" and Route.Score or 0
        Attack.WallbangRadius = type(Route) == "table" and Route.Radius or 0
        Attack.WallbangEstimatedRadius = type(Route) == "table" and Route.EstimatedRadius or 0
        Attack.HeadHitStep = type(Route) == "table" and Route.HitStep or 1
        Attack.BankContextKey = type(Route) == "table" and Route.ContextKey or nil
        Attack.RouteFeedbackKey = type(Route) == "table" and Route.RouteFeedbackKey or nil
        Attack.BlockerSignature = type(Route) == "table" and Route.BlockerSignature or nil
        Attack.WallbangOriginSide = type(Route) == "table" and Route.OriginSide or "center"
        Attack.WallbangStability = type(Route) == "table" and Route.Stability or 1
        Attack.WallbangExposure = type(Route) == "table" and Route.Exposure or 1
        Attack.RouteFeedbackEligible = type(Route) == "table" and Route.RouteFeedbackKey ~= nil
        Attack.PredictedPositionAtFire = PredictedPosition
        Attack.WallbangSafety = 1
        Attack.WallbangConfidence = 1
        Attack.WallbangObstacles = 0
        Attack.WallbangThickness = 0
        Attack.WallbangBaseOrigin = BaseOrigin
        Attack.WallbangTargetPosition = TargetPart.Position
        Attack.RouteValidAtFire = true
        Attack.NaturalFire = false
        RageBotAPI._ReportedShots[ShotId] = Attack
        local FeedbackDelay = math.clamp(0.44 + (tonumber(LocalPlayer:GetNetworkPing()) or 0) * 1.5, 0.48, 0.82)
        task.delay(FeedbackDelay, function()
            if Attack.BankFeedbackApplied ~= true then
                Attack.BankFeedbackApplied = true
                if Attack.DamageConfirmed == true then
                    RageBotAPI.ConfirmRageRoute(Attack)
                elseif Attack.VerifiedFire == true and Attack.RouteFeedbackEligible == true then
                    RageBotAPI.RejectRageRoute(Attack)
                end
            end
        end)

        task.delay(1.25, function()
            if RageBotAPI._ReportedShots[ShotId] == Attack then RageBotAPI._ReportedShots[ShotId] = nil end
        end)
    end

    ShootRemote:FireServer(Timestamp, ShotId, Tool, "FDS9I83", ShotOrigin, {Direction}, true)

    local DamageRemote = RageBotAPI.GetRageRemote(game.GameId == 1494262959 and "ZFKLF__H" or "ZFKLF_H")
    if DamageRemote and DamageRemote:IsA("RemoteEvent") then
        if game.GameId == 1494262959 then
            local DamageContext = {}
            DamageContext.HIP = nil
            DamageRemote:FireServer("🧈", Tool, ShotId, 1, TargetPart, HitPosition, Direction, DamageContext)
        else
            DamageRemote:FireServer("🍯", math.huge, Tool, ShotId, 1, TargetPart, HitPosition, Direction, Tool, nil, 19052023.49)
        end
    end

    Environment.CurShots += 1
    RageRuntimeState.CurShots = Environment.CurShots

    local FireDelay = RageBotAPI.CrimGetFireDelay(Tool, Config)
    local FiredAt = os.clock()
    RageCooldown[UserId] = FiredAt + FireDelay
    RageRuntimeState.NextShot = FiredAt + FireDelay

    if Ammo.Value <= 1 then RageBotAPI.CrimReload(Tool) end
    task.delay(FireDelay, function() RageTargetFlags[UserId] = nil end)

    RageSetWallbangDiagnostic(
        "sent",
        type(Route) == "table"
            and (
                tostring(Route.Stage or "crim")
                .. " r" .. tostring(math.floor((tonumber(Route.Radius) or 0) + 0.5))
                .. " b" .. tostring(math.floor(tonumber(Route.Blockers) or 0))
                .. " h" .. tostring(math.floor(tonumber(Route.HitStep) or 1))
                .. " s" .. tostring(math.floor((tonumber(Route.Stability) or 0) * 100 + 0.5))
                .. " e" .. tostring(math.floor((tonumber(Route.Exposure) or 0) * 100 + 0.5))
                .. " g" .. tostring(math.floor(tonumber(Route.DiscoveryGeneration) or 0))
                .. " d" .. tostring(math.floor(tonumber(Route.DiscoveredBlockers) or 0))
                .. " t" .. tostring(math.floor(tonumber(Route.Tested) or 0))
            )
            or "crim",
        type(Route) == "table" and tonumber(Route.Tested) or 1,
        (ShotOrigin - BaseOrigin).Magnitude
    )
    return true
end

function RageBotAPI.Enable()
    if RageBotEnabled then
        local Status = RageBotCoroutine and coroutine.status(RageBotCoroutine) or "dead"
        if Status ~= "dead" then return end
        RageBotEnabled = false
        RageBotCoroutine = nil
    end

    table.clear(RageCooldown)
    table.clear(RageTargetFlags)
    RageBotAPI.ResetCrimSearchState()
    RageBotEnabled = true
    RageRuntimeState.Running = true
    getgenv().RageBotting = true
    getgenv().RageBotLoopRunning = true
    RageBotStickyTarget = nil
    RageBotCurrentTarget = nil
    RageBotRuntime.Target = nil
    RageBotRuntime.PendingShot = nil
    RageBotRuntime.SelectedRoute = nil
        RageBotRuntime.WallbangPending = {}
    RageBotRuntime.SelectionTarget = nil
    RageBotRuntime.SelectionUntil = nil
    RageRuntimeState.NextShot = 0
    RageSetWallbangDiagnostic("idle", "enabled", 0)

    RageBotAPI.RefreshRageFOV()

    if typeof(
        getgenv().CurShots
    ) ~= "number"
    then
        getgenv().CurShots = 0
    end

    if RageBotCoroutine then
        task.cancel(
            RageBotCoroutine
        )
    end

    RageBotCoroutine =
        task.spawn(function()
            while RageBotEnabled
                and getgenv().RageBotting
                and getgenv().
                    RageBotLoopRunning
            do
                task.wait()

                local PlayerCharacter =
                    LocalPlayer.Character

                local LocalCharacter =
                    GetRageCharacter(
                        LocalPlayer
                    )
                    or PlayerCharacter

                local LocalRoot =
                    GetRageRootPart(
                        LocalCharacter
                    )
                    or GetRageRootPart(
                        PlayerCharacter
                    )

                if not LocalRoot then
                    continue
                end

                local Tool =
                    (
                        LocalCharacter
                        and LocalCharacter:
                            FindFirstChildWhichIsA(
                                "Tool"
                            )
                    )
                    or (
                        PlayerCharacter
                        and PlayerCharacter:
                            FindFirstChildWhichIsA(
                                "Tool"
                            )
                    )

                if not Tool then
                    continue
                end

                if type(
                    IsRageFirearm
                ) == "function"
                    and not IsRageFirearm(
                        Tool
                    )
                then
                    continue
                end

                local ToolData = RageBotAPI.GetRageToolData(Tool)
                local Values = ToolData and ToolData.Values
                local Ammo = ToolData and ToolData.Ammo

                if not Ammo
                    or typeof(
                        Ammo.Value
                    ) ~= "number"
                then
                    continue
                end

                if Ammo.Value <= 0 then
                    local Reload =
                        RageBotAPI.CrimReload

                    if type(Reload)
                        == "function"
                    then
                        Reload(
                            Tool
                        )
                    end

                    task.wait(
                        0.03
                    )

                    continue
                end

                local CurrentTime = os.clock()
                local NextShot = tonumber(RageRuntimeState.NextShot) or 0
                if CurrentTime + 0.001 < NextShot then
                    task.wait(math.min(math.max(NextShot - CurrentTime - 0.0005, 0.001), 0.025))
                    continue
                end

                local SelectionContext = RageBotAPI.CreateRageSelectionContext(LocalRoot)
                if not SelectionContext then
                    task.wait(0.01)
                    continue
                end

                local AcquireTarget =
                    RageBotAPI.AcquireRageTarget

                if type(AcquireTarget)
                    ~= "function"
                then
                    task.wait(
                        0.03
                    )

                    continue
                end

                local TargetPlayer, TargetCharacter, TargetPart = AcquireTarget(LocalRoot, SelectionContext)
                if not TargetPlayer or not TargetCharacter then
                    if RageBotRuntime.Target then RageBotAPI.ResetPeekGuard(RageBotRuntime.Target) end
                    RageBotCurrentTarget = nil
                    RageBotRuntime.Target = nil
                    task.wait(0.012)
                    continue
                end

                local Humanoid = TargetCharacter:FindFirstChildOfClass("Humanoid")
                local AimPart = TargetPart
                if not AimPart or not AimPart:IsA("BasePart") or not AimPart:IsDescendantOf(TargetCharacter) then
                    AimPart = RageBotAPI.GetRageTargetPart(TargetCharacter) or TargetCharacter:FindFirstChild("Head", true) or TargetCharacter:FindFirstChild("HumanoidRootPart", true)
                end
                if not AimPart or not AimPart:IsA("BasePart") or not Humanoid or Humanoid.Health <= 0 or TargetCharacter:FindFirstChildWhichIsA("ForceField") then
                    task.wait(0.008)
                    continue
                end

                if RageBotRuntime.Target and RageBotRuntime.Target ~= TargetPlayer then
                    RageBotAPI.ResetPeekGuard(RageBotRuntime.Target)
                end

                RageBotCurrentTarget = TargetPlayer
                RageBotRuntime.Target = TargetPlayer
                local Fired = RageBotAPI.RageFireShot(TargetPlayer, TargetCharacter, AimPart, LocalRoot, Tool)

                if not Fired then
                    RageTargetFlags[
                        TargetPlayer.UserId
                    ] = nil

                    RageBotRuntime.PendingShot =
                        nil

                    task.wait(
                        0.006
                    )
                end
            end

            RageRuntimeState.Running =
                false
        end)
end

function RageBotAPI.Disable()
    RageBotEnabled = false
    RageRuntimeState.Running = false
    getgenv().RageBotting = false
    getgenv().RageBotLoopRunning = false
    RageBotStickyTarget = nil
    RageBotCurrentTarget = nil
    RageBotRuntime.Target = nil
    RageBotRuntime.PendingShot = nil
    RageBotRuntime.SelectedRoute = nil
    RageBotRuntime.WallbangPending = {}
    RageRuntimeState.NextShot = 0
    RageBotAPI.RestoreAllRageFireRates()
    RageBotAPI.RefreshRageFOV()
    table.clear(RageCooldown)
    table.clear(RageTargetFlags)
    RageBotAPI.ResetCrimSearchState()
    if RageBotCoroutine then task.cancel(RageBotCoroutine); RageBotCoroutine = nil end
end

