        NotifyMinutes = 1, MoveSpeed = 32, PathMaxParamAttempts = 19, WaypointSpacing = 3, PickupDistance = 8, MoneySearchRadius = 42, MoneyCollectMaxPasses = 18, FarmTickSec = 0.2,
