function DestroyChinaHat()
    if S.ChinaHat.Motor and S.ChinaHat.Motor.Parent then S.ChinaHat.Motor:Destroy() end
    if S.ChinaHat.Model then S.ChinaHat.Model:Destroy() end
    S.ChinaHat.Model = nil
    S.ChinaHat.Motor = nil
    AtramentaReleaseBuffer(S.ChinaHat.SurfaceBeams)
    AtramentaReleaseBuffer(S.ChinaHat.OutlineBeams)
    AtramentaReleaseBuffer(S.ChinaHat.Attachments)
    S.ChinaHat.SurfaceBeams = {}
    S.ChinaHat.OutlineBeams = {}
    S.ChinaHat.Attachments = {}
    S.ChinaHat.AppearanceAccumulator = 0
    S.ChinaHat.AppearanceBatchIndex = 1
end

function GetChinaHatColor(Index, Offset)
    if not S.ChinaHat.Rainbow then return S.ChinaHat.Color end
    local Segments = math.max(S.ChinaHat.Segments, 1)
    local Hue = (S.ChinaHat.Time * S.ChinaHat.RainbowSpeed + (Index - 1) / Segments + (Offset or 0)) % 1
    return Color3.fromHSV(Hue, 0.82, 1)
end

function CreateChinaHatAttachment(Parent, Name, Position)
    local Attachment = Instance.new("Attachment")
    Attachment.Name = Name
    Attachment.Position = Position
    Attachment.Parent = Parent
    S.ChinaHat.Attachments[#S.ChinaHat.Attachments + 1] = Attachment
    return Attachment
end

function CreateChinaHatBeam(Parent, Name, Attachment0, Attachment1, Width0, Width1, Transparency, ZOffset)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = Attachment0
    Beam.Attachment1 = Attachment1
    Beam.FaceCamera = true
    Beam.Segments = 1
    Beam.Width0 = Width0
    Beam.Width1 = Width1
    Beam.Transparency = Transparency
    Beam.LightEmission = 0.82
    Beam.LightInfluence = 0
    Beam.Brightness = 1
    Beam.ZOffset = ZOffset
    Beam.Parent = Parent
    return Beam
end

function UpdateChinaHatAppearance(UseBatch)
    local Transparency = AngelWingClamp(S.ChinaHat.Transparency, 0, 0.94)
    local SurfaceBeams = S.ChinaHat.SurfaceBeams
    local OutlineBeams = S.ChinaHat.OutlineBeams
    local SurfaceCount = #SurfaceBeams
    local OutlineCount = #OutlineBeams
    local TotalCount = SurfaceCount + OutlineCount
    local StartIndex = UseBatch and S.ChinaHat.AppearanceBatchIndex or 1
    local EndIndex = UseBatch and math.min(StartIndex + S.ChinaHat.AppearanceBatchSize - 1, TotalCount) or TotalCount
    for GlobalIndex = StartIndex, math.min(EndIndex, SurfaceCount) do
        local Index = GlobalIndex
        local Data = SurfaceBeams[Index]
        local StartColor = GetChinaHatColor(Index, 0)
        local EndColor = GetChinaHatColor(Index + 1, 0)
        Data.Beam.Color = ColorSequence.new(StartColor, EndColor)
        Data.Beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.26, 0, 0.97)), NumberSequenceKeypoint.new(0.72,
            AngelWingClamp(Transparency + 0.20, 0, 0.96)), NumberSequenceKeypoint.new(1, AngelWingClamp(Transparency + 0.12, 0, 0.95)) })
    end
    local OutlineStart = math.max(StartIndex, SurfaceCount + 1)
    for GlobalIndex = OutlineStart, EndIndex do
        local Index = GlobalIndex - SurfaceCount
        local Data = OutlineBeams[Index]
        if not Data then break end
        local StartColor = GetChinaHatColor(Data.ColorIndex or Index, Data.HueOffset or 0)
        local EndColor = GetChinaHatColor((Data.ColorIndex or Index) + 1, Data.HueOffset or 0)
        Data.Beam.Color = ColorSequence.new(StartColor, EndColor)
        Data.Beam.Transparency = NumberSequence.new(AngelWingClamp(Transparency + (Data.Faint and 0.22 or 0), 0, 0.96))
    end
    if UseBatch and TotalCount > 0 then
        S.ChinaHat.AppearanceBatchIndex = EndIndex >= TotalCount and 1 or EndIndex + 1
    else
        S.ChinaHat.AppearanceBatchIndex = 1
    end
end

function CreateChinaHat(Character)
    DestroyChinaHat()
    Character = Character or LocalPlayer.Character
    if not Character then return end
    local Head = Character:FindFirstChild("Head")
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Head or not Humanoid or Humanoid.RigType ~= Enum.HumanoidRigType.R6 then return end
    local Model = Instance.new("Model")
    Model.Name = "MinecraftChinaHat"
    Model.Parent = Character
    local Pivot = Instance.new("Part")
    Pivot.Name = "ChinaHatPivot"
    Pivot.Size = Vector3.new(0.1, 0.1, 0.1)
    Pivot.Transparency = 1
    Pivot.Anchored = false
    Pivot.CanCollide = false
    Pivot.CanTouch = false
    Pivot.CanQuery = false
    Pivot.Massless = true
    Pivot.CastShadow = false
    Pivot.CFrame = Head.CFrame * CFrame.new(0, S.ChinaHat.Height, 0)
    Pivot.Parent = Model
    local Motor = Instance.new("Motor6D")
    Motor.Name = "ChinaHatMotor"
    Motor.Part0 = Head
    Motor.Part1 = Pivot
    Motor.C0 = CFrame.new(0, S.ChinaHat.Height, 0)
    Motor.C1 = CFrame.new()
    Motor.Parent = Head
    local Segments = S.ChinaHat.Segments
    local Scale = S.ChinaHat.Scale
    local Radius = 1.18 * Scale
    local RimHeight = -0.28 * Scale
    local ApexHeight = 0.48 * Scale
    local InnerRadius = Radius * 0.54
    local InnerHeight = RimHeight + (ApexHeight - RimHeight) * 0.46
    local ArcWidth = (Radius * math.pi * 2) / Segments
    local Apex = CreateChinaHatAttachment(Pivot, "HatApex", Vector3.new(0, ApexHeight, 0))
    local Rim = {}
    local Inner = {}
    for Index = 1, Segments do
        local Angle = (Index - 1) / Segments * math.pi * 2
        local X = math.cos(Angle)
        local Z = math.sin(Angle)
        Rim[Index] = CreateChinaHatAttachment(Pivot, "HatRim_" .. Index, Vector3.new(X * Radius, RimHeight, Z * Radius))
        Inner[Index] = CreateChinaHatAttachment(Pivot, "HatInner_" .. Index, Vector3.new(X * InnerRadius, InnerHeight, Z * InnerRadius))
    end
    for Index = 1, Segments do
        local NextIndex = Index % Segments + 1
        local Surface = CreateChinaHatBeam(Pivot, "HatSurface_" .. Index, Apex, Rim[Index], 0.018 * Scale, ArcWidth * 1.08, NumberSequence.new(0.42), -0.02)
        S.ChinaHat.SurfaceBeams[#S.ChinaHat.SurfaceBeams + 1] = { Beam = Surface }
        local RimBeam = CreateChinaHatBeam(Pivot, "HatRimLine_" .. Index, Rim[Index], Rim[NextIndex], 0.038 * Scale, 0.038 * Scale, NumberSequence.new(0.10), 0.03)
        S.ChinaHat.OutlineBeams[#S.ChinaHat.OutlineBeams + 1] = { Beam = RimBeam, ColorIndex = Index, HueOffset = 0, Faint = false }
        local InnerBeam = CreateChinaHatBeam(Pivot, "HatInnerLine_" .. Index, Inner[Index], Inner[NextIndex], 0.024 * Scale, 0.024 * Scale, NumberSequence.new(0.32), 0.02)
        S.ChinaHat.OutlineBeams[#S.ChinaHat.OutlineBeams + 1] = { Beam = InnerBeam, ColorIndex = Index, HueOffset = 0.04, Faint = true }
        if Index % 4 == 1 then
            local Spoke = CreateChinaHatBeam(Pivot, "HatSpoke_" .. Index, Apex, Rim[Index], 0.018 * Scale, 0.018 * Scale, NumberSequence.new(0.38), 0.04)
            S.ChinaHat.OutlineBeams[#S.ChinaHat.OutlineBeams + 1] = { Beam = Spoke, ColorIndex = Index, HueOffset = 0.02, Faint = true }
        end
    end
    S.ChinaHat.Model = Model
    S.ChinaHat.Motor = Motor
    S.ChinaHat.Time = 0
    S.ChinaHat.AppearanceAccumulator = 0
    UpdateChinaHatAppearance()
end

function UpdateChinaHat(DeltaTime)
    if not S.ChinaHat.Enabled then return end
    local Character = LocalPlayer.Character
    if not Character then
        DestroyChinaHat()
        return
    end
    if not S.ChinaHat.Model or S.ChinaHat.Model.Parent ~= Character then
        CreateChinaHat(Character)
        return
    end
    local Motor = S.ChinaHat.Motor
    if not Motor then return end
    DeltaTime = AngelWingClamp(tonumber(DeltaTime) or 0.016, 0.001, 0.05)
    S.ChinaHat.Time = S.ChinaHat.Time + DeltaTime
    local Rotation = math.rad(S.ChinaHat.Time * S.ChinaHat.SpinSpeed)
    local Bob = math.sin(S.ChinaHat.Time * 2) * 0.012
    local Target = CFrame.new(0, Bob, 0) * CFrame.Angles(0, Rotation, 0)
    Motor.Transform = Motor.Transform:Lerp(Target, AngelWingExpAlpha(10, DeltaTime))
    if S.ChinaHat.Rainbow then
        S.ChinaHat.AppearanceAccumulator = S.ChinaHat.AppearanceAccumulator + DeltaTime
        if S.ChinaHat.AppearanceAccumulator >= S.ChinaHat.AppearanceInterval then
            S.ChinaHat.AppearanceAccumulator = S.ChinaHat.AppearanceAccumulator % S.ChinaHat.AppearanceInterval
            UpdateChinaHatAppearance(true)
        end
    else
        S.ChinaHat.AppearanceAccumulator = 0
    end
end

function SetupChinaHat()
    if S.ChinaHat.Connection then S.ChinaHat.Connection:Disconnect() end
    S.ChinaHat.Connection = RunService.Heartbeat:Connect(UpdateChinaHat)
    if S.ChinaHat.CharacterConnection then S.ChinaHat.CharacterConnection:Disconnect() end
    S.ChinaHat.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
        task.spawn(function()
            task.wait(0.55)
            if S.ChinaHat.Enabled then CreateChinaHat(Character) end
        end)
    end)
    CreateChinaHat(LocalPlayer.Character)
end

function RebuildChinaHat()
    if not S.ChinaHat.Enabled then return end
    CreateChinaHat(LocalPlayer.Character)
end

function ToggleChinaHat(State)
    S.ChinaHat.Enabled = State
    if State then
        SetupChinaHat()
    else
        if S.ChinaHat.Connection then
            S.ChinaHat.Connection:Disconnect()
            S.ChinaHat.Connection = nil
        end
        if S.ChinaHat.CharacterConnection then
            S.ChinaHat.CharacterConnection:Disconnect()
            S.ChinaHat.CharacterConnection = nil
        end
        DestroyChinaHat()
    end
end

function AngelWingClamp(Value, Minimum, Maximum) return math.max(Minimum, math.min(Maximum, Value)) end

function AngelWingLerp(A, B, Alpha) return A + (B - A) * Alpha end

function AngelWingSmoothStep(Value)
    Value = AngelWingClamp(Value, 0, 1)
    return Value * Value * (3 - 2 * Value)
end

function AngelWingExpAlpha(Speed, DeltaTime) return 1 - math.exp(-Speed * DeltaTime) end

function AngelWingStableStroke(Stroke)
    Stroke = AngelWingClamp(tonumber(Stroke) or 0, -1, 1)
    local Magnitude = math.abs(Stroke)
    local Compressed = Magnitude / (1 + Magnitude * 0.62)
    return Stroke < 0 and -Compressed or Compressed
end

function HoldAngelWingsForRagdoll(Duration)
    if not S or not S.AngelWings then return end
    local Until = os.clock() + math.max(tonumber(Duration) or 0.18, 0.05)
    S.AngelWings.RagdollHoldUntil = math.max(tonumber(S.AngelWings.RagdollHoldUntil) or 0, Until)
end

function IsAngelWingGameRagdolled(Character, Humanoid)
    if not Character or not Humanoid or not Character.Parent or not Humanoid.Parent then return false end
    if os.clock() < (tonumber(S.AngelWings.RagdollHoldUntil) or 0) then return true end

    local State = Humanoid:GetState()
    if State == Enum.HumanoidStateType.Ragdoll
        or State == Enum.HumanoidStateType.FallingDown
        or State == Enum.HumanoidStateType.Physics
    then
        return true
    end

    local CharacterStats = Character:FindFirstChild("CharStats")
    if CharacterStats then
        local PlayerStats = CharacterStats:FindFirstChild(LocalPlayer.Name)
            or CharacterStats:FindFirstChild(tostring(LocalPlayer.UserId))
            or CharacterStats
        local Switch = PlayerStats:FindFirstChild("RagdollSwitch")
            or CharacterStats:FindFirstChild("RagdollSwitch", true)
        if Switch and Switch:IsA("BoolValue") and Switch.Value == true then return true end
    end

    return false
end

function SetAngelWingEmittersEnabled(Enabled)
    for _, Emitter in ipairs(S.AngelWings.Emitters) do
        if Emitter and Emitter.Parent then
            Emitter.Enabled = Enabled == true
            if not Enabled then Emitter.Rate = 0 end
        end
    end
end

function FreezeAngelWingsForRagdoll()
    local LeftMotor = S.AngelWings.LeftMotor
    local RightMotor = S.AngelWings.RightMotor

    if LeftMotor and LeftMotor.Parent then LeftMotor.Transform = CFrame.new() end
    if RightMotor and RightMotor.Parent then RightMotor.Transform = CFrame.new() end

    S.AngelWings.StrokeVelocity = 0
    S.AngelWings.PreviousStroke = AngelWingStableStroke(-1)
    S.AngelWings.CurrentActivity = 0.52
    S.AngelWings.FeatherAccumulator = 0
    S.AngelWings.EmitterAccumulator = 0
    SetAngelWingEmittersEnabled(false)
end

function RecoverAngelWingsFromRagdoll(Character)
    if not Character or Character ~= LocalPlayer.Character then return false end

    local LeftMotor = S.AngelWings.LeftMotor
    local RightMotor = S.AngelWings.RightMotor
    if not LeftMotor or not RightMotor or not LeftMotor.Parent or not RightMotor.Parent then
        CreateAngelWings(Character)
        return false
    end

    LeftMotor.Transform = CFrame.new()
    RightMotor.Transform = CFrame.new()
    S.AngelWings.Phase = 0
    S.AngelWings.PreviousStroke = AngelWingStableStroke(-1)
    S.AngelWings.StrokeVelocity = 0
    S.AngelWings.CurrentActivity = 0.56
    S.AngelWings.FeatherAccumulator = 0
    S.AngelWings.FeatherBatchIndex = 1
    S.AngelWings.EmitterAccumulator = 0
    S.AngelWings.ValidationAccumulator = 0
    UpdateAngelWingFeathers(0, 0.56)
    SetAngelWingEmittersEnabled(true)
    return true
end

function AngelWingFrame(Position, Tangent, Normal)
    local Axis = Tangent.Magnitude > 0.001 and Tangent.Unit or Vector3.new(1, 0, 0)
    local Up = Normal.Magnitude > 0.001 and Normal.Unit or Vector3.new(0, 1, 0)
    if math.abs(Axis:Dot(Up)) > 0.94 then Up = Vector3.new(0, 0, 1) end
    local Back = Axis:Cross(Up)
    if Back.Magnitude < 0.001 then
        Back = Vector3.new(0, 0, 1)
    else
        Back = Back.Unit
    end
    Up = Back:Cross(Axis)
    if Up.Magnitude < 0.001 then
        Up = Vector3.new(0, 1, 0)
    else
        Up = Up.Unit
    end
    return CFrame.fromMatrix(Position, Axis, Up, Back)
end

function DestroyAngelWingModel()
    if S.AngelWings.LeftMotor and S.AngelWings.LeftMotor.Parent then S.AngelWings.LeftMotor:Destroy() end
    if S.AngelWings.RightMotor and S.AngelWings.RightMotor.Parent then S.AngelWings.RightMotor:Destroy() end
    if S.AngelWings.Model and S.AngelWings.Model.Parent then S.AngelWings.Model:Destroy() end

    local Character = LocalPlayer.Character
    if Character then
        for _, Object in ipairs(Character:GetChildren()) do
            if Object:IsA("Model") and Object.Name == "AtramentaCosmeticWings" then Object:Destroy() end
        end
        local Torso = Character:FindFirstChild("Torso")
        if Torso then
            for _, Object in ipairs(Torso:GetChildren()) do
                if Object:IsA("Motor6D") and (Object.Name == "LeftWingMotor" or Object.Name == "RightWingMotor") then Object:Destroy() end
            end
        end
    end

    S.AngelWings.Model = nil
    S.AngelWings.LeftMotor = nil
    S.AngelWings.RightMotor = nil
    AtramentaReleaseBuffer(S.AngelWings.Feathers)
    AtramentaReleaseBuffer(S.AngelWings.Beams)
    AtramentaReleaseBuffer(S.AngelWings.Emitters)
    AtramentaReleaseBuffer(S.AngelWings.Trails)
    S.AngelWings.Feathers = {}
    S.AngelWings.Beams = {}
    S.AngelWings.Emitters = {}
    S.AngelWings.Trails = {}
    S.AngelWings.FeatherAccumulator = 0
    S.AngelWings.FeatherBatchIndex = 1
    S.AngelWings.EmitterAccumulator = 0
    S.AngelWings.ValidationAccumulator = 0
    S.AngelWings.CachedCharacter = nil
    S.AngelWings.CachedHumanoid = nil
    S.AngelWings.CachedRootPart = nil
    S.AngelWings.Ragdolled = false
    S.AngelWings.RecoverUntil = 0
    S.AngelWings.LastRagdollCharacter = nil
end

function GetAngelWingStyleScale()
    if S.AngelWings.Style == "Classic" then return 0.92 end
    if S.AngelWings.Style == "Compact" then return 0.76 end
    return 1.08
end

function GetAngelWingCounts()
    if S.AngelWings.Style == "Compact" then return 8, 6, 5 end
    if S.AngelWings.Style == "Classic" then return 10, 8, 6 end
    return 12, 9, 7
end

function GetAngelWingStroke(Phase)
    local Cycle = (Phase / (math.pi * 2)) % 1
    local Stroke
    local Downstroke
    if Cycle < 0.10 then
        local T = Cycle / 0.10
        Stroke = AngelWingLerp(-1, -0.96, AngelWingSmoothStep(T))
        Downstroke = false
    elseif Cycle < 0.40 then
        local T = (Cycle - 0.10) / 0.30
        Stroke = AngelWingLerp(-0.96, 1, 1 - (1 - T) ^ 3)
        Downstroke = true
    elseif Cycle < 0.48 then
        local T = (Cycle - 0.40) / 0.08
        Stroke = AngelWingLerp(1, 0.94, AngelWingSmoothStep(T))
        Downstroke = true
    else
        local T = (Cycle - 0.48) / 0.52
        Stroke = AngelWingLerp(0.94, -1, AngelWingSmoothStep(T))
        Downstroke = false
    end
    return Stroke, Downstroke, Cycle
end

function CreateAngelWingPivot(Torso, Model, Side)
    local Pivot = Instance.new("Part")
    Pivot.Name = Side < 0 and "LeftWingPivot" or "RightWingPivot"
    Pivot.Size = Vector3.new(0.12, 0.12, 0.12)
    Pivot.Transparency = 1
    Pivot.Anchored = false
    Pivot.CanCollide = false
    Pivot.CanTouch = false
    Pivot.CanQuery = false
    Pivot.Massless = true
    Pivot.CastShadow = false
    local Offset = Vector3.new(Side * S.AngelWings.SideOffset, S.AngelWings.HeightOffset, S.AngelWings.BackOffset)
    Pivot.CFrame = Torso.CFrame * CFrame.new(Offset)
    Pivot.Parent = Model
    local Motor = Instance.new("Motor6D")
    Motor.Name = Side < 0 and "LeftWingMotor" or "RightWingMotor"
    Motor.Part0 = Torso
    Motor.Part1 = Pivot
    Motor.C0 = CFrame.new(Offset)
    Motor.C1 = CFrame.new()
    Motor.Parent = Torso
    return Pivot, Motor
end

function CreateAngelWingAttachment(Parent, Name, Position, Tangent, Normal)
    local Attachment = Instance.new("Attachment")
    Attachment.Name = Name
    Attachment.CFrame = AngelWingFrame(Position, Tangent, Normal)
    Attachment.Parent = Parent
    return Attachment
end

function CreateAngelWingBeam(Parent, Name, Attachment0, Attachment1, Width0, Width1, Curve0, Curve1, FaceCamera, Color, Transparency, Brightness, ZOffset)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = Attachment0
    Beam.Attachment1 = Attachment1
    Beam.FaceCamera = FaceCamera
    Beam.Segments = 12
    Beam.Width0 = Width0
    Beam.Width1 = Width1
    Beam.CurveSize0 = Curve0
    Beam.CurveSize1 = Curve1
    Beam.Color = Color
    Beam.Transparency = Transparency
    Beam.LightEmission = 0.82
    Beam.LightInfluence = 0.06
    Beam.Brightness = Brightness
    Beam.ZOffset = ZOffset
    Beam.Parent = Parent
    S.AngelWings.Beams[#S.AngelWings.Beams + 1] = Beam
    return Beam
end

function CreateAngelWingFeather(Pivot, Side, Layer, Index, Count, RootPosition, TipPosition, Width, Curve, Flutter, Weight)
    local Progress = Count > 1 and(Index - 1) / (Count - 1) or 0
    local Direction = TipPosition - RootPosition
    local MainNormal = Vector3.new(0, 1, Side * 0.24)
    local CrossNormal = Direction:Cross(MainNormal)
    if CrossNormal.Magnitude < 0.001 then
        CrossNormal = Vector3.new(0, 0, 1)
    else
        CrossNormal = CrossNormal.Unit
    end
    local RootMain = CreateAngelWingAttachment(Pivot, "RootMain_" .. Layer .. "_" .. Index, RootPosition, Direction + Vector3.new(0, Curve * 0.52, 0), MainNormal)
    local TipMain = CreateAngelWingAttachment(Pivot, "TipMain_" .. Layer .. "_" .. Index, TipPosition, Direction + Vector3.new(0, -Curve * 0.18, Side * 0.12), MainNormal)
    local RootCross = CreateAngelWingAttachment(Pivot, "RootCross_" .. Layer .. "_" .. Index, RootPosition, Direction + Vector3.new(0, Curve * 0.52, 0), CrossNormal)
    local TipCross = CreateAngelWingAttachment(Pivot, "TipCross_" .. Layer .. "_" .. Index, TipPosition, Direction + Vector3.new(0, -Curve * 0.18, Side * 0.12), CrossNormal)
    local MainBeam = CreateAngelWingBeam(Pivot, "Feather_" .. Layer .. "_" .. Index, RootMain, TipMain, Width, Width * 0.012, Curve, Curve * 0.58, false,
        ColorSequence.new({ ColorSequenceKeypoint.new(0, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(0.76, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(1,
        S.AngelWings.GlowColor) }), NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.16), NumberSequenceKeypoint.new(0.74, 0.30), NumberSequenceKeypoint.new(1, 1) }), 0.92, 0.015)
    local VolumeBeam = CreateAngelWingBeam(Pivot, "Volume_" .. Layer .. "_" .. Index, RootCross, TipCross, Width * 0.22, Width * 0.005, Curve * 0.94, Curve * 0.52, false,
        ColorSequence.new(S.AngelWings.GlowColor, S.AngelWings.CoreColor), NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.48), NumberSequenceKeypoint.new(0.78, 0.68),
        NumberSequenceKeypoint.new(1, 1) }), 0.72, 0)
    local GlowBeam = CreateAngelWingBeam(Pivot, "Glow_" .. Layer .. "_" .. Index, RootMain, TipMain, Width * 1.22, Width * 0.02, Curve, Curve * 0.58, true,
        ColorSequence.new({ ColorSequenceKeypoint.new(0, S.AngelWings.GlowColor), ColorSequenceKeypoint.new(0.56, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(1,
        S.AngelWings.GlowColor) }), NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.78), NumberSequenceKeypoint.new(0.70, 0.88), NumberSequenceKeypoint.new(1, 1) }), 0.68, -0.02)
    S.AngelWings.Feathers[#S.AngelWings.Feathers + 1] = { Side = Side, Layer = Layer, Index = Index, Count = Count, Progress = Progress, RootPosition = RootPosition, TipPosition =
        TipPosition, Curve = Curve, Flutter = Flutter, Weight = Weight, Offset = Index * 0.52 + (Layer == "Primary" and 0 or Layer == "Secondary" and 1.8 or 3.1), RootMain = RootMain,
        TipMain = TipMain, RootCross = RootCross, TipCross = TipCross, MainBeam = MainBeam, VolumeBeam = VolumeBeam, GlowBeam = GlowBeam }
end

function CreateAngelWingSide(Pivot, Side, Scale)
    local PrimaryCount, SecondaryCount, CovertCount = GetAngelWingCounts()
    for Index = 1, PrimaryCount do
        local T = PrimaryCount > 1 and(Index - 1) / (PrimaryCount - 1) or 0
        CreateAngelWingFeather(Pivot, Side, "Primary", Index, PrimaryCount, Vector3.new(Side * (0.04 + T * 1.82) * Scale, (0.06 - T * 0.58) * Scale, (0.04 + T * 0.18) * Scale),
            Vector3.new(Side * (3.10 + T * 3.18) * Scale, (0.28 - T * 3.34) * Scale, (0.38 + T * 0.84) * Scale), (0.54 - T * 0.12) * Scale, (1.02 + T * 0.54) * Scale, (0.13 + T * 0.11)
            * Scale, 1)
    end
    for Index = 1, SecondaryCount do
        local T = SecondaryCount > 1 and(Index - 1) / (SecondaryCount - 1) or 0
        CreateAngelWingFeather(Pivot, Side, "Secondary", Index, SecondaryCount, Vector3.new(Side * (0.02 + T * 1.42) * Scale, (0.34 + T * 0.02) * Scale, (0.02 + T * 0.12) * Scale),
            Vector3.new(Side * (2.48 + T * 2.82) * Scale, (1.74 - T * 1.64) * Scale, (0.24 + T * 0.64) * Scale), (0.60 - T * 0.11) * Scale, (1.08 + T * 0.34) * Scale, (0.10 + T * 0.07)
            * Scale, 0.72)
    end
    for Index = 1, CovertCount do
        local T = CovertCount > 1 and(Index - 1) / (CovertCount - 1) or 0
        CreateAngelWingFeather(Pivot, Side, "Covert", Index, CovertCount, Vector3.new(Side * (0.01 + T * 0.94) * Scale, (0.60 + T * 0.08) * Scale, (0.01 + T * 0.08) * Scale),
            Vector3.new(Side * (1.68 + T * 2.12) * Scale, (2.28 - T * 0.92) * Scale, (0.14 + T * 0.46) * Scale), (0.66 - T * 0.14) * Scale, (0.94 + T * 0.26) * Scale, (0.07 + T * 0.05)
            * Scale, 0.46)
    end
end

function CreateAngelWingParticles(Pivot)
    local Aura = Instance.new("Attachment")
    Aura.Position = Vector3.new(0, 0.30, 0.06)
    Aura.Parent = Pivot
    local Emitter = Instance.new("ParticleEmitter")
    Emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
    Emitter.Color = ColorSequence.new(S.AngelWings.CoreColor, S.AngelWings.GlowColor)
    Emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.48), NumberSequenceKeypoint.new(0.66, 0.76), NumberSequenceKeypoint.new(1, 1) })
    Emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.06), NumberSequenceKeypoint.new(0.42, 0.14), NumberSequenceKeypoint.new(1, 0) })
    Emitter.Lifetime = NumberRange.new(0.70, 1.20)
    Emitter.Rate = 4
    Emitter.Speed = NumberRange.new(0.12, 0.46)
    Emitter.SpreadAngle = Vector2.new(100, 100)
    Emitter.Rotation = NumberRange.new(0, 360)
    Emitter.RotSpeed = NumberRange.new(-50, 50)
    Emitter.Drag = 2
    Emitter.Acceleration = Vector3.new(0, 0.42, 0)
    Emitter.VelocityInheritance = 0.18
    Emitter.LightEmission = 0.86
    Emitter.LightInfluence = 0
    Emitter.Brightness = 0.9
    Emitter.Parent = Aura
    S.AngelWings.Emitters[#S.AngelWings.Emitters + 1] = Emitter
end

function UpdateAngelWingAppearance()
    local Transparency = AngelWingClamp(S.AngelWings.Transparency, 0, 0.92)
    for Unused, Beam in ipairs(S.AngelWings.Beams) do
        if Beam.Name:find("Glow_") then
            Beam.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, S.AngelWings.GlowColor), ColorSequenceKeypoint.new(0.56, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(1,
                S.AngelWings.GlowColor) })
            Beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.55, 0, 0.96)), NumberSequenceKeypoint.new(0.70,
                AngelWingClamp(Transparency + 0.68, 0, 0.98)), NumberSequenceKeypoint.new(1, 1) })
        elseif Beam.Name:find("Volume_") then
            Beam.Color = ColorSequence.new(S.AngelWings.GlowColor, S.AngelWings.CoreColor)
            Beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.28, 0, 0.96)), NumberSequenceKeypoint.new(0.78,
                AngelWingClamp(Transparency + 0.46, 0, 0.98)), NumberSequenceKeypoint.new(1, 1) })
        else
            Beam.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(0.76, S.AngelWings.CoreColor), ColorSequenceKeypoint.new(1,
                S.AngelWings.GlowColor) })
            Beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, Transparency), NumberSequenceKeypoint.new(0.74, AngelWingClamp(Transparency + 0.14, 0, 0.96)),
                NumberSequenceKeypoint.new(1, 1) })
        end
    end
    for Unused, Emitter in ipairs(S.AngelWings.Emitters) do
        Emitter.Color = ColorSequence.new(S.AngelWings.CoreColor, S.AngelWings.GlowColor)
        Emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.30, 0, 0.92)), NumberSequenceKeypoint.new(0.66,
            AngelWingClamp(Transparency + 0.56, 0, 0.98)), NumberSequenceKeypoint.new(1, 1) })
    end
end

function CreateAngelWings(Character)
    DestroyAngelWingModel()
    Character = Character or LocalPlayer.Character
    if not Character then return end
    local Torso = Character:FindFirstChild("Torso")
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Torso or not Humanoid or Humanoid.RigType ~= Enum.HumanoidRigType.R6 then return end
    local Model = Instance.new("Model")
    Model.Name = "AtramentaCosmeticWings"
    Model.Parent = Character
    local LeftPivot, LeftMotor = CreateAngelWingPivot(Torso, Model, -1)
    local RightPivot, RightMotor = CreateAngelWingPivot(Torso, Model, 1)
    local Scale = S.AngelWings.Scale * GetAngelWingStyleScale()
    CreateAngelWingSide(LeftPivot, -1, Scale)
    CreateAngelWingSide(RightPivot, 1, Scale)
    CreateAngelWingParticles(LeftPivot)
    CreateAngelWingParticles(RightPivot)
    S.AngelWings.Model = Model
    S.AngelWings.LeftMotor = LeftMotor
    S.AngelWings.RightMotor = RightMotor
    S.AngelWings.Phase = 0
    S.AngelWings.PreviousStroke = AngelWingStableStroke(-1)
    S.AngelWings.StrokeVelocity = 0
    S.AngelWings.CurrentActivity = 0.62
    S.AngelWings.FeatherAccumulator = 0
    S.AngelWings.FeatherBatchIndex = 1
    S.AngelWings.EmitterAccumulator = 0
    S.AngelWings.CachedCharacter = Character
    S.AngelWings.CachedHumanoid = Humanoid
    S.AngelWings.CachedRootPart = Character:FindFirstChild("HumanoidRootPart")
    S.AngelWings.Ragdolled = false
    S.AngelWings.RecoverUntil = 0
    S.AngelWings.LastRagdollCharacter = nil
    S.AngelWings.RagdollHoldUntil = math.min(tonumber(S.AngelWings.RagdollHoldUntil) or 0, os.clock())
    UpdateAngelWingAppearance()
end

function UpdateAngelWingFeathers(Phase, Activity)
    local Feathers = S.AngelWings.Feathers
    local FeatherCount = #Feathers
    if FeatherCount == 0 then return end
    local StartIndex = S.AngelWings.FeatherBatchIndex
    local EndIndex = math.min(StartIndex + S.AngelWings.FeatherBatchSize - 1, FeatherCount)
    for Index = StartIndex, EndIndex do
        local Feather = Feathers[Index]
        local Delay = Feather.Progress * 0.34 + Feather.Weight * 0.08
        local DelayedStroke = GetAngelWingStroke(Phase - Delay)
        local StableStroke = AngelWingStableStroke(DelayedStroke)
        local Fold = AngelWingClamp((1 - StableStroke) * 0.40, 0.16, 0.70)
        local FlutterWave = math.sin(Phase * 1.52 + Feather.Offset)
        local FineWave = math.sin(Phase * 2.34 + Feather.Offset * 1.47)
        local Tip = Feather.TipPosition
        local FoldDistance = Fold * (0.20 + Feather.Progress * 0.62) * Feather.Weight
        Tip = Vector3.new(Tip.X * (1 - FoldDistance * 0.075), Tip.Y + FoldDistance * 0.30, Tip.Z - StableStroke * (0.18 + Feather.Progress * 0.40) * Feather.Weight)
        Tip = Tip + Vector3.new(0, FlutterWave * Feather.Flutter * (0.42 + Activity * 0.28), FineWave * Feather.Flutter * 0.26)
        local Direction = Tip - Feather.RootPosition
        local MainNormal = Vector3.new(0, 1, Feather.Side * (0.24 + FineWave * 0.05))
        local CrossNormal = Direction:Cross(MainNormal)
        if CrossNormal.Magnitude < 0.001 then
            CrossNormal = Vector3.new(0, 0, 1)
        else
            CrossNormal = CrossNormal.Unit
        end
        Feather.TipMain.CFrame = AngelWingFrame(Tip, Direction + Vector3.new(0, -Feather.Curve * 0.18, Feather.Side * FlutterWave * Feather.Flutter * 0.18), MainNormal)
        Feather.TipCross.CFrame = AngelWingFrame(Tip, Direction + Vector3.new(0, -Feather.Curve * 0.18, Feather.Side * FlutterWave * Feather.Flutter * 0.18), CrossNormal)
        local CurveScale = AngelWingClamp(1 + StableStroke * 0.07 * Feather.Weight + FineWave * 0.018, 0.86, 1.16)
        local Curve0 = Feather.Curve * CurveScale
        local Curve1 = Feather.Curve * 0.58 * AngelWingClamp(1 - StableStroke * 0.045 * Feather.Weight, 0.88, 1.14)
        Feather.MainBeam.CurveSize0 = Curve0
        Feather.MainBeam.CurveSize1 = Curve1
        Feather.VolumeBeam.CurveSize0 = Curve0 * 0.94
        Feather.VolumeBeam.CurveSize1 = Curve1 * 0.90
        Feather.GlowBeam.CurveSize0 = Curve0
        Feather.GlowBeam.CurveSize1 = Curve1
    end
    S.AngelWings.FeatherBatchIndex = EndIndex >= FeatherCount and 1 or EndIndex + 1
end

function UpdateAngelWings(DeltaTime)
    if not S.AngelWings.Enabled then return end
    local Character = LocalPlayer.Character
    if not Character then
        DestroyAngelWingModel()
        return
    end
    if not S.AngelWings.Model or S.AngelWings.Model.Parent ~= Character then
        CreateAngelWings(Character)
        return
    end
    local Humanoid = S.AngelWings.CachedHumanoid
    local RootPart = S.AngelWings.CachedRootPart
    if S.AngelWings.CachedCharacter ~= Character or not Humanoid or Humanoid.Parent ~= Character or not RootPart or RootPart.Parent ~= Character then
        Humanoid = Character:FindFirstChildOfClass("Humanoid")
        RootPart = Character:FindFirstChild("HumanoidRootPart")
        S.AngelWings.CachedCharacter = Character
        S.AngelWings.CachedHumanoid = Humanoid
        S.AngelWings.CachedRootPart = RootPart
    end
    local LeftMotor = S.AngelWings.LeftMotor
    local RightMotor = S.AngelWings.RightMotor
    if not Humanoid or not RootPart or not LeftMotor or not RightMotor or not LeftMotor.Parent or not RightMotor.Parent then
        CreateAngelWings(Character)
        return
    end

    DeltaTime = AngelWingClamp(tonumber(DeltaTime) or 0.016, 0.001, 0.05)

    local Ragdolled = IsAngelWingGameRagdolled(Character, Humanoid)
    if Ragdolled then
        if S.AngelWings.Ragdolled ~= true or S.AngelWings.LastRagdollCharacter ~= Character then
            S.AngelWings.Ragdolled = true
            S.AngelWings.LastRagdollCharacter = Character
        end
        S.AngelWings.RecoverUntil = os.clock() + S.AngelWings.RecoverDelay
        FreezeAngelWingsForRagdoll()
        return
    end

    if S.AngelWings.Ragdolled == true then
        if os.clock() < (tonumber(S.AngelWings.RecoverUntil) or 0) then
            FreezeAngelWingsForRagdoll()
            return
        end

        S.AngelWings.Ragdolled = false
        S.AngelWings.LastRagdollCharacter = nil
        if not RecoverAngelWingsFromRagdoll(Character) then return end
        LeftMotor = S.AngelWings.LeftMotor
        RightMotor = S.AngelWings.RightMotor
        if not LeftMotor or not RightMotor then return end
    end

    S.AngelWings.ValidationAccumulator = (tonumber(S.AngelWings.ValidationAccumulator) or 0) + DeltaTime
    if S.AngelWings.ValidationAccumulator >= S.AngelWings.ValidationInterval then
        S.AngelWings.ValidationAccumulator = 0
        local WingModels = 0
        for _, Object in ipairs(Character:GetChildren()) do
            if Object:IsA("Model") and Object.Name == "AtramentaCosmeticWings" then WingModels += 1 end
        end
        if WingModels ~= 1 or LeftMotor.Part0 == nil or LeftMotor.Part1 == nil or RightMotor.Part0 == nil or RightMotor.Part1 == nil then
            CreateAngelWings(Character)
            return
        end
    end
    local Movement = Humanoid.MoveDirection.Magnitude
    local State = Humanoid:GetState()
    local Airborne = State == Enum.HumanoidStateType.Jumping or State == Enum.HumanoidStateType.Freefall or State == Enum.HumanoidStateType.FallingDown
    local TargetActivity = 0.62
    if S.AngelWings.Reactive then TargetActivity = 0.62 + Movement * 0.14 + (Airborne and 0.20 or 0) end
    TargetActivity = AngelWingClamp(TargetActivity, 0.52, 0.96)
    S.AngelWings.CurrentActivity = AngelWingLerp(S.AngelWings.CurrentActivity, TargetActivity, AngelWingExpAlpha(4.8, DeltaTime))
    local Activity = AngelWingClamp(S.AngelWings.CurrentActivity, 0.45, 1)
    S.AngelWings.Phase = S.AngelWings.Phase + DeltaTime * S.AngelWings.FlapSpeed * (0.74 + Activity * 0.30) * math.pi * 2
    local Phase = S.AngelWings.Phase
    local Stroke, Downstroke, Cycle = GetAngelWingStroke(Phase)
    local StableStroke = AngelWingStableStroke(Stroke)
    local RawVelocity = (StableStroke - S.AngelWings.PreviousStroke) / DeltaTime
    S.AngelWings.PreviousStroke = StableStroke
    S.AngelWings.StrokeVelocity = AngelWingLerp(S.AngelWings.StrokeVelocity, AngelWingClamp(RawVelocity, -10, 10), AngelWingExpAlpha(10, DeltaTime))
    local StrokeVelocity = S.AngelWings.StrokeVelocity
    local Roll = StableStroke * 28 * Activity
    local Pitch = -6 + (Downstroke and -4 or 3) * Activity + math.sin(Cycle * math.pi * 2) * 1.2
    local Sweep = -StableStroke * 9 * Activity
    local AirSweep = AngelWingClamp(-RootPart.AssemblyLinearVelocity.Y * 0.055, -4, 5)
    local LeftTarget = CFrame.Angles(math.rad(Pitch + AirSweep * 0.12), math.rad(-10 + Sweep - AirSweep * 0.18 - StrokeVelocity * 0.10), math.rad(-24 + Roll))
    local RightTarget = CFrame.Angles(math.rad(Pitch + AirSweep * 0.12), math.rad(10 - Sweep + AirSweep * 0.18 + StrokeVelocity * 0.10), math.rad(24 - Roll))
    local TransformAlpha = AngelWingExpAlpha(10, DeltaTime)
    LeftMotor.Transform = LeftMotor.Transform:Lerp(LeftTarget, TransformAlpha)
    RightMotor.Transform = RightMotor.Transform:Lerp(RightTarget, TransformAlpha)
    S.AngelWings.FeatherAccumulator = S.AngelWings.FeatherAccumulator + DeltaTime
    if S.AngelWings.FeatherAccumulator >= S.AngelWings.FeatherInterval then
        S.AngelWings.FeatherAccumulator = S.AngelWings.FeatherAccumulator % S.AngelWings.FeatherInterval
        UpdateAngelWingFeathers(Phase, Activity)
    end
    local MotionEnergy = AngelWingClamp(math.abs(StrokeVelocity) / 14, 0, 1)
    S.AngelWings.EmitterAccumulator = S.AngelWings.EmitterAccumulator + DeltaTime
    if S.AngelWings.EmitterAccumulator >= S.AngelWings.EmitterInterval then
        S.AngelWings.EmitterAccumulator = S.AngelWings.EmitterAccumulator % S.AngelWings.EmitterInterval
        local MinimumSpeed = 0.10 + MotionEnergy * 0.18
        local MaximumSpeed = 0.42 + MotionEnergy * 0.42
        local Rate = 3 + MotionEnergy * 5
        for Unused, Emitter in ipairs(S.AngelWings.Emitters) do
            Emitter.Rate = Rate
            Emitter.Speed = NumberRange.new(MinimumSpeed, MaximumSpeed)
        end
    end
end

function RebuildAngelWings()
    if not S.AngelWings.Enabled then return end
    CreateAngelWings(LocalPlayer.Character)
end

function ToggleAngelWings(Enabled)
    S.AngelWings.Enabled = Enabled
    if Enabled then
        if not S.AngelWings.RenderConnection then S.AngelWings.RenderConnection = RunService.Heartbeat:Connect(UpdateAngelWings) end
        if not S.AngelWings.CharacterConnection then
            S.AngelWings.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
                S.AngelWings.RagdollHoldUntil = 0
                S.AngelWings.Ragdolled = false
                S.AngelWings.RecoverUntil = 0
                S.AngelWings.LastRagdollCharacter = nil
                task.spawn(function()
                    task.wait(0.65)
                    if S.AngelWings.Enabled and Character == LocalPlayer.Character then CreateAngelWings(Character) end
                end)
            end)
        end
        CreateAngelWings(LocalPlayer.Character)
    else
        if S.AngelWings.RenderConnection then
            S.AngelWings.RenderConnection:Disconnect()
            S.AngelWings.RenderConnection = nil
        end
        if S.AngelWings.CharacterConnection then
            S.AngelWings.CharacterConnection:Disconnect()
            S.AngelWings.CharacterConnection = nil
        end
        DestroyAngelWingModel()
    end
end

function GetAimFOVAnchorPosition()
    local CameraObject =
        GetCamera()

    if S.AimBot.SilentEnabled then
        local MousePosition =
            UserInputService:
                GetMouseLocation()

        S.AimBot.FOVPosition =
            MousePosition

        return MousePosition, true
    end

    if CameraObject then
        local CenterPosition =
            CameraObject.ViewportSize
            * 0.5

        S.AimBot.FOVPosition =
            CenterPosition

        return CenterPosition, false
    end

    local Fallback =
        S.AimBot.FOVPosition
        or Vector2.new(500, 500)

    return Fallback, false
end

function RemoveAimFOVCircle()
    local Circle = S.AimBot.FOVCircle

    if Circle then
        AtramentaCallChecked(function()
            Circle.Visible = false
            Circle:Remove()
        end)
    end

    if type(S.AimBot.FOVGlowCircles) == "table" then
        for _, GlowCircle in ipairs(
            S.AimBot.FOVGlowCircles
        ) do
            if GlowCircle then
                AtramentaCallChecked(
                    function()
                        GlowCircle.Visible = false
                        GlowCircle:Remove()
                    end
                )
            end
        end
    end

    if S.AimBot.FOVGlowCircle then
        AtramentaCallChecked(function()
            S.AimBot.FOVGlowCircle.Visible = false
            S.AimBot.FOVGlowCircle:Remove()
        end)
    end

    S.AimBot.FOVCircle = nil
    S.AimBot.FOVGlowCircle = nil
    S.AimBot.FOVGlowCircles = {}
end

function CreateAimFOVDrawingCircle(Color, Thickness, Transparency)
    local Success, Circle =
        AtramentaCallChecked(
            Drawing.new,
            "Circle"
        )

    if not Success or not Circle then
        return nil
    end

    Circle.Color = Color
    Circle.Filled = false
    Circle.Thickness = Thickness
    Circle.Transparency = Transparency
    Circle.Radius = S.AimBot.FOV
    Circle.NumSides = 72

    return Circle
end

function CreateAimFOVGlow(Position, Visible)
    S.AimBot.FOVGlowCircles = {}

    if not S.AimBot.FOVGlow then
        return
    end

    local BaseThickness =
        math.clamp(
            tonumber(
                S.AimBot.FOVGlowThickness
            )
            or 8,
            3,
            24
        )

    local BaseTransparency =
        math.clamp(
            tonumber(
                S.AimBot.FOVGlowTransparency
            )
            or 0.18,
            0,
            1
        )

    local Layers = {
        { 2.15, 0.28 },
        { 1.55, 0.52 },
        { 1.05, 0.82 }
    }

    for Index, Layer in ipairs(Layers) do
        local GlowCircle =
            CreateAimFOVDrawingCircle(
                S.AimBot.FOVGlowColor,
                math.max(
                    BaseThickness
                        * Layer[1],
                    1
                ),
                math.clamp(
                    BaseTransparency
                        * Layer[2],
                    0,
                    1
                )
            )

        if GlowCircle then
            GlowCircle.Position = Position
            GlowCircle.Visible = Visible
            S.AimBot.FOVGlowCircles[
                Index
            ] = GlowCircle
        end
    end

    S.AimBot.FOVGlowCircle =
        S.AimBot.FOVGlowCircles[3]
end

function CreateFOVCircle()
    RemoveAimFOVCircle()

    if not S.AimBot.ShowFOV
        or not Drawing
        or type(Drawing.new) ~= "function"
    then
        return
    end

    local Position =
        GetAimFOVAnchorPosition()

    local Visible =
        S.AimBot.Enabled
        and S.AimBot.ShowFOV

    CreateAimFOVGlow(
        Position,
        Visible
    )

    local Circle =
        CreateAimFOVDrawingCircle(
            S.AimBot.FOVColor,
            2,
            S.AimBot.FOVTransparency
        )

    if not Circle then
        RemoveAimFOVCircle()
        return
    end

    Circle.Position = Position
    Circle.Visible = Visible
    S.AimBot.FOVCircle = Circle
end

function UpdateFOVCircle()
    local Circle =
        S.AimBot.FOVCircle

    if not Circle then return end

    local CameraObject = GetCamera()

    if not CameraObject then
        Circle.Visible = false

        for _, GlowCircle in ipairs(
            S.AimBot.FOVGlowCircles
            or {}
        ) do
            GlowCircle.Visible = false
        end

        return
    end

    local Position =
        GetAimFOVAnchorPosition()

    local Visible =
        S.AimBot.Enabled
        and S.AimBot.ShowFOV

    Circle.Position = Position
    Circle.Radius = S.AimBot.FOV
    Circle.Color = S.AimBot.FOVColor
    Circle.Transparency =
        S.AimBot.FOVTransparency
    Circle.Visible = Visible

    if S.AimBot.FOVGlow
        and #(
            S.AimBot.FOVGlowCircles
            or {}
        ) == 0
    then
        CreateFOVCircle()
        return
    end

    local BaseThickness =
        math.clamp(
            tonumber(
                S.AimBot.FOVGlowThickness
            )
            or 8,
            3,
            24
        )

    local BaseTransparency =
        math.clamp(
            tonumber(
                S.AimBot.FOVGlowTransparency
            )
            or 0.18,
            0,
            1
        )

    local Layers = {
        { 2.15, 0.28 },
        { 1.55, 0.52 },
        { 1.05, 0.82 }
    }

    for Index, GlowCircle in ipairs(
        S.AimBot.FOVGlowCircles
        or {}
    ) do
        local Layer =
            Layers[Index]
            or Layers[#Layers]

        GlowCircle.Position = Position
        GlowCircle.Radius = S.AimBot.FOV
        GlowCircle.Color =
            S.AimBot.FOVGlowColor
        GlowCircle.Thickness =
            math.max(
                BaseThickness
                    * Layer[1],
                1
            )
        GlowCircle.Transparency =
            math.clamp(
                BaseTransparency
                    * Layer[2],
                0,
                1
            )
        GlowCircle.Visible =
            Visible
            and S.AimBot.FOVGlow
    end
end

function GetClosestPlayer()
    if not S.AimBot.Enabled then return nil end

    local CurrentTime = os.clock()
    local ScanInterval = math.max(
        tonumber(S.AimBot.TargetScanInterval) or 0.05,
        0.04
    )

    if CurrentTime - (S.AimBot.LastTargetScan or 0) < ScanInterval then
        return S.AimBot.CachedScanTarget
    end

    S.AimBot.LastTargetScan = CurrentTime

    local CameraObject = GetCamera()
    if not CameraObject then return nil end

    local ClosestPlayer = nil
    local ShortestDistance = S.AimBot.FOV
    local BestTier = -1

    local FOVPosition,
        UseScreenCoordinates =
        GetAimFOVAnchorPosition()

    local CameraPosition =
        CameraObject.CFrame.Position

    local WallParameters = nil
    if S.AimBot.WallCheck then
        WallParameters = RaycastParams.new()
        WallParameters.FilterType = Enum.RaycastFilterType.Exclude
        WallParameters.FilterDescendantsInstances = {
            LocalPlayer.Character,
            CameraObject
        }
        WallParameters.IgnoreWater = true
    end


    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        if IsAtramentaCombatTargetAllowed(PlayerObject) then
            local CharacterObject = PlayerObject.Character
            local HumanoidObject = CharacterObject
                and CharacterObject:FindFirstChildOfClass("Humanoid")
            local HumanoidRootPart = ResolverGetRoot(CharacterObject)

            if CharacterObject
                and HumanoidRootPart
                and HumanoidObject
                and HumanoidObject.Health > 0
            then
                if S.AimBot.DownedCheck
                    and HumanoidObject:GetState() == Enum.HumanoidStateType.Dead
                then
                    continue
                end

                local TargetPart = CharacterObject:FindFirstChild(S.AimBot.TargetPart)
                    or CharacterObject:FindFirstChild("Head")
                    or HumanoidRootPart

                if TargetPart and TargetPart:IsA("BasePart") then
                    local TargetPosition = TargetPart.Position

                    if WallParameters then
                        local Result = workspace:Raycast(
                            CameraPosition,
                            TargetPosition - CameraPosition,
                            WallParameters
                        )

                        if Result
                            and not Result.Instance:IsDescendantOf(CharacterObject)
                        then
                            continue
                        end
                    end

                    local ScreenPosition,
                        IsOnScreen

                    if UseScreenCoordinates then
                        ScreenPosition,
                            IsOnScreen =
                            CameraObject:
                                WorldToScreenPoint(
                                    TargetPosition
                                )
                    else
                        ScreenPosition,
                            IsOnScreen =
                            CameraObject:
                                WorldToViewportPoint(
                                    TargetPosition
                                )
                    end

                    if IsOnScreen
                        and ScreenPosition.Z > 0
                    then
                        local Distance = (
                            FOVPosition
                            - Vector2.new(
                                ScreenPosition.X,
                                ScreenPosition.Y
                            )
                        ).Magnitude

                        local Tier =
                            GetAtramentaCombatTargetTier(
                                PlayerObject
                            )

                        if Tier > BestTier
                            or Tier == BestTier
                                and Distance < ShortestDistance
                        then
                            BestTier = Tier
                            ShortestDistance = Distance
                            ClosestPlayer = PlayerObject
                        end
                    end
                end
            end
        end
    end

    S.AimBot.CachedScanTarget = ClosestPlayer
    return ClosestPlayer
end

function GetTargetPosition(CharacterObject, PlayerObject, AimMode)
    if not CharacterObject then return nil end

    local CurrentTime = os.clock()
    local UpdateInterval = math.max(
        tonumber(S.AimBot.PositionUpdateInterval) or (1 / 45),
        1 / 60
    )

    if S.AimBot.PositionCacheCharacter == CharacterObject
        and S.AimBot.PositionCacheValue
        and S.AimBot.PositionCacheMode == AimMode
        and CurrentTime - (S.AimBot.LastPositionUpdate or 0) < UpdateInterval
    then
        return S.AimBot.PositionCacheValue
    end

    local TargetPart = CharacterObject:FindFirstChild(S.AimBot.TargetPart)
        or CharacterObject:FindFirstChild("HumanoidRootPart")
        or CharacterObject:FindFirstChild("Head")

    if not TargetPart or not TargetPart:IsA("BasePart") then
        return nil
    end

    local PredictionTime = math.clamp(
        (tonumber(S.AimBot.Prediction) or 0) / 1000,
        0,
        0.30
    )


    local PositionValue = ResolveCombatPosition(
        PlayerObject,
        CharacterObject,
        TargetPart,
        PredictionTime,
        S.AimBot
    ) or TargetPart.Position

    local DivisorX
    local DivisorY
    if AimMode == "Silent Aim" then
        DivisorX = math.max(tonumber(S.AimBot.SilentPredictionDivisorX) or 1, 0.05)
        DivisorY = math.max(tonumber(S.AimBot.SilentPredictionDivisorY) or 1, 0.05)
    else
        DivisorX = math.max(tonumber(S.AimBot.AimbotPredictionDivisorX) or 1, 0.05)
        DivisorY = math.max(tonumber(S.AimBot.AimbotPredictionDivisorY) or 1, 0.05)
    end
    local PredictionOffset = PositionValue - TargetPart.Position
    PositionValue = TargetPart.Position + Vector3.new(
        PredictionOffset.X / DivisorX,
        PredictionOffset.Y / DivisorY,
        PredictionOffset.Z / DivisorX
    )

    S.AimBot.PositionCacheCharacter = CharacterObject
    S.AimBot.PositionCacheValue = PositionValue
    S.AimBot.PositionCacheMode = AimMode
    S.AimBot.LastPositionUpdate = CurrentTime

    return PositionValue
end

function GetAimSmoothAlpha(Axis)
    local Value
    if Axis == "Y" then
        Value = S.AimBot.SmoothnessY
    else
        Value = S.AimBot.SmoothnessX
    end
    return math.clamp(tonumber(Value) or tonumber(S.AimBot.Smoothness) or 0.1, 0.01, 1)
end

function SmoothAim(TargetPosition)
    if not TargetPosition then return end

    local CameraObject = GetCamera()
    if not CameraObject then return end

    local CurrentCFrame = CameraObject.CFrame
    local TargetDelta = TargetPosition - CurrentCFrame.Position
    if TargetDelta.Magnitude <= 0.001 then return end

    local CurrentDirection = CurrentCFrame.LookVector.Unit
    local TargetDirection = TargetDelta.Unit
    local CurrentYaw = math.atan2(-CurrentDirection.X, -CurrentDirection.Z)
    local TargetYaw = math.atan2(-TargetDirection.X, -TargetDirection.Z)
    local CurrentPitch = math.asin(math.clamp(CurrentDirection.Y, -1, 1))
    local TargetPitch = math.asin(math.clamp(TargetDirection.Y, -1, 1))
    local YawDelta = math.atan2(math.sin(TargetYaw - CurrentYaw), math.cos(TargetYaw - CurrentYaw))
    local NewYaw = CurrentYaw + YawDelta * GetAimSmoothAlpha("X")
    local NewPitch = CurrentPitch + (TargetPitch - CurrentPitch) * GetAimSmoothAlpha("Y")
    local CosPitch = math.cos(NewPitch)
    local Direction = Vector3.new(
        -math.sin(NewYaw) * CosPitch,
        math.sin(NewPitch),
        -math.cos(NewYaw) * CosPitch
    )
    CameraObject.CFrame = CFrame.lookAt(CurrentCFrame.Position, CurrentCFrame.Position + Direction)
end

function SmoothAimDirection(CurrentDirection, TargetDirection)
    if typeof(TargetDirection) ~= "Vector3"
        or TargetDirection.Magnitude <= 0.001
    then
        return nil
    end

    local TargetUnit = TargetDirection.Unit

    if typeof(CurrentDirection) ~= "Vector3"
        or CurrentDirection.Magnitude <= 0.001
    then
        return TargetUnit
    end

    local Alpha = math.clamp(
        (
            GetAimSmoothAlpha("X")
            + GetAimSmoothAlpha("Y")
        ) * 0.5,
        0.01,
        1
    )

    local Blended =
        CurrentDirection.Unit:Lerp(
            TargetUnit,
            Alpha
        )

    if Blended.Magnitude <= 0.001 then
        return TargetUnit
    end

    return Blended.Unit
end

function AimLoop()
    if not S.AimBot.Enabled then return end

    local CurrentTarget = nil

    if S.AimBot.Sticky then
        CurrentTarget = S.AimBot.Target

        if CurrentTarget then
            local CharacterObject = CurrentTarget.Character
            local HumanoidObject = CharacterObject
                and CharacterObject:FindFirstChildOfClass("Humanoid")

            if not CharacterObject
                or not HumanoidObject
                or HumanoidObject.Health <= 0
                or not IsAtramentaCombatTargetAllowed(
                    CurrentTarget
                )
            then
                CurrentTarget = nil
                S.AimBot.Target = nil
            end
        end

        if not CurrentTarget then
            CurrentTarget = GetClosestPlayer()
            S.AimBot.Target = CurrentTarget
        end
    else
        CurrentTarget = GetClosestPlayer()
    end

    if not S.AimBot.AimbotEnabled then
        S.AimBot.AimActive = false
        S.AimBot.Target = nil
        S.AimBot.CurrentTarget = nil
        return
    end

    S.AimBot.CurrentTarget = CurrentTarget

    if not S.AimBot.AimActive then return end

    if CurrentTarget and CurrentTarget.Character then
        local TargetPosition = GetTargetPosition(
            CurrentTarget.Character,
            CurrentTarget,
            "Aimbot"
        )

        if TargetPosition then
            SmoothAim(TargetPosition)
        end
    end
end

SilentAimController = SilentAimController or {
    Connection = nil,
    ToolConnection = nil,
    BoundTool = nil,
    CachedPart = nil,
    CachedPlayer = nil,
    CachedCharacter = nil,
    CachedAimPosition = nil,
    ShotDecision = true,
    ShotDecisionUntil = 0,
    RaycastHooked = false,
    FireHooked = false
}

SilentAimController.CachedAimPosition =
    nil

SilentAimInputState =
    SilentAimInputState
    or {
        ADS = false,
        Began = nil,
        Ended = nil
    }

function InstallSilentAimInputState()
    if SilentAimInputState.Began
        or SilentAimInputState.Ended
    then
        return
    end

    SilentAimInputState.Began =
        UserInputService.InputBegan:Connect(
            function(Input, Processed)
                if Processed then
                    return
                end

                if Input.UserInputType
                    == Enum.UserInputType.MouseButton2
                then
                    SilentAimInputState.ADS =
                        true
                end
            end
        )

    SilentAimInputState.Ended =
        UserInputService.InputEnded:Connect(
            function(Input)
                if Input.UserInputType
                    == Enum.UserInputType.MouseButton2
                then
                    SilentAimInputState.ADS =
                        false
                end
            end
        )
end

function IsSilentAimADS()
    return SilentAimInputState.ADS
        == true
end

InstallSilentAimInputState()

function GetSilentAimShotChance()
    local Chance =
        IsSilentAimADS()
        and tonumber(S.AimBot.SilentADSChance)
        or tonumber(S.AimBot.SilentHipChance)

    Chance =
        math.clamp(
            Chance
            or tonumber(S.AimBot.SilentHitChance)
            or 100,
            0,
            100
        )

    if S.AimBot.SilentRandomHitChance then
        local Minimum =
            math.clamp(
                tonumber(
                    S.AimBot.SilentRandomHitChanceMin
                )
                or 70,
                0,
                100
            )

        local Maximum =
            math.clamp(
                tonumber(
                    S.AimBot.SilentRandomHitChanceMax
                )
                or 100,
                Minimum,
                100
            )

        Chance =
            math.clamp(
                Chance
                * (
                    Minimum
                    + math.random()
                    * (
                        Maximum
                        - Minimum
                    )
                )
                / 100,
                0,
                100
            )
    end

    return Chance
end

function BeginSilentAimShotDecision()
    SilentAimController.ShotDecision =
        math.random() * 100
        <= GetSilentAimShotChance()

    SilentAimController.ShotDecisionUntil =
        os.clock() + 0.08

    return SilentAimController.ShotDecision
end

function ShouldSilentAimRedirect()
    if os.clock() <= (SilentAimController.ShotDecisionUntil or 0) then
        return SilentAimController.ShotDecision == true
    end
    return BeginSilentAimShotDecision()
end

function SilentAimGetMousePosition()
    return UserInputService:GetMouseLocation()
end

function SilentAimGetScreenPosition(WorldPosition)
    local CameraObject =
        GetCamera()

    if not CameraObject
        or typeof(WorldPosition)
            ~= "Vector3"
    then
        return nil, false
    end

    local Screen,
        OnScreen =
        CameraObject:
            WorldToScreenPoint(
                WorldPosition
            )

    return Vector2.new(
        Screen.X,
        Screen.Y
    ),
        OnScreen
        and Screen.Z > 0
end

function IsSilentAimTargetInsideFOV(
    TargetPart
)
    if not TargetPart
        or not TargetPart.Parent
        or not TargetPart:IsA("BasePart")
    then
        return false
    end

    local ScreenPosition,
        OnScreen =
        SilentAimGetScreenPosition(
            TargetPart.Position
        )

    if not OnScreen
        or not ScreenPosition
    then
        return false
    end

    local FOVPosition =
        SilentAimGetMousePosition()

    local FOVRadius =
        math.max(
            tonumber(S.AimBot.FOV)
            or 130,
            0
        )

    return (
        ScreenPosition
        - FOVPosition
    ).Magnitude <= FOVRadius
end

function SilentAimGetDirection(Origin, Position)
    if typeof(Origin) ~= "Vector3" or typeof(Position) ~= "Vector3" then return nil end
    local Delta = Position - Origin
    if Delta.Magnitude <= 0.001 then return nil end
    return Delta.Unit * 1000
end

function SilentAimScanClosestPart()
    local FovRadius =
        math.max(
            tonumber(S.AimBot.FOV)
            or 120,
            1
        )

    local MousePosition =
        SilentAimGetMousePosition()

    local ClosestPart,
        ClosestPlayer,
        ClosestCharacter

    local ClosestDistance =
        FovRadius

    local BestTier = -1

    local PartName =
        S.AimBot.TargetPart
        or "Torso"

    for _, PlayerObject in ipairs(
        Players:GetPlayers()
    ) do
        if not IsAtramentaCombatTargetAllowed(
            PlayerObject
        ) then
            continue
        end

        local Character =
            PlayerObject.Character

        if not Character then
            continue
        end

        local Humanoid =
            Character:
                FindFirstChildOfClass(
                    "Humanoid"
                )

        if not Humanoid
            or Humanoid.Health <= 0
            or Character:
                FindFirstChildWhichIsA(
                    "ForceField"
                )
        then
            continue
        end

        if S.AimBot.DownedCheck
            and type(IsRageDowned) == "function"
            and IsRageDowned(PlayerObject)
        then
            continue
        end

        local TargetPart =
            Character:
                FindFirstChild(
                    PartName
                )
            or Character:
                FindFirstChild(
                    "Head"
                )
            or Character:
                FindFirstChild(
                    "Torso"
                )
            or Character:
                FindFirstChild(
                    "HumanoidRootPart"
                )

        if not TargetPart
            or not TargetPart:IsA("BasePart")
        then
            continue
        end

        local ScreenPosition,
            OnScreen =
            SilentAimGetScreenPosition(
                TargetPart.Position
            )

        if not OnScreen
            or not ScreenPosition
        then
            continue
        end

        local Distance =
            (
                MousePosition
                - ScreenPosition
            ).Magnitude

        local Tier =
            GetAtramentaCombatTargetTier(
                PlayerObject
            )

        if Tier > BestTier
            or Tier == BestTier
                and Distance < ClosestDistance
        then
            BestTier = Tier
            ClosestDistance = Distance
            ClosestPart = TargetPart
            ClosestPlayer = PlayerObject
            ClosestCharacter = Character
        end
    end

    SilentAimController.CachedPart =
        ClosestPart

    SilentAimController.CachedPlayer =
        ClosestPlayer

    SilentAimController.CachedCharacter =
        ClosestCharacter

    local CachedAimPosition

    if ClosestPart
        and ClosestCharacter
        and ClosestPlayer
    then
        CachedAimPosition =
            GetSilentAimPosition(
                ClosestPlayer,
                ClosestCharacter,
                ClosestPart
            )
            or ClosestPart.Position
    end

    SilentAimController.CachedAimPosition =
        typeof(CachedAimPosition)
            == "Vector3"
        and CachedAimPosition
        or nil

    return ClosestPart,
        ClosestPlayer,
        ClosestCharacter
end

function GetSilentAimTarget()
    local Part = SilentAimController.CachedPart
    local PlayerObject = SilentAimController.CachedPlayer
    local Character = SilentAimController.CachedCharacter
    if Part
        and Part.Parent
        and Character
        and Character.Parent
        and PlayerObject
        and PlayerObject.Parent
    then
        local Humanoid =
            Character:
                FindFirstChildOfClass(
                    "Humanoid"
                )

        if Humanoid
            and Humanoid.Health > 0
            and IsAtramentaCombatTargetAllowed(
                PlayerObject
            )
            and IsSilentAimTargetInsideFOV(
                Part
            )
        then
            S.AimBot.CurrentTarget =
                PlayerObject

            return PlayerObject,
                Character,
                Part
        end
    end

    SilentAimController.CachedPart = nil
    SilentAimController.CachedPlayer = nil
    SilentAimController.CachedCharacter = nil
    SilentAimController.CachedAimPosition = nil

    Part,
        PlayerObject,
        Character =
        SilentAimScanClosestPart()
    if not Part then return nil end
    S.AimBot.CurrentTarget = PlayerObject
    return PlayerObject, Character, Part
end

function BindSilentAimTool(Tool)
    SilentAimController.BoundTool =
        Tool
end

function IsSilentAimWeaponRay(Origin, Direction, RaycastParameters)
    if typeof(Origin) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 25 then
        return false
    end
    if RaycastParameters ~= nil and typeof(RaycastParameters) ~= "RaycastParams" then
        return false
    end
    local Character = LocalPlayer.Character
    if not Character then return false end
    local CameraObject = GetCamera()
    if CameraObject and (Origin - CameraObject.CFrame.Position).Magnitude <= 18 then return true end
    local RootPart = Character:FindFirstChild("HumanoidRootPart")
    if RootPart and (Origin - RootPart.Position).Magnitude <= 18 then return true end
    local Head = Character:FindFirstChild("Head")
    if Head and Head:IsA("BasePart") and (Origin - Head.Position).Magnitude <= 18 then return true end
    local Tool = Character:FindFirstChildOfClass("Tool")
    local Handle = Tool and Tool:FindFirstChild("Handle")
    if Handle and Handle:IsA("BasePart") and (Origin - Handle.Position).Magnitude <= 18 then return true end
    return false
end

function GetSilentAimPosition(TargetPlayer, TargetCharacter, TargetPart)
    if not TargetPart or not TargetPart.Parent then return nil end
    local TargetPosition
    if type(GetTargetPosition) == "function" then
        TargetPosition = GetTargetPosition(TargetCharacter, TargetPlayer, "Silent Aim")
    end
    if typeof(TargetPosition) ~= "Vector3" then
        TargetPosition = TargetPart.Position
    end
    local PredictionOffset = TargetPosition - TargetPart.Position
    if PredictionOffset.Magnitude > 8 then
        TargetPosition = TargetPart.Position + PredictionOffset.Unit * 8
    end
    return TargetPosition
end

function IsNoFallDamageActive()
    local Environment = type(getgenv) == "function" and getgenv() or _G
    if NoFallDamageEnabled == true or Environment.CV2_NoFall == true then
        return true
    end
    local FarmSettings = type(AtramentaFarmModule) == "table" and AtramentaFarmModule.Settings or nil
    return type(FarmSettings) == "table" and FarmSettings.AntiFallDamage == true
end

function DisableLegacySilentAimHooks()
    local Environment = type(getgenv) == "function" and getgenv() or _G
    local FireState = rawget(Environment, "AtramentaSilentAimFireHookV2")
    local OldFireState = rawget(Environment, "AtramentaSilentAimFireHook")
    local OldRaycastState = rawget(Environment, "AtramentaSilentAimRaycastHook")

    if type(FireState) == "table" then FireState.Handler = nil end
    if type(OldFireState) == "table" then
        OldFireState.Handler = nil
        OldFireState.NamecallInstalled = false
    end
    if type(OldRaycastState) == "table" then
        OldRaycastState.Handler = nil
        OldRaycastState.Installed = false
        OldRaycastState.OldNamecall = nil
    end
end

function InstallAtramentaSharedNamecallRouter()
    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false
    end
    local Environment = type(getgenv) == "function" and getgenv() or _G
    local State = rawget(Environment, "AtramentaSharedNamecallRouterV2")
    if type(State) ~= "table" then
        State = { Installed = false, OldNamecall = nil, Handler = nil }
        rawset(Environment, "AtramentaSharedNamecallRouterV2", State)
    end

    local Events =
        ReplicatedStorage:
            FindFirstChild("Events")

    State.FallRemote =
        Events
        and Events:
            FindFirstChild("__RZDONL")
        or nil

    State.MoveRemote =
        Events
        and Events:
            FindFirstChild("MOVZREP")
        or nil

    State.Handler = function(Self, Method, Arguments)
        if Method == "FireServer" then
            local TracerState = rawget(Environment, "AtramentaBulletTracerShotHook")
            if type(TracerState) == "table"
                and TracerState.Enabled
                and (tonumber(TracerState.FireServerVersion) or 0) < 1
            then
                task.defer(
                    DispatchBulletTracerRemoteShot,
                    Self,
                    table.unpack(Arguments, 1, Arguments.n)
                )
            end

        end

        if HideHeadEnabled
            and Method == "FireServer"
            and Self == State.MoveRemote
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            local Packet = Arguments[1]
            if typeof(Packet) == "table" and typeof(Packet[1]) == "table" then
                local Direction = Packet[1][3]
                if typeof(Direction) == "Vector3" and Direction.Magnitude > 0.001 then
                    local NewArguments = table.pack(table.unpack(Arguments, 1, Arguments.n))
                    local NewPacket = table.clone(Packet)
                    local Movement = table.clone(Packet[1])
                    Movement[3] = GetHideHeadNetworkDirection(Direction)
                    NewPacket[1] = Movement
                    NewArguments[1] = NewPacket
                    return "Forward", NewArguments
                end
            end
        end

        if AntiBarbwireEnabled and Method == "FireServer" then
            local Arg1 = Arguments[1]
            local IsBarrierRemote = Self == State.FallRemote or typeof(Self) == "Instance" and Self.Name == "__RZDONL"
            if IsBarrierRemote and AntiBarbwireRemoteKeys[Arg1] then return "Block" end
        end

        if IsNoFallDamageActive()
            and (Method == "FireServer" or Method == "InvokeServer")
        then

            local FlyRagdollActive = (FlyEnabled == true and FlyMethod == "Ragdoll")

            local Arg1 = Arguments[1]
            local SelfName =
                Self
                and Self.Name
                or ""

            if not FlyRagdollActive then
                if SelfName == "__RZDONL" and Arg1 == "BHHh" then
                    return "Block"
                end
                if Arg1 == "FlllD" or Arg1 == "FllH" or Arg1 == "BHHh" then
                    return "Block"
                end
                if type(SelfName) == "string" then
                    if SelfName == "__RZDONL" then

                        if Arg1 ~= "__---r" then
                            return "Block"
                        end
                    end
                    if SelfName == "FallDamage" or SelfName == "FD_Event" then
                        return "Block"
                    end
                    if SelfName == "BreakLimb" then
                        return "Block"
                    end
                end
            else

                if Arg1 == "FlllD" or Arg1 == "FllH" then
                    if SelfName ~= "__RZDONL" then
                        return "Block"
                    end
                end
                if type(SelfName) == "string" then
                    if SelfName == "FallDamage" or SelfName == "FD_Event" then
                        return "Block"
                    end
                end
            end
        end

        if Method ~= "Raycast" or Self ~= workspace then
            return nil
        end

        if type(checkcaller) == "function" and checkcaller() then
            return nil
        end

        local ArgumentCount =
            tonumber(Arguments.n)
            or #Arguments

        if ArgumentCount < 2
            or ArgumentCount > 3
        then
            return nil
        end

        local Origin = Arguments[1]
        local Direction = Arguments[2]
        local RaycastParameters = Arguments[3]

        if typeof(Origin) ~= "Vector3"
            or typeof(Direction) ~= "Vector3"
            or Direction.Magnitude <= 0.001
        then
            return nil
        end

        if RaycastParameters ~= nil
            and typeof(RaycastParameters) ~= "RaycastParams"
        then
            return nil
        end

        if not IsSilentAimWeaponRay(Origin, Direction, RaycastParameters) then
            return nil
        end

        if not S.AimBot.SilentEnabled or not ShouldSilentAimRedirect() then
            return nil
        end

        local TargetPart =
            SilentAimController.
                CachedPart

        local TargetPosition =
            SilentAimController.
                CachedAimPosition

        if not TargetPart
            or not TargetPart.Parent
            or typeof(TargetPosition)
                ~= "Vector3"
        then
            return nil
        end

        local Delta =
            TargetPosition - Origin

        if Delta.Magnitude <= 0.001 then
            return nil
        end

        local RedirectedDirection =
            Delta.Unit
            * Direction.Magnitude

        local NewArguments =
            table.pack(
                table.unpack(
                    Arguments,
                    1,
                    Arguments.n
                )
            )

        NewArguments[2] =
            RedirectedDirection

        return "Forward",
            NewArguments
    end

    if State.Installed and type(State.OldNamecall) == "function" then
        SilentAimController.RaycastHooked = true
        return true
    end

    local function IsInternalRedoRay()
        if type(debug) == "table"
            and type(debug.info) == "function"
        then
            for Level = 2, 8 do
                local FunctionName = debug.info(Level, "n")
                local SourceName = debug.info(Level, "s")

                if type(FunctionName) == "string" then
                    if FunctionName == "RedoRay"
                        or (
                            FunctionName == "Update"
                            and type(SourceName) == "string"
                            and (
                                SourceName:find("LaserM", 1, true)
                                or SourceName:find("LaserHandler", 1, true)
                            )
                        )
                        or (
                            (FunctionName == "Raycast" or FunctionName == "RayCast")
                            and type(SourceName) == "string"
                            and (
                                SourceName:find("NewModules.Client.Services.Blood", 1, true)
                                or SourceName:find("Services.Blood", 1, true)
                            )
                        )
                    then
                        return true
                    end
                end

                if type(SourceName) == "string"
                    and (
                        SourceName:find("LaserM", 1, true)
                        or SourceName:find("LaserHandler", 1, true)
                        or SourceName:find("NewModules.Client.Services.Blood", 1, true)
                        or SourceName:find("Services.Blood", 1, true)
                    )
                then
                    return true
                end
            end
        end

        if type(getcallingscript) == "function" then
            local CallingScript = getcallingscript()

            if typeof(CallingScript) == "Instance" then
                local CallingName = CallingScript.Name

                if type(CallingName) == "string"
                    and (
                        CallingName == "LaserM"
                        or CallingName == "LaserHandler"
                        or CallingName == "Blood"
                    )
                then
                    return true
                end
            end
        end

        return false
    end

    local OldNamecall
    local Callback = function(Self, ...)
        local Method =
            getnamecallmethod()

        if Method == "Raycast"
            and Self == workspace
            and IsInternalRedoRay()
        then
            return OldNamecall(Self, ...)
        end

        if AntiBarbwireEnabled
            and Method == "FireServer"
            and typeof(Self) == "Instance"
            and Self.Name == "__RZDONL"
        then
            local Arguments = {...}
            if AntiBarbwireRemoteKeys[Arguments[1]] then return end
        end

        local Handler =
            State.Handler

        if type(Handler) ~= "function" then
            return OldNamecall(
                Self,
                ...
            )
        end

        local Arguments =
            table.pack(...)

        local Action,
            NewArguments =
            Handler(
                Self,
                Method,
                Arguments
            )

        if Action == "Block" then
            return nil
        end

        if Action == "Forward"
            and type(NewArguments) == "table"
        then
            return OldNamecall(
                Self,
                table.unpack(
                    NewArguments,
                    1,
                    NewArguments.n
                )
            )
        end

        return OldNamecall(
            Self,
            ...
        )
    end
    if type(newcclosure) == "function" then Callback = newcclosure(Callback) end
    OldNamecall = hookmetamethod(game, "__namecall", Callback)
    if type(OldNamecall) ~= "function" then
        State.Installed = false
        State.OldNamecall = nil
        SilentAimController.RaycastHooked = false
        return false
    end
    State.OldNamecall = OldNamecall
    State.Installed = true
    SilentAimController.RaycastHooked = true
    return true
end

function InstallSilentAimRaycastHook()
    DisableLegacySilentAimHooks()
    return InstallAtramentaSharedNamecallRouter()
end

function InstallSilentAimFireHook()
    DisableLegacySilentAimHooks()
    SilentAimController.FireHooked = false
    return false
end

function DisableSilentAimController()
    if SilentAimController.Connection then
        SilentAimController.Connection:Disconnect()
        SilentAimController.Connection = nil
    end
    if SilentAimController.ToolConnection then
        SilentAimController.ToolConnection:Disconnect()
        SilentAimController.ToolConnection = nil
    end
    SilentAimController.BoundTool = nil
    SilentAimController.CachedPart = nil
    SilentAimController.CachedPlayer = nil
    SilentAimController.CachedCharacter = nil
    SilentAimController.CachedAimPosition = nil
    SilentAimController.ShotDecision = true
    SilentAimController.ShotDecisionUntil = 0
end

function EnableSilentAimController()
    InstallSilentAimRaycastHook()
    if SilentAimController.Connection then return true end
    SilentAimController.Connection = RunService.RenderStepped:Connect(function()
        if not S.AimBot.SilentEnabled then return end
        SilentAimScanClosestPart()
        local Character = LocalPlayer.Character
        local Tool = Character and Character:FindFirstChildOfClass("Tool")
        BindSilentAimTool(Tool)
    end)
    return true
end

function UpdateSilentAimController()
    if S.AimBot.SilentEnabled then EnableSilentAimController() else DisableSilentAimController() end
end

DisableLegacySilentAimHooks()
InstallAtramentaSharedNamecallRouter()

function RefreshAimEngine()
    local EngineEnabled = S.AimBot.AimbotEnabled or S.AimBot.SilentEnabled
    S.AimBot.Enabled = EngineEnabled
    S.AimBot.Resolver = true
    S.AimBot.ResolverMode = "Adaptive"
    S.AimBot.ResolverStrength = 0.85
    S.AimBot.Target = nil
    S.AimBot.CurrentTarget = nil
    S.AimBot.CachedScanTarget = nil
    S.AimBot.LastTargetScan = 0
    S.AimBot.PositionCacheCharacter = nil
    S.AimBot.PositionCacheValue = nil
    S.AimBot.PositionCacheMode = nil
    S.AimBot.LastPositionUpdate = 0
    if EngineEnabled then
        if S.AimBot.ShowFOV then CreateFOVCircle() else RemoveAimFOVCircle() end
        if not S.AimBot.FOVUpdateConnection then S.AimBot.FOVUpdateConnection = RunService.RenderStepped:Connect(UpdateFOVCircle) end
        if not S.AimBot.Connection then S.AimBot.Connection = RunService.RenderStepped:Connect(AimLoop) end
        UpdateSilentAimController()
        return
    end
    S.AimBot.AimActive = false
    RemoveAimFOVCircle()
    DisableSilentAimController()
    if S.AimBot.FOVUpdateConnection then S.AimBot.FOVUpdateConnection:Disconnect(); S.AimBot.FOVUpdateConnection = nil end
    if S.AimBot.Connection then S.AimBot.Connection:Disconnect(); S.AimBot.Connection = nil end
end

function ToggleAimBot(StateValue)
    S.AimBot.AimbotEnabled = StateValue == true

    if not S.AimBot.AimbotEnabled then
        S.AimBot.AimActive = false
        S.AimBot.Target = nil
        S.AimBot.CurrentTarget = nil
    end

    RefreshAimEngine()
end

function ToggleSilentAim(StateValue)
    S.AimBot.SilentEnabled = StateValue == true
    RefreshAimEngine()
end


function SetupBlur()
    if not S.Blur.BlurEffect then
        S.Blur.BlurEffect = Instance.new("BlurEffect", game:GetService("Lighting"))
        S.Blur.BlurEffect.Size = 0
    end
    if S.Blur.Connection then
        S.Blur.Connection:Disconnect()
        S.Blur.Connection = nil
    end
    S.Blur.Connection = RunService.RenderStepped:Connect(function()
        if not S.Blur.Enabled or not S.Blur.BlurEffect then return end
        local CameraObject = GetCamera()
        if not CameraObject then return end
        S.Blur.CurrentLookVector = CameraObject.CFrame.LookVector
        S.Blur.RotationSpeed = (S.Blur.CurrentLookVector - (S.Blur.LastLookVector or S.Blur.CurrentLookVector)).Magnitude * 130
        S.Blur.BlurEffect.Size = math.clamp(S.Blur.RotationSpeed, 0, 20)
        S.Blur.LastLookVector = S.Blur.CurrentLookVector
    end)
end

function DisableBlur()
    if S.Blur.Connection then
        S.Blur.Connection:Disconnect()
        S.Blur.Connection = nil
    end
    if S.Blur.BlurEffect then
        S.Blur.BlurEffect.Size = 0
        S.Blur.BlurEffect:Destroy()
        S.Blur.BlurEffect = nil
    end
end

function ToggleBlur(StateValue)
    S.Blur.Enabled = StateValue
    if StateValue then SetupBlur() else DisableBlur() end
end

function GetCameraFOVDesired()
    return math.clamp(
        tonumber(S.CameraFOV.Value) or 90,
        40,
        120
    )
end

function DisconnectCameraFOVWatcher()
    if S.CameraFOV.ChangeConnection then
        S.CameraFOV.ChangeConnection:Disconnect()
        S.CameraFOV.ChangeConnection = nil
    end
    S.CameraFOV.Camera = nil
end

function BindCameraFOVWatcher(CameraObject)
    if not CameraObject then return end

    if S.CameraFOV.Camera == CameraObject
        and S.CameraFOV.ChangeConnection
    then
        return
    end

    DisconnectCameraFOVWatcher()

    S.CameraFOV.Camera = CameraObject

    if S.CameraFOV.SavedValues[CameraObject] == nil then
        S.CameraFOV.SavedValues[CameraObject] =
            CameraObject.FieldOfView
    end

    S.CameraFOV.ChangeConnection =
        CameraObject:
            GetPropertyChangedSignal(
                "FieldOfView"
            ):
            Connect(function()
                if not S.CameraFOV.Enabled
                    or S.CameraFOV.Applying
                then
                    return
                end

                local Desired =
                    GetCameraFOVDesired()

                if math.abs(
                    CameraObject.FieldOfView
                    - Desired
                ) <= 0.001
                then
                    return
                end

                S.CameraFOV.Applying = true
                CameraObject.FieldOfView = Desired
                S.CameraFOV.Applying = false
            end)
end

function UpdateCameraFOV()
    if not S.CameraFOV.Enabled then
        return
    end

    local CameraObject =
        GetCamera()

    if not CameraObject then
        return
    end

    BindCameraFOVWatcher(
        CameraObject
    )

    local Desired =
        GetCameraFOVDesired()

    if math.abs(
        CameraObject.FieldOfView
        - Desired
    ) > 0.001
    then
        S.CameraFOV.Applying = true
        CameraObject.FieldOfView = Desired
        S.CameraFOV.Applying = false
    end
end

function EnableCameraFOV()
    local CameraObject =
        GetCamera()

    if CameraObject then
        if S.CameraFOV.SavedValues[CameraObject] == nil then
            S.CameraFOV.SavedValues[CameraObject] =
                CameraObject.FieldOfView
        end

        S.CameraFOV.SavedValue =
            S.CameraFOV.SavedValues[
                CameraObject
            ]

        BindCameraFOVWatcher(
            CameraObject
        )
    end

    AtramentaCallChecked(function()
        RunService:
            UnbindFromRenderStep(
                S.CameraFOV.BindName
            )
    end)

    S.CameraFOV.Enabled = true

    RunService:BindToRenderStep(
        S.CameraFOV.BindName,
        Enum.RenderPriority.Last.Value,
        UpdateCameraFOV
    )

    UpdateCameraFOV()
end

function DisableCameraFOV()
    S.CameraFOV.Enabled = false

    AtramentaCallChecked(function()
        RunService:
            UnbindFromRenderStep(
                S.CameraFOV.BindName
            )
    end)

    DisconnectCameraFOVWatcher()

    local CameraObject =
        GetCamera()

    if CameraObject then
        local Saved =
            S.CameraFOV.SavedValues[
                CameraObject
            ]

        if Saved == nil then
            Saved =
                S.CameraFOV.SavedValue
        end

        if Saved ~= nil then
            AtramentaCallChecked(function()
                CameraObject.FieldOfView =
                    Saved
            end)
        end
    end

    S.CameraFOV.SavedValue = nil
    S.CameraFOV.Applying = false
end

function ToggleCameraFOV(State)
    if State == true then
        EnableCameraFOV()
    else
        DisableCameraFOV()
    end
end

function DisconnectFreecamInputs()
    for _, Connection in ipairs(S.Freecam.InputConnections) do
        AtramentaCallChecked(function()
            Connection:Disconnect()
        end)
    end

    S.Freecam.InputConnections = {}
end

function AddFreecamInputConnection(Connection)
    S.Freecam.InputConnections[#S.Freecam.InputConnections + 1] = Connection
    return Connection
end

function ApplyFreecamMouseState()
    if S.Freecam.OnMobile then
        return
    end

    if not S.Freecam.Enabled then
        return
    end

    if S.Freecam.Rotating then
        UserInputService.MouseBehavior =
            Enum.MouseBehavior.LockCenter
        UserInputService.MouseIconEnabled = false
    else
        UserInputService.MouseBehavior =
            Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
    end
end

function ResolveFreecamMouseRestore(SavedCameraMode)
    if SavedCameraMode == Enum.CameraMode.LockFirstPerson then
        return Enum.MouseBehavior.LockCenter, false
    end
    return Enum.MouseBehavior.Default, true
end

function ReleaseFreecamCharacter(Saved)
    local Character = LocalPlayer.Character
    local CurrentRoot = Character and (Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso"))

    if Saved and Saved.RootPart and Saved.RootPart.Parent then
        Saved.RootPart.Anchored = false
        Saved.RootPart.AssemblyLinearVelocity = Vector3.zero
        Saved.RootPart.AssemblyAngularVelocity = Vector3.zero
    end

    if CurrentRoot and CurrentRoot.Parent then
        CurrentRoot.Anchored = false
        CurrentRoot.AssemblyLinearVelocity = Vector3.zero
        CurrentRoot.AssemblyAngularVelocity = Vector3.zero
    end
end

function ForceRestorePlayerCamera(Saved, RestoreTransform)
    local CameraObject = GetCamera()
    local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    ReleaseFreecamCharacter(Saved)

    if Saved.MinZoom ~= nil then LocalPlayer.CameraMinZoomDistance = Saved.MinZoom end
    if Saved.MaxZoom ~= nil then LocalPlayer.CameraMaxZoomDistance = Saved.MaxZoom end

    local Mode = Saved.CameraMode or Enum.CameraMode.Classic
    LocalPlayer.CameraMode = Enum.CameraMode.Classic

    if CameraObject then
        local Subject = Saved.Subject
        if not Subject or not Subject.Parent then Subject = Humanoid end

        CameraObject.CameraType = Enum.CameraType.Custom
        if Subject then CameraObject.CameraSubject = Subject end
        if Saved.FOV then CameraObject.FieldOfView = Saved.FOV end

        if RestoreTransform ~= false then
            if typeof(Saved.CameraCFrame) == "CFrame" then CameraObject.CFrame = Saved.CameraCFrame end
            if typeof(Saved.CameraFocus) == "CFrame" then CameraObject.Focus = Saved.CameraFocus end
        end
    end

    LocalPlayer.CameraMode = Mode

    local Behavior, Icon = ResolveFreecamMouseRestore(Mode)
    UserInputService.MouseBehavior = Behavior
    UserInputService.MouseIconEnabled = Icon

    return Mode
end

function RestoreFreecamCameraState(Saved, Token)
    if S.Freecam.Enabled or S.Freecam.MouseRestoreToken ~= Token then return end

    local Mode = ForceRestorePlayerCamera(Saved, true)

    task.spawn(function()
        RunService.RenderStepped:Wait()
        if S.Freecam.Enabled or S.Freecam.MouseRestoreToken ~= Token then return end

        local CameraObject = GetCamera()
        local Character = LocalPlayer.Character
        local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

        ReleaseFreecamCharacter(Saved)

        if CameraObject then
            local Subject = Saved.Subject
            if not Subject or not Subject.Parent then Subject = Humanoid end
            CameraObject.CameraType = Enum.CameraType.Custom
            if Subject then CameraObject.CameraSubject = Subject end
            if Saved.FOV then CameraObject.FieldOfView = Saved.FOV end
        end

        LocalPlayer.CameraMode = Mode

        if Mode == Enum.CameraMode.LockFirstPerson then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false
        else
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled = true
        end

        RunService.RenderStepped:Wait()
        if S.Freecam.Enabled or S.Freecam.MouseRestoreToken ~= Token then return end

        ReleaseFreecamCharacter(Saved)

        if Mode ~= Enum.CameraMode.LockFirstPerson then
            local CurrentCamera = GetCamera()
            local Distance = CurrentCamera and (CurrentCamera.CFrame.Position - CurrentCamera.Focus.Position).Magnitude or math.huge
            if Distance > 1.05 then
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            end
        end

        S.Freecam.StartedFirstPerson = false
        S.Freecam.SavedCameraMode = nil
        S.Freecam.SavedMinZoom = nil
        S.Freecam.SavedMaxZoom = nil
        S.Freecam.SavedMouseBehavior = nil
        S.Freecam.SavedMouseIconEnabled = nil
        S.Freecam.SavedCameraType = nil
        S.Freecam.SavedCameraSubject = nil
        S.Freecam.SavedCameraCFrame = nil
        S.Freecam.SavedCameraFocus = nil
        S.Freecam.SavedFieldOfView = nil
        S.Freecam.SavedRootAnchored = nil
        S.Freecam.SavedRootPart = nil
    end)
end

function SetFreecamRotationState(State)
    S.Freecam.Rotating = State == true
    S.Freecam.MouseDelta = Vector2.zero
    ApplyFreecamMouseState()
end

function GetFreecamMovementVector(CameraFrame)
    local Move = Vector3.zero
    local Keys = S.Freecam.KeysDown

    if UserInputService:IsKeyDown(Enum.KeyCode.W)
        or Keys[Enum.KeyCode.W]
    then
        Move += CameraFrame.LookVector
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.S)
        or Keys[Enum.KeyCode.S]
    then
        Move -= CameraFrame.LookVector
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.A)
        or Keys[Enum.KeyCode.A]
    then
        Move -= CameraFrame.RightVector
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.D)
        or Keys[Enum.KeyCode.D]
    then
        Move += CameraFrame.RightVector
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.E)
        or UserInputService:IsKeyDown(Enum.KeyCode.Space)
        or Keys[Enum.KeyCode.E]
        or Keys[Enum.KeyCode.Space]
    then
        Move += Vector3.yAxis
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.Q)
        or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
        or Keys[Enum.KeyCode.Q]
        or Keys[Enum.KeyCode.LeftControl]
    then
        Move -= Vector3.yAxis
    end

    if Move.Magnitude > 0 then
        return Move.Unit
    end

    return Vector3.zero
end

function UpdateFreecam(DeltaTime)
    if not S.Freecam.Enabled then
        return
    end

    local CameraObject = GetCamera()
    if not CameraObject then
        ToggleFreecam(false)
        return
    end

    DeltaTime = math.clamp(tonumber(DeltaTime) or 0, 0, 1 / 30)

    if LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson then
        LocalPlayer.CameraMode = Enum.CameraMode.Classic
    end

    CameraObject.CameraType = Enum.CameraType.Scriptable
    if S.Freecam.Rotating ~= S.Freecam.RightMouseDown then SetFreecamRotationState(S.Freecam.RightMouseDown) end

    if S.Freecam.Rotating then
        local Delta =
            UserInputService:GetMouseDelta()

        if S.Freecam.MouseDelta.Magnitude > Delta.Magnitude then
            Delta = S.Freecam.MouseDelta
        end

        S.Freecam.MouseDelta = Vector2.zero

        local Sensitivity = math.clamp(tonumber(S.Freecam.Sensitivity) or 0.18, 0.02, 0.60)
        local RotationScale = math.rad(Sensitivity)

        S.Freecam.Yaw -= Delta.X * RotationScale
        S.Freecam.Pitch = math.clamp(
            S.Freecam.Pitch - Delta.Y * RotationScale,
            math.rad(-89),
            math.rad(89)
        )
    else
        S.Freecam.MouseDelta = Vector2.zero
    end

    local RotationFrame =
        CFrame.Angles(0, S.Freecam.Yaw, 0)
        * CFrame.Angles(S.Freecam.Pitch, 0, 0)

    local Movement = GetFreecamMovementVector(RotationFrame)
    local Speed = math.clamp(tonumber(S.Freecam.Speed) or 18, 1, 120)

    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
        Speed *= math.clamp(tonumber(S.Freecam.BoostMultiplier) or 2, 1, 3)
    end

    local TargetVelocity = Movement * Speed
    local Acceleration = math.clamp(tonumber(S.Freecam.Acceleration) or 14, 1, 30)
    local Alpha = 1 - math.exp(-Acceleration * DeltaTime)

    if Movement.Magnitude > 0 then
        S.Freecam.Velocity =
            S.Freecam.Velocity:Lerp(TargetVelocity, Alpha)

        if S.Freecam.Velocity.Magnitude > Speed
            and S.Freecam.Velocity.Magnitude > 0
        then
            S.Freecam.Velocity =
                S.Freecam.Velocity.Unit * Speed
        end
    else
        S.Freecam.Velocity =
            S.Freecam.Velocity:Lerp(
                Vector3.zero,
                math.clamp(Alpha * 1.35, 0, 1)
            )
    end

    S.Freecam.Position += S.Freecam.Velocity * DeltaTime

    local CameraFrame =
        CFrame.new(S.Freecam.Position) * RotationFrame

    CameraObject.CFrame = CameraFrame
    CameraObject.Focus =
        CFrame.new(
            S.Freecam.Position
            + CameraFrame.LookVector * 512
        )

    ApplyFreecamMouseState()
end

function SetupFreecam()
    local CameraObject = GetCamera()
    if not CameraObject then
        S.Freecam.Enabled = false
        return
    end

    DisconnectFreecamInputs()

    AtramentaCallChecked(function()
        RunService:UnbindFromRenderStep("AtramentaFreecam")
    end)

    S.Freecam.SavedCameraType = CameraObject.CameraType
    S.Freecam.SavedCameraSubject = CameraObject.CameraSubject
    S.Freecam.SavedCameraCFrame = CameraObject.CFrame
    S.Freecam.SavedCameraFocus = CameraObject.Focus
    S.Freecam.SavedFieldOfView = CameraObject.FieldOfView
    S.Freecam.SavedMouseBehavior = UserInputService.MouseBehavior
    S.Freecam.SavedMouseIconEnabled = UserInputService.MouseIconEnabled
    S.Freecam.SavedCameraMode = LocalPlayer.CameraMode
    S.Freecam.SavedMinZoom = LocalPlayer.CameraMinZoomDistance
    S.Freecam.SavedMaxZoom = LocalPlayer.CameraMaxZoomDistance

    local CameraDistance =
        (
            CameraObject.CFrame.Position
            - CameraObject.Focus.Position
        ).Magnitude

    S.Freecam.StartedFirstPerson =
        LocalPlayer.CameraMode
            == Enum.CameraMode.LockFirstPerson
        or CameraDistance <= 1.05
        or (
            tonumber(S.Freecam.SavedMinZoom) ~= nil
            and tonumber(S.Freecam.SavedMaxZoom) ~= nil
            and S.Freecam.SavedMinZoom <= 0.6
            and S.Freecam.SavedMaxZoom <= 0.6
        )

    S.Freecam.MouseRestoreToken += 1
    S.Freecam.Position = CameraObject.CFrame.Position

    local Pitch, Yaw = CameraObject.CFrame:ToOrientation()
    S.Freecam.Pitch = math.clamp(Pitch, math.rad(-89), math.rad(89))
    S.Freecam.Yaw = Yaw
    S.Freecam.Velocity = Vector3.zero
    S.Freecam.MouseDelta = Vector2.zero
    S.Freecam.KeysDown = {}
    S.Freecam.Rotating = false
    S.Freecam.RightMouseDown = false

    local Character = LocalPlayer.Character
    local RootPart =
        Character
        and Character:FindFirstChild("HumanoidRootPart")

    S.Freecam.SavedRootPart = RootPart

    if RootPart then
        S.Freecam.SavedRootAnchored = RootPart.Anchored
        RootPart.Anchored = true
    else
        S.Freecam.SavedRootAnchored = nil
    end

    LocalPlayer.CameraMode = Enum.CameraMode.Classic
    CameraObject.CameraType = Enum.CameraType.Scriptable
    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    UserInputService.MouseIconEnabled = true

    AddFreecamInputConnection(
        UserInputService.InputBegan:Connect(function(Input)
            if not S.Freecam.Enabled then
                return
            end

            if Input.UserInputType == Enum.UserInputType.MouseButton2 then
                S.Freecam.RightMouseDown = true
                SetFreecamRotationState(true)
            elseif Input.KeyCode == Enum.KeyCode.W
                or Input.KeyCode == Enum.KeyCode.A
                or Input.KeyCode == Enum.KeyCode.S
                or Input.KeyCode == Enum.KeyCode.D
                or Input.KeyCode == Enum.KeyCode.Q
                or Input.KeyCode == Enum.KeyCode.E
                or Input.KeyCode == Enum.KeyCode.Space
                or Input.KeyCode == Enum.KeyCode.LeftControl
            then
                S.Freecam.KeysDown[Input.KeyCode] = true
            end
        end)
    )

    AddFreecamInputConnection(
        UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton2 then
                S.Freecam.RightMouseDown = false
                SetFreecamRotationState(false)
            elseif Input.KeyCode ~= Enum.KeyCode.Unknown then
                S.Freecam.KeysDown[Input.KeyCode] = nil
            end
        end)
    )

    AddFreecamInputConnection(
        UserInputService.InputChanged:Connect(function(Input)
            if not S.Freecam.Enabled then
                return
            end

            if Input.UserInputType == Enum.UserInputType.MouseMovement
                and S.Freecam.Rotating
            then
                S.Freecam.MouseDelta +=
                    Vector2.new(Input.Delta.X, Input.Delta.Y)
            end
        end)
    )

    AtramentaCallChecked(function()
        AddFreecamInputConnection(
            UserInputService.WindowFocusReleased:Connect(function()
                S.Freecam.RightMouseDown = false
                SetFreecamRotationState(false)
            end)
        )
    end)

    RunService:BindToRenderStep(
        "AtramentaFreecam",
        Enum.RenderPriority.Camera.Value + 100,
        UpdateFreecam
    )

    ApplyFreecamMouseState()
end

function DisableFreecam()
    AtramentaCallChecked(function()
        RunService:UnbindFromRenderStep("AtramentaFreecam")
    end)

    DisconnectFreecamInputs()

    S.Freecam.RightMouseDown = false
    S.Freecam.Rotating = false
    S.Freecam.MouseDelta = Vector2.zero
    S.Freecam.KeysDown = {}
    S.Freecam.Velocity = Vector3.zero

    S.Freecam.MouseRestoreToken += 1
    local Token = S.Freecam.MouseRestoreToken

    local Saved = {
        CameraType = S.Freecam.SavedCameraType,
        Subject = S.Freecam.SavedCameraSubject,
        FOV = S.Freecam.SavedFieldOfView,
        CameraCFrame = S.Freecam.SavedCameraCFrame,
        CameraFocus = S.Freecam.SavedCameraFocus,
        CameraMode = S.Freecam.SavedCameraMode,
        MinZoom = S.Freecam.SavedMinZoom,
        MaxZoom = S.Freecam.SavedMaxZoom,
        RootAnchored = S.Freecam.SavedRootAnchored,
        RootPart = S.Freecam.SavedRootPart,
        WasFirstPerson = S.Freecam.StartedFirstPerson == true
    }

    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    UserInputService.MouseIconEnabled = true
    ReleaseFreecamCharacter(Saved)
    ForceRestorePlayerCamera(Saved, true)
    RestoreFreecamCameraState(Saved, Token)

    S.Freecam.Position = nil

    if S.CameraFOV and S.CameraFOV.Enabled then
        UpdateCameraFOV()
    end
end

function ToggleFreecam(State)
    State = State == true

    if State == S.Freecam.Enabled then
        return
    end

    if State then
        S.Freecam.Enabled = true
        SetupFreecam()
    else
        S.Freecam.Enabled = false
        DisableFreecam()
    end
end

AtramentaCallChecked(function()
    RunService:UnbindFromRenderStep("AtramentaFreecam")
    if S.Freecam.Enabled then return end
    local Character = LocalPlayer.Character
    local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    if RootPart and RootPart.Anchored and not SafeFarmTeleportLock then RootPart.Anchored = false end
end)

WeaponModsThread = nil
WeaponIdentityFields = { "Damage", "HeadshotMultiplier", "LimbMultiplier", "Spread", "Recoil", "FireRate", "MagSize", "StoredAmmo", "Range", "BulletsPerShot" }
WeaponRecoilFields = { "Recoil", "RecoilAmount", "CameraRecoil", "CameraRecoilAmount", "Kickback", "Kick", "ViewKick", "RecoilX", "RecoilY", "RecoilZ" }
WeaponRecoilBooleanFields = { "CameraRecoilingEnabled", "RecoilEnabled", "CameraRecoilEnabled" }
WeaponSpreadFields = { "Spread", "SpreadMin", "SpreadMax", "HipSpread", "AimSpread", "ADSSpread", "Bloom", "BloomMin", "BloomMax" }
WeaponCrosshairFields = { "CrossExpansion", "CrosshairExpansion", "CrosshairBloom", "CrosshairKick" }
WeaponMovementSpreadFields = { "WalkSpreadIncrease", "MoveSpreadIncrease", "MovementSpread", "JumpSpreadIncrease" }
WeaponRecoilDamperFields = { "RecoilDamper", "RecoilDamping", "RecoilDecay" }
WeaponReloadTimeFields = { "ReloadTime" }
WeaponReloadSpeedFields = { "ReloadAnimSpeed" }
WeaponEquipTimeFields = { "EquipTime" }
WeaponEquipSpeedFields = { "EquipAnimSpeed" }
WeaponShotgunReloadTimeFields = { "ReloadStartTime", "ShellInTime", "ReloadFinishTime", "FinishPumpWait", "LoopEndDelay" }
WeaponShotgunReloadSpeedFields = { "ReloadStartAnimSpeed", "ShellInAnimSpeed" }

function IsWeaponConfigNR(Object)
    if type(Object) ~= "table" then return false end
    local IdentityScore = 0
    for _, Field in ipairs(WeaponIdentityFields) do
        if type(rawget(Object, Field)) == "number" then IdentityScore = IdentityScore + 1 end
    end
    local HasAccuracy = type(rawget(Object, "Spread")) == "number" or type(rawget(Object, "Recoil")) == "number"
    local HasWeaponRate = type(rawget(Object, "FireRate")) == "number" or type(rawget(Object, "MagSize")) == "number"
    local HasTiming = type(rawget(Object, "ReloadTime")) == "number" or type(rawget(Object, "EquipTime")) == "number"
    return IdentityScore >= 4 and HasWeaponRate and (HasAccuracy or HasTiming)
end

function RememberWeaponFieldNR(Object, Field)
    local Original = S.NoRecoil.OriginalValues[Object]
    if not Original then Original = {}; S.NoRecoil.OriginalValues[Object] = Original end
    if Original[Field] == nil then Original[Field] = rawget(Object, Field) end
end

function SetWeaponFieldNR(Object, Field, Value)
    local Current = rawget(Object, Field)
    if Current == nil or type(Current) ~= type(Value) or Current == Value then return false end
    RememberWeaponFieldNR(Object, Field)
    local WasReadonly = type(isreadonly) == "function" and type(setreadonly) == "function" and isreadonly(Object)
    if WasReadonly then AtramentaCallChecked(setreadonly, Object, false) end
    local Success = AtramentaCallChecked(function() Object[Field] = Value end)
    if WasReadonly then AtramentaCallChecked(setreadonly, Object, true) end
    return Success
end

function ApplyNestedWeaponGroupNR(Key, Value)
    if type(Value) ~= "table" then return end
    local Name = string.lower(tostring(Key))
    local IsRecoil = string.find(Name, "recoil", 1, true) or string.find(Name, "kick", 1, true)
    local IsSpread = string.find(Name, "spread", 1, true) or string.find(Name, "bloom", 1, true)
    local IsCrosshair = string.find(Name, "cross", 1, true)
    if not IsRecoil and not IsSpread and not IsCrosshair then return end
    for NestedField, NestedValue in pairs(Value) do
        if type(NestedValue) == "number" then
            if IsSpread and S.NoRecoil.Settings.GunMods.Spread then
                SetWeaponFieldNR(Value, NestedField, tonumber(S.NoRecoil.Settings.GunMods.SpreadAmount) or 0)
            elseif IsRecoil and S.NoRecoil.Settings.GunMods.NoRecoil then
                SetWeaponFieldNR(Value, NestedField, 0)
            elseif IsCrosshair and S.NoRecoil.Settings.GunMods.NoCrosshair then
                SetWeaponFieldNR(Value, NestedField, 0)
            end
        elseif type(NestedValue) == "boolean" and IsRecoil and S.NoRecoil.Settings.GunMods.NoRecoil then
            SetWeaponFieldNR(Value, NestedField, false)
        end
    end
end

function AddWeaponConfigNR(Cache, Seen, Object)
    if not IsWeaponConfigNR(Object) or Seen[Object] then return end
    Seen[Object] = true
    Cache[#Cache + 1] = Object
end

function RegisterWeaponConfigNR(Object)
    if not IsWeaponConfigNR(Object) then return false end

    if S.NoRecoil.WeaponLookup[Object] then
        return true
    end

    S.NoRecoil.WeaponLookup[Object] = true
    S.NoRecoil.WeaponCache[#S.NoRecoil.WeaponCache + 1] = Object
    return true
end

function RegisterToolWeaponConfigNR(Tool)
    if not Tool or not Tool:IsA("Tool") then return false end

    local Registered = false
    local ConfigModule = Tool:FindFirstChild("Config")

    if ConfigModule and ConfigModule:IsA("ModuleScript") then
        local Success, Config = AtramentaCallChecked(require, ConfigModule)

        if Success and type(Config) == "table" then
            Registered = RegisterWeaponConfigNR(Config) or Registered

            for _, Value in pairs(Config) do
                if type(Value) == "table" and IsWeaponConfigNR(Value) then
                    Registered = RegisterWeaponConfigNR(Value) or Registered
                end
            end
        end
    end

    return Registered
end

function RefreshVisibleWeaponConfigsNR()
    local Character = LocalPlayer.Character
    local Backpack =
        LocalPlayer:FindFirstChildOfClass("Backpack")
        or LocalPlayer:FindFirstChild("Backpack")

    if Character then
        for _, Child in ipairs(Character:GetChildren()) do
            if Child:IsA("Tool") then RegisterToolWeaponConfigNR(Child) end
        end
    end

    if Backpack then
        for _, Child in ipairs(Backpack:GetChildren()) do
            if Child:IsA("Tool") then RegisterToolWeaponConfigNR(Child) end
        end
    end
end

function CacheWeaponsNR(Force)
    if S.NoRecoil.Scanning then return false end

    RefreshVisibleWeaponConfigsNR()

    local Now = os.clock()
    local Cooldown = math.max(tonumber(S.NoRecoil.ScanCooldown) or 90, 15)
    local FullScanNeeded =
        S.NoRecoil.CacheReady ~= true
        or Now - (tonumber(S.NoRecoil.LastScan) or 0) >= Cooldown

    if not FullScanNeeded then return true end

    S.NoRecoil.Scanning = true

    local Seen = setmetatable({}, {__mode = "k"})
    local Cache = setmetatable({}, {__mode = "v"})

    for _, WeaponObject in pairs(S.NoRecoil.WeaponCache) do
        AddWeaponConfigNR(Cache, Seen, WeaponObject)
    end

    local Success = AtramentaScanGarbage(
        true,
        function(Object)
            AddWeaponConfigNR(Cache, Seen, Object)
        end,
        768
    )

    if Success then
        local Lookup = setmetatable({}, {__mode = "k"})

        for _, WeaponObject in pairs(Cache) do
            if type(WeaponObject) == "table" then
                Lookup[WeaponObject] = true
            end
        end

        S.NoRecoil.WeaponCache = Cache
        S.NoRecoil.WeaponLookup = Lookup
        S.NoRecoil.CacheReady = true
        S.NoRecoil.LastScan = os.clock()

        RefreshVisibleWeaponConfigsNR()
    end

    S.NoRecoil.Scanning = false
    return Success
end

function ApplyExactWeaponConfigNR(WeaponObject)
    if S.NoRecoil.Settings.GunMods.NoRecoil then
        for _, Field in ipairs(WeaponRecoilFields) do SetWeaponFieldNR(WeaponObject, Field, 0) end
        for _, Field in ipairs(WeaponRecoilBooleanFields) do SetWeaponFieldNR(WeaponObject, Field, false) end
        for _, Field in ipairs(WeaponRecoilDamperFields) do SetWeaponFieldNR(WeaponObject, Field, 1) end
    end
    if S.NoRecoil.Settings.GunMods.Spread then
        local SpreadAmount = tonumber(S.NoRecoil.Settings.GunMods.SpreadAmount) or 0
        for _, Field in ipairs(WeaponSpreadFields) do SetWeaponFieldNR(WeaponObject, Field, SpreadAmount) end
        for _, Field in ipairs(WeaponMovementSpreadFields) do SetWeaponFieldNR(WeaponObject, Field, 0) end
    end
    if S.NoRecoil.Settings.GunMods.NoCrosshair then
        for _, Field in ipairs(WeaponCrosshairFields) do SetWeaponFieldNR(WeaponObject, Field, 0) end
    end
    if S.NoRecoil.Settings.GunMods.InstantEquip then
        for _, Field in ipairs(WeaponEquipTimeFields) do SetWeaponFieldNR(WeaponObject, Field, 0.01) end
        for _, Field in ipairs(WeaponEquipSpeedFields) do SetWeaponFieldNR(WeaponObject, Field, 100) end
    end

    for Key, Value in pairs(WeaponObject) do ApplyNestedWeaponGroupNR(Key, Value) end
end

WeaponInstantReloadState = WeaponInstantReloadState or {
    Busy = false,
    LastRequest = 0,
    InputConnection = nil,
    CharacterAddedConnection = nil,
    CharacterChildConnection = nil,
    BackpackChildConnection = nil,
    ToolConnections = {},
    BoundTool = nil,
    BindToken = 0
}

function IsReloadableTool(Tool)
    if not Tool or not Tool:IsA("Tool") then
        return false
    end

    local Values = Tool:FindFirstChild("Values")
    if Values then
        if Values:FindFirstChild("SERVER_Ammo")
            or Values:FindFirstChild("Ammo")
            or Values:FindFirstChild("SERVER_StoredAmmo")
            or Values:FindFirstChild("StoredAmmo")
        then
            return true
        end
    end

    if Tool:FindFirstChild("Hitmarker", true) then
        return true
    end

    local ConfigModule = Tool:FindFirstChild("Config")
    if ConfigModule and ConfigModule:IsA("ModuleScript") then
        local Success, Config = AtramentaCallChecked(require, ConfigModule)
        if Success and type(Config) == "table" then
            if tonumber(Config.MagSize)
                or tonumber(Config.FireRate)
                or tonumber(Config.ReloadTime)
                or tonumber(Config.Ammo)
            then
                return true
            end
        end
    end

    if type(IsRageFirearm) == "function" and IsRageFirearm(Tool) then
        return true
    end

    return false
end

function WaitForReloadableTool(Tool, Timeout)
    if not Tool then
        return false
    end

    Timeout = tonumber(Timeout) or 4
    local Deadline = os.clock() + Timeout

    while Tool.Parent and os.clock() < Deadline do
        if IsReloadableTool(Tool) then
            local Values = Tool:FindFirstChild("Values")
            local Ammo = Values and (
                Values:FindFirstChild("SERVER_Ammo")
                or Values:FindFirstChild("Ammo")
            )

            if Ammo then
                return true
            end

            if Tool:FindFirstChild("Config") then
                return true
            end
        end

        task.wait(0.05)
    end

    return IsReloadableTool(Tool)
end

function GetWeaponInstantReloadTool()
    local Character = LocalPlayer and LocalPlayer.Character
    if not Character then
        return nil
    end

    local Tool = Character:FindFirstChildOfClass("Tool")
    if Tool and IsReloadableTool(Tool) then
        return Tool
    end

    for _, Child in ipairs(Character:GetChildren()) do
        if Child:IsA("Tool") and IsReloadableTool(Child) then
            return Child
        end
    end

    return nil
end

function DisconnectWeaponInstantReloadTool()
    for _, Connection in ipairs(WeaponInstantReloadState.ToolConnections) do
        if typeof(Connection) == "RBXScriptConnection" then
            AtramentaCallChecked(function()
                Connection:Disconnect()
            end)
        end
    end

    WeaponInstantReloadState.ToolConnections = {}
    WeaponInstantReloadState.BoundTool = nil
    WeaponInstantReloadState.Busy = false
    WeaponInstantReloadState.BindToken =
        (WeaponInstantReloadState.BindToken or 0) + 1
end

function PerformWeaponInstantReload(Tool)
    if not S.NoRecoil.Settings.GunMods.InstantReload
        or WeaponInstantReloadState.Busy
        or not Tool
        or not Tool.Parent
    then
        return false
    end

    if not IsReloadableTool(Tool) then
        return false
    end

    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values and (
        Values:FindFirstChild("SERVER_Ammo")
        or Values:FindFirstChild("Ammo")
    )
    local Stored = Values and (
        Values:FindFirstChild("SERVER_StoredAmmo")
        or Values:FindFirstChild("StoredAmmo")
    )

    local AmmoValue = Ammo and tonumber(Ammo.Value)
    local StoredValue = Stored and tonumber(Stored.Value)
    local MagSize =
        type(GetRageMagazineSize) == "function"
        and GetRageMagazineSize(Tool)
        or nil

    if StoredValue ~= nil and StoredValue <= 0 then
        return false
    end

    if AmmoValue ~= nil
        and MagSize
        and AmmoValue >= MagSize
    then
        return false
    end

    local Now = os.clock()
    if Now - (WeaponInstantReloadState.LastRequest or 0) < 0.035 then
        return false
    end

    local Events = ReplicatedStorage:FindFirstChild("Events")
    local ReloadEvent = Events and Events:FindFirstChild("GNX_R")
    if not ReloadEvent then
        return false
    end

    WeaponInstantReloadState.LastRequest = Now
    WeaponInstantReloadState.Busy = true

    local function FireReload()
        local Timestamp =
            type(GetRageProtocolTimestamp) == "function"
            and GetRageProtocolTimestamp(Tool)
            or (
                type(RageBotAPI) == "table"
                and type(RageBotAPI.GetServerTimestamp) == "function"
                and RageBotAPI.GetServerTimestamp(
                    Tool,
                    type(GetRageWeaponConfig) == "function"
                        and GetRageWeaponConfig(Tool)
                        or nil
                )
                or tick()
            )

        ReloadEvent:FireServer(
            Timestamp,
            "KLWE89U0",
            Tool
        )
    end

    local Requested = AtramentaCallChecked(FireReload)
    WeaponInstantReloadState.Busy = false

    if Requested then
        task.delay(0.04, function()
            if not S.NoRecoil.Settings.GunMods.InstantReload
                or not Tool
                or not Tool.Parent
            then
                return
            end

            local CurrentValues = Tool:FindFirstChild("Values")
            local CurrentAmmo = CurrentValues and (
                CurrentValues:FindFirstChild("SERVER_Ammo")
                or CurrentValues:FindFirstChild("Ammo")
            )

            if CurrentAmmo
                and AmmoValue ~= nil
                and tonumber(CurrentAmmo.Value) <= AmmoValue
            then
                AtramentaCallChecked(FireReload)
            end
        end)
    end

    return Requested == true
end

function BindWeaponInstantReloadTool(Tool)
    if not Tool or not Tool:IsA("Tool") then
        return
    end

    if WeaponInstantReloadState.BoundTool == Tool then
        return
    end

    if not S.NoRecoil.Settings.GunMods.InstantReload then
        return
    end

    DisconnectWeaponInstantReloadTool()

    local Token = WeaponInstantReloadState.BindToken

    task.spawn(function()
        if not WaitForReloadableTool(Tool, 5) then
            return
        end

        if Token ~= WeaponInstantReloadState.BindToken then
            return
        end

        if not S.NoRecoil.Settings.GunMods.InstantReload
            or not Tool.Parent
            or Tool.Parent ~= LocalPlayer.Character
        then
            return
        end

        local Values = Tool:FindFirstChild("Values")
        local Ammo = Values and (
            Values:FindFirstChild("SERVER_Ammo")
            or Values:FindFirstChild("Ammo")
        )
        local Stored = Values and (
            Values:FindFirstChild("SERVER_StoredAmmo")
            or Values:FindFirstChild("StoredAmmo")
        )

        if not Ammo then
            task.wait(0.25)
            Values = Tool:FindFirstChild("Values")
            Ammo = Values and (
                Values:FindFirstChild("SERVER_Ammo")
                or Values:FindFirstChild("Ammo")
            )
            Stored = Values and (
                Values:FindFirstChild("SERVER_StoredAmmo")
                or Values:FindFirstChild("StoredAmmo")
            )
        end

        if Token ~= WeaponInstantReloadState.BindToken then
            return
        end

        WeaponInstantReloadState.BoundTool = Tool

        if Ammo then
            WeaponInstantReloadState.ToolConnections[
                #WeaponInstantReloadState.ToolConnections + 1
            ] =
                Ammo:GetPropertyChangedSignal("Value"):Connect(function()
                    if S.NoRecoil.Settings.GunMods.InstantReload then
                        PerformWeaponInstantReload(Tool)
                    end
                end)
        end

        if Stored then
            WeaponInstantReloadState.ToolConnections[
                #WeaponInstantReloadState.ToolConnections + 1
            ] =
                Stored:GetPropertyChangedSignal("Value"):Connect(function()
                    if S.NoRecoil.Settings.GunMods.InstantReload then
                        PerformWeaponInstantReload(Tool)
                    end
                end)
        end

        WeaponInstantReloadState.ToolConnections[
            #WeaponInstantReloadState.ToolConnections + 1
        ] =
            Tool.AncestryChanged:Connect(function(_, Parent)
                if Parent ~= LocalPlayer.Character then
                    if WeaponInstantReloadState.BoundTool == Tool then
                        DisconnectWeaponInstantReloadTool()
                    end
                end
            end)

        task.defer(function()
            PerformWeaponInstantReload(Tool)
        end)
    end)
end

function RefreshWeaponInstantReloadBinding()
    if not S.NoRecoil.Settings.GunMods.InstantReload then
        DisconnectWeaponInstantReloadTool()
        return
    end

    local Tool = GetWeaponInstantReloadTool()
    if Tool then
        BindWeaponInstantReloadTool(Tool)
    else
        local Character = LocalPlayer.Character
        if Character then
            for _, Child in ipairs(Character:GetChildren()) do
                if Child:IsA("Tool") then
                    BindWeaponInstantReloadTool(Child)
                    break
                end
            end
        end
    end
end

function DisconnectWeaponInstantReloadRuntime()
    DisconnectWeaponInstantReloadTool()

    local Fields = {
        "InputConnection",
        "CharacterAddedConnection",
        "CharacterChildConnection",
        "BackpackChildConnection"
    }

    for _, Field in ipairs(Fields) do
        local Connection = WeaponInstantReloadState[Field]
        if typeof(Connection) == "RBXScriptConnection" then
            AtramentaCallChecked(function()
                Connection:Disconnect()
            end)
        end
        WeaponInstantReloadState[Field] = nil
    end
end

function InstallWeaponInstantReloadInput()
    if WeaponInstantReloadState.InputConnection
        and WeaponInstantReloadState.InputConnection.Connected
        and WeaponInstantReloadState.CharacterAddedConnection
        and WeaponInstantReloadState.CharacterAddedConnection.Connected
    then
        RefreshWeaponInstantReloadBinding()
        return
    end

    DisconnectWeaponInstantReloadRuntime()

    WeaponInstantReloadState.InputConnection =
        UserInputService.InputBegan:Connect(function(Input, Processed)
            if Processed or Input.KeyCode ~= Enum.KeyCode.R then
                return
            end

            local Tool =
                GetWeaponInstantReloadTool()
                or (
                    LocalPlayer.Character
                    and LocalPlayer.Character:FindFirstChildOfClass("Tool")
                )

            if Tool then
                PerformWeaponInstantReload(Tool)
            end
        end)

    local function BindCharacter(Character)
        if not Character then
            return
        end

        local OldConnection =
            WeaponInstantReloadState.CharacterChildConnection

        if typeof(OldConnection) == "RBXScriptConnection" then
            OldConnection:Disconnect()
        end

        WeaponInstantReloadState.CharacterChildConnection =
            Character.ChildAdded:Connect(function(Child)
                if Child:IsA("Tool") then
                    task.defer(function()
                        BindWeaponInstantReloadTool(Child)
                    end)

                    if S.NoRecoil.Enabled then
                        task.defer(function()
                            if type(HandleWeaponNR) == "function" then
                                HandleWeaponNR(Child)
                            end
                        end)
                    end
                end
            end)

        task.defer(function()
            RefreshWeaponInstantReloadBinding()

            if S.NoRecoil.Enabled and type(HandleWeaponNR) == "function" then
                for _, Child in ipairs(Character:GetChildren()) do
                    if Child:IsA("Tool") then
                        HandleWeaponNR(Child)
                    end
                end
            end
        end)

        task.delay(0.5, function()
            if Character == LocalPlayer.Character then
                RefreshWeaponInstantReloadBinding()
            end
        end)

        task.delay(1.5, function()
            if Character == LocalPlayer.Character then
                RefreshWeaponInstantReloadBinding()
                if S.NoRecoil.Enabled and type(RefreshGunModsNR) == "function" then
                    CacheWeaponsNR(true)
                    ApplyGunModsNR()
                end
            end
        end)
    end

    local function BindBackpack(Backpack)
        local OldConnection =
            WeaponInstantReloadState.BackpackChildConnection

        if typeof(OldConnection) == "RBXScriptConnection" then
            OldConnection:Disconnect()
        end

        if not Backpack then
            return
        end

        WeaponInstantReloadState.BackpackChildConnection =
            Backpack.ChildAdded:Connect(function(Child)
                if Child:IsA("Tool") and S.NoRecoil.Enabled then
                    task.delay(0.08, function()
                        if Child.Parent and type(HandleWeaponNR) == "function" then
                            HandleWeaponNR(Child)
                        end
                    end)
                end
            end)
    end

    if LocalPlayer.Character then
        BindCharacter(LocalPlayer.Character)
    end

    local Backpack =
        LocalPlayer:FindFirstChildOfClass("Backpack")
        or LocalPlayer:FindFirstChild("Backpack")

    BindBackpack(Backpack)

    WeaponInstantReloadState.CharacterAddedConnection =
        LocalPlayer.CharacterAdded:Connect(function(Character)
            WeaponInstantReloadState.Busy = false
            WeaponInstantReloadState.LastRequest = 0
            DisconnectWeaponInstantReloadTool()
            BindCharacter(Character)

            task.defer(function()
                local NewBackpack =
                    LocalPlayer:FindFirstChildOfClass("Backpack")
                    or LocalPlayer:FindFirstChild("Backpack")
                BindBackpack(NewBackpack)
            end)
        end)
end

InstallWeaponInstantReloadInput()


function ApplyGunModsNR()
    for _, WeaponObject in pairs(S.NoRecoil.WeaponCache) do
        if IsWeaponConfigNR(WeaponObject) then ApplyExactWeaponConfigNR(WeaponObject) end
    end
end

function ResetGunModsNR()
    for WeaponObject, Original in pairs(S.NoRecoil.OriginalValues) do
        if type(WeaponObject) == "table" and type(Original) == "table" then
            local WasReadonly = type(isreadonly) == "function" and type(setreadonly) == "function" and isreadonly(WeaponObject)
            if WasReadonly then AtramentaCallChecked(setreadonly, WeaponObject, false) end
            for Field, Value in pairs(Original) do AtramentaCallChecked(function() WeaponObject[Field] = Value end) end
            if WasReadonly then AtramentaCallChecked(setreadonly, WeaponObject, true) end
        end
    end
end

function DisableRCLConnectionNR(ConnectionObject)
    if S.NoRecoil.RCLLookup[ConnectionObject] then return end
    local DisableMethod = ConnectionObject.Disable or ConnectionObject.DisableConnection
    if type(DisableMethod) ~= "function" then return end
    local Success = AtramentaCallChecked(DisableMethod, ConnectionObject)
    if Success then
        S.NoRecoil.RCLLookup[ConnectionObject] = true
        S.NoRecoil.RCLConnections[#S.NoRecoil.RCLConnections + 1] = ConnectionObject
    end
end

function HandleRCLObjectNR(Object)
    if not S.NoRecoil.Enabled or not S.NoRecoil.Settings.GunMods.NoRecoil or type(getconnections) ~= "function" then return end
    if not Object or Object.Name ~= "RCL" or not Object:IsA("BindableEvent") then return end
    local Success, Connections = AtramentaCallChecked(getconnections, Object.Event)
    if not Success or type(Connections) ~= "table" then return end
    for _, ConnectionObject in ipairs(Connections) do DisableRCLConnectionNR(ConnectionObject) end
end

function DisableCameraRecoilNR(ScanExisting)
    if not S.NoRecoil.Settings.GunMods.NoRecoil then return end
    if not ScanExisting then return end
    for _, Object in ipairs(game:GetDescendants()) do
        if Object.Name == "RCL" and Object:IsA("BindableEvent") then HandleRCLObjectNR(Object) end
    end
end

function RestoreCameraRecoilNR()
    for _, ConnectionObject in ipairs(S.NoRecoil.RCLConnections) do
        local EnableMethod = ConnectionObject.Enable or ConnectionObject.EnableConnection
        if type(EnableMethod) == "function" then AtramentaCallChecked(EnableMethod, ConnectionObject) end
    end
    S.NoRecoil.RCLConnections = {}
    S.NoRecoil.RCLLookup = setmetatable({}, { __mode = "k" })
end

function RefreshGunModsNR()
    ResetGunModsNR()
    RestoreCameraRecoilNR()

    if not S.NoRecoil.Enabled then return end

    ApplyGunModsNR()
    DisableCameraRecoilNR(false)
end

function HandleWeaponNR(WeaponObject)
    if not S.NoRecoil.Enabled or not WeaponObject or not WeaponObject:IsA("Tool") then
        return
    end

    if S.NoRecoil.ToolJobs[WeaponObject] then return end
    S.NoRecoil.ToolJobs[WeaponObject] = true

    task.spawn(function()
        local Deadline = os.clock() + 4
        local Registered = false

        while S.NoRecoil.Enabled
            and WeaponObject.Parent
            and os.clock() < Deadline
        do
            local Parent = WeaponObject.Parent
            local Backpack =
                LocalPlayer:FindFirstChildOfClass("Backpack")
                or LocalPlayer:FindFirstChild("Backpack")

            if Parent == LocalPlayer.Character or Parent == Backpack then
                Registered = RegisterToolWeaponConfigNR(WeaponObject) or Registered

                if Registered then
                    ApplyGunModsNR()
                elseif S.NoRecoil.CacheReady ~= true then
                    CacheWeaponsNR(false)
                    ApplyGunModsNR()
                end

                if WeaponObject:FindFirstChild("Config")
                    or WeaponObject:FindFirstChild("Values")
                then
                    break
                end
            end

            task.wait(0.18)
        end

        if S.NoRecoil.Enabled and WeaponObject.Parent then
            RegisterToolWeaponConfigNR(WeaponObject)
            CacheWeaponsNR(false)
            ApplyGunModsNR()
        end

        S.NoRecoil.ToolJobs[WeaponObject] = nil
    end)
end

function OnCharacterAddedNR(CharacterObject)
    if not CharacterObject then return end

    if S.NoRecoil.CharacterChildConnection then
        AtramentaCallChecked(function()
            S.NoRecoil.CharacterChildConnection:Disconnect()
        end)
        S.NoRecoil.CharacterChildConnection = nil
    end

    task.defer(function()
        RefreshVisibleWeaponConfigsNR()
        CacheWeaponsNR(false)
        ApplyGunModsNR()
    end)

    for _, ChildObject in ipairs(CharacterObject:GetChildren()) do
        if ChildObject:IsA("Tool") then
            HandleWeaponNR(ChildObject)
        end
    end

    S.NoRecoil.CharacterChildConnection =
        CharacterObject.ChildAdded:Connect(function(ChildObject)
            if ChildObject:IsA("Tool") then
                HandleWeaponNR(ChildObject)
            end
        end)

    task.delay(0.75, function()
        if S.NoRecoil.Enabled and CharacterObject == LocalPlayer.Character then
            RefreshVisibleWeaponConfigsNR()
            CacheWeaponsNR(false)
            ApplyGunModsNR()
        end
    end)

    task.delay(2, function()
        if S.NoRecoil.Enabled and CharacterObject == LocalPlayer.Character then
            RefreshVisibleWeaponConfigsNR()
            CacheWeaponsNR(false)
            ApplyGunModsNR()
        end
    end)
end

function EnableNoRecoil()
    if S.NoRecoil.Enabled then RefreshGunModsNR(); return end
    S.NoRecoil.Enabled = true
    S.NoRecoil.OriginalValues = setmetatable({}, { __mode = "k" })
    S.NoRecoil.RCLConnections = {}
    S.NoRecoil.RCLLookup = setmetatable({}, { __mode = "k" })
    CacheWeaponsNR(true)
    ApplyGunModsNR()
    DisableCameraRecoilNR(true)

    S.NoRecoil.Connections[#S.NoRecoil.Connections + 1] = game.DescendantAdded:Connect(function(Object)
        if Object.Name == "RCL" then task.defer(HandleRCLObjectNR, Object) end
    end)

    if LocalPlayer.Character then OnCharacterAddedNR(LocalPlayer.Character) end
end

function DisableNoRecoil()
    if not S.NoRecoil.Enabled then return end
    S.NoRecoil.Enabled = false
    if WeaponModsThread then task.cancel(WeaponModsThread); WeaponModsThread = nil end
    ResetGunModsNR()
    RestoreCameraRecoilNR()

    for _, ConnectionObject in ipairs(S.NoRecoil.Connections) do
        AtramentaCallChecked(function() ConnectionObject:Disconnect() end)
    end
    S.NoRecoil.Connections = {}

    if S.NoRecoil.CharacterChildConnection then
        AtramentaCallChecked(function()
            S.NoRecoil.CharacterChildConnection:Disconnect()
        end)
        S.NoRecoil.CharacterChildConnection = nil
    end

    S.NoRecoil.WeaponCache = setmetatable({}, {__mode = "v"})
    S.NoRecoil.WeaponLookup = setmetatable({}, {__mode = "k"})
    S.NoRecoil.ToolJobs = setmetatable({}, {__mode = "k"})
    S.NoRecoil.OriginalValues = setmetatable({}, {__mode = "k"})
    S.NoRecoil.CacheReady, S.NoRecoil.LastScan, S.NoRecoil.Scanning = false, 0, false
    AtramentaStepGC(32)
end

function ToggleNoRecoil(StateValue)
    if StateValue then EnableNoRecoil() else DisableNoRecoil() end
end

function FindRespawnButton()
    local Cached = AtramentaPerformanceRuntime and AtramentaPerformanceRuntime.RespawnButton or nil
    if Cached and Cached.Parent and Cached:IsA("GuiButton") then return Cached end

    local Gui = PlayerGui
    if not Gui or not Gui.Parent then
        Gui = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui") or nil
    end
    if not Gui then return nil end

    for _, Descendant in ipairs(Gui:GetDescendants()) do
        if Descendant and Descendant:IsA("GuiButton") then
            local Name = string.lower(tostring(Descendant.Name or ""))
            local Text = Descendant:IsA("TextButton") and string.lower(tostring(Descendant.Text or "")) or ""
            if string.find(Name, "respawn", 1, true) or string.find(Text, "respawn", 1, true) then
                if AtramentaPerformanceRuntime then AtramentaPerformanceRuntime.RespawnButton = Descendant end
                return Descendant
            end
        end
    end

    return nil
end

function TriggerRespawnButton()
    local RespawnButton = FindRespawnButton()
    if not RespawnButton or not RespawnButton.Parent then return false end
    if type(ActivateGuiButton) ~= "function" then return false end
    return ActivateGuiButton(RespawnButton) == true
end

function GetDeathRespawnEvent()
    if DeathRespawnEvent and DeathRespawnEvent.Parent then return DeathRespawnEvent end
    local Events = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Events")
    DeathRespawnEvent = Events and Events:FindFirstChild("DeathRespawn") or nil
    return DeathRespawnEvent
end

function TriggerRespawnRemote()
    local Remote = GetDeathRespawnEvent()
    if not Remote then return false end

    if Remote:IsA("RemoteEvent") then
        local Success = AtramentaCallChecked(function() Remote:FireServer("KMG4R904") end)
        if Success then return true end
        return AtramentaCallChecked(function() Remote:FireServer() end) == true
    end

    if Remote:IsA("RemoteFunction") then
        local Success = AtramentaCallChecked(function() Remote:InvokeServer("KMG4R904") end)
        if Success then return true end
        return AtramentaCallChecked(function() Remote:InvokeServer() end) == true
    end

    if Remote:IsA("BindableEvent") then
        return AtramentaCallChecked(function() Remote:Fire() end) == true
    end

    return false
end

function RequestCharacterRespawn()
    if not LocalPlayer then return false end

    local Character = LocalPlayer.Character
    if not Character or not Character.Parent then return false end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Humanoid or not Humanoid.Parent or Humanoid.Health > 0 then return false end

    local CurrentTime = os.clock()
    if RespawnSafetyState.RespawnRequestedFor == Character
        and CurrentTime - (tonumber(RespawnSafetyState.LastRespawnRequest) or 0) < 2.2
    then
        return false
    end

    RespawnSafetyState.RespawnRequestedFor = Character
    RespawnSafetyState.LastRespawnRequest = CurrentTime

    if TriggerRespawnRemote() then return true end
    return TriggerRespawnButton()
end

function AutoRespawnEnable()
    if AutoRespawnEnabled then return end
    AutoRespawnEnabled = true

    if AutoRespawnCoroutine then
        AtramentaCallChecked(function() task.cancel(AutoRespawnCoroutine) end)
        AutoRespawnCoroutine = nil
    end

    AutoRespawnCoroutine = task.spawn(function()
        while AutoRespawnEnabled do
            task.wait(0.55)
            if not AutoRespawnEnabled then break end

            local Character = LocalPlayer and LocalPlayer.Character
            local Humanoid = Character and Character.Parent and Character:FindFirstChildOfClass("Humanoid") or nil

            if Character and Humanoid and Humanoid.Parent and Humanoid.Health <= 0 then
                RequestCharacterRespawn()
                task.wait(0.85)
            elseif not Character then
                RespawnSafetyState.RespawnRequestedFor = nil
            end
        end

        AutoRespawnCoroutine = nil
    end)
end

function AutoRespawnDisable()
    AutoRespawnEnabled = false
    RespawnSafetyState.RespawnRequestedFor = nil

    if AutoRespawnCoroutine then
        AtramentaCallChecked(function() task.cancel(AutoRespawnCoroutine) end)
        AutoRespawnCoroutine = nil
    end
end

function FormatUptime(Seconds)
    Seconds = math.max(math.floor(Seconds), 0)
    local Hours = math.floor(Seconds / 3600)
    local Minutes = math.floor(Seconds % 3600 / 60)
    local RemainingSeconds = Seconds % 60
    return string.format("%02d:%02d:%02d", Hours, Minutes, RemainingSeconds)
end

function GetAtramentaArmorValue(Character)
    if not Character then return 0 end

    local AttributeNames = { "Armor", "Armour", "ArmorValue", "ArmorHealth", "VestHealth" }
    for _, Name in ipairs(AttributeNames) do
        local Value = Character:GetAttribute(Name)
        if type(Value) == "number" then return math.max(0, math.floor(Value + 0.5)) end
    end

    local Containers = { Character, Character:FindFirstChild("Values"), Character:FindFirstChild("Stats") }
    for _, Container in ipairs(Containers) do
        if Container then
            for _, Name in ipairs(AttributeNames) do
                local ValueObject = Container:FindFirstChild(Name)
                if ValueObject and (ValueObject:IsA("NumberValue") or ValueObject:IsA("IntValue")) then
                    return math.max(0, math.floor(ValueObject.Value + 0.5))
                end
            end
        end
    end

    return 0
end

function GetAtramentaTargetWeapon(Character)
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    return Tool and Tool.Name or "Unarmed"
end

function GetAtramentaToolTexture(Tool)
    if not Tool or not Tool:IsA("Tool") then
        return ""
    end

    local Texture = ""

    AtramentaCallChecked(function()
        Texture = Tool.TextureId or ""
    end)

    if type(Texture) == "string" and Texture ~= "" then
        return Texture
    end

    local Handle = Tool:FindFirstChild("Handle") or Tool:FindFirstChild("WeaponHandle")

    if Handle then
        local TextureObject =
            Handle:FindFirstChildOfClass("Decal")
            or Handle:FindFirstChildOfClass("Texture")

        if TextureObject and type(TextureObject.Texture) == "string" then
            return TextureObject.Texture
        end
    end

    return ""
end

function GetAtramentaHUDInventory(PlayerObject, Limit)
    Limit = math.clamp(tonumber(Limit) or 5, 1, 5)

    local Result = {}
    local Seen = {}
    local Character = PlayerObject and PlayerObject.Character

    local function AddTool(Tool, Equipped)
        if #Result >= Limit
            or not Tool
            or not Tool:IsA("Tool")
            or Seen[Tool]
        then
            return
        end

        Seen[Tool] = true

        local Name = tostring(Tool.Name or "Item")

        Result[#Result + 1] = {
            Name = Name,
            Image = GetAtramentaToolTexture(Tool),
            Text = string.sub(string.upper(Name), 1, 2),
            Equipped = Equipped == true
        }
    end

    if Character then
        for _, Child in ipairs(Character:GetChildren()) do
            AddTool(Child, true)
        end
    end

    local Backpack =
        PlayerObject
        and (
            PlayerObject:FindFirstChildOfClass("Backpack")
            or PlayerObject:FindFirstChild("Backpack")
        )

    if Backpack then
        for _, Child in ipairs(Backpack:GetChildren()) do
            AddTool(Child, false)
        end
    end

    if #Result == 0 then
        Result[1] = {
            Name = "Fists",
            Image = "",
            Text = "FST",
            Equipped = true
        }
    end

    local Signature = {}

    for Index, Entry in ipairs(Result) do
        Signature[Index] = table.concat({
            tostring(Entry.Name),
            tostring(Entry.Image),
            Entry.Equipped and "1" or "0"
        }, ":")
    end

    return Result, table.concat(Signature, "|")
end

function IsAtramentaHUDTargetValid(Player)
    if not Player or Player == LocalPlayer or not Player.Parent then return false end

    local Character = Player.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    if not Character or not Humanoid or Humanoid.Health <= 0 or not Root then return false end

    if type(IsRageDowned) == "function" then
        local Success, Downed = AtramentaCallChecked(IsRageDowned, Player)
        if Success and Downed then return false end
    end

    return true
end

function GetAtramentaHUDTarget()
    if RageBotEnabled and IsAtramentaHUDTargetValid(RageBotCurrentTarget) then
        return RageBotCurrentTarget, "RAGE"
    end

    local AimTarget = S and S.AimBot and (S.AimBot.CurrentTarget or S.AimBot.Target)
    if S and S.AimBot and S.AimBot.Enabled and IsAtramentaHUDTargetValid(AimTarget) then
        return AimTarget, "AIM"
    end

    return nil, nil
end

function SyncAtramentaESPPreview()
    if type(Library) ~= "table"
        or type(Library.Flags) ~= "table"
    then
        return
    end

    local PlayerState =
        VisualState.Player

    Library.Flags["Player ESP"] =
        PlayerState.Enabled == true

    Library.Flags["Player ESP Boxes"] =
        PlayerState.Boxes == true

    Library.Flags["Player ESP Box Style"] =
        PlayerState.BoxStyle

    Library.Flags["Player ESP Box Color"] =
        PlayerState.BoxColor

    Library.Flags["Player ESP Fill"] =
        PlayerState.Fill == true

    Library.Flags["Player ESP Fill Color"] =
        PlayerState.FillColor

    Library.Flags["Player ESP Fill Transparency"] =
        PlayerState.FillTransparency

    Library.Flags["Player ESP Text Color"] =
        PlayerState.TextColor

    Library.Flags["Player ESP Health High Color"] =
        PlayerState.HealthHighColor

    Library.Flags["Player ESP Health Low Color"] =
        PlayerState.HealthLowColor

    Library.Flags["Player ESP Text Size"] =
        PlayerState.TextSize

    Library.Flags["Player ESP Health Bar"] =
        PlayerState.HealthBar == true

    Library.Flags["Player ESP Health Value"] =
        PlayerState.HealthText == true

    Library.Flags["Player ESP Names"] =
        PlayerState.Names == true

    Library.Flags["Player ESP Weapon"] =
        PlayerState.Weapon == true

    Library.Flags["Player ESP Distance"] =
        PlayerState.Distance == true

    Library.Flags["Player ESP Level"] =
        PlayerState.Level == true

    Library.Flags["Player ESP Level Color"] =
        PlayerState.LevelColor

    local LayoutFlags = {
        "Player ESP Health Bar Offset",
        "Player ESP Health Value Offset",
        "Player ESP Name Offset",
        "Player ESP Weapon Offset",
        "Player ESP Distance Offset",
        "Player ESP Level Offset"
    }

    for _, Flag in ipairs(LayoutFlags) do
        if typeof(Library.Flags[Flag])
            ~= "Vector2"
        then
            Library.Flags[Flag] =
                Vector2.zero
        end
    end
end

function UpdateAtramentaTargetHUD()
    return
end

function CreateAtramentaVisualWidgets()
    local Widgets =
        VisualState.Widgets

    if not Widgets then return end

    if Widgets.UpdateConnection then
        Widgets.UpdateConnection:Disconnect()
        Widgets.UpdateConnection = nil
    end

    Widgets.ESPPreview = nil
    Widgets.TargetHUD = nil

    SyncAtramentaESPPreview()
end

function DestroyAtramentaVisualWidgets()
    local Widgets =
        VisualState.Widgets

    if not Widgets then return end

    if Widgets.UpdateConnection then
        Widgets.UpdateConnection:Disconnect()
        Widgets.UpdateConnection = nil
    end

    Widgets.ESPPreview = nil
    Widgets.TargetHUD = nil

    if Widgets.PlayerList then
        Widgets.PlayerList:Destroy()
        Widgets.PlayerList = nil
    end

    Widgets.LastTarget = nil
    Widgets.LastMode = nil
    Widgets.LastInfo = nil
    Widgets.LastInventorySignature = nil
    Widgets.MenuWindow = nil
end


