function BuildAtramentaMenu()
    local Window = Library:Window({
        Name = "Atramenta.rip",
        Size = UDim2.new(0, 820, 0, 430),
        FadeSpeed = 0.12,
        Style = "Atramenta Emerald",
        StyleCallback = function(Value)
            ApplyThemePreset(Value)

            if VisualState
                and VisualState.Widgets
            then
                VisualState.Widgets.LastTarget = nil
                VisualState.Widgets.LastMode = nil
                VisualState.Widgets.LastInfo = nil
                VisualState.Widgets.LastInventorySignature = nil
            end
        end
    })
    Window.IsOpen = true
    VisualState.Widgets.MenuWindow = Window
    local Watermark = Library:Watermark("Atramenta.rip")
    local KeybindList = Library:KeybindList()
    local PlayerList = nil

    if type(Library.PlayerList) == "function" then
        PlayerList = Library:PlayerList({
            Brand = "Atramenta",
            Visible = false,
            Scale = 100,
            StatusChanged = function(Player, Status)
                AtramentaSetPlayerStatusRuntime(
                    Player,
                    Status
                )
            end,
            Spectate = function(Player)
                local CameraObject = GetCamera()
                local Character = Player and Player.Character
                local Humanoid =
                    Character
                    and Character:
                        FindFirstChildOfClass(
                            "Humanoid"
                        )

                if CameraObject and Humanoid then
                    CameraObject.CameraSubject =
                        Humanoid
                end
            end,
            Unspectate = function()
                local CameraObject = GetCamera()
                local Character =
                    LocalPlayer.Character

                local Humanoid =
                    Character
                    and Character:
                        FindFirstChildOfClass(
                            "Humanoid"
                        )

                if CameraObject and Humanoid then
                    CameraObject.CameraSubject =
                        Humanoid
                end
            end
        })

        VisualState.Widgets.PlayerList =
            PlayerList
    end

    Library.MenuKeybind = Enum.KeyCode.Delete
    Watermark:SetVisibility(true)
    if type(Watermark.SetScale) == "function" then
        Watermark:SetScale(VisualState.Widgets.WatermarkScale * 100)
    end
    KeybindList:SetVisibility(false)
    local Combat =
        Window:Page({
            Name = "Combat",
            Columns = 2,
            Subtabs = true
        })

    local Visuals =
        Window:Page({
            Name = "Visuals",
            Columns = 2,
            Subtabs = true
        })

    local Movement =
        Window:Page({
            Name = "Movement",
            Columns = 2,
            Subtabs = true
        })

    local WorldPage =
        Window:Page({
            Name = "World",
            Columns = 2,
            Subtabs = true
        })

    local Utility =
        Window:Page({
            Name = "Utility",
            Columns = 2,
            Subtabs = true
        })

    local CombatRage =
        Combat:SubPage({
            Name = "Ragebot",
            Icon = "rifle",
            Columns = 2
        })

    local CombatLegit =
        Combat:SubPage({
            Name = "Legitbot",
            Icon = "target",
            Columns = 2
        })

    local CombatWeapons =
        Combat:SubPage({
            Name = "Weapons",
            Icon = "weapon",
            Columns = 2
        })

    local VisualESP =
        Visuals:SubPage({
            Name = "Players",
            Icon = "eye",
            Columns = 2
        })

    local VisualHits =
