    local function SetRageUiVisible(Control, Visible)
        if not Control then return end

        if typeof(Control) == "Instance" then
            if Control:IsA("GuiObject") then
                Control.Visible = Visible
            end
            return
        end

        if type(Control) ~= "table" then return end

        local Keys = {
            "Holder",
            "Container",
            "Frame",
            "Main",
            "Root",
            "Instance",
            "Object",
            "Content",
            "SectionFrame",
            "SectionContent",
            "Element"
        }

        for _, Key in ipairs(Keys) do
            local Object = rawget(Control, Key)
            if typeof(Object) == "Instance"
                and Object:IsA("GuiObject")
            then
                Object.Visible = Visible
            end
        end
    end

    local function RefreshRageFOVUi()
        local Visible =
            RageBotSettings.TargetSelection
                == "FOV"

        SetRageUiVisible(
            RageFOVSection,
            Visible
        )

        for _, Control in ipairs(
            RageFOVControls
        ) do
            SetRageUiVisible(
                Control,
                Visible
            )
        end

        RageBotAPI.RefreshRageFOV()
    end

