GameVisualState.OriginalUnload = Library.Unload
Library.Unload = function(...)
    RageBotAPI.DestroyRageFOV()
    ExtendedVisualState:Destroy()
    GameVisualState:Destroy()
    RestoreAtramentaPerformanceFlags()
    return GameVisualState.OriginalUnload(...)
end

(function()
    local Environment = type(getgenv) == "function" and getgenv() or _G
    local OldState = rawget(Environment, "AtramentaRootMotorCompat")
    if type(OldState) == "table" then
        if OldState.CharacterConnection then OldState.CharacterConnection:Disconnect() end
        if OldState.RootConnection then OldState.RootConnection:Disconnect() end
    end

    local State = {CharacterConnection = nil, RootConnection = nil}
    rawset(Environment, "AtramentaRootMotorCompat", State)

    local function EnsureRootMotor(Character)
        if not Character or not Character.Parent then return end
        local Root = Character:FindFirstChild("HumanoidRootPart")
        if not Root or not Root:IsA("BasePart") or Root:FindFirstChild("Motor6D") then return end

        local Source = Root:FindFirstChildWhichIsA("Motor6D")
        if not Source then
            for _, Object in ipairs(Character:GetDescendants()) do
                if Object:IsA("Motor6D") and (Object.Part0 == Root or Object.Part1 == Root) then Source = Object break end
            end
        end

        local Alias = Instance.new("Motor6D")
        Alias.Name, Alias.Part0, Alias.Part1 = "Motor6D", nil, nil
        Alias.C0, Alias.C1, Alias.Transform = Source and Source.C0 or CFrame.new(), Source and Source.C1 or CFrame.new(), Source and Source.Transform or CFrame.new()
        Alias:SetAttribute("AtramentaCompatibilityAlias", true)
        Alias.Parent = Root

        if State.RootConnection then State.RootConnection:Disconnect() end
        State.RootConnection = Root.ChildRemoved:Connect(function(Child)
            if Child.Name == "Motor6D" then task.defer(function() if Character == LocalPlayer.Character and Root.Parent then EnsureRootMotor(Character) end end) end
        end)
    end

    local function BindCharacter(Character)
        task.defer(function()
            if Character ~= LocalPlayer.Character then return end
            local Root = Character:FindFirstChild("HumanoidRootPart") or Character:WaitForChild("HumanoidRootPart", 8)
            if Root then EnsureRootMotor(Character) end
        end)
    end

    State.CharacterConnection = LocalPlayer.CharacterAdded:Connect(BindCharacter)
    if LocalPlayer.Character then BindCharacter(LocalPlayer.Character) end
end)()

BuildAtramentaMenu()
GameVisualState:Start()
ExtendedVisualState:Start()
if S.CharacterAddedConnection then S.CharacterAddedConnection:Disconnect() end
if RespawnSafetyState.RemovingConnection then RespawnSafetyState.RemovingConnection:Disconnect() end
RespawnSafetyState.RemovingConnection = LocalPlayer.CharacterRemoving:Connect(function(Character)
    ClearRespawnTransientState(Character)
end)
S.CharacterAddedConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
    RespawnSafetyState.Generation += 1
    local Generation = RespawnSafetyState.Generation
    local Preserved = RespawnSafetyState.Preserved or {}
    RespawnSafetyState.Suspended = true
    RespawnSafetyState.CurrentCharacter = Character
    RespawnSafetyState.RespawnRequestedFor = nil
    BindRespawnSafety(Character)
    AtramentaCallChecked(function()
        if type(InstallWeaponInstantReloadInput) == "function" then
            InstallWeaponInstantReloadInput()
        end
        if S.NoRecoil and S.NoRecoil.Enabled and type(OnCharacterAddedNR) == "function" then
            OnCharacterAddedNR(Character)
        end
        if S.NoRecoil and S.NoRecoil.Settings and S.NoRecoil.Settings.GunMods and S.NoRecoil.Settings.GunMods.InstantReload then
            WeaponInstantReloadState.Busy = false
            WeaponInstantReloadState.LastRequest = 0
            RefreshWeaponInstantReloadBinding()
        end
    end)
    task.spawn(function()
        if not Character or not Character.Parent then return end

        local Humanoid = Character:FindFirstChildOfClass("Humanoid") or Character:WaitForChild("Humanoid", 8)
        local RootPart = Character:FindFirstChild("HumanoidRootPart") or Character:WaitForChild("HumanoidRootPart", 8)
        if not Humanoid or not RootPart or not Humanoid.Parent or not RootPart.Parent then return end

        local StartedAt = os.clock()
        while Generation == RespawnSafetyState.Generation
            and Character == LocalPlayer.Character
            and Character.Parent
            and (not Character:IsDescendantOf(workspace) or Humanoid.Parent and Humanoid.Health <= 0)
            and os.clock() - StartedAt < 8
        do
            task.wait(0.1)
        end

        task.wait(0.8)

        if not (
            Generation == RespawnSafetyState.Generation
            and Character == LocalPlayer.Character
            and Character.Parent
            and Humanoid.Parent
            and RootPart.Parent
            and Humanoid.Health > 0
        ) then
            return
        end

        RespawnSafetyState.Suspended = false
        RespawnSafetyState.Preserved = nil

        if FullBrightEnabled then
            AtramentaCallChecked(function()
                if FullBrightLight then
                    FullBrightLight:Destroy()
                    FullBrightLight = nil
                end

                FullBrightApply()
            end)
        end

        if S.ChinaHat.Enabled then
            AtramentaCallChecked(function()
                CreateChinaHat(Character)
            end)
        end

        if S.AngelWings.Enabled then
            AtramentaCallChecked(function()
                RebuildAngelWings()
            end)
        end

        if Preserved.World
            and WorldEffectsState.Enabled
        then
            AtramentaCallChecked(
                StartWorldEffects
            )
        end

        task.wait(0.15)

        if not (
            Generation == RespawnSafetyState.Generation
        ) then
            return
        end

        if Preserved.Arms then
            AtramentaCallChecked(
                ArmsChamsEnable
            )
        end

        if Preserved.Weapon then
            AtramentaCallChecked(
                WeaponChamsEnable
            )
        end

        if Preserved.Bunny
            or Preserved.Strafe
            or Preserved.Air
        then
            BunnyHopEnabled =
                Preserved.Bunny == true

            AutoStrafeEnabled =
                Preserved.Strafe == true

            AirControlEnabled =
                Preserved.Air == true

            AtramentaCallChecked(
                UpdateMovementAssistConnection
            )
        end

        task.wait(0.35)

        if not (
            Generation == RespawnSafetyState.Generation
        ) then
            return
        end

        if Preserved.Noclip then
            AtramentaCallChecked(
                NoclipEnable
            )
        end

        if Preserved.Fly then
            AtramentaCallChecked(
                FlyEnable
            )
        end

        if Preserved.Invis then
            AtramentaCallChecked(
                InvisibilityEnable
            )
        end

        task.wait(0.35)

        if Generation == RespawnSafetyState.Generation then
            if Preserved.Stamina then
                AtramentaCallChecked(
                    InfStaminaEnable
                )
            end

            if Preserved.NoFall then
                AtramentaCallChecked(
                    NoFallDamageEnable
                )
            end

            if Preserved.Rage then
                AtramentaCallChecked(function()
                    RageBotAPI.Enable()
                end)
            end
        end
    end)
end)
if LocalPlayer.Character then
    RespawnSafetyState.Suspended = false
    BindRespawnSafety(LocalPlayer.Character)
end
